// GERADO AUTOMATICAMENTE por scripts/gerar-template-bot.mjs a partir da pasta bot-template/.
// Não edite aqui: edite os arquivos em bot-template/ (o "npm run dev" e o "npm run build" geram de novo).
export const TEMPLATE_VERSION = "2583feabeb4b";

export const TEMPLATE_FILES: Record<string, string> = {
  ".env.example": "# Token do bot: Developer Portal → sua aplicação → Bot → Reset Token\nDISCORD_TOKEN=\n\n# Opcional: ID de um servidor de testes. Com ele, os comandos aparecem na hora nesse servidor.\n# Sem ele, os comandos são registrados em todos os servidores (pode levar alguns minutos).\nGUILD_ID=\n",
  ".gitignore": "node_modules/\n.env\ndata/\nlogs/\n.parar\n.inicializador.json\n",
  "config.json": "{\n  \"nome\": \"Meu Bot\",\n  \"cor\": \"#5865F2\",\n  \"status\": \"Use /ajuda\",\n  \"modulos\": [\n    \"moderacao\",\n    \"automod\",\n    \"antiraid\",\n    \"verificacao\",\n    \"boasvindas\",\n    \"logs\",\n    \"convites\",\n    \"niveis\",\n    \"economia\",\n    \"reputacao\",\n    \"tickets\",\n    \"avaliacoes\",\n    \"formularios\",\n    \"sugestoes\",\n    \"enquetes\",\n    \"sorteios\",\n    \"cargos\",\n    \"cargostemp\",\n    \"callstemp\",\n    \"contadores\",\n    \"destaques\",\n    \"contagem\",\n    \"afk\",\n    \"autorespostas\",\n    \"anuncios\",\n    \"embeds\",\n    \"aniversarios\",\n    \"minecraft\",\n    \"utilidades\",\n    \"diversao\",\n    \"personalizar\"\n  ]\n}\n",
  "extras/inicializador/inicializador.ps1": "﻿# Inicializador de bots (usado pelo \"Iniciar bot.bat\").\n# Acha os bots no PC, faz a primeira configuração por janelas (Node.js, token, intents, servidor),\n# instala o que falta, liga o bot sem terminal e deixa parar, ver o registro e ligar junto com o Windows.\n# Ninguém precisa digitar comandos.\nparam([string]$Ligar)\n\n$ErrorActionPreference = 'Stop'\nAdd-Type -AssemblyName System.Windows.Forms\nAdd-Type -AssemblyName System.Drawing\nAdd-Type -AssemblyName Microsoft.VisualBasic\n[System.Windows.Forms.Application]::EnableVisualStyles()\ntry { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}\n\n$titulo = 'Inicializador de bots'\n$pastaCache = Join-Path $env:APPDATA 'InicializadorBots'\n$arquivoCache = Join-Path $pastaCache 'bots.json'\n$fmt = 'dd/MM/yyyy HH:mm'\n$utf8 = New-Object System.Text.UTF8Encoding($false)\n$PULAR = @('node_modules', '.git', 'windows', 'program files', 'program files (x86)', 'programdata', 'appdata', '$recycle.bin',\n  'system volume information', 'recovery', 'msocache', 'perflogs', 'data', 'data-backup', '.cache', '.npm', 'steamapps', 'windowsapps', 'logs')\n$NOMES_INTENT = @{ members = 'Server Members Intent'; content = 'Message Content Intent'; presence = 'Presence Intent' }\n\nfunction Aviso([string]$texto, [string]$icone = 'Information') {\n  [void][System.Windows.Forms.MessageBox]::Show($texto, $titulo, 'OK', $icone)\n}\nfunction Pergunta([string]$texto, [string]$icone = 'Question') {\n  return ([System.Windows.Forms.MessageBox]::Show($texto, $titulo, 'YesNo', $icone) -eq [System.Windows.Forms.DialogResult]::Yes)\n}\nfunction Esperar([int]$ms) {\n  $fim = (Get-Date).AddMilliseconds($ms)\n  while ((Get-Date) -lt $fim) { [System.Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 50 }\n}\n\n# ---------------- Node.js ----------------\nfunction AtualizarPath {\n  $m = [Environment]::GetEnvironmentVariable('Path', 'Machine')\n  $u = [Environment]::GetEnvironmentVariable('Path', 'User')\n  $env:Path = \"$m;$u\"\n}\nfunction NodeExe {\n  $c = Get-Command node.exe -ErrorAction SilentlyContinue\n  if ($c) { return $c.Source }\n  foreach ($p in @(\"$env:ProgramFiles\\nodejs\\node.exe\", \"${env:ProgramFiles(x86)}\\nodejs\\node.exe\", \"$env:LOCALAPPDATA\\Programs\\nodejs\\node.exe\")) {\n    if ($p -and (Test-Path -LiteralPath $p)) { $env:Path = \"$(Split-Path $p);$env:Path\"; return $p }\n  }\n  return $null\n}\nfunction NodeVersao {\n  $exe = NodeExe\n  if (-not $exe) { return $null }\n  try { return ((& $exe -v) | Out-String).Trim() } catch { return $null }\n}\nfunction NodeServe([string]$v) {\n  if (-not $v) { return $false }\n  $m = [regex]::Match($v, 'v(\\d+)\\.(\\d+)')\n  if (-not $m.Success) { return $false }\n  $maior = [int]$m.Groups[1].Value; $menor = [int]$m.Groups[2].Value\n  return ($maior -gt 18) -or ($maior -eq 18 -and $menor -ge 17)\n}\nfunction Baixar([string]$url, [string]$destino, $rotulo) {\n  $wc = New-Object System.Net.WebClient\n  $t = $wc.DownloadFileTaskAsync($url, $destino)\n  while (-not $t.IsCompleted) { [System.Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 100 }\n  if ($t.IsFaulted) { throw $t.Exception.InnerException }\n}\n# Instala o Node.js LTS: pelo winget (se o Windows tiver) ou baixando o instalador oficial do nodejs.org\nfunction InstalarNode($rotulo) {\n  $winget = Get-Command winget.exe -ErrorAction SilentlyContinue\n  if ($winget) {\n    $rotulo.Text = 'Instalando o Node.js pelo Windows (winget)... pode aparecer uma janela pedindo permissão.'\n    $p = Start-Process -FilePath $winget.Source -ArgumentList @('install', '--id', 'OpenJS.NodeJS.LTS', '-e', '--silent', '--accept-package-agreements', '--accept-source-agreements') -WindowStyle Hidden -PassThru\n    while (-not $p.HasExited) { [System.Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 200 }\n    AtualizarPath\n    if (NodeServe (NodeVersao)) { return $true }\n  }\n  $rotulo.Text = 'Baixando o Node.js do site oficial (nodejs.org)...'\n  [System.Windows.Forms.Application]::DoEvents()\n  $arq = 'x64'\n  if (-not [Environment]::Is64BitOperatingSystem) { $arq = 'x86' }\n  $lista = (New-Object System.Net.WebClient).DownloadString('https://nodejs.org/dist/latest-v22.x/SHASUMS256.txt')\n  $m = [regex]::Match($lista, \"node-v22\\.\\d+\\.\\d+-$arq\\.msi\")\n  if (-not $m.Success) { throw 'não achei o instalador do Node.js no site.' }\n  $msi = Join-Path $env:TEMP $m.Value\n  Baixar \"https://nodejs.org/dist/latest-v22.x/$($m.Value)\" $msi $rotulo\n  $rotulo.Text = 'Instalando o Node.js... confirme a janela de permissão do Windows, se aparecer.'\n  $p = Start-Process -FilePath 'msiexec.exe' -ArgumentList @('/i', \"`\"$msi`\"\", '/passive', '/norestart') -PassThru\n  while (-not $p.HasExited) { [System.Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 200 }\n  AtualizarPath\n  return (NodeServe (NodeVersao))\n}\n\n# ---------------- arquivos do bot ----------------\nfunction EhBot([string]$pasta) {\n  return (Test-Path -LiteralPath (Join-Path $pasta 'index.js')) -and\n         (Test-Path -LiteralPath (Join-Path $pasta 'config.json')) -and\n         (Test-Path -LiteralPath (Join-Path $pasta 'src\\core\\nucleo.js'))\n}\nfunction LerEnv([string]$pasta) {\n  $h = @{}\n  $arq = Join-Path $pasta '.env'\n  if (Test-Path -LiteralPath $arq) {\n    foreach ($l in [System.IO.File]::ReadAllLines($arq)) {\n      $m = [regex]::Match($l, '^\\s*([A-Z_]+)\\s*=\\s*(.*)$')\n      if ($m.Success) { $h[$m.Groups[1].Value] = $m.Groups[2].Value.Trim().Trim('\"') }\n    }\n  }\n  return $h\n}\n# Grava chaves no .env sem apagar as outras linhas\nfunction SalvarEnv([string]$pasta, [hashtable]$novos) {\n  $arq = Join-Path $pasta '.env'\n  $linhas = New-Object System.Collections.Generic.List[string]\n  $feitos = @{}\n  if (Test-Path -LiteralPath $arq) {\n    foreach ($l in [System.IO.File]::ReadAllLines($arq)) {\n      $m = [regex]::Match($l, '^\\s*([A-Z_]+)\\s*=')\n      if ($m.Success -and $novos.ContainsKey($m.Groups[1].Value)) {\n        $k = $m.Groups[1].Value\n        if (-not $feitos[$k]) { $linhas.Add(\"$k=$($novos[$k])\"); $feitos[$k] = $true }\n      } else { $linhas.Add($l) }\n    }\n  }\n  foreach ($k in $novos.Keys) { if (-not $feitos[$k]) { $linhas.Add(\"$k=$($novos[$k])\") } }\n  [System.IO.File]::WriteAllLines($arq, [string[]]$linhas, $utf8)\n}\nfunction DepsOk([string]$pasta) { return (Test-Path -LiteralPath (Join-Path $pasta 'node_modules\\discord.js\\package.json')) }\n\n# Intents privilegiadas que os módulos deste bot usam (lidas do próprio código)\nfunction IntentsNecessarios([string]$pasta) {\n  $precisa = New-Object System.Collections.Generic.List[string]\n  try { $mods = @((Get-Content -LiteralPath (Join-Path $pasta 'config.json') -Raw -Encoding UTF8 | ConvertFrom-Json).modulos) } catch { $mods = @() }\n  $textos = @()\n  foreach ($id in $mods) {\n    $arq = Join-Path $pasta \"src\\modules\\$id.js\"\n    if (Test-Path -LiteralPath $arq) { $textos += [System.IO.File]::ReadAllText($arq) }\n  }\n  $tudo = $textos -join \"`n\"\n  if ($tudo.Contains('GatewayIntentBits.GuildMembers')) { $precisa.Add('members') }\n  if ($tudo.Contains('GatewayIntentBits.MessageContent')) { $precisa.Add('content') }\n  if ($tudo.Contains('GatewayIntentBits.GuildPresences')) { $precisa.Add('presence') }\n  return $precisa\n}\n\n# ---------------- Discord ----------------\nfunction Api([string]$token, [string]$rota) {\n  $h = @{ Authorization = \"Bot $token\"; 'User-Agent' = 'DiscordBot (https://byteup, 1.0) Inicializador' }\n  return Invoke-RestMethod -Uri \"https://discord.com/api/v10$rota\" -Headers $h -Method Get -TimeoutSec 20\n}\nfunction CodigoErro($erro) {\n  try { return [int]$erro.Exception.Response.StatusCode } catch { return 0 }\n}\n# Confere o token: devolve @{ ok; nome; appId; flags; erro }\nfunction ConferirToken([string]$token) {\n  try {\n    $eu = Api $token '/users/@me'\n    $app = Api $token '/applications/@me'\n    return @{ ok = $true; nome = $eu.username; appId = [string]$app.id; flags = [int64]$app.flags; erro = $null }\n  } catch {\n    $c = CodigoErro $_\n    if ($c -eq 401) { return @{ ok = $false; erro = 'Token errado. Gere outro no Developer Portal (Bot → Reset Token) e cole aqui.' } }\n    return @{ ok = $false; erro = \"Não consegui falar com o Discord (sem internet?). $($_.Exception.Message)\" }\n  }\n}\nfunction IntentLigado([int64]$flags, [string]$nome) {\n  switch ($nome) {\n    'presence' { return (($flags -band (1 -shl 12)) -ne 0) -or (($flags -band (1 -shl 13)) -ne 0) }\n    'members' { return (($flags -band (1 -shl 14)) -ne 0) -or (($flags -band (1 -shl 15)) -ne 0) }\n    'content' { return (($flags -band (1 -shl 18)) -ne 0) -or (($flags -band (1 -shl 19)) -ne 0) }\n  }\n  return $true\n}\nfunction ServidoresDoBot([string]$token) {\n  try { return @((Api $token '/users/@me/guilds') | ForEach-Object { [string]$_.id }) } catch { return $null }\n}\n\n# ---------------- ligar / parar ----------------\nfunction ArqEstado([string]$pasta) { return (Join-Path $pasta '.inicializador.json') }\nfunction ProcessoDoBot([string]$pasta) {\n  $arq = ArqEstado $pasta\n  if (-not (Test-Path -LiteralPath $arq)) { return $null }\n  try {\n    $e = Get-Content -LiteralPath $arq -Raw -Encoding UTF8 | ConvertFrom-Json\n    $p = Get-Process -Id ([int]$e.pid) -ErrorAction SilentlyContinue\n    if (-not $p -or @('cmd', 'node') -notcontains $p.ProcessName) { return $null }\n    # o Windows reaproveita números de processo: confere a hora em que começou\n    if ([math]::Abs(($p.StartTime - [datetime]$e.inicio).TotalSeconds) -gt 10) { return $null }\n    return $p\n  } catch { return $null }\n}\nfunction InstalarDeps([string]$pasta, $rotulo) {\n  $logs = Join-Path $pasta 'logs'\n  if (-not (Test-Path -LiteralPath $logs)) { New-Item -ItemType Directory -Path $logs | Out-Null }\n  $log = Join-Path $logs 'instalacao.log'\n  $rotulo.Text = 'Instalando o que o bot precisa (discord.js)... na primeira vez leva 1 ou 2 minutos.'\n  $p = Start-Process -FilePath 'cmd.exe' -ArgumentList @('/c', \"npm install --no-audit --no-fund > `\"$log`\" 2>&1\") -WorkingDirectory $pasta -WindowStyle Hidden -PassThru\n  while (-not $p.HasExited) { [System.Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 200 }\n  if ($p.ExitCode -ne 0 -or -not (DepsOk $pasta)) {\n    $fim = ''\n    try { $fim = ((Get-Content -LiteralPath $log -Encoding UTF8 -Tail 12) -join \"`n\") } catch {}\n    throw \"a instalação falhou (sem internet?).`n`n$fim\"\n  }\n}\n# Liga o bot sem janela. Devolve o processo.\nfunction LigarBot([string]$pasta) {\n  $exe = NodeExe\n  if (-not $exe) { throw 'o Node.js não está instalado.' }\n  $logs = Join-Path $pasta 'logs'\n  if (-not (Test-Path -LiteralPath $logs)) { New-Item -ItemType Directory -Path $logs | Out-Null }\n  $saida = Join-Path $logs 'bot.log'\n  $erros = Join-Path $logs 'erros.log'\n  foreach ($a in @($saida, $erros)) {\n    if (Test-Path -LiteralPath $a) { Move-Item -LiteralPath $a -Destination ($a -replace '\\.log$', '-anterior.log') -Force }\n  }\n  Remove-Item -LiteralPath (Join-Path $pasta '.parar') -Force -ErrorAction SilentlyContinue\n  # roda num console próprio e invisível: fechar outras janelas não derruba o bot\n  $psi = New-Object System.Diagnostics.ProcessStartInfo\n  $psi.FileName = \"$env:SystemRoot\\System32\\cmd.exe\"\n  $psi.Arguments = \"/d /c `\"`\"$exe`\" index.js > `\"$saida`\" 2> `\"$erros`\"`\"\"\n  $psi.WorkingDirectory = $pasta\n  $psi.UseShellExecute = $false\n  $psi.CreateNoWindow = $true\n  $p = [System.Diagnostics.Process]::Start($psi)\n  $estado = @{ pid = $p.Id; inicio = $p.StartTime.ToString('o') } | ConvertTo-Json\n  [System.IO.File]::WriteAllText((ArqEstado $pasta), $estado, $utf8)\n  return $p\n}\nfunction LerLog([string]$arq) {\n  if (-not (Test-Path -LiteralPath $arq)) { return '' }\n  try {\n    $fs = [System.IO.File]::Open($arq, 'Open', 'Read', 'ReadWrite')\n    $sr = New-Object System.IO.StreamReader($fs, [System.Text.Encoding]::UTF8)\n    $t = $sr.ReadToEnd(); $sr.Close(); return $t\n  } catch { return '' }\n}\n# Espera o bot dizer que está online (ou falhar). Devolve @{ ok; servidores; convite; erro }\nfunction AguardarOnline([string]$pasta, $proc, $rotulo) {\n  $saida = Join-Path $pasta 'logs\\bot.log'\n  $erros = Join-Path $pasta 'logs\\erros.log'\n  $limite = (Get-Date).AddSeconds(90)\n  while ((Get-Date) -lt $limite) {\n    $txt = LerLog $saida\n    if ($txt -match 'online como') {\n      Esperar 1500 # o link de convite vem logo depois\n      $txt = LerLog $saida\n      $serv = 0\n      $m = [regex]::Match($txt, 'em (\\d+) servidor')\n      if ($m.Success) { $serv = [int]$m.Groups[1].Value }\n      $conv = [regex]::Match($txt, 'https://discord\\.com/\\S*oauth2\\S+').Value\n      return @{ ok = $true; servidores = $serv; convite = $conv; erro = $null }\n    }\n    if ($proc.HasExited) {\n      Esperar 300\n      $err = (LerLog $erros).Trim()\n      if (-not $err) { $err = (LerLog $saida).Trim() }\n      return @{ ok = $false; erro = $err }\n    }\n    if ($rotulo) { $rotulo.Text = 'Ligando o bot e conectando ao Discord...' }\n    Esperar 400\n  }\n  return @{ ok = $false; erro = 'O bot demorou demais para conectar. Veja o registro.' }\n}\nfunction PararBot([string]$pasta) {\n  $p = ProcessoDoBot $pasta\n  if (-not $p) { return }\n  # pede para o bot salvar e desligar sozinho; se não der em 15 s, fecha à força\n  [System.IO.File]::WriteAllText((Join-Path $pasta '.parar'), 'parar', $utf8)\n  $fim = (Get-Date).AddSeconds(15)\n  while (-not $p.HasExited -and (Get-Date) -lt $fim) { [System.Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 200; $p.Refresh() }\n  if (-not $p.HasExited) {\n    # fecha o console invisível e o node junto\n    Start-Process -FilePath \"$env:SystemRoot\\System32\\taskkill.exe\" -ArgumentList @('/PID', $p.Id, '/T', '/F') -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue\n  }\n  Remove-Item -LiteralPath (Join-Path $pasta '.parar') -Force -ErrorAction SilentlyContinue\n}\n\n# ---------------- ligar junto com o Windows ----------------\nfunction AtalhoInicio($bot) {\n  $nome = ($bot.Nome -replace '[^\\p{L}\\p{N} _-]', '').Trim()\n  if (-not $nome) { $nome = 'Bot' }\n  return (Join-Path ([Environment]::GetFolderPath('Startup')) \"Ligar bot $nome.lnk\")\n}\nfunction AlternarInicio($bot) {\n  $lnk = AtalhoInicio $bot\n  if (Test-Path -LiteralPath $lnk) {\n    Remove-Item -LiteralPath $lnk -Force\n    Aviso \"Pronto: o bot $($bot.Nome) não liga mais sozinho com o Windows.\"\n    return\n  }\n  $sh = New-Object -ComObject WScript.Shell\n  $a = $sh.CreateShortcut($lnk)\n  $a.TargetPath = \"$env:SystemRoot\\System32\\WindowsPowerShell\\v1.0\\powershell.exe\"\n  $a.Arguments = \"-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `\"$PSCommandPath`\" -Ligar `\"$($bot.Pasta)`\"\"\n  $a.WorkingDirectory = $bot.Pasta\n  $a.WindowStyle = 7\n  $a.Description = \"Liga o bot $($bot.Nome)\"\n  $a.Save()\n  Aviso \"Pronto: o bot $($bot.Nome) vai ligar sozinho sempre que o computador ligar (sem abrir janela).`n`nPara desfazer, clique de novo em \"\"Ligar com o Windows\"\".\"\n}\n\n# Tira a marca \"baixado da internet\" dos scripts (o Windows bloqueia .bat/.ps1 com essa marca).\n# Assim o Transferidor e os outros scripts da pasta do bot funcionam sem aviso.\nfunction Desbloquear([string]$pasta) {\n  try {\n    Get-ChildItem -LiteralPath $pasta -File -ErrorAction SilentlyContinue |\n      Where-Object { @('.bat', '.cmd', '.ps1', '.js', '.json', '.html') -contains $_.Extension.ToLowerInvariant() } |\n      Unblock-File -ErrorAction SilentlyContinue\n  } catch {}\n}\nDesbloquear $PSScriptRoot\n\n# Modo sem janela (atalho do Windows): só liga o bot, se estiver configurado\nif ($Ligar) {\n  if ((EhBot $Ligar) -and (DepsOk $Ligar) -and (LerEnv $Ligar)['DISCORD_TOKEN'] -and -not (ProcessoDoBot $Ligar)) {\n    AtualizarPath\n    [void](LigarBot $Ligar)\n  }\n  exit 0\n}\n\n# ---------------- procurar no PC ----------------\nfunction InfoBot([string]$pasta) {\n  $nome = '(sem nome)'\n  try { $nome = (Get-Content -LiteralPath (Join-Path $pasta 'config.json') -Raw -Encoding UTF8 | ConvertFrom-Json).nome } catch {}\n  $versao = (Get-Item -LiteralPath (Join-Path $pasta 'index.js')).LastWriteTime\n  $dados = @(Get-ChildItem -LiteralPath (Join-Path $pasta 'data') -Filter '*.json' -File -ErrorAction SilentlyContinue)\n  $atividade = $null\n  if ($dados.Count -gt 0) { $atividade = ($dados | Sort-Object LastWriteTime -Descending | Select-Object -First 1).LastWriteTime }\n  return [pscustomobject]@{ Nome = $nome; Pasta = $pasta; Versao = $versao; Atividade = $atividade; Dados = $dados.Count; Situacao = '' }\n}\nfunction Configurado($bot) {\n  return ((LerEnv $bot.Pasta)['DISCORD_TOKEN']) -and (DepsOk $bot.Pasta) -and (NodeServe (NodeVersao))\n}\nfunction EstadoTexto($bot) {\n  if (ProcessoDoBot $bot.Pasta) { return 'Ligado' }\n  if (-not ((LerEnv $bot.Pasta)['DISCORD_TOKEN']) -or -not (DepsOk $bot.Pasta)) { return 'Configurar' }\n  return 'Desligado'\n}\n\nfunction Procurar($rotulo) {\n  $achados = New-Object System.Collections.Generic.List[string]\n  $fila = New-Object System.Collections.Generic.Queue[object]\n  $fila.Enqueue(@($env:USERPROFILE, 7))\n  foreach ($d in [System.IO.DriveInfo]::GetDrives()) {\n    if ($d.DriveType -eq 'Fixed' -and $d.IsReady) { $fila.Enqueue(@($d.RootDirectory.FullName, 5)) }\n  }\n  $vistas = @{}\n  $n = 0\n  while ($fila.Count -gt 0) {\n    $item = $fila.Dequeue()\n    $pasta = [string]$item[0]\n    $fundo = [int]$item[1]\n    $chave = $pasta.ToLowerInvariant().TrimEnd('\\')\n    if ($vistas.ContainsKey($chave)) { continue }\n    $vistas[$chave] = $true\n    $n++\n    if ($n % 200 -eq 0) {\n      $rotulo.Text = \"Procurando... $pasta\"\n      [System.Windows.Forms.Application]::DoEvents()\n    }\n    if (EhBot $pasta) { $achados.Add($pasta); continue }\n    if ($fundo -le 0) { continue }\n    try {\n      foreach ($sub in [System.IO.Directory]::EnumerateDirectories($pasta)) {\n        $nomeSub = [System.IO.Path]::GetFileName($sub).ToLowerInvariant()\n        if ($PULAR -contains $nomeSub -or $nomeSub.StartsWith('data-backup')) { continue }\n        $attr = [System.IO.File]::GetAttributes($sub)\n        if ($attr -band [System.IO.FileAttributes]::ReparsePoint) { continue }\n        $fila.Enqueue(@($sub, ($fundo - 1)))\n      }\n    } catch {}\n  }\n  return $achados\n}\nfunction SalvarCache($pastas) {\n  if (-not (Test-Path -LiteralPath $pastaCache)) { New-Item -ItemType Directory -Path $pastaCache | Out-Null }\n  ConvertTo-Json -InputObject @($pastas) | Set-Content -LiteralPath $arquivoCache -Encoding UTF8\n}\nfunction LerCache {\n  if (-not (Test-Path -LiteralPath $arquivoCache)) { return @() }\n  try { return @((Get-Content -LiteralPath $arquivoCache -Raw -Encoding UTF8 | ConvertFrom-Json) | Where-Object { $_ -and (EhBot $_) }) } catch { return @() }\n}\nfunction MarcarSituacao($bots) {\n  foreach ($grupo in ($bots | Group-Object Nome)) {\n    if ($grupo.Count -lt 2) { continue }\n    $ordem = @($grupo.Group | Sort-Object Versao -Descending)\n    $ordem[0].Situacao = 'mais novo'\n    for ($k = 1; $k -lt $ordem.Count; $k++) { $ordem[$k].Situacao = 'mais antigo' }\n    if ($ordem.Count -gt 2) { for ($k = 1; $k -lt $ordem.Count - 1; $k++) { $ordem[$k].Situacao = 'antigo' } }\n  }\n}\n\n# ---------------- assistente de configuração ----------------\nfunction NovoGrupo($form, [string]$texto, [int]$y, [int]$altura) {\n  $g = New-Object System.Windows.Forms.GroupBox\n  $g.Text = $texto\n  $g.Location = New-Object System.Drawing.Point(12, $y)\n  $g.Size = New-Object System.Drawing.Size(640, $altura)\n  $form.Controls.Add($g)\n  return $g\n}\nfunction NovoRotulo($pai, [string]$texto, [int]$x, [int]$y, [int]$l, [int]$a) {\n  $r = New-Object System.Windows.Forms.Label\n  $r.Text = $texto\n  $r.Location = New-Object System.Drawing.Point($x, $y)\n  $r.Size = New-Object System.Drawing.Size($l, $a)\n  $pai.Controls.Add($r)\n  return $r\n}\nfunction NovoBotaoEm($pai, [string]$texto, [int]$x, [int]$y, [int]$l) {\n  $b = New-Object System.Windows.Forms.Button\n  $b.Text = $texto\n  $b.Location = New-Object System.Drawing.Point($x, $y)\n  $b.Size = New-Object System.Drawing.Size($l, 30)\n  $pai.Controls.Add($b)\n  return $b\n}\n$VERDE = [System.Drawing.Color]::FromArgb(0, 128, 60)\n$VERMELHO = [System.Drawing.Color]::FromArgb(190, 30, 30)\n\n# Abre o assistente. Devolve $true se o bot ficou pronto para ligar.\nfunction Assistente($bot) {\n  $script:wz = @{ bot = $bot; nodeOk = $false; tokenOk = $false; intentsOk = $false; info = $null; precisa = (IntentsNecessarios $bot.Pasta) }\n  $env0 = LerEnv $bot.Pasta\n\n  $f = New-Object System.Windows.Forms.Form\n  $f.Text = \"Configurar o bot $($bot.Nome)\"\n  $f.Size = New-Object System.Drawing.Size(680, 690)\n  $f.StartPosition = 'CenterScreen'\n  $f.FormBorderStyle = 'FixedDialog'\n  $f.MaximizeBox = $false\n  $f.Font = New-Object System.Drawing.Font('Segoe UI', 9.5)\n  $script:wz.form = $f\n  [void](NovoRotulo $f \"Vamos deixar o bot pronto. Siga os passos de cima para baixo; cada um fica verde quando estiver certo.\" 14 10 640 36)\n\n  # 1. Node.js\n  $g1 = NovoGrupo $f '1. Node.js (o programa que roda o bot)' 48 70\n  $script:wz.st1 = NovoRotulo $g1 '' 12 26 430 34\n  $script:wz.bt1 = NovoBotaoEm $g1 'Instalar o Node.js' 460 22 166\n\n  # 2. Token\n  $g2 = NovoGrupo $f '2. Token do bot' 124 150\n  [void](NovoRotulo $g2 'No Developer Portal: abra a sua aplicação → Bot → Reset Token → Copy. Cole aqui:' 12 22 610 20)\n  $script:wz.link2 = New-Object System.Windows.Forms.LinkLabel\n  $script:wz.link2.Text = 'Abrir o Developer Portal'\n  $script:wz.link2.Location = New-Object System.Drawing.Point(12, 44)\n  $script:wz.link2.Size = New-Object System.Drawing.Size(300, 20)\n  $g2.Controls.Add($script:wz.link2)\n  $script:wz.tk = New-Object System.Windows.Forms.TextBox\n  $script:wz.tk.Location = New-Object System.Drawing.Point(12, 70)\n  $script:wz.tk.Size = New-Object System.Drawing.Size(440, 26)\n  $script:wz.tk.UseSystemPasswordChar = $true\n  if ($env0['DISCORD_TOKEN']) { $script:wz.tk.Text = $env0['DISCORD_TOKEN'] }\n  $g2.Controls.Add($script:wz.tk)\n  $script:wz.ver = New-Object System.Windows.Forms.CheckBox\n  $script:wz.ver.Text = 'Mostrar'\n  $script:wz.ver.Location = New-Object System.Drawing.Point(462, 71)\n  $script:wz.ver.Size = New-Object System.Drawing.Size(80, 24)\n  $g2.Controls.Add($script:wz.ver)\n  $script:wz.bt2 = NovoBotaoEm $g2 'Conferir' 546 68 80\n  $script:wz.st2 = NovoRotulo $g2 '' 12 104 610 40\n\n  # 3. Intents\n  $g3 = NovoGrupo $f '3. Permissões especiais (Privileged Gateway Intents)' 282 140\n  $script:wz.st3 = NovoRotulo $g3 'Confira o token primeiro.' 12 24 610 72\n  $script:wz.link3 = New-Object System.Windows.Forms.LinkLabel\n  $script:wz.link3.Text = 'Abrir a página do bot no Developer Portal para ligar'\n  $script:wz.link3.Location = New-Object System.Drawing.Point(12, 104)\n  $script:wz.link3.Size = New-Object System.Drawing.Size(420, 22)\n  $script:wz.link3.Enabled = $false\n  $g3.Controls.Add($script:wz.link3)\n  $script:wz.bt3 = NovoBotaoEm $g3 'Conferir de novo' 476 100 150\n  $script:wz.bt3.Enabled = $false\n\n  # 4. Servidor\n  $g4 = NovoGrupo $f '4. ID do seu servidor (opcional, mas recomendado)' 430 126\n  [void](NovoRotulo $g4 \"Com ele, os comandos aparecem na hora no seu servidor. No Discord: Configurações → Avançado → ligue o Modo desenvolvedor. Depois clique com o botão direito no servidor → Copiar ID do servidor.\" 12 22 610 56)\n  $script:wz.gid = New-Object System.Windows.Forms.TextBox\n  $script:wz.gid.Location = New-Object System.Drawing.Point(12, 84)\n  $script:wz.gid.Size = New-Object System.Drawing.Size(240, 26)\n  if ($env0['GUILD_ID']) { $script:wz.gid.Text = $env0['GUILD_ID'] }\n  $g4.Controls.Add($script:wz.gid)\n  $script:wz.st4 = NovoRotulo $g4 '' 262 87 360 22\n\n  # final\n  $script:wz.barra = New-Object System.Windows.Forms.ProgressBar\n  $script:wz.barra.Location = New-Object System.Drawing.Point(12, 566)\n  $script:wz.barra.Size = New-Object System.Drawing.Size(640, 14)\n  $script:wz.barra.Style = 'Marquee'\n  $script:wz.barra.Visible = $false\n  $f.Controls.Add($script:wz.barra)\n  $script:wz.stF = NovoRotulo $f '' 14 584 640 22\n  $script:wz.btOk = NovoBotaoEm $f 'Instalar e ligar o bot' 392 608 160\n  $script:wz.btOk.Enabled = $false\n  $script:wz.btCancel = NovoBotaoEm $f 'Cancelar' 560 608 92\n  $script:wz.pronto = $false\n\n  $script:wz.atualizar = {\n    $w = $script:wz\n    # 1\n    $v = NodeVersao\n    $w.nodeOk = NodeServe $v\n    if ($w.nodeOk) { $w.st1.Text = \"✔ Node.js $v instalado.\"; $w.st1.ForeColor = $VERDE; $w.bt1.Visible = $false }\n    elseif ($v) { $w.st1.Text = \"✖ Node.js $v é antigo demais. Clique para instalar o atual.\"; $w.st1.ForeColor = $VERMELHO; $w.bt1.Visible = $true }\n    else { $w.st1.Text = '✖ Node.js não está instalado. Clique no botão: ele baixa e instala sozinho.'; $w.st1.ForeColor = $VERMELHO; $w.bt1.Visible = $true }\n    # 3\n    if ($w.tokenOk) {\n      $linhas = @()\n      $falta = 0\n      foreach ($i in $w.precisa) {\n        if (IntentLigado $w.info.flags $i) { $linhas += \"✔ $($NOMES_INTENT[$i])\" } else { $linhas += \"✖ $($NOMES_INTENT[$i]) (desligada)\"; $falta++ }\n      }\n      if (-not $w.precisa.Count) { $w.st3.Text = '✔ Este bot não precisa de nenhuma permissão especial.'; $w.st3.ForeColor = $VERDE; $w.intentsOk = $true }\n      elseif ($falta) { $w.st3.Text = ($linhas -join \"`n\") + \"`nLigue as que estão com ✖ (na página Bot, desça até Privileged Gateway Intents, ligue e clique em Save Changes). Depois clique em Conferir de novo.\"; $w.st3.ForeColor = $VERMELHO; $w.intentsOk = $false }\n      else { $w.st3.Text = ($linhas -join \"`n\"); $w.st3.ForeColor = $VERDE; $w.intentsOk = $true }\n      $w.link3.Enabled = $true; $w.bt3.Enabled = $true\n    }\n    # 4\n    $g = $w.gid.Text.Trim()\n    if (-not $g) { $w.st4.Text = 'Pode deixar vazio.'; $w.st4.ForeColor = [System.Drawing.Color]::Gray }\n    elseif ($g -match '^\\d{17,20}$') { $w.st4.Text = '✔ ID válido.'; $w.st4.ForeColor = $VERDE }\n    else { $w.st4.Text = '✖ O ID tem só números (17 a 20).'; $w.st4.ForeColor = $VERMELHO }\n    $gidOk = (-not $g) -or ($g -match '^\\d{17,20}$')\n    $w.btOk.Enabled = $w.nodeOk -and $w.tokenOk -and $w.intentsOk -and $gidOk\n  }\n  $script:wz.conferirToken = {\n    $w = $script:wz\n    $t = $w.tk.Text.Trim()\n    $w.tokenOk = $false\n    if (-not $t) { $w.st2.Text = 'Cole o token do bot.'; $w.st2.ForeColor = $VERMELHO; & $w.atualizar; return }\n    $w.st2.Text = 'Conferindo com o Discord...'; $w.st2.ForeColor = [System.Drawing.Color]::Gray\n    $w.form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor; [System.Windows.Forms.Application]::DoEvents()\n    $r = ConferirToken $t\n    $w.form.Cursor = [System.Windows.Forms.Cursors]::Default\n    if ($r.ok) {\n      $w.info = $r; $w.tokenOk = $true\n      $w.st2.Text = \"✔ Token certo: bot $($r.nome).\"; $w.st2.ForeColor = $VERDE\n    } else { $w.st2.Text = \"✖ $($r.erro)\"; $w.st2.ForeColor = $VERMELHO }\n    & $w.atualizar\n  }\n\n  $script:wz.bt1.Add_Click({\n    $w = $script:wz\n    $w.bt1.Enabled = $false; $w.barra.Visible = $true\n    try {\n      $ok = InstalarNode $w.stF\n      if ($ok) { $w.stF.Text = 'Node.js instalado.' } else { $w.stF.Text = 'Não deu para confirmar a instalação. Se instalou, feche e abra o Inicializador de novo.' }\n    } catch {\n      $w.stF.Text = ''\n      if (Pergunta \"Não consegui instalar o Node.js sozinho ($($_.Exception.Message)).`n`nAbrir o site para instalar você mesmo? Escolha a versão LTS e clique em Avançar até o fim.\") { Start-Process 'https://nodejs.org/pt' }\n    }\n    $w.barra.Visible = $false; $w.bt1.Enabled = $true\n    & $w.atualizar\n  })\n  $script:wz.link2.Add_LinkClicked({ Start-Process 'https://discord.com/developers/applications' })\n  $script:wz.ver.Add_CheckedChanged({ $script:wz.tk.UseSystemPasswordChar = -not $script:wz.ver.Checked })\n  $script:wz.bt2.Add_Click({ & $script:wz.conferirToken })\n  $script:wz.tk.Add_TextChanged({ $script:wz.tokenOk = $false; $script:wz.intentsOk = $false; $script:wz.st2.Text = ''; & $script:wz.atualizar })\n  $script:wz.link3.Add_LinkClicked({ if ($script:wz.info) { Start-Process \"https://discord.com/developers/applications/$($script:wz.info.appId)/bot\" } })\n  $script:wz.bt3.Add_Click({ & $script:wz.conferirToken })\n  $script:wz.gid.Add_TextChanged({ & $script:wz.atualizar })\n  $script:wz.btCancel.Add_Click({ $script:wz.form.Close() })\n  $script:wz.btOk.Add_Click({\n    $w = $script:wz\n    $w.btOk.Enabled = $false; $w.btCancel.Enabled = $false; $w.barra.Visible = $true\n    try {\n      $novos = @{ DISCORD_TOKEN = $w.tk.Text.Trim() }\n      $novos['GUILD_ID'] = $w.gid.Text.Trim()\n      SalvarEnv $w.bot.Pasta $novos\n      if (-not (DepsOk $w.bot.Pasta)) { InstalarDeps $w.bot.Pasta $w.stF }\n      $w.pronto = $true\n      $w.form.Close()\n    } catch {\n      $w.barra.Visible = $false; $w.btCancel.Enabled = $true\n      $w.stF.Text = ''\n      Aviso \"Não consegui terminar: $($_.Exception.Message)\" 'Error'\n      & $w.atualizar\n    }\n  })\n  $f.Add_Shown({\n    & $script:wz.atualizar\n    if ($script:wz.tk.Text.Trim()) { & $script:wz.conferirToken }\n  })\n  [void]$f.ShowDialog()\n  return $script:wz.pronto\n}\n\n# ---------------- ligar com aviso do resultado ----------------\nfunction IniciarComResultado($bot, $rotulo) {\n  if (ProcessoDoBot $bot.Pasta) { Aviso \"O bot $($bot.Nome) já está ligado.\"; return }\n  if (-not (Configurado $bot)) {\n    if (-not (Assistente $bot)) { return }\n  }\n  $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor\n  $proc = LigarBot $bot.Pasta\n  $r = AguardarOnline $bot.Pasta $proc $rotulo\n  $form.Cursor = [System.Windows.Forms.Cursors]::Default\n  $rotulo.Text = 'Escolha o bot e use os botões abaixo.'\n  if ($r.ok) {\n    $env1 = LerEnv $bot.Pasta\n    $gid = $env1['GUILD_ID']\n    $faltaServidor = $r.servidores -eq 0\n    if ($gid -and -not $faltaServidor) {\n      $lista = ServidoresDoBot $env1['DISCORD_TOKEN']\n      if ($lista -ne $null -and -not ($lista -contains $gid)) { $faltaServidor = $true }\n    }\n    if ($faltaServidor -and $r.convite) {\n      if (Pergunta \"✔ O bot $($bot.Nome) está ligado!`n`nFalta só adicionar o bot ao seu servidor. Abrir o link de convite agora?`n`n(Escolha o servidor, clique em Autorizar e pronto. O bot continua ligado; pode fechar o Inicializador.)\" 'Information') {\n        Start-Process $r.convite\n      }\n    } else {\n      Aviso \"✔ O bot $($bot.Nome) está ligado e em $($r.servidores) servidor(es).`n`nPode fechar o Inicializador: o bot continua ligado. Para desligar, abra o Inicializador e clique em Parar.\"\n    }\n    return\n  }\n  $e = [string]$r.erro\n  if ($e -match 'token est[aá] errado|TokenInvalid|invalid token') {\n    if (Pergunta \"O Discord recusou o token do bot.`n`nAbrir a configuração para colar o token novo?\" 'Warning') { if (Assistente $bot) { IniciarComResultado $bot $rotulo } }\n  } elseif ($e -match 'disallowed intents|Privileged Gateway') {\n    if (Pergunta \"Faltam permissões especiais (intents) no Developer Portal.`n`nAbrir a configuração para conferir?\" 'Warning') { if (Assistente $bot) { IniciarComResultado $bot $rotulo } }\n  } else {\n    if ($e.Length -gt 1500) { $e = $e.Substring($e.Length - 1500) }\n    Aviso \"O bot não ligou.`n`n$e`n`nSe não entender, use \"\"Ver registro\"\" e mande o print para o suporte.\" 'Error'\n  }\n}\n\n# ---------------- registro ----------------\nfunction VerRegistro($bot) {\n  $f = New-Object System.Windows.Forms.Form\n  $f.Text = \"Registro do bot $($bot.Nome)\"\n  $f.Size = New-Object System.Drawing.Size(860, 560)\n  $f.StartPosition = 'CenterScreen'\n  $t = New-Object System.Windows.Forms.TextBox\n  $t.Multiline = $true; $t.ReadOnly = $true; $t.ScrollBars = 'Both'; $t.WordWrap = $false\n  $t.Font = New-Object System.Drawing.Font('Consolas', 9.5)\n  $t.Location = New-Object System.Drawing.Point(10, 10)\n  $t.Size = New-Object System.Drawing.Size(824, 460)\n  $t.Anchor = 'Top, Bottom, Left, Right'\n  $f.Controls.Add($t)\n  $script:regBot = $bot; $script:regTxt = $t\n  $carregar = {\n    $p = $script:regBot.Pasta\n    $s = LerLog (Join-Path $p 'logs\\bot.log')\n    $e = LerLog (Join-Path $p 'logs\\erros.log')\n    $txt = $s\n    if ($e.Trim()) { $txt += \"`r`n----- ERROS -----`r`n$e\" }\n    if (-not $txt.Trim()) { $txt = 'Ainda não há registro: ligue o bot pelo Inicializador.' }\n    $script:regTxt.Text = ($txt -replace \"(?<!`r)`n\", \"`r`n\")\n    $script:regTxt.SelectionStart = $script:regTxt.Text.Length\n    $script:regTxt.ScrollToCaret()\n  }\n  $b = NovoBotaoEm $f 'Atualizar' 10 480 110\n  $b.Anchor = 'Bottom, Left'\n  $b.Add_Click($carregar)\n  $f.Add_Shown($carregar)\n  [void]$f.ShowDialog()\n}\n\n# ---------------- janela principal ----------------\n$form = New-Object System.Windows.Forms.Form\n$form.Text = $titulo\n$form.Size = New-Object System.Drawing.Size(940, 500)\n$form.StartPosition = 'CenterScreen'\n$form.Font = New-Object System.Drawing.Font('Segoe UI', 9.5)\n\n$rotulo = New-Object System.Windows.Forms.Label\n$rotulo.Location = New-Object System.Drawing.Point(12, 10)\n$rotulo.Size = New-Object System.Drawing.Size(900, 36)\n$rotulo.Text = 'Escolha o bot e use os botões abaixo.'\n$form.Controls.Add($rotulo)\n\n$lista = New-Object System.Windows.Forms.ListView\n$lista.Location = New-Object System.Drawing.Point(12, 50)\n$lista.Size = New-Object System.Drawing.Size(900, 340)\n$lista.View = 'Details'\n$lista.FullRowSelect = $true\n$lista.MultiSelect = $false\n$lista.HideSelection = $false\n[void]$lista.Columns.Add('Bot', 150)\n[void]$lista.Columns.Add('Estado', 85)\n[void]$lista.Columns.Add('Situação', 85)\n[void]$lista.Columns.Add('Versão de', 115)\n[void]$lista.Columns.Add('Última atividade', 115)\n[void]$lista.Columns.Add('Pasta', 330)\n$form.Controls.Add($lista)\n\nfunction NovoBotao([string]$texto, [int]$x, [int]$largura) {\n  $b = New-Object System.Windows.Forms.Button\n  $b.Text = $texto\n  $b.Location = New-Object System.Drawing.Point($x, 402)\n  $b.Size = New-Object System.Drawing.Size($largura, 34)\n  $form.Controls.Add($b)\n  return $b\n}\n$btIniciar = NovoBotao 'Ligar' 12 90\n$btParar = NovoBotao 'Parar' 106 80\n$btConfig = NovoBotao 'Configurar' 190 100\n$btRegistro = NovoBotao 'Ver registro' 294 105\n$btWindows = NovoBotao 'Ligar com o Windows' 403 150\n$btAbrir = NovoBotao 'Abrir pasta' 557 100\n$btApagar = NovoBotao 'Apagar (Lixeira)' 661 125\n$btProcurar = NovoBotao 'Procurar de novo' 790 122\n$form.AcceptButton = $btIniciar\n\n$script:bots = @()\n\nfunction Preencher {\n  $lista.Items.Clear()\n  foreach ($b in $script:bots) {\n    $it = New-Object System.Windows.Forms.ListViewItem($b.Nome)\n    [void]$it.SubItems.Add((EstadoTexto $b))\n    [void]$it.SubItems.Add($b.Situacao)\n    [void]$it.SubItems.Add($b.Versao.ToString($fmt))\n    if ($b.Atividade) { [void]$it.SubItems.Add($b.Atividade.ToString($fmt)) } else { [void]$it.SubItems.Add('sem dados') }\n    [void]$it.SubItems.Add($b.Pasta)\n    if ($b.Situacao -like '*antigo') { $it.ForeColor = [System.Drawing.Color]::Gray }\n    $it.Tag = $b\n    [void]$lista.Items.Add($it)\n  }\n  if ($lista.Items.Count -gt 0) {\n    $escolher = 0\n    for ($k = 0; $k -lt $script:bots.Count; $k++) { if ($script:bots[$k].Situacao -eq 'mais novo') { $escolher = $k; break } }\n    $lista.Items[$escolher].Selected = $true\n  }\n  $copias = @($script:bots | Where-Object { $_.Situacao -like '*antigo' }).Count\n  if ($script:bots.Count -eq 0) {\n    $rotulo.Text = 'Não achei nenhum bot no seu PC. Extraia o .zip do bot numa pasta e clique em \"Procurar de novo\".'\n  } elseif ($copias -gt 0) {\n    $rotulo.Text = \"Achei $($script:bots.Count) bot(s). Há $copias cópia(s) antiga(s) de um mesmo bot (em cinza): depois de conferir que o mais novo está com os dados, você pode apagar a antiga.\"\n  } else {\n    $rotulo.Text = \"Achei $($script:bots.Count) bot(s). Escolha um e clique em Ligar (na primeira vez, ele abre a configuração).\"\n  }\n  AtualizarBotoes\n}\nfunction AtualizarEstados {\n  foreach ($it in $lista.Items) {\n    $e = EstadoTexto $it.Tag\n    if ($it.SubItems[1].Text -ne $e) { $it.SubItems[1].Text = $e }\n    if ($e -eq 'Ligado') { $it.ForeColor = $VERDE } elseif ($it.Tag.Situacao -like '*antigo') { $it.ForeColor = [System.Drawing.Color]::Gray } else { $it.ForeColor = [System.Drawing.SystemColors]::WindowText }\n  }\n  AtualizarBotoes\n}\nfunction AtualizarBotoes {\n  $b = $null\n  if ($lista.SelectedItems.Count) { $b = $lista.SelectedItems[0].Tag }\n  $ligado = $b -and (ProcessoDoBot $b.Pasta)\n  $btIniciar.Enabled = $b -and -not $ligado\n  $btParar.Enabled = [bool]$ligado\n  if ($b -and (Test-Path -LiteralPath (AtalhoInicio $b))) { $btWindows.Text = 'Não ligar com o Windows' } else { $btWindows.Text = 'Ligar com o Windows' }\n}\n\nfunction Carregar([bool]$procurarDeNovo) {\n  $pastas = @()\n  if (-not $procurarDeNovo) { $pastas = LerCache }\n  if ($pastas.Count -eq 0) {\n    $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor\n    $rotulo.Text = 'Procurando bots no seu PC (na primeira vez pode levar alguns minutos)...'\n    [System.Windows.Forms.Application]::DoEvents()\n    $pastas = @(Procurar $rotulo)\n    $form.Cursor = [System.Windows.Forms.Cursors]::Default\n    SalvarCache $pastas\n  }\n  foreach ($p in $pastas) { Desbloquear $p }\n  $script:bots = @($pastas | ForEach-Object { InfoBot $_ } | Sort-Object Nome, Versao)\n  MarcarSituacao $script:bots\n  Preencher\n  AtualizarEstados\n}\n\nfunction Selecionado {\n  if ($lista.SelectedItems.Count -eq 0) { Aviso 'Escolha um bot na lista.'; return $null }\n  return $lista.SelectedItems[0].Tag\n}\n\n$btIniciar.Add_Click({\n  $b = Selecionado\n  if (-not $b) { return }\n  if ($b.Situacao -like '*antigo') {\n    if (-not (Pergunta \"Este é uma cópia ANTIGA do bot $($b.Nome). Tem uma versão mais nova na lista.`n`nLigar esta mesmo assim?\" 'Warning')) { return }\n  }\n  $outro = $script:bots | Where-Object { $_.Nome -eq $b.Nome -and $_.Pasta -ne $b.Pasta -and (ProcessoDoBot $_.Pasta) } | Select-Object -First 1\n  if ($outro) {\n    if (-not (Pergunta \"Outra cópia deste bot já está ligada:`n$($outro.Pasta)`n`nDois ao mesmo tempo com o mesmo token não funcionam. Desligar a outra e ligar esta?\" 'Warning')) { return }\n    PararBot $outro.Pasta\n  }\n  try { IniciarComResultado $b $rotulo } catch { $form.Cursor = [System.Windows.Forms.Cursors]::Default; Aviso \"Não consegui ligar: $($_.Exception.Message)\" 'Error' }\n  AtualizarEstados\n})\n$lista.Add_DoubleClick({ if ($btIniciar.Enabled) { $btIniciar.PerformClick() } })\n$lista.Add_SelectedIndexChanged({ AtualizarBotoes })\n\n$btParar.Add_Click({\n  $b = Selecionado\n  if (-not $b) { return }\n  $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor\n  $rotulo.Text = \"Desligando o bot $($b.Nome) (salvando os dados)...\"\n  PararBot $b.Pasta\n  $form.Cursor = [System.Windows.Forms.Cursors]::Default\n  $rotulo.Text = \"O bot $($b.Nome) foi desligado.\"\n  AtualizarEstados\n})\n$btConfig.Add_Click({\n  $b = Selecionado\n  if (-not $b) { return }\n  $ligado = ProcessoDoBot $b.Pasta\n  if (Assistente $b) {\n    if ($ligado) {\n      if (Pergunta 'Configuração salva. Reiniciar o bot agora para valer?') { PararBot $b.Pasta; IniciarComResultado $b $rotulo }\n    } elseif (Pergunta 'Configuração salva. Ligar o bot agora?') { IniciarComResultado $b $rotulo }\n  }\n  AtualizarEstados\n})\n$btRegistro.Add_Click({ $b = Selecionado; if ($b) { VerRegistro $b } })\n$btWindows.Add_Click({\n  $b = Selecionado\n  if (-not $b) { return }\n  if (-not (Test-Path -LiteralPath (AtalhoInicio $b)) -and -not (Configurado $b)) { Aviso 'Configure e ligue o bot uma vez antes (botão Ligar).'; return }\n  try { AlternarInicio $b } catch { Aviso \"Não consegui: $($_.Exception.Message)\" 'Error' }\n  AtualizarBotoes\n})\n$btAbrir.Add_Click({\n  $b = Selecionado\n  if ($b) { Start-Process explorer.exe -ArgumentList \"`\"$($b.Pasta)`\"\" }\n})\n$btApagar.Add_Click({\n  $b = Selecionado\n  if (-not $b) { return }\n  if (ProcessoDoBot $b.Pasta) { Aviso 'Este bot está ligado. Clique em Parar antes de apagar.' 'Warning'; return }\n  $novo = $script:bots | Where-Object { $_.Nome -eq $b.Nome -and $_.Situacao -eq 'mais novo' } | Select-Object -First 1\n  $texto = \"Mandar para a Lixeira a pasta do bot $($b.Nome)?`n`n$($b.Pasta)`n`nVersão de $($b.Versao.ToString($fmt))\"\n  $icone = 'Question'\n  if ($novo -and $novo.Pasta -ne $b.Pasta -and $b.Atividade -and (-not $novo.Atividade -or $b.Atividade -gt $novo.Atividade)) {\n    $texto += \"`n`nATENÇÃO: esta cópia tem dados MAIS RECENTES que a versão nova. Transfira os dados antes (Transferir dados.bat) ou você pode perder XP, dinheiro e configurações.\"\n    $icone = 'Warning'\n  } elseif ($b.Situacao -eq 'mais novo' -or -not $novo) {\n    $texto += \"`n`nEsta é a versão mais nova (ou a única) deste bot.\"\n    $icone = 'Warning'\n  }\n  $texto += \"`n`nDá para recuperar pela Lixeira.\"\n  if (-not (Pergunta $texto $icone)) { return }\n  try {\n    $lnk = AtalhoInicio $b\n    if (Test-Path -LiteralPath $lnk) { Remove-Item -LiteralPath $lnk -Force }\n    [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteDirectory($b.Pasta, 'OnlyErrorDialogs', 'SendToRecycleBin')\n    $restantes = @($script:bots | Where-Object { $_.Pasta -ne $b.Pasta } | ForEach-Object { $_.Pasta })\n    SalvarCache $restantes\n    Carregar $false\n  } catch {\n    Aviso \"Não consegui apagar (algum arquivo está aberto?).`n`n$($_.Exception.Message)\" 'Error'\n  }\n})\n$btProcurar.Add_Click({ Carregar $true })\n\n$relogio = New-Object System.Windows.Forms.Timer\n$relogio.Interval = 4000\n$relogio.Add_Tick({ AtualizarEstados })\n$form.Add_Shown({ Carregar $false; $relogio.Start() })\n$form.Add_FormClosing({\n  $relogio.Stop()\n  $ligados = @($script:bots | Where-Object { ProcessoDoBot $_.Pasta })\n  if ($ligados.Count) {\n    [void][System.Windows.Forms.MessageBox]::Show(\"O bot continua ligado depois que você fechar esta janela.`nPara desligar, abra o Inicializador e clique em Parar.\", $titulo, 'OK', 'Information')\n  }\n})\n\ntry {\n  [void]$form.ShowDialog()\n} catch {\n  Aviso \"Algo deu errado: $($_.Exception.Message)\" 'Error'\n  exit 1\n}\n",
  "extras/inicializador/Iniciar bot.bat": "@echo off\nrem Inicializador: dois cliques para configurar e ligar o seu bot (pode ficar em qualquer pasta). Nada de terminal.\nstart \"\" powershell -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -STA -File \"%~dp0inicializador.ps1\"\n",
  "extras/personalizar/Personalizar bot.html": "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Personalizar bot</title>\n<style>\n:root{\n  --bg:#08070a;--surface:#111014;--surface2:#17151c;--surface3:#1e1b25;--border:rgba(255,255,255,.09);--border2:rgba(255,255,255,.16);\n  --text:#f4f1f6;--muted:#aaa3b5;--soft:#7d7588;--brand:#b64cff;--brand-soft:#d9b4ff;--brand-dark:#7330a3;\n  --green:#73d99f;--yellow:#f2c96d;--red:#f07878;--discord:#313338;--discord2:#2b2d31;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%}\nbody{background:radial-gradient(1200px 600px at 10% -10%,rgba(182,76,255,.14),transparent 60%),var(--bg);color:var(--text);font:14px/1.5 system-ui,-apple-system,\"Segoe UI\",Roboto,Ubuntu,sans-serif}\nbutton,input,select,textarea{font:inherit;color:inherit}\na{color:var(--brand-soft)}\n.app{display:grid;grid-template-columns:290px 1fr;height:100vh}\naside{border-right:1px solid var(--border);background:rgba(17,16,20,.85);display:flex;flex-direction:column;min-height:0}\n.marca{padding:18px 18px 12px;border-bottom:1px solid var(--border)}\n.marca b{font-size:15px;letter-spacing:.2px}\n.marca small{display:block;color:var(--soft);font-size:12px;margin-top:2px}\n.busca{padding:12px 14px;border-bottom:1px solid var(--border)}\n.busca input[type=search]{width:100%;background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:9px 12px;outline:none}\n.busca input[type=search]:focus{border-color:var(--brand)}\n.busca label{display:flex;gap:8px;align-items:center;margin-top:9px;color:var(--muted);font-size:12.5px;cursor:pointer}\n.busca input[type=checkbox]{accent-color:var(--brand);width:15px;height:15px;margin:0}\nnav{overflow:auto;padding:8px;flex:1}\nnav button{display:flex;width:100%;align-items:center;justify-content:space-between;gap:8px;background:none;border:0;border-radius:10px;padding:8px 10px;text-align:left;color:var(--muted);cursor:pointer}\nnav button:hover{background:var(--surface2);color:var(--text)}\nnav button.on{background:rgba(182,76,255,.14);color:var(--text);box-shadow:inset 0 0 0 1px rgba(182,76,255,.35)}\nnav .sec{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--soft);padding:12px 10px 4px}\n.qtd{font-size:11.5px;color:var(--soft)}\n.qtd .alt{color:var(--brand-soft);font-weight:700}\nmain{overflow:auto;min-height:0}\nheader{position:sticky;top:0;z-index:5;display:flex;align-items:center;gap:10px;padding:14px 26px;background:rgba(8,7,10,.88);backdrop-filter:blur(10px);border-bottom:1px solid var(--border)}\nheader h1{font-size:18px;margin:0;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\nheader .status{font-size:12.5px;color:var(--soft)}\nheader .status.sujo{color:var(--yellow)}\n.btn{border:1px solid var(--border2);background:var(--surface2);border-radius:999px;padding:8px 16px;cursor:pointer;font-weight:600;white-space:nowrap}\n.btn:hover{border-color:var(--brand-soft)}\n.btn.pri{background:var(--brand);border-color:var(--brand);color:#fff}\n.btn.pri:hover{filter:brightness(1.1)}\n.btn.peq{padding:4px 11px;font-size:12px;font-weight:600}\n.btn:disabled{opacity:.45;cursor:default}\n.conteudo{padding:22px 26px 80px;max-width:1080px}\n.vazio{display:grid;place-items:center;min-height:calc(100vh - 70px);padding:30px}\n.solta{border:2px dashed rgba(182,76,255,.45);border-radius:24px;padding:44px 40px;text-align:center;max-width:620px;background:rgba(182,76,255,.05)}\n.solta.sobre{background:rgba(182,76,255,.14);border-color:var(--brand)}\n.solta h2{margin:6px 0 8px;font-size:22px}\n.solta p{color:var(--muted);margin:6px 0}\n.solta ol{text-align:left;color:var(--muted);margin:18px auto 22px;max-width:470px;padding-left:20px}\n.solta ol li{margin:6px 0}\n.solta code,.dica code{background:var(--surface3);padding:1px 6px;border-radius:6px;color:var(--brand-soft)}\n.icone-grande{width:64px;height:64px;border-radius:20px;display:grid;place-items:center;margin:0 auto;background:linear-gradient(160deg,#1f1030,#0a0710);border:1px solid rgba(182,76,255,.45);box-shadow:0 0 30px -8px rgba(182,76,255,.8)}\n.titulo-sec{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;margin:4px 0 14px}\n.titulo-sec h2{margin:0;font-size:20px}\n.titulo-sec p{margin:2px 0 0;color:var(--muted);font-size:13px}\n.cartao{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:14px 16px;margin-bottom:12px}\n.cartao.alterado{border-color:rgba(182,76,255,.5);box-shadow:inset 3px 0 0 var(--brand)}\n.cab{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px}\n.tag{font-size:11px;font-weight:700;letter-spacing:.03em;padding:2px 8px;border-radius:999px;background:var(--surface3);color:var(--muted)}\n.tag.tipo{background:rgba(182,76,255,.14);color:var(--brand-soft)}\n.chave{font:12px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:var(--soft)}\n.cab .esp{flex:1}\ntextarea{width:100%;min-height:42px;resize:vertical;background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:9px 11px;outline:none;line-height:1.45}\ntextarea:focus,input.campo:focus,select:focus{border-color:var(--brand)}\ninput.campo,select{width:100%;background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:8px 11px;outline:none}\n.vars{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;align-items:center}\n.vars span.rot{font-size:11.5px;color:var(--soft);margin-right:2px}\n.var{border:1px solid rgba(182,76,255,.35);background:rgba(182,76,255,.08);color:var(--brand-soft);border-radius:8px;padding:1px 8px;font:12px ui-monospace,Menlo,Consolas,monospace;cursor:pointer}\n.var:hover{background:rgba(182,76,255,.2)}\n.rodape-cartao{display:flex;gap:10px;align-items:center;margin-top:8px;font-size:12px;color:var(--soft)}\n.rodape-cartao .esp{flex:1}\n.conta.ruim{color:var(--red);font-weight:700}\n.alerta{font-size:12.5px;color:var(--yellow);margin-top:6px}\n.alerta.erro{color:var(--red)}\n.previa{margin-top:10px;background:var(--discord);border-radius:10px;padding:10px 12px;font-size:14px;color:#dbdee1;line-height:1.4;word-wrap:break-word}\n.previa .rot{display:block;font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;color:#949ba4;margin-bottom:4px}\n.md strong{color:#f2f3f5}\n.md code{background:#1e1f22;border-radius:4px;padding:1px 4px;font-size:85%}\n.md pre{background:#1e1f22;border-radius:6px;padding:8px;margin:4px 0;white-space:pre-wrap}\n.md blockquote{margin:2px 0;padding-left:10px;border-left:4px solid #4e5058}\n.md h1,.md h2,.md h3{margin:4px 0;color:#f2f3f5}.md h1{font-size:20px}.md h2{font-size:17px}.md h3{font-size:15px}\n.md .mencao{background:rgba(88,101,242,.3);color:#c9cdfb;border-radius:3px;padding:0 2px}\n.md .var-p{background:rgba(182,76,255,.25);color:#ecd7ff;border-radius:4px;padding:0 3px}\n.md .emoji{width:1.3em;height:1.3em;vertical-align:-.3em;object-fit:contain}\n.md a{color:#00a8fc;text-decoration:none}\n.grade{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.grade3{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}\n.grade4{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}\n.campo-rot{display:block;font-size:12px;color:var(--muted);margin:0 0 5px;font-weight:600}\n.linha-cor{display:flex;gap:8px}\n.linha-cor input[type=color]{width:42px;height:38px;padding:2px;border:1px solid var(--border);border-radius:10px;background:var(--surface2);cursor:pointer}\n.embed{display:flex;background:var(--discord2);border-radius:4px;overflow:hidden;max-width:520px;margin-top:10px}\n.embed .barra{width:4px;flex:none}\n.embed .corpo{padding:10px 14px 12px;flex:1;display:grid;grid-template-columns:1fr auto;gap:8px}\n.embed .tit{font-weight:700;color:#f2f3f5;grid-column:1}\n.embed .desc{font-size:13.5px;color:#dbdee1;grid-column:1}\n.embed .mini{width:64px;height:64px;border-radius:4px;background:#1e1f22 center/cover;grid-column:2;grid-row:1/3}\n.embed .img{grid-column:1/3;height:120px;border-radius:4px;background:#1e1f22 center/cover;display:grid;place-items:center;color:#949ba4;font-size:12px}\n.embed .rod{grid-column:1/3;font-size:12px;color:#949ba4}\n.ph{display:grid;place-items:center;color:#949ba4;font-size:10.5px;text-align:center;padding:4px}\n.dica{background:rgba(182,76,255,.07);border:1px solid rgba(182,76,255,.25);border-radius:14px;padding:12px 14px;color:var(--muted);font-size:13px;margin-bottom:16px}\n.dica b{color:var(--text)}\n.toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);background:var(--surface3);border:1px solid var(--border2);padding:10px 18px;border-radius:999px;box-shadow:0 10px 40px rgba(0,0,0,.5);font-weight:600;opacity:0;pointer-events:none;transition:opacity .2s}\n.toast.on{opacity:1}\n.mais{width:100%;margin-top:6px}\n.sub-grupo{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--soft);margin:22px 0 10px}\n.presenca{display:flex;align-items:center;gap:12px;background:var(--discord2);border-radius:10px;padding:12px 14px;margin-top:12px;max-width:420px}\n.ava{width:42px;height:42px;border-radius:50%;background:linear-gradient(160deg,#b64cff,#4b1f73);position:relative;flex:none}\n.ava i{position:absolute;right:-2px;bottom:-2px;width:14px;height:14px;border-radius:50%;border:3px solid var(--discord2)}\n\n/* botões e menus com cara de Discord */\n.dbtn{display:inline-flex;align-items:center;gap:6px;min-height:32px;padding:2px 16px;border-radius:8px;font-size:14px;font-weight:500;color:#fff;border:0;cursor:default;white-space:nowrap;max-width:100%;overflow:hidden;text-overflow:ellipsis}\n.dbtn.Primary{background:#5865f2}.dbtn.Secondary{background:#4e5058}.dbtn.Success{background:#248046}.dbtn.Danger{background:#da373c}.dbtn.Link{background:#4e5058}\n.dbtn .emoji{width:20px;height:20px}\n.dbtn.oculto{opacity:.35;text-decoration:line-through}\n.dlinha{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}\n.dselect{display:flex;justify-content:space-between;align-items:center;background:#1e1f22;border:1px solid #1e1f22;border-radius:6px;padding:9px 12px;color:#949ba4;max-width:420px;margin-top:8px}\n.dopcoes{background:#2b2d31;border-radius:6px;max-width:420px;margin-top:4px;padding:4px}\n.dopcoes div{padding:6px 8px;border-radius:4px;color:#dbdee1;font-size:14px}.dopcoes small{display:block;color:#949ba4;font-size:12px}\n.swatches{display:flex;gap:6px;flex-wrap:wrap}\n.sw{border:2px solid transparent;border-radius:8px;padding:5px 10px;font-size:12px;font-weight:700;color:#fff;cursor:pointer}\n.sw.Primary{background:#5865f2}.sw.Secondary{background:#4e5058}.sw.Success{background:#248046}.sw.Danger{background:#da373c}\n.sw.on{border-color:#fff;box-shadow:0 0 0 2px var(--brand)}\n.sw.padrao{background:var(--surface3);color:var(--muted)}\n.chave-liga{display:inline-flex;align-items:center;gap:8px;cursor:pointer;color:var(--muted);font-size:13px}\n.chave-liga input{accent-color:var(--brand);width:16px;height:16px}\n.dmodal{background:#313338;border-radius:8px;max-width:440px;padding:16px;margin-top:10px}\n.dmodal h4{margin:0 0 12px;color:#f2f3f5;font-size:18px}\n.dmodal label{display:block;font-size:12px;font-weight:700;color:#b5bac1;text-transform:uppercase;margin:10px 0 6px}\n.dmodal label i{color:#f23f43;font-style:normal}\n.dmodal .inp{background:#1e1f22;border-radius:4px;padding:9px 10px;color:#6d6f78;font-size:14px;min-height:38px}\n.dmodal .inp.longa{min-height:76px}\n.dmodal .acoes{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}\n.lista-criados{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px}\n.lista-criados button{border:1px solid var(--border2);background:var(--surface2);border-radius:999px;padding:6px 14px;cursor:pointer;font-weight:600}\n.lista-criados button.on{border-color:var(--brand);background:rgba(182,76,255,.18)}\n.item{background:var(--surface2);border:1px solid var(--border);border-radius:12px;padding:12px;margin-top:10px}\n.item .cab b{font-size:13px}\n.mini-btns{display:flex;gap:6px}\n.mini-btns button{border:1px solid var(--border2);background:var(--surface3);border-radius:8px;padding:2px 9px;cursor:pointer;color:var(--muted)}\n.mini-btns button:hover{color:var(--text);border-color:var(--brand-soft)}\n.mini-btns button.perigo:hover{border-color:var(--red);color:var(--red)}\n.linha2{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}\n.linha3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-top:10px}\n.mt{margin-top:10px}\n@media (max-width:860px){.linha2,.linha3{grid-template-columns:1fr}}\n@media (max-width:860px){.app{grid-template-columns:1fr}aside{display:none}.grade,.grade3,.grade4{grid-template-columns:1fr}}\n</style>\n</head>\n<body>\n<div class=\"app\">\n  <aside>\n    <div class=\"marca\">\n      <b id=\"nomeBot\">Personalizar bot</b>\n      <small id=\"infoArquivo\">Nenhum arquivo aberto</small>\n    </div>\n    <div class=\"busca\">\n      <input id=\"busca\" type=\"search\" placeholder=\"Procurar em todos os textos…\" disabled>\n      <label><input id=\"soAlterados\" type=\"checkbox\" disabled> Só os que eu mudei</label>\n    </div>\n    <nav id=\"menu\"></nav>\n  </aside>\n  <main id=\"principal\">\n    <header>\n      <h1 id=\"tituloPagina\">Personalizar bot</h1>\n      <span class=\"status\" id=\"estado\"></span>\n      <button class=\"btn\" id=\"btnAbrir\">Abrir arquivo</button>\n      <button class=\"btn pri\" id=\"btnSalvar\" disabled>Salvar</button>\n      <input type=\"file\" id=\"arquivo\" accept=\".json,application/json\" hidden>\n    </header>\n    <div id=\"area\"></div>\n  </main>\n</div>\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\n'use strict';\n// ------------------------------------------------------------------\n// Personalizar bot: edita o arquivo baixado com /personalizar baixar.\n// Tudo roda aqui no seu computador; nada é enviado para a internet.\n// ------------------------------------------------------------------\nconst TIPOS = {\n  texto: 'Texto', resposta: 'Resposta (só quem usou vê)', descricao: 'Texto do embed', conteudo: 'Mensagem',\n  titulo: 'Título', campo: 'Nome de campo', valor: 'Valor de campo', rodape: 'Rodapé', autor: 'Autor do embed',\n  botao: 'Botão', rotulo: 'Pergunta de formulário', placeholder: 'Dica dentro do campo', opcao: 'Opção de menu',\n  motivo: 'Motivo', canal: 'Nome de canal'\n};\nconst LIMITES_PADRAO = { texto: 2000, resposta: 3900, descricao: 4000, conteudo: 2000, titulo: 256, campo: 256, valor: 1024, rodape: 2048, autor: 256, botao: 80, rotulo: 45, placeholder: 150, opcao: 100, motivo: 500, canal: 100 };\nconst EXEMPLOS = {\n  usuario: '<@1>', autor: '<@2>', alvo: '<@3>', membro: '<@1>', dono: '<@1>', atendente: '<@2>', por: '<@2>', mencao: '<@1>',\n  tag: 'ana', nome: 'Ana', servidor: 'Meu Servidor', membros: '1.234', canal: '<#1>', cargo: '<@&1>', motivo: 'Spam no chat',\n  duracao: '10min', quando: '<t:1893456000:R>', relativo: '<t:1893456000:R>', data: '25 de dezembro', numero: '7', total: '3',\n  nivel: '5', xp: '1.250', dinheiro: '🪙 **500** moedas', moeda: '🪙', premio: 'Nitro', vencedores: '1', limite: '5', pontos: '10',\n  estrelas: '⭐⭐⭐⭐⭐', media: '4,8', titulo: 'Candidatura', perguntas_total: '3', codigo: 'abc123', convidou: '<@2>', convites: '4',\n  link: 'https://discord.com', endereco: 'jogar.servidor.com', latencia: '42', segundos: '30', status: 'aprovada', gatilho: 'ip',\n  tipo: 'mensagens apagadas', acao: 'expulsar', erro: 'Não consegui.', aviso: '', extra: '', lista: '• item', posicao: '1',\n  avatar: 'https://cdn.discordapp.com/embed/avatars/0.png', servidor_icone: 'https://cdn.discordapp.com/embed/avatars/1.png'\n};\nconst EMOJI_NOMES = { sucesso: 'Sucesso', erro: 'Erro', aviso: 'Aviso', info: 'Informação' };\nconst COR_NOMES = { padrao: 'Cor padrão das mensagens', sucesso: 'Sucesso', erro: 'Erro', aviso: 'Aviso' };\nconst PRESENCA_TIPOS = { personalizado: 'Status personalizado', jogando: 'Jogando', ouvindo: 'Ouvindo', assistindo: 'Assistindo', competindo: 'Competindo em' };\nconst PRESENCA_STATUS = { online: ['Online', '#23a55a'], idle: ['Ausente', '#f0b232'], dnd: ['Não perturbe', '#f23f43'] };\n\nlet dados = null;          // arquivo aberto (catálogo + valores)\nlet valores = null;        // o que está sendo editado\nlet atual = 'geral-config'; // seção aberta\nlet sujo = false;\nlet limiteLista = 120;\n\nconst $ = (s) => document.querySelector(s);\nconst esc = (s) => String(s ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nconst varsDe = (s) => [...new Set([...String(s).matchAll(/\\{(\\w+)\\}/g)].map((m) => m[1]))];\nconst vazio = () => ({ textos: {}, visuais: {}, emojis: {}, cores: {}, presenca: {}, botoes: {}, criados: { paineis: [], formularios: [] } });\n\nfunction toast(msg) {\n  const t = $('#toast');\n  t.textContent = msg;\n  t.classList.add('on');\n  clearTimeout(toast.t);\n  toast.t = setTimeout(() => t.classList.remove('on'), 2600);\n}\n\n// ---------------- prévia com cara de Discord ----------------\nfunction markdown(texto, vars) {\n  let s = esc(texto);\n  // variáveis: troca pelo exemplo (ou mostra a etiqueta)\n  s = s.replace(/\\{(\\w+)\\}/g, (m, k) => {\n    if (vars && !vars.includes(k)) return `<span class=\"var-p\" title=\"Esta variável não existe neste texto\">{${k}}</span>`;\n    const ex = EXEMPLOS[k];\n    return ex !== undefined ? esc(ex) : `<span class=\"var-p\">${k}</span>`;\n  });\n  const blocos = [];\n  s = s.replace(/```(?:\\w+\\n)?([\\s\\S]*?)```/g, (m, c) => { blocos.push(`<pre>${c}</pre>`); return `\\u0000${blocos.length - 1}\\u0000`; });\n  s = s.replace(/`([^`\\n]+)`/g, '<code>$1</code>');\n  s = s.replace(/&lt;a?:(\\w+):(\\d+)&gt;/g, (m, n, id) => `<img class=\"emoji\" alt=\":${n}:\" title=\":${n}:\" src=\"https://cdn.discordapp.com/emojis/${id}.webp?size=48\" onerror=\"this.replaceWith(':${n}:')\">`);\n  s = s.replace(/&lt;@!?\\d+&gt;/g, '<span class=\"mencao\">@Ana</span>');\n  s = s.replace(/&lt;@&amp;\\d+&gt;/g, '<span class=\"mencao\">@Cargo</span>');\n  s = s.replace(/&lt;#\\d+&gt;/g, '<span class=\"mencao\">#canal</span>');\n  s = s.replace(/&lt;t:\\d+(?::\\w)?&gt;/g, '<span class=\"mencao\">em 2 horas</span>');\n  s = s.replace(/\\[([^\\]]+)\\]\\((https?:[^)\\s]+)\\)/g, '<a href=\"$2\" target=\"_blank\" rel=\"noopener\">$1</a>');\n  s = s.replace(/\\*\\*\\*(.+?)\\*\\*\\*/g, '<strong><em>$1</em></strong>');\n  s = s.replace(/\\*\\*(.+?)\\*\\*/g, '<strong>$1</strong>');\n  s = s.replace(/__(.+?)__/g, '<u>$1</u>');\n  s = s.replace(/(^|[^\\w*])\\*(?!\\s)(.+?)\\*(?!\\w)/g, '$1<em>$2</em>');\n  s = s.replace(/(^|\\W)_(?!\\s)(.+?)_(?!\\w)/g, '$1<em>$2</em>');\n  s = s.replace(/~~(.+?)~~/g, '<s>$1</s>');\n  s = s.split('\\n').map((l) => {\n    if (/^### /.test(l)) return `<h3>${l.slice(4)}</h3>`;\n    if (/^## /.test(l)) return `<h2>${l.slice(3)}</h2>`;\n    if (/^# /.test(l)) return `<h1>${l.slice(2)}</h1>`;\n    if (/^&gt; /.test(l)) return `<blockquote>${l.slice(5)}</blockquote>`;\n    if (/^[-*] /.test(l)) return `• ${l.slice(2)}<br>`;\n    return `${l}<br>`;\n  }).join('').replace(/<br>$/, '');\n  return s.replace(/\\u0000(\\d+)\\u0000/g, (m, n) => blocos[n]);\n}\n\n// ---------------- abrir / salvar ----------------\nfunction abrirJson(texto, nomeArquivo) {\n  let json;\n  try { json = JSON.parse(texto.replace(/^\\uFEFF/, '')); } catch { return toast('Esse arquivo não é um JSON válido.'); }\n  if (json.formato !== 'byteup-personalizacao' || !json.catalogo?.textos) {\n    return toast('Esse arquivo não serve. Use o que o bot manda no /personalizar baixar.');\n  }\n  dados = json;\n  valores = Object.assign(vazio(), structuredClone(json.valores || {}));\n  for (const k of Object.keys(vazio())) valores[k] = valores[k] || vazio()[k];\n  valores.criados.paineis = valores.criados.paineis || [];\n  valores.criados.formularios = valores.criados.formularios || [];\n  dados.catalogo.botoes = dados.catalogo.botoes || {};\n  dados.catalogo.modais = dados.catalogo.modais || {};\n  dados.servidores = dados.servidores || [];\n  // rascunho guardado neste navegador\n  const r = lerRascunho();\n  if (r && r.base === assinatura() && JSON.stringify(r.valores) !== JSON.stringify(valores) && confirm('Encontrei alterações que você não salvou da última vez. Quer recuperar?')) {\n    valores = Object.assign(vazio(), r.valores);\n    marcarSujo(true);\n  } else marcarSujo(false);\n  $('#nomeBot').textContent = json.bot || 'Seu bot';\n  $('#infoArquivo').textContent = `${Object.keys(json.catalogo.textos).length} textos · ${nomeArquivo || 'arquivo'}`;\n  $('#busca').disabled = false;\n  $('#soAlterados').disabled = false;\n  $('#btnSalvar').disabled = false;\n  atual = 'geral-config';\n  montarMenu();\n  mostrar();\n  toast('Arquivo aberto ✓');\n}\n\nfunction limpar(v) {\n  // guarda só o que é diferente do padrão\n  const out = vazio();\n  for (const [k, s] of Object.entries(v.textos)) if (s && s !== dados.catalogo.textos[k]?.padrao) out.textos[k] = s;\n  for (const [k, x] of Object.entries(v.visuais)) {\n    const y = {};\n    for (const c of ['cor', 'imagem', 'miniatura', 'rodape']) if (x?.[c]) y[c] = x[c];\n    if (Object.keys(y).length) out.visuais[k] = y;\n  }\n  for (const [k, e] of Object.entries(v.emojis)) if (e && e !== dados.catalogo.emojis?.[k]) out.emojis[k] = e;\n  for (const [k, c] of Object.entries(v.cores)) if (c && c !== dados.catalogo.cores?.[k]) out.cores[k] = c;\n  for (const [k, b] of Object.entries(v.botoes || {})) {\n    const y = {};\n    if (b?.emoji) y.emoji = b.emoji;\n    if (b?.estilo) y.estilo = b.estilo;\n    if (b?.oculto) y.oculto = true;\n    if (Object.keys(y).length) out.botoes[k] = y;\n  }\n  out.criados = structuredClone(v.criados || { paineis: [], formularios: [] });\n  if (v.presenca.texto) out.presenca.texto = v.presenca.texto;\n  if (v.presenca.tipo && v.presenca.tipo !== 'personalizado') out.presenca.tipo = v.presenca.tipo;\n  if (v.presenca.status && v.presenca.status !== 'online') out.presenca.status = v.presenca.status;\n  return out;\n}\n\nfunction salvar() {\n  if (!dados) return;\n  const final = { ...dados, gerado: new Date().toISOString(), valores: limpar(valores) };\n  const blob = new Blob([JSON.stringify(final, null, 1)], { type: 'application/json' });\n  const a = document.createElement('a');\n  a.href = URL.createObjectURL(blob);\n  a.download = 'personalizacao.json';\n  document.body.appendChild(a);\n  a.click();\n  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1000);\n  dados.valores = final.valores;\n  marcarSujo(false);\n  apagarRascunho();\n  toast('Salvo! Agora use /personalizar aplicar no Discord com este arquivo.');\n}\n\nconst assinatura = () => `${dados?.bot}|${Object.keys(dados?.catalogo?.textos || {}).length}`;\nfunction lerRascunho() { try { return JSON.parse(localStorage.getItem('byteup-personalizar') || 'null'); } catch { return null; } }\nfunction guardarRascunho() { try { localStorage.setItem('byteup-personalizar', JSON.stringify({ base: assinatura(), valores })); } catch { /* sem armazenamento */ } }\nfunction apagarRascunho() { try { localStorage.removeItem('byteup-personalizar'); } catch { /* sem armazenamento */ } }\n\nfunction marcarSujo(v) {\n  sujo = v;\n  const e = $('#estado');\n  e.textContent = v ? '● alterações não salvas' : dados ? 'tudo salvo' : '';\n  e.className = 'status' + (v ? ' sujo' : '');\n  if (v) { clearTimeout(marcarSujo.t); marcarSujo.t = setTimeout(guardarRascunho, 400); }\n}\n\n// ---------------- menu ----------------\nfunction contagens(modulo) {\n  const chaves = Object.entries(dados.catalogo.textos).filter(([, v]) => v.modulo === modulo).map(([k]) => k);\n  const vis = Object.entries(dados.catalogo.visuais || {}).filter(([, v]) => v.modulo === modulo).map(([k]) => k);\n  const bts = Object.entries(dados.catalogo.botoes || {}).filter(([, v]) => v.modulo === modulo).map(([k]) => k);\n  const alt = chaves.filter((k) => valores.textos[k] && valores.textos[k] !== dados.catalogo.textos[k].padrao).length\n    + vis.filter((k) => Object.values(valores.visuais[k] || {}).some(Boolean)).length\n    + bts.filter((k) => Object.values(valores.botoes[k] || {}).some(Boolean)).length;\n  return { total: chaves.length, alt };\n}\n\nfunction montarMenu() {\n  const modulos = (dados.modulos || []).filter((m) => contagens(m.id).total);\n  const altGeral = Object.keys(limpar(valores).emojis).length + Object.keys(limpar(valores).cores).length + (valores.presenca.texto ? 1 : 0);\n  let h = `<div class=\"sec\">Geral</div>\n    <button data-sec=\"geral-config\" class=\"${atual === 'geral-config' ? 'on' : ''}\"><span>🎨 Cores, emojis e status</span><span class=\"qtd\">${altGeral ? `<span class=\"alt\">${altGeral}</span>` : ''}</span></button>\n    <div class=\"sec\">Criar</div>\n    <button data-sec=\"criar-paineis\" class=\"${atual === 'criar-paineis' ? 'on' : ''}\"><span>🧩 Painéis</span><span class=\"qtd\">${valores.criados.paineis.length ? `<span class=\"alt\">${valores.criados.paineis.length}</span>` : ''}</span></button>\n    <button data-sec=\"criar-formularios\" class=\"${atual === 'criar-formularios' ? 'on' : ''}\"><span>📝 Formulários</span><span class=\"qtd\">${valores.criados.formularios.length ? `<span class=\"alt\">${valores.criados.formularios.length}</span>` : ''}</span></button>\n    <div class=\"sec\">Textos por módulo</div>`;\n  for (const m of modulos) {\n    const c = contagens(m.id);\n    h += `<button data-sec=\"${esc(m.id)}\" class=\"${atual === m.id ? 'on' : ''}\"><span>${esc(m.nome)}</span><span class=\"qtd\">${c.alt ? `<span class=\"alt\">${c.alt}</span> / ` : ''}${c.total}</span></button>`;\n  }\n  $('#menu').innerHTML = h;\n}\n$('#menu').addEventListener('click', (e) => {\n  const b = e.target.closest('button[data-sec]');\n  if (!b) return;\n  atual = b.dataset.sec;\n  $('#busca').value = '';\n  limiteLista = 120;\n  montarMenu();\n  mostrar();\n  $('#principal').scrollTop = 0;\n});\n\n// ---------------- telas ----------------\nfunction telaVazia() {\n  $('#tituloPagina').textContent = 'Personalizar bot';\n  $('#area').innerHTML = `<div class=\"vazio\"><div class=\"solta\" id=\"solta\">\n    <div class=\"icone-grande\"><svg width=\"34\" height=\"34\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#d9b4ff\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z\"/></svg></div>\n    <h2>Personalize todos os textos do seu bot</h2>\n    <p>Mensagens, títulos, botões, cores, emojis e o status. Tudo fica no seu computador.</p>\n    <ol>\n      <li>No Discord, use <code>/personalizar baixar</code> e salve o arquivo <code>personalizacao.json</code>.</li>\n      <li>Arraste o arquivo para cá (ou clique em <b>Abrir arquivo</b>).</li>\n      <li>Edite o que quiser e clique em <b>Salvar</b>.</li>\n      <li>No Discord, use <code>/personalizar aplicar</code> e envie o arquivo salvo. Vale na hora.</li>\n    </ol>\n    <button class=\"btn pri\" onclick=\"document.getElementById('arquivo').click()\">Abrir arquivo</button>\n  </div></div>`;\n}\n\nfunction mostrar() {\n  if (!dados) return telaVazia();\n  const busca = $('#busca').value.trim().toLowerCase();\n  if (busca) return telaBusca(busca);\n  if (atual === 'geral-config') return telaGeral();\n  if (atual === 'criar-paineis') return telaPaineis();\n  if (atual === 'criar-formularios') return telaFormularios();\n  return telaModulo(atual);\n}\n\nfunction cartaoTexto(chave) {\n  const c = dados.catalogo.textos[chave];\n  const valor = valores.textos[chave] ?? c.padrao;\n  const alterado = valor !== c.padrao;\n  const limite = (dados.limites || LIMITES_PADRAO)[c.tipo] ?? 2000;\n  const linhas = Math.min(8, Math.max(1, Math.ceil(valor.length / 90), valor.split('\\n').length));\n  const dicaPadrao = /^(msg_|nome_sala_padrao)/.test(chave.split('.')[1]) ? '<div class=\"alerta\" style=\"color:var(--muted)\">Usado quando o servidor não definiu uma mensagem própria no /config.</div>' : '';\n  return `<div class=\"cartao ${alterado ? 'alterado' : ''}\" data-chave=\"${esc(chave)}\">\n    <div class=\"cab\"><span class=\"tag tipo\">${esc(TIPOS[c.tipo] || 'Texto')}</span><span class=\"chave\">${esc(chave)}</span><span class=\"esp\"></span>\n      ${alterado ? '<button class=\"btn peq\" data-acao=\"restaurar\">Voltar ao padrão</button>' : ''}</div>\n    <textarea rows=\"${linhas}\" data-campo=\"texto\" spellcheck=\"true\">${esc(valor)}</textarea>\n    ${c.vars.length ? `<div class=\"vars\"><span class=\"rot\">Variáveis:</span>${c.vars.map((v) => `<button class=\"var\" data-var=\"${esc(v)}\" title=\"Inserir {${esc(v)}}\">{${esc(v)}}</button>`).join('')}</div>` : ''}\n    ${dicaPadrao}\n    <div class=\"avisos\"></div>\n    <div class=\"previa md\"><span class=\"rot\">Prévia</span><div class=\"render\"></div></div>\n    <div class=\"rodape-cartao\">${alterado ? `<span title=\"${esc(c.padrao)}\">Padrão: ${esc(c.padrao.length > 90 ? c.padrao.slice(0, 89) + '…' : c.padrao)}</span>` : '<span>Texto padrão</span>'}<span class=\"esp\"></span><span class=\"conta\" data-limite=\"${limite}\"></span></div>\n  </div>`;\n}\n\nfunction atualizarCartao(el) {\n  const chave = el.dataset.chave;\n  const c = dados.catalogo.textos[chave];\n  const ta = el.querySelector('textarea');\n  const v = ta.value;\n  el.querySelector('.render').innerHTML = markdown(v, c.vars) || '<span style=\"color:#949ba4\">(vazio: vai usar o texto padrão)</span>';\n  const conta = el.querySelector('.conta');\n  const lim = Number(conta.dataset.limite);\n  conta.textContent = `${v.length} / ${lim}`;\n  conta.classList.toggle('ruim', v.length > lim);\n  const avisos = [];\n  const desconhecidas = varsDe(v).filter((x) => !c.vars.includes(x));\n  if (desconhecidas.length) avisos.push(`<div class=\"alerta\">⚠️ ${desconhecidas.map((x) => `{${esc(x)}}`).join(', ')} não existe neste texto e vai aparecer escrito assim.</div>`);\n  if (v.length > lim) avisos.push(`<div class=\"alerta erro\">Passou do limite do Discord (${lim}). O bot vai cortar o final.</div>`);\n  if (!v.trim()) avisos.push('<div class=\"alerta\">Vazio: o bot usa o texto padrão.</div>');\n  el.querySelector('.avisos').innerHTML = avisos.join('');\n}\n\nfunction ligarCartoes(raiz) {\n  raiz.querySelectorAll('.cartao[data-chave]').forEach(atualizarCartao);\n}\n\n$('#area').addEventListener('input', (e) => {\n  const el = e.target.closest('.cartao[data-chave]');\n  if (el && e.target.matches('textarea')) {\n    const chave = el.dataset.chave;\n    const padrao = dados.catalogo.textos[chave].padrao;\n    const v = e.target.value;\n    if (v === padrao || !v.trim()) delete valores.textos[chave];\n    else valores.textos[chave] = v;\n    el.classList.toggle('alterado', v !== padrao && !!v.trim());\n    atualizarCartao(el);\n    marcarSujo(true);\n    atualizarContagemMenu();\n    return;\n  }\n  const vis = e.target.closest('.cartao[data-visual]');\n  if (vis) { lerVisual(vis); marcarSujo(true); atualizarContagemMenu(); return; }\n  const bc = e.target.closest('.cartao[data-botao]');\n  if (bc) { lerBotao(bc, e.target); marcarSujo(true); atualizarContagemMenu(); return; }\n  if (e.target.closest('[data-pn]')) { editarPainel(e); return; }\n  if (e.target.closest('[data-fm]')) { editarFormulario(e); return; }\n  const g = e.target.closest('[data-geral]');\n  if (g) { lerGeral(); marcarSujo(true); atualizarContagemMenu(); }\n});\n$('#area').addEventListener('change', (e) => {\n  if (e.target.closest('[data-geral]')) { lerGeral(); marcarSujo(true); atualizarContagemMenu(); return; }\n  if (e.target.matches('select, input[type=checkbox]')) {\n    const bc = e.target.closest('.cartao[data-botao]');\n    if (bc) { lerBotao(bc, e.target); marcarSujo(true); atualizarContagemMenu(); return; }\n    if (e.target.closest('[data-pn]')) { editarPainel(e, true); return; }\n    if (e.target.closest('[data-fm]')) { editarFormulario(e, true); return; }\n  }\n});\n\nlet ultimoFoco = null;\n$('#area').addEventListener('focusin', (e) => { if (e.target.matches('textarea,input.campo')) ultimoFoco = e.target; });\n$('#area').addEventListener('click', (e) => {\n  const v = e.target.closest('.var');\n  if (v) {\n    const card = v.closest('.cartao');\n    const alvo = ultimoFoco && card.contains(ultimoFoco) ? ultimoFoco : card.querySelector('textarea, [data-v=\"miniatura\"]');\n    if (!alvo) return;\n    const ins = `{${v.dataset.var}}`;\n    const ini = alvo.selectionStart ?? alvo.value.length, fim = alvo.selectionEnd ?? alvo.value.length;\n    alvo.value = alvo.value.slice(0, ini) + ins + alvo.value.slice(fim);\n    alvo.focus();\n    alvo.selectionStart = alvo.selectionEnd = ini + ins.length;\n    alvo.dispatchEvent(new Event('input', { bubbles: true }));\n    return;\n  }\n  const r = e.target.closest('[data-acao=\"restaurar\"]');\n  if (r) {\n    const el = r.closest('.cartao[data-chave]');\n    delete valores.textos[el.dataset.chave];\n    el.outerHTML = cartaoTexto(el.dataset.chave);\n    ligarCartoes($('#area'));\n    marcarSujo(true);\n    atualizarContagemMenu();\n    return;\n  }\n  const rv = e.target.closest('[data-acao=\"restaurar-visual\"]');\n  if (rv) {\n    const el = rv.closest('.cartao[data-visual]');\n    delete valores.visuais[el.dataset.visual];\n    el.outerHTML = cartaoVisual(el.dataset.visual);\n    $('#area').querySelectorAll('.cartao[data-visual]').forEach(previaVisual);\n    marcarSujo(true);\n    atualizarContagemMenu();\n    return;\n  }\n  if (e.target.closest('[data-acao=\"mais\"]')) { limiteLista += 150; mostrar(); return; }\n  if (cliqueBotao(e) || cliquePainel(e) || cliqueFormulario(e)) return;\n});\n\nfunction atualizarContagemMenu() {\n  clearTimeout(atualizarContagemMenu.t);\n  atualizarContagemMenu.t = setTimeout(montarMenu, 250);\n}\n\nfunction telaModulo(id) {\n  const mod = (dados.modulos || []).find((m) => m.id === id) || { nome: id };\n  $('#tituloPagina').textContent = mod.nome;\n  const so = $('#soAlterados').checked;\n  const bts = Object.entries(dados.catalogo.botoes || {}).filter(([, v]) => v.modulo === id).map(([k]) => k);\n  const mds = Object.entries(dados.catalogo.modais || {}).filter(([, v]) => v.modulo === id);\n  // textos que já aparecem nos cartões de botão e de modal não se repetem na lista\n  const usados = new Set([...bts.map((k) => dados.catalogo.botoes[k].rotulo).filter(Boolean), ...mds.flatMap(([, m]) => m.textos)]);\n  let chaves = Object.entries(dados.catalogo.textos).filter(([k, v]) => v.modulo === id && !usados.has(k)).map(([k]) => k);\n  if (so) chaves = chaves.filter((k) => valores.textos[k] !== undefined);\n  const vis = Object.entries(dados.catalogo.visuais || {}).filter(([, v]) => v.modulo === id).map(([k]) => k);\n  const partes = [`${chaves.length} texto(s)`];\n  if (bts.length) partes.push(`${bts.length} botão(ões)`);\n  if (mds.length) partes.push(`${mds.length} modal(is)`);\n  if (vis.length) partes.push(`${vis.length} embed(s) com aparência personalizável`);\n  let h = `<div class=\"conteudo\"><div class=\"titulo-sec\"><div><h2>${esc(mod.nome)}</h2><p>${partes.join(' · ')}</p></div></div>`;\n  if (!so) {\n    if (vis.length) h += `<div class=\"sub-grupo\">Aparência dos embeds</div>${vis.map(cartaoVisual).join('')}`;\n    if (bts.length) h += `<div class=\"sub-grupo\">Botões</div>${bts.map(cartaoBotao).join('')}`;\n    for (const [, m] of mds) h += `<div class=\"sub-grupo\">Modal: ${esc(m.nome)}</div>${m.textos.filter((k) => dados.catalogo.textos[k]).map(cartaoTexto).join('')}`;\n    if (vis.length || bts.length || mds.length) h += '<div class=\"sub-grupo\">Textos</div>';\n  }\n  if (!chaves.length) h += `<div class=\"dica\">${so ? 'Nenhum texto alterado neste módulo.' : 'Este módulo não tem textos.'}</div>`;\n  h += chaves.slice(0, limiteLista).map(cartaoTexto).join('');\n  if (chaves.length > limiteLista) h += `<button class=\"btn mais\" data-acao=\"mais\">Mostrar mais (${chaves.length - limiteLista})</button>`;\n  $('#area').innerHTML = h + '</div>';\n  ligarCartoes($('#area'));\n  $('#area').querySelectorAll('.cartao[data-visual]').forEach(previaVisual);\n  $('#area').querySelectorAll('.cartao[data-botao]').forEach(previaBotao);\n}\n\nfunction telaBusca(busca) {\n  $('#tituloPagina').textContent = 'Procurar';\n  const so = $('#soAlterados').checked;\n  const nomes = Object.fromEntries((dados.modulos || []).map((m) => [m.id, m.nome]));\n  const achados = Object.entries(dados.catalogo.textos)\n    .filter(([k, v]) => (!so || valores.textos[k] !== undefined) && (k.toLowerCase().includes(busca) || v.padrao.toLowerCase().includes(busca) || (valores.textos[k] || '').toLowerCase().includes(busca)))\n    .map(([k]) => k);\n  let h = `<div class=\"conteudo\"><div class=\"titulo-sec\"><div><h2>“${esc(busca)}”</h2><p>${achados.length} texto(s) encontrado(s)</p></div></div>`;\n  let ultimo = '';\n  for (const k of achados.slice(0, limiteLista)) {\n    const m = dados.catalogo.textos[k].modulo;\n    if (m !== ultimo) { h += `<div class=\"sub-grupo\">${esc(nomes[m] || m)}</div>`; ultimo = m; }\n    h += cartaoTexto(k);\n  }\n  if (achados.length > limiteLista) h += `<button class=\"btn mais\" data-acao=\"mais\">Mostrar mais (${achados.length - limiteLista})</button>`;\n  $('#area').innerHTML = h + '</div>';\n  ligarCartoes($('#area'));\n}\n\nlet buscaT;\n$('#busca').addEventListener('input', () => { clearTimeout(buscaT); buscaT = setTimeout(() => { limiteLista = 120; mostrar(); }, 200); });\n$('#soAlterados').addEventListener('change', () => { limiteLista = 120; mostrar(); });\n\n// ---------------- aparência dos embeds ----------------\nfunction cartaoVisual(chave) {\n  const c = dados.catalogo.visuais[chave];\n  const v = valores.visuais[chave] || {};\n  const alterado = Object.values(v).some(Boolean);\n  const corPadrao = valores.cores.padrao || dados.catalogo.cores?.padrao || '#5865f2';\n  const dicaVars = c.vars.length ? `Pode usar ${c.vars.map((x) => `<code>{${x}}</code>`).join(' ou ')} ou um link https://. Use <code>-</code> para tirar.` : 'Um link https:// (ou <code>-</code> para tirar).';\n  return `<div class=\"cartao ${alterado ? 'alterado' : ''}\" data-visual=\"${esc(chave)}\">\n    <div class=\"cab\"><span class=\"tag tipo\">Embed</span><b>${esc(c.nome)}</b><span class=\"esp\"></span>${alterado ? '<button class=\"btn peq\" data-acao=\"restaurar-visual\">Voltar ao padrão</button>' : ''}</div>\n    <div class=\"grade\">\n      <div><span class=\"campo-rot\">Cor da barra</span><div class=\"linha-cor\"><input type=\"color\" data-v=\"corpicker\" value=\"${esc(v.cor || corPadrao)}\"><input class=\"campo\" data-v=\"cor\" placeholder=\"padrão (${esc(corPadrao)})\" value=\"${esc(v.cor || '')}\" maxlength=\"7\"></div></div>\n      <div><span class=\"campo-rot\">Rodapé</span><input class=\"campo\" data-v=\"rodape\" placeholder=\"${esc(c.padrao?.rodape ? 'padrão: ' + c.padrao.rodape : 'sem rodapé extra')}\" value=\"${esc(v.rodape || '')}\" maxlength=\"2048\"></div>\n      <div><span class=\"campo-rot\">Miniatura (imagem pequena à direita)</span><input class=\"campo\" data-v=\"miniatura\" placeholder=\"${esc(c.padrao?.miniatura ? 'padrão: ' + c.padrao.miniatura : 'sem miniatura')}\" value=\"${esc(v.miniatura || '')}\"></div>\n      <div><span class=\"campo-rot\">Imagem grande (banner)</span><input class=\"campo\" data-v=\"imagem\" placeholder=\"${esc(c.padrao?.imagem ? 'padrão: ' + c.padrao.imagem : 'sem imagem')}\" value=\"${esc(v.imagem || '')}\"></div>\n    </div>\n    ${c.vars.length ? `<div class=\"vars\"><span class=\"rot\">Para as imagens:</span>${c.vars.map((x) => `<button class=\"var\" data-var=\"${esc(x)}\">{${esc(x)}}</button>`).join('')}</div>` : ''}\n    <div class=\"alerta\" style=\"color:var(--muted)\">${dicaVars}</div>\n    <div class=\"avisos\"></div>\n    <div class=\"embed\"><div class=\"barra\"></div><div class=\"corpo\"><div class=\"tit\">${esc(c.nome)}</div><div class=\"mini ph\"></div><div class=\"desc\">Exemplo do texto desta mensagem.</div><div class=\"img ph\"></div><div class=\"rod\"></div></div></div>\n  </div>`;\n}\n\nfunction urlExemplo(u) {\n  if (!u || u === '-') return '';\n  const s = u.replace(/\\{(\\w+)\\}/g, (m, k) => EXEMPLOS[k] || '');\n  return /^https?:\\/\\//i.test(s) ? s : '';\n}\n\nfunction previaVisual(el) {\n  const chave = el.dataset.visual;\n  const c = dados.catalogo.visuais[chave];\n  const v = valores.visuais[chave] || {};\n  const cor = v.cor || valores.cores.padrao || dados.catalogo.cores?.padrao || '#5865f2';\n  el.querySelector('.barra').style.background = cor;\n  const mini = el.querySelector('.mini');\n  const miniUrl = v.miniatura ? urlExemplo(v.miniatura) : c.padrao?.miniatura?.startsWith('{') ? urlExemplo(c.padrao.miniatura) : '';\n  const mostraMini = v.miniatura ? v.miniatura !== '-' : !!c.padrao?.miniatura;\n  mini.style.display = mostraMini ? '' : 'none';\n  mini.style.backgroundImage = miniUrl ? `url(\"${miniUrl}\")` : '';\n  mini.textContent = mostraMini && !miniUrl ? (c.padrao?.miniatura || 'miniatura') : '';\n  const img = el.querySelector('.img');\n  const imgUrl = urlExemplo(v.imagem);\n  img.style.display = v.imagem && v.imagem !== '-' ? '' : 'none';\n  img.style.backgroundImage = imgUrl ? `url(\"${imgUrl}\")` : '';\n  img.textContent = imgUrl ? '' : 'imagem';\n  el.querySelector('.rod').textContent = v.rodape && v.rodape !== '-' ? v.rodape.replace(/\\{(\\w+)\\}/g, (m, k) => (c.vars.includes(k) ? EXEMPLOS[k] ?? m : m)) : '';\n  const avisos = [];\n  if (v.cor && !/^#[0-9a-f]{6}$/i.test(v.cor)) avisos.push('A cor precisa ser assim: #B64CFF');\n  for (const campo of ['miniatura', 'imagem']) {\n    const u = v[campo];\n    if (u && u !== '-' && !/^https?:\\/\\/\\S+$/i.test(u) && !/^\\{\\w+\\}$/.test(u)) avisos.push(`${campo === 'imagem' ? 'Imagem' : 'Miniatura'}: use um link que começa com https:// ou uma variável.`);\n  }\n  el.querySelector('.avisos').innerHTML = avisos.map((a) => `<div class=\"alerta erro\">${esc(a)}</div>`).join('');\n}\n\nfunction lerVisual(el) {\n  const chave = el.dataset.visual;\n  const v = {};\n  const picker = el.querySelector('[data-v=\"corpicker\"]');\n  const corTxt = el.querySelector('[data-v=\"cor\"]');\n  if (document.activeElement === picker) corTxt.value = picker.value;\n  else if (/^#[0-9a-f]{6}$/i.test(corTxt.value)) picker.value = corTxt.value;\n  for (const c of ['cor', 'rodape', 'miniatura', 'imagem']) {\n    const x = el.querySelector(`[data-v=\"${c}\"]`).value.trim();\n    if (x) v[c] = x;\n  }\n  if (Object.keys(v).length) valores.visuais[chave] = v;\n  else delete valores.visuais[chave];\n  el.classList.toggle('alterado', Object.keys(v).length > 0);\n  previaVisual(el);\n}\n\n// ---------------- geral: cores, emojis e status ----------------\nfunction telaGeral() {\n  $('#tituloPagina').textContent = 'Cores, emojis e status';\n  const cat = dados.catalogo;\n  const p = valores.presenca;\n  let h = `<div class=\"conteudo\">\n    <div class=\"titulo-sec\"><div><h2>Cores, emojis e status</h2><p>Valem para o bot inteiro. Os textos de cada módulo ficam no menu ao lado.</p></div></div>\n    <div class=\"dica\">Quando terminar, clique em <b>Salvar</b> e envie o arquivo no Discord com <code>/personalizar aplicar</code>. A cor escolhida em <code>/config cor</code> num servidor continua valendo nele.</div>\n    <div class=\"sub-grupo\">Cores</div><div class=\"cartao\" data-geral><div class=\"grade4\">`;\n  for (const k of Object.keys(cat.cores || {})) {\n    const v = valores.cores[k] || '';\n    const pad = cat.cores[k] || '#5865f2';\n    h += `<div><span class=\"campo-rot\">${esc(COR_NOMES[k] || k)}</span><div class=\"linha-cor\"><input type=\"color\" data-cor-picker=\"${k}\" value=\"${esc(v || pad)}\"><input class=\"campo\" data-cor=\"${k}\" placeholder=\"${esc(pad || 'do config.json')}\" value=\"${esc(v)}\" maxlength=\"7\"></div></div>`;\n  }\n  h += `</div><div class=\"alerta\" style=\"color:var(--muted)\">A cor padrão é a das mensagens comuns. Sucesso, erro e aviso são as das respostas rápidas (✅ ❌ ⚠️).</div></div>\n    <div class=\"sub-grupo\">Emojis das respostas rápidas</div><div class=\"cartao\" data-geral><div class=\"grade4\">`;\n  for (const k of Object.keys(cat.emojis || {})) {\n    h += `<div><span class=\"campo-rot\">${esc(EMOJI_NOMES[k] || k)}</span><input class=\"campo\" data-emoji=\"${k}\" placeholder=\"${esc(cat.emojis[k])}\" value=\"${esc(valores.emojis[k] || '')}\" maxlength=\"100\"></div>`;\n  }\n  h += `</div><div class=\"alerta\" style=\"color:var(--muted)\">Aceita emoji normal (✅) ou um emoji do seu servidor/aplicação: no Discord, digite <code>\\\\:nome:</code> e copie o resultado, que fica assim: <code>&lt;a:nome:123456789&gt;</code>.</div>\n    <div class=\"previa md\"><span class=\"rot\">Prévia</span><div id=\"previaEmojis\"></div></div></div>\n    <div class=\"sub-grupo\">Status do bot</div><div class=\"cartao\" data-geral><div class=\"grade3\">\n      <div><span class=\"campo-rot\">Tipo</span><select data-pres=\"tipo\">${Object.entries(PRESENCA_TIPOS).map(([k, n]) => `<option value=\"${k}\" ${((p.tipo || 'personalizado') === k) ? 'selected' : ''}>${n}</option>`).join('')}</select></div>\n      <div><span class=\"campo-rot\">Texto</span><input class=\"campo\" data-pres=\"texto\" maxlength=\"128\" placeholder=\"padrão do config.json\" value=\"${esc(p.texto || '')}\"></div>\n      <div><span class=\"campo-rot\">Bolinha</span><select data-pres=\"status\">${Object.entries(PRESENCA_STATUS).map(([k, [n]]) => `<option value=\"${k}\" ${((p.status || 'online') === k) ? 'selected' : ''}>${n}</option>`).join('')}</select></div>\n    </div><div class=\"presenca\"><div class=\"ava\"><i id=\"bolinha\"></i></div><div><b>${esc(dados.bot || 'Seu bot')}</b><div id=\"previaStatus\" style=\"font-size:13px;color:#b5bac1\"></div></div></div></div>\n  </div>`;\n  $('#area').innerHTML = h;\n  previaGeral();\n}\n\nfunction lerGeral() {\n  const area = $('#area');\n  area.querySelectorAll('[data-cor]').forEach((inp) => {\n    const k = inp.dataset.cor;\n    const picker = area.querySelector(`[data-cor-picker=\"${k}\"]`);\n    if (document.activeElement === picker) inp.value = picker.value;\n    else if (/^#[0-9a-f]{6}$/i.test(inp.value)) picker.value = inp.value;\n    const v = inp.value.trim();\n    if (v) valores.cores[k] = v; else delete valores.cores[k];\n  });\n  area.querySelectorAll('[data-emoji]').forEach((inp) => {\n    const v = inp.value.trim();\n    if (v) valores.emojis[inp.dataset.emoji] = v; else delete valores.emojis[inp.dataset.emoji];\n  });\n  for (const campo of ['tipo', 'texto', 'status']) {\n    const el = area.querySelector(`[data-pres=\"${campo}\"]`);\n    if (!el) continue;\n    const v = el.value.trim();\n    if (v) valores.presenca[campo] = v; else delete valores.presenca[campo];\n  }\n  previaGeral();\n}\n\nfunction previaGeral() {\n  const cat = dados.catalogo;\n  const pe = $('#previaEmojis');\n  if (pe) {\n    pe.innerHTML = Object.keys(cat.emojis || {}).map((k) => {\n      const cor = valores.cores[k] || cat.cores?.[k] || '#5865f2';\n      return `<div class=\"embed\" style=\"margin-top:6px\"><div class=\"barra\" style=\"background:${esc(/^#[0-9a-f]{6}$/i.test(cor) ? cor : '#5865f2')}\"></div><div class=\"corpo\" style=\"display:block\">${markdown(`${valores.emojis[k] || cat.emojis[k]} Exemplo de resposta de ${(EMOJI_NOMES[k] || k).toLowerCase()}.`)}</div></div>`;\n    }).join('');\n  }\n  const ps = $('#previaStatus');\n  if (ps) {\n    const p = valores.presenca;\n    const tipo = p.tipo || 'personalizado';\n    const texto = p.texto || '(status do config.json)';\n    ps.innerHTML = tipo === 'personalizado' ? esc(texto) : `${esc(PRESENCA_TIPOS[tipo])} <b>${esc(texto)}</b>`;\n    $('#bolinha').style.background = PRESENCA_STATUS[p.status || 'online'][1];\n  }\n}\n\n// ---------------- botões ----------------\nconst ESTILOS = { Primary: 'Azul', Secondary: 'Cinza', Success: 'Verde', Danger: 'Vermelho' };\nconst emojiHtml = (e) => {\n  if (!e || e === '-') return '';\n  const m = /^<a?:(\\w+):(\\d+)>$/.exec(e);\n  return m ? `<img class=\"emoji\" alt=\":${esc(m[1])}:\" src=\"https://cdn.discordapp.com/emojis/${m[2]}.webp?size=48\">` : `<span>${esc(e)}</span>`;\n};\nconst emojiOk = (e) => !e || e === '-' || /^<a?:\\w{2,32}:\\d{15,22}>$/.test(e) || (/^[\\p{Extended_Pictographic}\\p{Regional_Indicator}\\p{Emoji_Modifier}‍️⃣#*0-9]+$/u.test(e) && /[\\p{Extended_Pictographic}\\p{Regional_Indicator}⃣]/u.test(e));\nconst dbtn = (rotulo, emoji, estilo, extra = '') => `<span class=\"dbtn ${esc(estilo)} ${extra}\">${emojiHtml(emoji)}${rotulo ? `<span>${esc(rotulo)}</span>` : ''}${estilo === 'Link' ? ' ↗' : ''}</span>`;\n\nfunction cartaoBotao(k) {\n  const d = dados.catalogo.botoes[k];\n  const v = valores.botoes[k] || {};\n  const rot = d.rotulo && dados.catalogo.textos[d.rotulo];\n  const alterado = Object.values(v).some(Boolean) || (d.rotulo && valores.textos[d.rotulo] !== undefined);\n  const sw = d.estilo === 'Link' ? '<span class=\"alerta\" style=\"color:var(--muted)\">Botão de link: o Discord deixa sempre cinza.</span>'\n    : `<div class=\"swatches\"><button class=\"sw padrao ${!v.estilo ? 'on' : ''}\" data-estilo=\"\">Padrão</button>${Object.entries(ESTILOS).map(([e, n]) => `<button class=\"sw ${e} ${v.estilo === e ? 'on' : ''}\" data-estilo=\"${e}\">${n}</button>`).join('')}</div>`;\n  return `<div class=\"cartao ${alterado ? 'alterado' : ''}\" data-botao=\"${esc(k)}\">\n    <div class=\"cab\"><span class=\"tag tipo\">Botão</span><b>${esc(d.nome)}</b><span class=\"esp\"></span>${alterado ? '<button class=\"btn peq\" data-acao=\"restaurar-botao\">Voltar ao padrão</button>' : ''}</div>\n    <div class=\"grade\">\n      <div><span class=\"campo-rot\">Texto</span>${rot ? `<input class=\"campo\" data-rotulo=\"${esc(d.rotulo)}\" maxlength=\"80\" value=\"${esc(valores.textos[d.rotulo] ?? rot.padrao)}\">` : `<div class=\"alerta\" style=\"color:var(--muted);margin:0\">${esc(d.rotuloInfo || 'Automático')}</div>`}</div>\n      <div><span class=\"campo-rot\">Emoji</span><input class=\"campo\" data-b=\"emoji\" ${d.emojiFixo ? 'disabled' : ''} placeholder=\"${esc(d.emojiFixo ? 'automático' : d.emoji && d.emoji !== '-' ? 'padrão: ' + d.emoji : 'sem emoji')}\" value=\"${esc(v.emoji || '')}\"></div>\n    </div>\n    ${rot && d.rotuloInfo ? `<div class=\"alerta\" style=\"color:var(--muted)\">${esc(d.rotuloInfo)}</div>` : ''}\n    <div class=\"mt\"><span class=\"campo-rot\">Cor</span>${sw}</div>\n    ${d.ocultavel ? `<div class=\"mt\"><label class=\"chave-liga\"><input type=\"checkbox\" data-b=\"mostrar\" ${v.oculto ? '' : 'checked'}> Mostrar este botão</label></div>` : ''}\n    <div class=\"avisos\"></div>\n    <div class=\"previa\"><span class=\"rot\">Prévia</span><div class=\"dlinha\"></div></div>\n    <div class=\"alerta\" style=\"color:var(--muted)\">Emoji: um emoji normal (🎫) ou do servidor (<code>&lt;:nome:id&gt;</code>). Use <code>-</code> para tirar o emoji.</div>\n  </div>`;\n}\n\nfunction previaBotao(el) {\n  const k = el.dataset.botao;\n  const d = dados.catalogo.botoes[k];\n  const v = valores.botoes[k] || {};\n  const rotulo = d.rotulo ? (valores.textos[d.rotulo] ?? dados.catalogo.textos[d.rotulo]?.padrao ?? '') : '(automático)';\n  const emoji = d.emojiFixo ? d.emoji : v.emoji || d.emoji;\n  const estilo = d.estilo === 'Link' ? 'Link' : v.estilo || d.estilo;\n  el.querySelector('.dlinha').innerHTML = dbtn(rotulo, emoji, estilo, v.oculto ? 'oculto' : '') + (v.oculto ? '<span class=\"alerta\" style=\"margin:6px 0 0\">Escondido: não aparece no Discord.</span>' : '');\n  const avisos = [];\n  if (v.emoji && !emojiOk(v.emoji)) avisos.push('Esse emoji não funciona num botão. Use um emoji normal ou <:nome:id>.');\n  if (d.rotulo && !rotulo.trim() && (!emoji || emoji === '-')) avisos.push('O botão precisa de texto ou emoji.');\n  el.querySelector('.avisos').innerHTML = avisos.map((a) => `<div class=\"alerta erro\">${esc(a)}</div>`).join('');\n}\n\nfunction lerBotao(el, alvo) {\n  const k = el.dataset.botao;\n  const v = (valores.botoes[k] = valores.botoes[k] || {});\n  if (alvo.dataset.rotulo) {\n    const chave = alvo.dataset.rotulo;\n    const pad = dados.catalogo.textos[chave].padrao;\n    if (alvo.value === pad || !alvo.value.trim()) delete valores.textos[chave];\n    else valores.textos[chave] = alvo.value;\n  }\n  if (alvo.dataset.b === 'emoji') { if (alvo.value.trim()) v.emoji = alvo.value.trim(); else delete v.emoji; }\n  if (alvo.dataset.b === 'mostrar') { if (alvo.checked) delete v.oculto; else v.oculto = true; }\n  if (!Object.keys(v).length) delete valores.botoes[k];\n  el.classList.add('alterado');\n  previaBotao(el);\n}\n\nfunction cliqueBotao(e) {\n  const el = e.target.closest('.cartao[data-botao]');\n  if (!el) return false;\n  const k = el.dataset.botao;\n  const sw = e.target.closest('.sw');\n  if (sw) {\n    const v = (valores.botoes[k] = valores.botoes[k] || {});\n    if (sw.dataset.estilo) v.estilo = sw.dataset.estilo; else delete v.estilo;\n    if (!Object.keys(v).length) delete valores.botoes[k];\n    el.querySelectorAll('.sw').forEach((x) => x.classList.toggle('on', x === sw));\n    previaBotao(el);\n    marcarSujo(true);\n    atualizarContagemMenu();\n    return true;\n  }\n  if (e.target.closest('[data-acao=\"restaurar-botao\"]')) {\n    const d = dados.catalogo.botoes[k];\n    delete valores.botoes[k];\n    if (d.rotulo) delete valores.textos[d.rotulo];\n    el.outerHTML = cartaoBotao(k);\n    $('#area').querySelectorAll('.cartao[data-botao]').forEach(previaBotao);\n    marcarSujo(true);\n    atualizarContagemMenu();\n    return true;\n  }\n  return false;\n}\n\n// ---------------- servidores (cargos e canais) ----------------\nconst servidor = (id) => (dados.servidores || []).find((s) => s.id === id);\nfunction opcoes(lista, atual, vazioTexto, prefixo = '') {\n  let h = `<option value=\"\">${esc(vazioTexto)}</option>`;\n  h += lista.map((x) => `<option value=\"${esc(x.id)}\" ${x.id === atual ? 'selected' : ''}>${esc(prefixo + x.nome)}</option>`).join('');\n  if (atual && !lista.some((x) => x.id === atual)) h += `<option value=\"${esc(atual)}\" selected>(não encontrado: ${esc(atual)})</option>`;\n  return h;\n}\nconst cargosDe = (sid) => servidor(sid)?.cargos || [];\nconst canaisDe = (sid, tipo) => (servidor(sid)?.canais || []).filter((c) => c.tipo === tipo);\nconst opcoesServidor = (atual, vazio = 'Qualquer servidor') => opcoes(dados.servidores || [], atual, vazio);\nconst semServidores = () => (dados.servidores || []).length ? '' : '<div class=\"alerta\">O arquivo não trouxe a lista de cargos e canais. Use <code>/personalizar baixar</code> de novo (com o bot já no servidor).</div>';\nconst novoId = (base, existentes) => {\n  const b = (base || 'item').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 24) || 'item';\n  let id = b;\n  for (let n = 2; existentes.includes(id); n++) id = `${b}-${n}`;\n  return id;\n};\n\n// ---------------- painéis criados ----------------\nlet painelSel = null;\nconst ACOES = { cargo: 'Dar/tirar cargo', mensagem: 'Responder uma mensagem', formulario: 'Abrir formulário', ticket: 'Abrir ticket', link: 'Abrir link' };\nconst temTickets = () => (dados.modulos || []).some((m) => m.id === 'tickets');\n\nfunction novoItem(pn) {\n  const id = novoId('opcao', pn.itens.map((x) => x.id));\n  return { id, rotulo: pn.tipo === 'menu' ? 'Nova opção' : 'Novo botão', emoji: '', descricao: '', estilo: 'Primary', acao: { tipo: 'mensagem', mensagem: 'Olá, {usuario}!' } };\n}\n\nfunction telaPaineis() {\n  $('#tituloPagina').textContent = 'Painéis';\n  const pns = valores.criados.paineis;\n  if (!pns.some((p) => p.id === painelSel)) painelSel = pns[0]?.id ?? null;\n  let h = `<div class=\"conteudo\"><div class=\"titulo-sec\"><div><h2>Painéis</h2><p>Mensagens com botões ou menu que você monta: dar cargo, responder, abrir formulário${temTickets() ? ', abrir ticket' : ''} ou abrir link.</p></div><button class=\"btn pri\" data-acao=\"novo-painel\" ${pns.length >= 25 ? 'disabled' : ''}>+ Novo painel</button></div>\n    <div class=\"dica\">Depois de <b>Salvar</b> e aplicar com <code>/personalizar aplicar</code>, publique no canal com <code>/painel enviar</code>. Se você mudar um painel já publicado, ele se atualiza sozinho ao aplicar de novo.</div>`;\n  if (!pns.length) h += '<div class=\"dica\">Nenhum painel ainda. Clique em <b>+ Novo painel</b>.</div>';\n  else h += `<div class=\"lista-criados\">${pns.map((p) => `<button data-acao=\"sel-painel\" data-id=\"${esc(p.id)}\" class=\"${p.id === painelSel ? 'on' : ''}\">${esc(p.nome)}</button>`).join('')}</div>`;\n  const pn = pns.find((p) => p.id === painelSel);\n  if (pn) h += editorPainel(pn);\n  $('#area').innerHTML = h + '</div>';\n  if (pn) previaPainel(pn);\n}\n\nfunction editorPainel(pn) {\n  const menu = pn.tipo === 'menu';\n  const sid = pn.servidor;\n  const itens = pn.itens.map((it, n) => {\n    const a = it.acao;\n    let campos = '';\n    if (a.tipo === 'cargo') campos = `<div class=\"linha2\"><div><span class=\"campo-rot\">Cargo</span><select data-ia=\"cargo\" data-idx=\"${n}\">${opcoes(cargosDe(sid), a.cargo, sid ? 'Escolha o cargo' : 'Escolha o servidor do painel primeiro', '@')}</select></div>\n      <div><span class=\"campo-rot\">Ao clicar</span><select data-ia=\"modo\" data-idx=\"${n}\">${[['alternar', 'Dá se não tem, tira se tem'], ['dar', 'Só dá'], ['tirar', 'Só tira']].map(([v, t]) => `<option value=\"${v}\" ${a.modo === v ? 'selected' : ''}>${t}</option>`).join('')}</select></div></div>\n      <div class=\"mt\"><span class=\"campo-rot\">Resposta (opcional)</span><input class=\"campo\" data-ia=\"mensagem\" data-idx=\"${n}\" maxlength=\"2000\" placeholder=\"Padrão: Você ganhou o cargo… · variáveis {usuario} {nome} {cargo}\" value=\"${esc(a.mensagem || '')}\"></div>`;\n    if (a.tipo === 'mensagem') campos = `<div class=\"mt\"><span class=\"campo-rot\">Mensagem (só quem clicou vê)</span><textarea data-ia=\"mensagem\" data-idx=\"${n}\" rows=\"3\" maxlength=\"2000\">${esc(a.mensagem || '')}</textarea><div class=\"alerta\" style=\"color:var(--muted)\">Variáveis: {usuario} {nome} {servidor}</div></div>`;\n    if (a.tipo === 'formulario') campos = `<div class=\"mt\"><span class=\"campo-rot\">Formulário</span><select data-ia=\"formulario\" data-idx=\"${n}\">${opcoes(valores.criados.formularios.map((f) => ({ id: f.id, nome: f.titulo })), a.formulario, valores.criados.formularios.length ? 'Escolha o formulário' : 'Crie um formulário na aba Formulários')}</select></div>`;\n    if (a.tipo === 'ticket') campos = `<div class=\"linha3\"><div><span class=\"campo-rot\">Assunto</span><input class=\"campo\" data-ia=\"assunto\" data-idx=\"${n}\" maxlength=\"80\" placeholder=\"Padrão: o nome do botão\" value=\"${esc(a.assunto || '')}\"></div>\n      <div><span class=\"campo-rot\">Categoria</span><select data-ia=\"categoria\" data-idx=\"${n}\">${opcoes(canaisDe(sid, 'categoria'), a.categoria, 'A do /config tickets', '📁 ')}</select></div>\n      <div><span class=\"campo-rot\">Equipe avisada</span><select data-ia=\"equipe\" data-idx=\"${n}\">${opcoes(cargosDe(sid), a.equipe, 'A do /config tickets', '@')}</select></div></div>\n      <div class=\"mt\"><span class=\"campo-rot\">Mensagem de abertura (opcional)</span><textarea data-ia=\"mensagem\" data-idx=\"${n}\" rows=\"2\" maxlength=\"2000\" placeholder=\"Padrão: a mensagem do /config tickets · variáveis {usuario} {nome} {servidor} {assunto}\">${esc(a.mensagem || '')}</textarea></div>`;\n    if (a.tipo === 'link') campos = `<div class=\"mt\"><span class=\"campo-rot\">Link</span><input class=\"campo\" data-ia=\"url\" data-idx=\"${n}\" maxlength=\"500\" placeholder=\"https://\" value=\"${esc(a.url || '')}\"></div>`;\n    const acoes = Object.entries(ACOES).filter(([k]) => (k !== 'link' || !menu) && (k !== 'ticket' || temTickets() || a.tipo === 'ticket'));\n    return `<div class=\"item\" data-item=\"${n}\">\n      <div class=\"cab\"><b>${menu ? 'Opção' : 'Botão'} ${n + 1}</b><span class=\"esp\"></span><div class=\"mini-btns\"><button data-acao=\"item-sobe\" data-idx=\"${n}\" title=\"Subir\">↑</button><button data-acao=\"item-desce\" data-idx=\"${n}\" title=\"Descer\">↓</button><button class=\"perigo\" data-acao=\"item-apaga\" data-idx=\"${n}\" title=\"Apagar\">✕</button></div></div>\n      <div class=\"linha3\">\n        <div><span class=\"campo-rot\">Nome</span><input class=\"campo\" data-it=\"rotulo\" data-idx=\"${n}\" maxlength=\"${menu ? 100 : 80}\" value=\"${esc(it.rotulo)}\"></div>\n        <div><span class=\"campo-rot\">Emoji</span><input class=\"campo\" data-it=\"emoji\" data-idx=\"${n}\" placeholder=\"opcional\" value=\"${esc(it.emoji)}\"></div>\n        ${menu ? `<div><span class=\"campo-rot\">Descrição</span><input class=\"campo\" data-it=\"descricao\" data-idx=\"${n}\" maxlength=\"100\" placeholder=\"opcional\" value=\"${esc(it.descricao)}\"></div>`\n          : `<div><span class=\"campo-rot\">O que faz</span><select data-ia=\"tipo\" data-idx=\"${n}\">${acoes.map(([k, t]) => `<option value=\"${k}\" ${a.tipo === k ? 'selected' : ''}>${t}</option>`).join('')}</select></div>`}\n      </div>\n      ${menu ? `<div class=\"mt\"><span class=\"campo-rot\">O que faz</span><select data-ia=\"tipo\" data-idx=\"${n}\">${acoes.map(([k, t]) => `<option value=\"${k}\" ${a.tipo === k ? 'selected' : ''}>${t}</option>`).join('')}</select></div>`\n        : a.tipo === 'link' ? '' : `<div class=\"mt\"><span class=\"campo-rot\">Cor</span><div class=\"swatches\">${Object.entries(ESTILOS).map(([e, t]) => `<button class=\"sw ${e} ${it.estilo === e ? 'on' : ''}\" data-it-estilo=\"${e}\" data-idx=\"${n}\">${t}</button>`).join('')}</div></div>`}\n      ${campos}\n      <div class=\"avisos-item\"></div>\n    </div>`;\n  }).join('');\n  return `<div class=\"cartao\" data-pn=\"${esc(pn.id)}\">\n    <div class=\"linha3\" style=\"margin-top:0\">\n      <div><span class=\"campo-rot\">Nome do painel (só para você)</span><input class=\"campo\" data-p=\"nome\" maxlength=\"80\" value=\"${esc(pn.nome)}\"></div>\n      <div><span class=\"campo-rot\">Servidor</span><select data-p=\"servidor\">${opcoesServidor(pn.servidor)}</select></div>\n      <div><span class=\"campo-rot\">Tipo</span><select data-p=\"tipo\"><option value=\"botoes\" ${!menu ? 'selected' : ''}>Botões (até 25)</option><option value=\"menu\" ${menu ? 'selected' : ''}>Menu de seleção (até 25)</option></select></div>\n    </div>\n    ${semServidores()}\n    ${menu ? `<div class=\"mt\"><span class=\"campo-rot\">Texto do menu fechado</span><input class=\"campo\" data-p=\"placeholder\" maxlength=\"150\" placeholder=\"Escolha uma opção\" value=\"${esc(pn.placeholder)}\"></div>` : ''}\n    <div class=\"sub-grupo\">Mensagem</div>\n    <div class=\"linha2\" style=\"margin-top:0\">\n      <div><span class=\"campo-rot\">Título do embed</span><input class=\"campo\" data-e=\"titulo\" maxlength=\"256\" value=\"${esc(pn.embed.titulo)}\"></div>\n      <div><span class=\"campo-rot\">Cor</span><div class=\"linha-cor\"><input type=\"color\" data-e=\"corpicker\" value=\"${esc(pn.embed.cor || valores.cores.padrao || '#5865f2')}\"><input class=\"campo\" data-e=\"cor\" maxlength=\"7\" placeholder=\"padrão do bot\" value=\"${esc(pn.embed.cor)}\"></div></div>\n    </div>\n    <div class=\"mt\"><span class=\"campo-rot\">Texto do embed</span><textarea data-e=\"descricao\" rows=\"4\" maxlength=\"4000\">${esc(pn.embed.descricao)}</textarea></div>\n    <div class=\"linha3\">\n      <div><span class=\"campo-rot\">Imagem grande</span><input class=\"campo\" data-e=\"imagem\" placeholder=\"https://\" value=\"${esc(pn.embed.imagem)}\"></div>\n      <div><span class=\"campo-rot\">Miniatura</span><input class=\"campo\" data-e=\"miniatura\" placeholder=\"https:// ou {servidor_icone}\" value=\"${esc(pn.embed.miniatura)}\"></div>\n      <div><span class=\"campo-rot\">Rodapé</span><input class=\"campo\" data-e=\"rodape\" maxlength=\"2048\" value=\"${esc(pn.embed.rodape)}\"></div>\n    </div>\n    <div class=\"mt\"><span class=\"campo-rot\">Texto fora do embed (opcional)</span><input class=\"campo\" data-p=\"conteudo\" maxlength=\"2000\" value=\"${esc(pn.conteudo)}\"></div>\n    <div class=\"alerta\" style=\"color:var(--muted)\">Variáveis: {servidor} {membros}. Nas imagens: {servidor_icone}.</div>\n    <div class=\"sub-grupo\">${menu ? 'Opções do menu' : 'Botões'} (${pn.itens.length}/25)</div>\n    ${itens}\n    <button class=\"btn mais\" data-acao=\"item-novo\" ${pn.itens.length >= 25 ? 'disabled' : ''}>+ Adicionar ${menu ? 'opção' : 'botão'}</button>\n    <div class=\"avisos-painel mt\"></div>\n    <div class=\"sub-grupo\">Prévia</div>\n    <div class=\"previa-painel\"></div>\n    <div class=\"mt\" style=\"display:flex;gap:8px;justify-content:flex-end\"><button class=\"btn peq\" data-acao=\"dup-painel\">Duplicar</button><button class=\"btn peq\" data-acao=\"del-painel\" style=\"border-color:var(--red);color:var(--red)\">Apagar painel</button></div>\n  </div>`;\n}\n\nfunction avisosPainel(pn) {\n  const av = [];\n  if (!pn.embed.titulo.trim() && !pn.embed.descricao.trim() && !pn.conteudo.trim()) av.push('Coloque um título, um texto ou um texto fora do embed.');\n  if (pn.embed.cor && !/^#[0-9a-f]{6}$/i.test(pn.embed.cor)) av.push('A cor precisa ser assim: #B64CFF.');\n  for (const c of ['imagem', 'miniatura']) if (pn.embed[c] && !/^https?:\\/\\/\\S+$/i.test(pn.embed[c]) && !/^\\{\\w+\\}$/.test(pn.embed[c])) av.push(`${c === 'imagem' ? 'Imagem' : 'Miniatura'}: use um link https://.`);\n  if (!pn.itens.length) av.push(`Adicione pelo menos ${pn.tipo === 'menu' ? 'uma opção' : 'um botão'}.`);\n  if (pn.itens.some((it) => it.acao.tipo === 'cargo') && !pn.servidor) av.push('Escolha o servidor: o painel tem botão de cargo.');\n  return av;\n}\nfunction avisosItem(pn, it) {\n  const av = [];\n  const a = it.acao;\n  if (pn.tipo === 'menu' && !it.rotulo.trim()) av.push('A opção precisa de um nome.');\n  if (pn.tipo !== 'menu' && !it.rotulo.trim() && !it.emoji) av.push('O botão precisa de nome ou emoji.');\n  if (it.emoji && !emojiOk(it.emoji)) av.push('Emoji inválido: use um emoji normal ou <:nome:id>.');\n  if (a.tipo === 'cargo' && !a.cargo) av.push('Escolha o cargo.');\n  if (a.tipo === 'mensagem' && !a.mensagem?.trim()) av.push('Escreva a mensagem.');\n  if (a.tipo === 'formulario' && !valores.criados.formularios.some((f) => f.id === a.formulario)) av.push('Escolha o formulário.');\n  if (a.tipo === 'link' && !/^https?:\\/\\/\\S+$/i.test(a.url || '')) av.push('O link precisa começar com https://');\n  if (a.tipo === 'ticket' && !temTickets()) av.push('Este bot não tem o módulo Tickets.');\n  return av;\n}\n\nfunction previaPainel(pn) {\n  const el = $('#area').querySelector('[data-pn]');\n  if (!el) return;\n  const sv = servidor(pn.servidor);\n  const sub = (t) => String(t || '').replace(/\\{servidor\\}/g, sv?.nome || 'Meu Servidor').replace(/\\{membros\\}/g, '1.234');\n  const cor = /^#[0-9a-f]{6}$/i.test(pn.embed.cor) ? pn.embed.cor : valores.cores.padrao || '#5865f2';\n  const url = (u) => { const x = String(u || '').replace('{servidor_icone}', 'https://cdn.discordapp.com/embed/avatars/1.png'); return /^https?:\\/\\//.test(x) ? x : ''; };\n  let h = '<div class=\"previa md\">';\n  if (pn.conteudo) h += `<div>${markdown(sub(pn.conteudo))}</div>`;\n  if (pn.embed.titulo || pn.embed.descricao) {\n    h += `<div class=\"embed\"><div class=\"barra\" style=\"background:${esc(cor)}\"></div><div class=\"corpo\">\n      ${pn.embed.titulo ? `<div class=\"tit\">${markdown(sub(pn.embed.titulo))}</div>` : ''}\n      ${pn.embed.miniatura ? `<div class=\"mini\" style=\"background-image:url('${esc(url(pn.embed.miniatura))}')\"></div>` : ''}\n      ${pn.embed.descricao ? `<div class=\"desc\">${markdown(sub(pn.embed.descricao))}</div>` : ''}\n      ${pn.embed.imagem ? `<div class=\"img\" style=\"background-image:url('${esc(url(pn.embed.imagem))}')\">${url(pn.embed.imagem) ? '' : 'imagem'}</div>` : ''}\n      ${pn.embed.rodape ? `<div class=\"rod\">${esc(sub(pn.embed.rodape))}</div>` : ''}\n    </div></div>`;\n  }\n  if (pn.tipo === 'menu') {\n    h += `<div class=\"dselect\"><span>${esc(pn.placeholder || 'Escolha uma opção')}</span><span>▾</span></div><div class=\"dopcoes\">${pn.itens.map((it) => `<div>${emojiHtml(it.emoji)} ${esc(it.rotulo)}${it.descricao ? `<small>${esc(it.descricao)}</small>` : ''}</div>`).join('')}</div>`;\n  } else {\n    for (let n = 0; n < pn.itens.length; n += 5) h += `<div class=\"dlinha\">${pn.itens.slice(n, n + 5).map((it) => dbtn(it.rotulo, it.emoji, it.acao.tipo === 'link' ? 'Link' : it.estilo)).join('')}</div>`;\n  }\n  el.querySelector('.previa-painel').innerHTML = h + '</div>';\n  el.querySelector('.avisos-painel').innerHTML = avisosPainel(pn).map((a) => `<div class=\"alerta erro\">${esc(a)}</div>`).join('');\n  el.querySelectorAll('.item[data-item]').forEach((x) => {\n    x.querySelector('.avisos-item').innerHTML = avisosItem(pn, pn.itens[+x.dataset.item]).map((a) => `<div class=\"alerta erro\">${esc(a)}</div>`).join('');\n  });\n}\n\nfunction editarPainel(e, estrutura = false) {\n  const pn = valores.criados.paineis.find((p) => p.id === painelSel);\n  if (!pn) return;\n  const t = e.target;\n  const d = t.dataset;\n  let redesenhar = false;\n  if (d.p) {\n    pn[d.p] = t.value;\n    if (d.p === 'tipo') {\n      redesenhar = true;\n      if (pn.tipo === 'menu') pn.itens.forEach((it) => { if (it.acao.tipo === 'link') it.acao = { tipo: 'mensagem', mensagem: '' }; });\n    }\n    if (d.p === 'servidor') redesenhar = true;\n    if (d.p === 'nome') $('#area').querySelector(`.lista-criados [data-id=\"${CSS.escape(pn.id)}\"]`).textContent = pn.nome;\n  } else if (d.e) {\n    if (d.e === 'corpicker') { pn.embed.cor = t.value; t.parentElement.querySelector('[data-e=\"cor\"]').value = t.value; }\n    else {\n      pn.embed[d.e] = t.value;\n      if (d.e === 'cor' && /^#[0-9a-f]{6}$/i.test(t.value)) t.parentElement.querySelector('[data-e=\"corpicker\"]').value = t.value;\n    }\n  } else if (d.it) {\n    pn.itens[+d.idx][d.it] = t.value.trim() === '' ? '' : d.it === 'emoji' ? t.value.trim() : t.value;\n  } else if (d.ia) {\n    const it = pn.itens[+d.idx];\n    if (d.ia === 'tipo') {\n      it.acao = { tipo: t.value, mensagem: '' };\n      if (t.value === 'cargo') it.acao.modo = 'alternar';\n      redesenhar = true;\n    } else it.acao[d.ia] = t.value;\n  }\n  marcarSujo(true);\n  if (redesenhar || (estrutura && (d.p === 'tipo' || d.ia === 'tipo' || d.p === 'servidor'))) {\n    const y = $('#principal').scrollTop;\n    telaPaineis();\n    $('#principal').scrollTop = y;\n  } else previaPainel(pn);\n}\n\nfunction cliquePainel(e) {\n  const b = e.target.closest('[data-acao], [data-it-estilo]');\n  if (!b || !(b.closest('[data-pn]') || /painel/.test(b.dataset.acao || ''))) return false;\n  const pns = valores.criados.paineis;\n  const pn = pns.find((p) => p.id === painelSel);\n  const ac = b.dataset.acao;\n  const redesenha = () => { const y = $('#principal').scrollTop; telaPaineis(); $('#principal').scrollTop = y; marcarSujo(true); atualizarContagemMenu(); };\n  if (ac === 'novo-painel') {\n    const id = novoId('painel', pns.map((p) => p.id));\n    const sv = dados.servidores?.[0]?.id || '';\n    pns.push({ id, nome: `Painel ${pns.length + 1}`, servidor: sv, tipo: 'botoes', placeholder: '', conteudo: '', embed: { titulo: 'Título do painel', descricao: 'Clique num botão abaixo.', cor: '', imagem: '', miniatura: '', rodape: '' }, itens: [] });\n    painelSel = id;\n    pns.at(-1).itens.push(novoItem(pns.at(-1)));\n    redesenha();\n    return true;\n  }\n  if (ac === 'sel-painel') { painelSel = b.dataset.id; telaPaineis(); return true; }\n  if (!pn) return false;\n  if (b.dataset.itEstilo) {\n    pn.itens[+b.dataset.idx].estilo = b.dataset.itEstilo;\n    b.parentElement.querySelectorAll('.sw').forEach((x) => x.classList.toggle('on', x === b));\n    marcarSujo(true);\n    previaPainel(pn);\n    return true;\n  }\n  const n = +b.dataset.idx;\n  if (ac === 'item-novo') { if (pn.itens.length < 25) pn.itens.push(novoItem(pn)); redesenha(); return true; }\n  if (ac === 'item-apaga') { pn.itens.splice(n, 1); redesenha(); return true; }\n  if (ac === 'item-sobe' && n > 0) { [pn.itens[n - 1], pn.itens[n]] = [pn.itens[n], pn.itens[n - 1]]; redesenha(); return true; }\n  if (ac === 'item-desce' && n < pn.itens.length - 1) { [pn.itens[n + 1], pn.itens[n]] = [pn.itens[n], pn.itens[n + 1]]; redesenha(); return true; }\n  if (ac === 'dup-painel' && pns.length < 25) {\n    const c = structuredClone(pn);\n    c.id = novoId(pn.id, pns.map((p) => p.id));\n    c.nome = `${pn.nome} (cópia)`;\n    pns.push(c);\n    painelSel = c.id;\n    redesenha();\n    return true;\n  }\n  if (ac === 'del-painel') {\n    if (!confirm(`Apagar o painel \"${pn.nome}\"? Mensagens já enviadas dele param de funcionar.`)) return true;\n    pns.splice(pns.indexOf(pn), 1);\n    painelSel = null;\n    redesenha();\n    return true;\n  }\n  return ['item-sobe', 'item-desce'].includes(ac);\n}\n\n// ---------------- formulários criados ----------------\nlet formSel = null;\nfunction telaFormularios() {\n  $('#tituloPagina').textContent = 'Formulários';\n  const fs = valores.criados.formularios;\n  if (!fs.some((f) => f.id === formSel)) formSel = fs[0]?.id ?? null;\n  let h = `<div class=\"conteudo\"><div class=\"titulo-sec\"><div><h2>Formulários</h2><p>Janelas com até 5 perguntas. As respostas vão para o canal que você escolher.</p></div><button class=\"btn pri\" data-acao=\"novo-form\" ${fs.length >= 25 ? 'disabled' : ''}>+ Novo formulário</button></div>\n    <div class=\"dica\">Para abrir um formulário, crie um <b>Painel</b> com um botão (ou opção de menu) com a ação <b>Abrir formulário</b>.</div>`;\n  if (!fs.length) h += '<div class=\"dica\">Nenhum formulário ainda. Clique em <b>+ Novo formulário</b>.</div>';\n  else h += `<div class=\"lista-criados\">${fs.map((f) => `<button data-acao=\"sel-form\" data-id=\"${esc(f.id)}\" class=\"${f.id === formSel ? 'on' : ''}\">${esc(f.titulo)}</button>`).join('')}</div>`;\n  const f = fs.find((x) => x.id === formSel);\n  if (f) h += editorFormulario(f);\n  $('#area').innerHTML = h + '</div>';\n  if (f) previaFormulario(f);\n}\n\nfunction editorFormulario(f) {\n  const sid = f.servidor;\n  const perguntas = f.perguntas.map((q, n) => `<div class=\"item\" data-q=\"${n}\">\n    <div class=\"cab\"><b>Pergunta ${n + 1}</b><span class=\"esp\"></span><div class=\"mini-btns\"><button data-acao=\"q-sobe\" data-idx=\"${n}\">↑</button><button data-acao=\"q-desce\" data-idx=\"${n}\">↓</button><button class=\"perigo\" data-acao=\"q-apaga\" data-idx=\"${n}\">✕</button></div></div>\n    <div class=\"linha2\" style=\"margin-top:0\">\n      <div><span class=\"campo-rot\">Pergunta (até 45 letras)</span><input class=\"campo\" data-qf=\"rotulo\" data-idx=\"${n}\" maxlength=\"45\" value=\"${esc(q.rotulo)}\"></div>\n      <div><span class=\"campo-rot\">Dica dentro do campo</span><input class=\"campo\" data-qf=\"placeholder\" data-idx=\"${n}\" maxlength=\"100\" placeholder=\"opcional\" value=\"${esc(q.placeholder)}\"></div>\n    </div>\n    <div class=\"linha3\">\n      <div><span class=\"campo-rot\">Tamanho da resposta</span><select data-qf=\"longa\" data-idx=\"${n}\"><option value=\"\">Curta (1 linha)</option><option value=\"1\" ${q.longa ? 'selected' : ''}>Longa (parágrafo)</option></select></div>\n      <div><span class=\"campo-rot\">Mínimo de letras</span><input class=\"campo\" type=\"number\" min=\"0\" max=\"4000\" data-qf=\"min\" data-idx=\"${n}\" value=\"${q.min || 0}\"></div>\n      <div><span class=\"campo-rot\">Máximo de letras</span><input class=\"campo\" type=\"number\" min=\"1\" max=\"4000\" data-qf=\"max\" data-idx=\"${n}\" value=\"${q.max}\"></div>\n    </div>\n    <div class=\"mt\"><label class=\"chave-liga\"><input type=\"checkbox\" data-qf=\"obrigatoria\" data-idx=\"${n}\" ${q.obrigatoria ? 'checked' : ''}> Obrigatória</label></div>\n  </div>`).join('');\n  return `<div class=\"cartao\" data-fm=\"${esc(f.id)}\">\n    <div class=\"linha2\" style=\"margin-top:0\">\n      <div><span class=\"campo-rot\">Título (até 45 letras)</span><input class=\"campo\" data-f=\"titulo\" maxlength=\"45\" value=\"${esc(f.titulo)}\"></div>\n      <div><span class=\"campo-rot\">Servidor</span><select data-f=\"servidor\">${opcoesServidor(f.servidor, 'Escolha o servidor')}</select></div>\n    </div>\n    ${semServidores()}\n    <div class=\"linha2\">\n      <div><span class=\"campo-rot\">Canal que recebe as respostas</span><select data-f=\"canal\">${opcoes(canaisDe(sid, 'texto'), f.canal, sid ? 'Escolha o canal' : 'Escolha o servidor primeiro', '# ')}</select></div>\n      <div><span class=\"campo-rot\">Cargo para quem enviar (opcional)</span><select data-f=\"cargo\">${opcoes(cargosDe(sid), f.cargo, 'Nenhum', '@')}</select></div>\n    </div>\n    <div class=\"mt\"><span class=\"campo-rot\">Mensagem depois de enviar (opcional)</span><input class=\"campo\" data-f=\"mensagem\" maxlength=\"2000\" placeholder=\"Padrão: Formulário enviado! Obrigado. · variáveis {usuario} {nome} {servidor}\" value=\"${esc(f.mensagem)}\"></div>\n    <div class=\"sub-grupo\">Perguntas (${f.perguntas.length}/5)</div>\n    ${perguntas}\n    <button class=\"btn mais\" data-acao=\"q-nova\" ${f.perguntas.length >= 5 ? 'disabled' : ''}>+ Adicionar pergunta</button>\n    <div class=\"avisos-form mt\"></div>\n    <div class=\"sub-grupo\">Prévia</div>\n    <div class=\"previa-form\"></div>\n    <div class=\"mt\" style=\"display:flex;justify-content:flex-end\"><button class=\"btn peq\" data-acao=\"del-form\" style=\"border-color:var(--red);color:var(--red)\">Apagar formulário</button></div>\n  </div>`;\n}\n\nfunction previaFormulario(f) {\n  const el = $('#area').querySelector('[data-fm]');\n  if (!el) return;\n  el.querySelector('.previa-form').innerHTML = `<div class=\"dmodal\"><h4>${esc(f.titulo || 'Formulário')}</h4>${f.perguntas.map((q) => `<label>${esc(q.rotulo || 'Pergunta')} ${q.obrigatoria ? '<i>*</i>' : ''}</label><div class=\"inp ${q.longa ? 'longa' : ''}\">${esc(q.placeholder)}</div>`).join('')}<div class=\"acoes\"><span class=\"dbtn Secondary\">Cancelar</span><span class=\"dbtn Primary\">Enviar</span></div></div>`;\n  const av = [];\n  if (!f.titulo.trim()) av.push('Coloque um título.');\n  if (!f.perguntas.length) av.push('Adicione pelo menos uma pergunta.');\n  if (f.perguntas.some((q) => !q.rotulo.trim())) av.push('Toda pergunta precisa de texto.');\n  if (f.perguntas.some((q) => q.min > q.max)) av.push('O mínimo de letras não pode passar do máximo.');\n  if (!f.canal) av.push('Escolha o canal que recebe as respostas.');\n  el.querySelector('.avisos-form').innerHTML = av.map((a) => `<div class=\"alerta erro\">${esc(a)}</div>`).join('');\n}\n\nfunction editarFormulario(e, estrutura = false) {\n  const f = valores.criados.formularios.find((x) => x.id === formSel);\n  if (!f) return;\n  const t = e.target;\n  const d = t.dataset;\n  if (d.f) {\n    f[d.f] = t.value;\n    if (d.f === 'titulo') $('#area').querySelector(`.lista-criados [data-id=\"${CSS.escape(f.id)}\"]`).textContent = f.titulo || '(sem título)';\n  } else if (d.qf) {\n    const q = f.perguntas[+d.idx];\n    if (d.qf === 'obrigatoria') q.obrigatoria = t.checked;\n    else if (d.qf === 'longa') { q.longa = !!t.value; q.max = Math.min(q.max, 4000); if (q.longa && q.max === 200) q.max = 1000; if (!q.longa && q.max === 1000) q.max = 200; }\n    else if (d.qf === 'min' || d.qf === 'max') q[d.qf] = Math.max(d.qf === 'max' ? 1 : 0, Math.min(4000, parseInt(t.value, 10) || 0));\n    else q[d.qf] = t.value;\n  }\n  marcarSujo(true);\n  if (estrutura && (d.f === 'servidor' || d.qf === 'longa')) {\n    if (d.f === 'servidor') { f.canal = ''; f.cargo = ''; }\n    const y = $('#principal').scrollTop; telaFormularios(); $('#principal').scrollTop = y;\n  } else previaFormulario(f);\n}\n\nfunction cliqueFormulario(e) {\n  const b = e.target.closest('[data-acao]');\n  if (!b || !/form|^q-/.test(b.dataset.acao)) return false;\n  const fs = valores.criados.formularios;\n  const f = fs.find((x) => x.id === formSel);\n  const ac = b.dataset.acao;\n  const redesenha = () => { const y = $('#principal').scrollTop; telaFormularios(); $('#principal').scrollTop = y; marcarSujo(true); atualizarContagemMenu(); };\n  if (ac === 'novo-form') {\n    const id = novoId('formulario', fs.map((x) => x.id));\n    fs.push({ id, titulo: `Formulário ${fs.length + 1}`, servidor: dados.servidores?.[0]?.id || '', canal: '', cargo: '', mensagem: '', perguntas: [{ rotulo: 'Qual o seu nome?', placeholder: '', longa: false, obrigatoria: true, min: 0, max: 200 }] });\n    formSel = id;\n    redesenha();\n    return true;\n  }\n  if (ac === 'sel-form') { formSel = b.dataset.id; telaFormularios(); return true; }\n  if (!f) return false;\n  const n = +b.dataset.idx;\n  if (ac === 'q-nova' && f.perguntas.length < 5) { f.perguntas.push({ rotulo: 'Nova pergunta', placeholder: '', longa: false, obrigatoria: true, min: 0, max: 200 }); redesenha(); return true; }\n  if (ac === 'q-apaga') { f.perguntas.splice(n, 1); redesenha(); return true; }\n  if (ac === 'q-sobe' && n > 0) { [f.perguntas[n - 1], f.perguntas[n]] = [f.perguntas[n], f.perguntas[n - 1]]; redesenha(); return true; }\n  if (ac === 'q-desce' && n < f.perguntas.length - 1) { [f.perguntas[n + 1], f.perguntas[n]] = [f.perguntas[n], f.perguntas[n + 1]]; redesenha(); return true; }\n  if (ac === 'del-form') {\n    const usado = valores.criados.paineis.filter((p) => p.itens.some((it) => it.acao.tipo === 'formulario' && it.acao.formulario === f.id));\n    if (!confirm(usado.length ? `Este formulário é usado em: ${usado.map((p) => p.nome).join(', ')}. Apagar mesmo assim?` : `Apagar o formulário \"${f.titulo}\"?`)) return true;\n    fs.splice(fs.indexOf(f), 1);\n    formSel = null;\n    redesenha();\n    return true;\n  }\n  return true;\n}\n\n// ---------------- arquivos ----------------\n$('#btnAbrir').addEventListener('click', () => $('#arquivo').click());\n$('#btnSalvar').addEventListener('click', salvar);\n$('#arquivo').addEventListener('change', (e) => {\n  const f = e.target.files[0];\n  if (!f) return;\n  if (sujo && !confirm('Você tem alterações não salvas. Abrir outro arquivo mesmo assim?')) return;\n  f.text().then((t) => abrirJson(t, f.name));\n  e.target.value = '';\n});\ndocument.addEventListener('dragover', (e) => { e.preventDefault(); $('#solta')?.classList.add('sobre'); });\ndocument.addEventListener('dragleave', (e) => { if (!e.relatedTarget) $('#solta')?.classList.remove('sobre'); });\ndocument.addEventListener('drop', (e) => {\n  e.preventDefault();\n  $('#solta')?.classList.remove('sobre');\n  const f = e.dataTransfer.files[0];\n  if (!f) return;\n  if (sujo && !confirm('Você tem alterações não salvas. Abrir outro arquivo mesmo assim?')) return;\n  f.text().then((t) => abrirJson(t, f.name));\n});\ndocument.addEventListener('keydown', (e) => {\n  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') { e.preventDefault(); salvar(); }\n});\nwindow.addEventListener('beforeunload', (e) => { if (sujo) { e.preventDefault(); e.returnValue = ''; } });\n\ntelaVazia();\n</script>\n</body>\n</html>\n",
  "extras/transferidor/Transferir dados.bat": "@echo off\nrem Transferidor de dados: de dois cliques neste arquivo (ele fica dentro da pasta do bot NOVO).\ntitle Transferir dados do bot\npowershell -NoProfile -ExecutionPolicy Bypass -STA -File \"%~dp0transferir-dados.ps1\"\nif errorlevel 1 pause\n",
  "extras/transferidor/transferir-dados.ps1": "﻿# Transferidor de dados do bot (usado pelo \"Transferir dados.bat\").\n# Copia a pasta \"data\" e o arquivo \".env\" de um bot antigo para este bot (a pasta onde este arquivo está).\n# Nada é apagado: os dados que este bot já tinha vão para uma pasta \"data-backup-...\".\n\n$ErrorActionPreference = 'Stop'\nAdd-Type -AssemblyName System.Windows.Forms\n[System.Windows.Forms.Application]::EnableVisualStyles()\n\n$titulo = 'Transferir dados do bot'\nfunction Aviso([string]$texto, [string]$icone = 'Information') {\n  [void][System.Windows.Forms.MessageBox]::Show($texto, $titulo, 'OK', $icone)\n}\nfunction UltimaMudanca($arquivos) {\n  if (-not $arquivos) { return $null }\n  return ($arquivos | Sort-Object LastWriteTime -Descending | Select-Object -First 1).LastWriteTime\n}\nfunction NomeDoBot([string]$pasta) {\n  try { return (Get-Content (Join-Path $pasta 'config.json') -Raw -Encoding UTF8 | ConvertFrom-Json).nome } catch { return '(sem nome)' }\n}\n\ntry {\n  $destino = $PSScriptRoot\n  if (-not (Test-Path (Join-Path $destino 'index.js')) -or -not (Test-Path (Join-Path $destino 'config.json'))) {\n    Aviso \"Este arquivo precisa ficar dentro da pasta do bot NOVO (junto do index.js).`n`nPasta atual:`n$destino\" 'Warning'\n    exit 1\n  }\n\n  # 1) escolher a pasta do bot antigo\n  $janela = New-Object System.Windows.Forms.FolderBrowserDialog\n  $janela.Description = 'Escolha a pasta do bot ANTIGO (a que tem os dados que você quer manter)'\n  $janela.ShowNewFolderButton = $false\n  if ($janela.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { exit 0 }\n  $origem = $janela.SelectedPath\n\n  # se escolheu a própria pasta \"data\", sobe um nível\n  if ((Split-Path $origem -Leaf) -ieq 'data' -and (Test-Path (Join-Path (Split-Path $origem -Parent) 'config.json'))) {\n    $origem = Split-Path $origem -Parent\n  }\n  if ((Resolve-Path $origem).Path.TrimEnd('\\') -ieq (Resolve-Path $destino).Path.TrimEnd('\\')) {\n    Aviso 'Você escolheu a pasta deste mesmo bot. Escolha a pasta do bot ANTIGO.' 'Warning'\n    exit 1\n  }\n\n  # 2) conferir se é mesmo um bot com dados\n  $dataOrigem = Join-Path $origem 'data'\n  $arqOrigem = @(Get-ChildItem $dataOrigem -Filter '*.json' -File -ErrorAction SilentlyContinue)\n  if (-not (Test-Path (Join-Path $origem 'config.json')) -or $arqOrigem.Count -eq 0) {\n    Aviso \"Essa pasta não parece ser um bot com dados (não achei config.json e a pasta data com arquivos).`n`n$origem\" 'Warning'\n    exit 1\n  }\n\n  $dataDestino = Join-Path $destino 'data'\n  $arqDestino = @(Get-ChildItem $dataDestino -Filter '*.json' -File -ErrorAction SilentlyContinue)\n  $ultimaOrigem = UltimaMudanca $arqOrigem\n  $ultimaDestino = UltimaMudanca $arqDestino\n  $temEnv = Test-Path (Join-Path $origem '.env')\n  $fmt = 'dd/MM/yyyy HH:mm'\n\n  # 3) resumo e confirmação\n  $linhas = @(\n    \"DE (bot antigo): $(NomeDoBot $origem)\",\n    $origem,\n    \"$($arqOrigem.Count) arquivo(s) de dados · última atividade em $($ultimaOrigem.ToString($fmt))\",\n    '',\n    \"PARA (este bot): $(NomeDoBot $destino)\",\n    $destino,\n    ''\n  )\n  if ($temEnv) { $linhas += 'O token (.env) também será copiado.' } else { $linhas += 'Não achei o .env no bot antigo: configure o token depois.' }\n  if ($arqDestino.Count -gt 0) {\n    $linhas += \"Os $($arqDestino.Count) arquivo(s) de dados que este bot já tem vão para uma cópia de segurança.\"\n    if ($ultimaDestino -gt $ultimaOrigem) {\n      $linhas += ''\n      $linhas += \"ATENÇÃO: este bot tem dados MAIS NOVOS ($($ultimaDestino.ToString($fmt))) que o antigo ($($ultimaOrigem.ToString($fmt))). Confira se escolheu as pastas certas.\"\n    }\n  }\n  $linhas += ''\n  $linhas += 'Antes de continuar, DESLIGUE o bot antigo (feche o terminal dele).'\n  $linhas += ''\n  $linhas += 'Copiar agora?'\n  $icone = if ($ultimaDestino -and $ultimaDestino -gt $ultimaOrigem) { 'Warning' } else { 'Question' }\n  $resp = [System.Windows.Forms.MessageBox]::Show(($linhas -join \"`n\"), $titulo, 'YesNo', $icone)\n  if ($resp -ne [System.Windows.Forms.DialogResult]::Yes) { exit 0 }\n\n  # 4) cópia de segurança do que este bot já tinha\n  $carimbo = Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'\n  $backup = $null\n  if (Test-Path $dataDestino) {\n    $backup = Join-Path $destino \"data-backup-$carimbo\"\n    Move-Item $dataDestino $backup\n  }\n\n  # 5) copia os dados e o token\n  Copy-Item $dataOrigem $dataDestino -Recurse -Force\n  if ($temEnv) {\n    $envDestino = Join-Path $destino '.env'\n    if (Test-Path $envDestino) { Copy-Item $envDestino (Join-Path $destino \".env.backup-$carimbo\") -Force }\n    Copy-Item (Join-Path $origem '.env') $envDestino -Force\n  }\n\n  # 6) instala as dependências, se ainda não instalou\n  $instalou = $true\n  if (-not (Test-Path (Join-Path $destino 'node_modules'))) {\n    if (Get-Command npm -ErrorAction SilentlyContinue) {\n      Write-Host 'Instalando as dependências do bot (npm install)... aguarde.'\n      Push-Location $destino\n      & npm install --no-audit --no-fund\n      $instalou = ($LASTEXITCODE -eq 0)\n      Pop-Location\n    } else { $instalou = $false }\n  }\n\n  $fim = @(\"Pronto! $($arqOrigem.Count) arquivo(s) de dados copiados.\")\n  if ($backup) { $fim += \"Os dados antigos deste bot estão guardados em: $(Split-Path $backup -Leaf)\" }\n  if (-not $instalou) { $fim += ''; $fim += 'Falta instalar: abra um terminal nesta pasta e rode  npm install  (precisa do Node.js).' }\n  $fim += ''\n  $fim += 'Agora é só ligar este bot (npm start). Pode apagar a pasta do bot antigo depois de conferir que está tudo certo.'\n  Aviso ($fim -join \"`n\")\n  exit 0\n} catch {\n  Aviso \"Algo deu errado e nada foi apagado.`n`n$($_.Exception.Message)\" 'Error'\n  exit 1\n}\n",
  "index.js": "import './src/core/env.js';\nimport { existsSync, unlinkSync } from 'node:fs';\nimport {\n  Client,\n  Events,\n  GatewayIntentBits,\n  InteractionContextType,\n  MessageFlags,\n  OAuth2Scopes,\n  PermissionFlagsBits,\n  PermissionsBitField,\n  REST,\n  Routes,\n  SlashCommandBuilder,\n} from 'discord.js';\nimport { CONFIG, erroGenerico, aplicarPresenca } from './src/core/util.js';\nimport { registrarNomeModulo } from './src/core/textos.js';\nimport { salvarTudo } from './src/core/db.js';\nimport nucleo, { registrarModulos } from './src/core/nucleo.js';\n\nconst token = process.env.DISCORD_TOKEN;\nif (!token) {\n  console.error('❌ Falta o token do bot. Copie o arquivo .env.example para .env e preencha DISCORD_TOKEN (veja o README).');\n  process.exit(1);\n}\n\n// ---------------- módulos ----------------\n// A lista vem do config.json. Cada módulo é um arquivo em src/modules.\nconst modulos = [nucleo];\nfor (const id of CONFIG.modulos ?? []) {\n  try {\n    const m = (await import(`./src/modules/${id}.js`)).default;\n    modulos.push(m);\n  } catch (e) {\n    console.error(`❌ Não consegui carregar o módulo \"${id}\": ${e.message}`);\n  }\n}\nregistrarModulos(modulos);\nfor (const m of modulos) if (m.id !== 'nucleo') registrarNomeModulo(m.id, m.nome);\n\nconst intents = new Set([GatewayIntentBits.Guilds]);\nconst partials = new Set();\n// permissões que o bot pede no link de convite: as básicas + as de cada módulo\nconst permissoes = new PermissionsBitField([\n  PermissionFlagsBits.ViewChannel,\n  PermissionFlagsBits.SendMessages,\n  PermissionFlagsBits.SendMessagesInThreads,\n  PermissionFlagsBits.EmbedLinks,\n  PermissionFlagsBits.AttachFiles,\n  PermissionFlagsBits.ReadMessageHistory,\n  PermissionFlagsBits.UseExternalEmojis,\n  PermissionFlagsBits.AddReactions,\n]);\nfor (const m of modulos) {\n  for (const x of m.intents ?? []) intents.add(x);\n  for (const p of m.partials ?? []) partials.add(p);\n  for (const p of m.permissoes ?? []) permissoes.add(p);\n}\n\nconst client = new Client({ intents: [...intents], partials: [...partials] });\n\n// ---------------- comandos ----------------\nconst comandos = new Map();\nfor (const m of modulos) {\n  for (const c of m.comandos ?? []) comandos.set(c.data.name, { ...c, modulo: m });\n}\n\n// /config: os subcomandos gerais + um grupo para cada módulo que tem configuração\nconst config = new SlashCommandBuilder()\n  .setName('config')\n  .setDescription('Configura o bot neste servidor')\n  .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild);\nnucleo.montarConfigRaiz(config);\nfor (const m of modulos) {\n  if (m.config?.montar) config.addSubcommandGroup((g) => m.config.montar(g.setName(m.config.grupo)));\n}\ncomandos.set('config', {\n  data: config,\n  modulo: nucleo,\n  async executar(i) {\n    const grupo = i.options.getSubcommandGroup(false);\n    const sub = i.options.getSubcommand();\n    if (!grupo) return nucleo.executarConfigRaiz(i, sub);\n    const m = modulos.find((x) => x.config?.grupo === grupo);\n    return m?.config.executar(i, sub);\n  },\n});\n\n// todos os comandos funcionam só dentro de servidores\nfor (const c of comandos.values()) c.data.setContexts?.(InteractionContextType.Guild);\n\n// botões, menus e formulários: o customId começa com o prefixo do módulo (\"tk:abrir\", \"sr:entrar:123\"...)\nconst componentes = new Map();\nconst prefixosDM = new Set(); // botões que também funcionam na DM (ex.: avaliação de atendimento)\nfor (const m of modulos) {\n  for (const [prefixo, fn] of Object.entries(m.componentes ?? {})) componentes.set(prefixo, fn);\n  for (const prefixo of m.componentesDM ?? []) prefixosDM.add(prefixo);\n}\n\n// ---------------- eventos dos módulos ----------------\n// Cada evento chama os módulos em sequência. Quem tem \"prioridade\" menor roda antes\n// (o AutoMod roda primeiro: assim os outros já sabem se a mensagem foi apagada).\nconst eventos = new Map();\nfor (const m of [...modulos].sort((a, b) => (a.prioridade ?? 10) - (b.prioridade ?? 10))) {\n  for (const [nome, fn] of Object.entries(m.eventos ?? {})) {\n    if (!eventos.has(nome)) eventos.set(nome, []);\n    eventos.get(nome).push({ fn, modulo: m.id });\n  }\n}\nfor (const [nome, lista] of eventos) {\n  client.on(nome, async (...args) => {\n    for (const { fn, modulo } of lista) {\n      try {\n        await fn(...args);\n      } catch (e) {\n        console.error(`[${modulo}] erro no evento ${nome}:`, e);\n      }\n    }\n  });\n}\n\n// ---------------- interações ----------------\nasync function avisarErro(i) {\n  const payload = { content: erroGenerico(), flags: MessageFlags.Ephemeral };\n  if (i.deferred || i.replied) await i.followUp(payload).catch(() => {});\n  else await i.reply(payload).catch(() => {});\n}\n\nclient.on(Events.InteractionCreate, async (i) => {\n  if (!i.inGuild()) {\n    // fora de servidor, só os botões/formulários que os módulos liberaram para a DM\n    const componente = i.isButton() || i.isAnySelectMenu() || i.isModalSubmit();\n    if (!componente || !prefixosDM.has(i.customId.split(':')[0])) return;\n  }\n  try {\n    if (i.isAutocomplete()) {\n      const c = comandos.get(i.commandName);\n      if (c?.autocompletar) await c.autocompletar(i);\n      return;\n    }\n    if (i.isChatInputCommand()) {\n      const c = comandos.get(i.commandName);\n      if (c) await c.executar(i);\n      return;\n    }\n    if (i.isButton() || i.isAnySelectMenu() || i.isModalSubmit()) {\n      const partes = i.customId.split(':');\n      const fn = componentes.get(partes[0]);\n      if (fn) await fn(i, partes.slice(1));\n    }\n  } catch (e) {\n    console.error('[interação] erro:', e);\n    if (i.isRepliable()) await avisarErro(i);\n  }\n});\n\n// ---------------- ligar ----------------\nclient.once(Events.ClientReady, async (c) => {\n  console.log(`✅ ${CONFIG.nome || c.user.username} online como ${c.user.tag} · em ${c.guilds.cache.size} servidor(es)`);\n  console.log(`   Módulos: ${modulos.map((m) => m.nome).join(', ')}`);\n  const convite = c.generateInvite({ scopes: [OAuth2Scopes.Bot, OAuth2Scopes.ApplicationsCommands], permissions: permissoes });\n  console.log(`   Link para adicionar o bot a um servidor:\\n   ${convite}`);\n\n  const corpo = [...comandos.values()].map((x) => x.data.toJSON());\n  const rest = new REST({ version: '10' }).setToken(token);\n  try {\n    if (process.env.GUILD_ID) {\n      await rest.put(Routes.applicationGuildCommands(c.user.id, process.env.GUILD_ID), { body: corpo });\n      console.log(`   ${corpo.length} comandos registrados no servidor ${process.env.GUILD_ID}.`);\n    } else {\n      await rest.put(Routes.applicationCommands(c.user.id), { body: corpo });\n      console.log(`   ${corpo.length} comandos registrados em todos os servidores.`);\n    }\n  } catch (e) {\n    console.error('❌ Não consegui registrar os comandos:', e.message);\n  }\n\n  aplicarPresenca(c);\n\n  for (const m of modulos) {\n    try {\n      await m.aoIniciar?.(c);\n    } catch (e) {\n      console.error(`[${m.id}] erro ao iniciar:`, e);\n    }\n  }\n});\n\n// salva os dados antes de desligar\nconst desligar = () => {\n  salvarTudo();\n  process.exit(0);\n};\nfor (const sinal of ['SIGINT', 'SIGTERM']) process.on(sinal, desligar);\n\n// O Inicializador liga o bot sem janela; para desligar com segurança ele cria o arquivo \".parar\"\nconst arquivoParar = new URL('./.parar', import.meta.url);\nsetInterval(() => {\n  if (!existsSync(arquivoParar)) return;\n  try { unlinkSync(arquivoParar); } catch { /* já apagado */ }\n  console.log('⏹️ Desligando a pedido do Inicializador...');\n  desligar();\n}, 2000).unref();\nprocess.on('unhandledRejection', (e) => console.error('[erro]', e));\n\nclient.login(token).catch((e) => {\n  console.error('❌ Não consegui entrar no Discord:', e.message);\n  if (e.code === 'TokenInvalid' || /invalid token/i.test(e.message)) {\n    console.error('   O token está errado. Gere outro no Developer Portal → Bot → Reset Token e cole no .env.');\n  }\n  if (/disallowed intents/i.test(e.message)) {\n    console.error('   Ative as \"Privileged Gateway Intents\" pedidas no README, no Developer Portal → Bot.');\n  }\n  process.exit(1);\n});\n",
  "package.json": "{\n  \"name\": \"meu-bot\",\n  \"version\": \"1.0.0\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"scripts\": {\n    \"start\": \"node index.js\"\n  },\n  \"engines\": {\n    \"node\": \">=18.17\"\n  },\n  \"dependencies\": {\n    \"discord.js\": \"^14.16.3\",\n    \"dotenv\": \"^16.4.7\"\n  }\n}\n",
  "src/core/db.js": "import fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\n\n/**\n * Armazenamento simples em arquivos JSON (pasta \"data\", ao lado do index.js).\n * Não precisa instalar banco de dados: cada coleção vira um arquivo, ex.: data/niveis.json.\n * Para fazer backup, basta copiar a pasta \"data\".\n *\n *   const niveis = colecao('niveis');\n *   const membro = niveis.de(guildId, userId);   // cria o objeto se não existir\n *   membro.xp = (membro.xp ?? 0) + 10;\n *   niveis.salvar();                            // grava em até 1,5 s (junta várias mudanças)\n */\n\nconst PASTA = fileURLToPath(new URL('../../data', import.meta.url));\nfs.mkdirSync(PASTA, { recursive: true });\n\nconst cache = new Map();\nconst timers = new Map();\nconst arquivo = (nome) => path.join(PASTA, `${nome}.json`);\n\nfunction carregar(nome) {\n  if (cache.has(nome)) return cache.get(nome);\n  let dados = {};\n  try {\n    dados = JSON.parse(fs.readFileSync(arquivo(nome), 'utf8'));\n  } catch (e) {\n    if (e.code !== 'ENOENT') {\n      // arquivo corrompido: guarda uma cópia e começa do zero, sem derrubar o bot\n      const copia = arquivo(`${nome}.corrompido-${Date.now()}`);\n      try { fs.renameSync(arquivo(nome), copia); } catch { /* sem cópia */ }\n      console.error(`[dados] ${nome}.json estava corrompido. Cópia salva em ${copia}`);\n    }\n  }\n  cache.set(nome, dados);\n  return dados;\n}\n\nfunction gravar(nome) {\n  const tmp = `${arquivo(nome)}.tmp`;\n  fs.writeFileSync(tmp, JSON.stringify(cache.get(nome)));\n  fs.renameSync(tmp, arquivo(nome)); // troca de uma vez: o arquivo nunca fica pela metade\n}\n\nfunction agendar(nome) {\n  if (timers.has(nome)) return;\n  timers.set(nome, setTimeout(() => {\n    timers.delete(nome);\n    try { gravar(nome); } catch (e) { console.error(`[dados] Falha ao salvar ${nome}:`, e.message); }\n  }, 1500));\n}\n\nexport function colecao(nome) {\n  const raiz = carregar(nome);\n  return {\n    /** Objeto em raiz[a][b]..., criado se não existir. */\n    de(...chaves) {\n      let o = raiz;\n      for (const k of chaves) {\n        if (o[k] == null || typeof o[k] !== 'object') o[k] = {};\n        o = o[k];\n      }\n      return o;\n    },\n    /** Lê raiz[a][b]... sem criar nada. */\n    ler(...chaves) {\n      let o = raiz;\n      for (const k of chaves) {\n        if (o == null) return undefined;\n        o = o[k];\n      }\n      return o;\n    },\n    apagar(...chaves) {\n      const ultima = chaves.pop();\n      const pai = this.ler(...chaves);\n      if (pai && ultima in pai) delete pai[ultima];\n      agendar(nome);\n    },\n    raiz,\n    salvar() { agendar(nome); },\n  };\n}\n\n/** Grava tudo na hora (usado ao desligar o bot). */\nexport function salvarTudo() {\n  for (const nome of cache.keys()) {\n    clearTimeout(timers.get(nome));\n    timers.delete(nome);\n    try { gravar(nome); } catch (e) { console.error(`[dados] Falha ao salvar ${nome}:`, e.message); }\n  }\n}\n",
  "src/core/env.js": "import { fileURLToPath } from 'node:url';\nimport dotenv from 'dotenv';\n\n// Lê o arquivo .env da pasta do bot (funciona mesmo se o bot for iniciado de outra pasta).\ndotenv.config({ path: fileURLToPath(new URL('../../.env', import.meta.url)), quiet: true });\n",
  "src/core/nucleo.js": "import { SlashCommandBuilder, version as djsVersion } from 'discord.js';\nimport { CONFIG, ajustes, salvarAjustes, embed, responder, responderCampos, duracaoTexto, fmt } from './util.js';\nimport { textos } from './textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('geral', {\n  config_configurar_este_modulo: '`/config {grupo}` · configurar este módulo',\n  cont: '{nome} (cont.)',\n  comandos: ['📖 Comandos do {nome}', 'titulo'],\n  administradores_use_config_ver: ['Administradores: use /config ver para ver tudo o que está configurado', 'rodape'],\n  pong: ['🏓 Pong!', 'titulo'],\n  conexao_gateway: ['Conexão (gateway)', 'campo'],\n  ms: '{ws} ms',\n  medindo: 'medindo…',\n  resposta: ['Resposta', 'campo'],\n  ms_2: '{api} ms',\n  servidores: ['Servidores', 'campo'],\n  membros: ['Membros', 'campo'],\n  online_ha: ['Online há', 'campo'],\n  modulos: ['Módulos', 'campo'],\n  nenhum: 'nenhum',\n  discord_js_node: ['discord.js {djsVersion} · Node {node}', 'rodape'],\n  use_cor_hexadecimal_como: ['Use uma cor em hexadecimal, como **#5865F2**.', 'resposta'],\n  cor_definida: ['Cor definida para **{cor}**.', 'resposta'],\n  cargo_equipe: 'Cargo da equipe: {cargo}.',\n  cargo_equipe_removido: 'Cargo da equipe removido.',\n  geral: ['Geral', 'campo'],\n  padrao: 'padrão',\n  cor: 'Cor: **{cor}**',\n  definida_so_quem_tem: 'não definida (só quem tem Gerenciar servidor)',\n  equipe: 'Equipe: {staff}',\n  configuracao_deste_servidor: ['⚙️ Configuração deste servidor', 'titulo'],\n});\n\n/**\n * Núcleo: vem em todo bot. /ajuda, /ping, /sobre e o começo do /config\n * (/config ver, /config cor, /config staff). Cada módulo instalado acrescenta\n * o seu grupo dentro do /config (ex.: /config logs canal).\n */\n\nlet MODULOS = [];\nexport const registrarModulos = (lista) => { MODULOS = lista; };\n\nconst ajuda = {\n  data: new SlashCommandBuilder().setName('ajuda').setDescription('Mostra todos os comandos do bot'),\n  async executar(i) {\n    const campos = [];\n    for (const m of MODULOS) {\n      const linhas = (m.comandos ?? []).map((c) => `\\`/${c.data.name}\\` · ${c.data.description}`);\n      if (m.config?.grupo) linhas.push(tx('config_configurar_este_modulo', { grupo: m.config.grupo }));\n      if (!linhas.length) continue;\n      // um campo aceita até 1024 caracteres: quebra em partes se precisar\n      let atual = '';\n      let parte = 0;\n      for (const l of linhas) {\n        if ((atual + l + '\\n').length > 1000) {\n          campos.push({ name: parte ? tx('cont', { nome: m.nome }) : m.nome, value: atual });\n          atual = '';\n          parte++;\n        }\n        atual += `${l}\\n`;\n      }\n      if (atual) campos.push({ name: parte ? tx('cont', { nome: m.nome }) : m.nome, value: atual });\n    }\n    await responderCampos(\n      i,\n      () =>\n        embed(i.guildId)\n          .setTitle(tx('comandos', { nome: CONFIG.nome || i.client.user.username }))\n          .setThumbnail(i.client.user.displayAvatarURL())\n          .setFooter({ text: tx('administradores_use_config_ver') }),\n      campos\n    );\n  },\n};\n\nconst ping = {\n  data: new SlashCommandBuilder().setName('ping').setDescription('Mostra a latência do bot'),\n  async executar(i) {\n    const inicio = Date.now();\n    await i.deferReply();\n    const api = Date.now() - inicio;\n    const ws = i.client.ws.ping;\n    await i.editReply({\n      embeds: [\n        embed(i.guildId)\n          .setTitle(tx('pong'))\n          .addFields(\n            { name: tx('conexao_gateway'), value: ws >= 0 ? tx('ms', { ws }) : tx('medindo'), inline: true },\n            { name: tx('resposta'), value: tx('ms_2', { api }), inline: true },\n          ),\n      ],\n    });\n  },\n};\n\nconst sobre = {\n  data: new SlashCommandBuilder().setName('sobre').setDescription('Informações sobre o bot'),\n  async executar(i) {\n    const c = i.client;\n    const membros = c.guilds.cache.reduce((t, g) => t + (g.memberCount || 0), 0);\n    const nomes = MODULOS.filter((m) => m.id !== 'nucleo').map((m) => m.nome);\n    await i.reply({\n      embeds: [\n        embed(i.guildId)\n          .setTitle(CONFIG.nome || c.user.username)\n          .setThumbnail(c.user.displayAvatarURL())\n          .addFields(\n            { name: tx('servidores'), value: fmt(c.guilds.cache.size), inline: true },\n            { name: tx('membros'), value: fmt(membros), inline: true },\n            { name: tx('online_ha'), value: duracaoTexto(c.uptime ?? 0), inline: true },\n            { name: tx('modulos'), value: nomes.length ? nomes.join(', ') : tx('nenhum') },\n          )\n          .setFooter({ text: tx('discord_js_node', { djsVersion, node: process.versions.node }) }),\n      ],\n    });\n  },\n};\n\n/** Subcomandos \"soltos\" do /config (sem grupo). */\nfunction montarConfigRaiz(cmd) {\n  return cmd\n    .addSubcommand((s) => s.setName('ver').setDescription('Mostra tudo o que está configurado neste servidor'))\n    .addSubcommand((s) =>\n      s\n        .setName('cor')\n        .setDescription('Cor das mensagens do bot neste servidor')\n        .addStringOption((o) => o.setName('cor').setDescription('Em hexadecimal, ex.: #5865F2').setRequired(true).setMaxLength(7))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('staff')\n        .setDescription('Cargo da equipe (atende tickets, aprova sugestões...)')\n        .addRoleOption((o) => o.setName('cargo').setDescription('Deixe vazio para remover').setRequired(false))\n    );\n}\n\nasync function executarConfigRaiz(i, sub) {\n  const geral = ajustes(i.guildId, 'geral', { cor: null, staff: null });\n  if (sub === 'cor') {\n    const valor = i.options.getString('cor').trim();\n    if (!/^#?[0-9a-f]{6}$/i.test(valor)) return responder(i, tx('use_cor_hexadecimal_como'), 'erro');\n    geral.cor = valor.startsWith('#') ? valor : `#${valor}`;\n    salvarAjustes();\n    return responder(i, tx('cor_definida', { cor: geral.cor }), 'sucesso');\n  }\n  if (sub === 'staff') {\n    const cargo = i.options.getRole('cargo');\n    geral.staff = cargo?.id ?? null;\n    salvarAjustes();\n    return responder(i, cargo ? tx('cargo_equipe', { cargo }) : tx('cargo_equipe_removido'), 'sucesso');\n  }\n  if (sub === 'ver') {\n    const campos = [\n      {\n        name: tx('geral'),\n        value: [tx('cor', { cor: geral.cor || CONFIG.cor || tx('padrao') }), tx('equipe', { staff: geral.staff ? `<@&${geral.staff}>` : tx('definida_so_quem_tem') })].join('\\n'),\n      },\n    ];\n    for (const m of MODULOS) {\n      if (!m.config?.resumo) continue;\n      const linhas = await m.config.resumo(i.guild);\n      if (linhas?.length) campos.push({ name: m.nome, value: linhas.join('\\n') });\n    }\n    return responderCampos(i, () => embed(i.guildId).setTitle(tx('configuracao_deste_servidor')), campos, { efemero: true });\n  }\n}\n\nexport default {\n  id: 'nucleo',\n  nome: tx('geral'),\n  comandos: [ajuda, ping, sobre],\n  montarConfigRaiz,\n  executarConfigRaiz,\n};\n",
  "src/core/textos.js": "import fs from 'node:fs';\nimport { ButtonBuilder, ButtonStyle, ActionRowBuilder } from 'discord.js';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\n\n/**\n * Textos do bot. Todo texto que o bot manda passa por aqui:\n *\n *   const t = textos('moderacao', { banido: '**{tag}** foi banido(a). Motivo: {motivo}' });\n *   responder(i, t('banido', { tag: user.tag, motivo }));\n *\n * Com o módulo Personalização, o dono do bot troca qualquer texto, as cores, os emojis\n * das respostas e o status pelo arquivo \"Personalizar bot.html\" + /personalizar.\n * O que foi personalizado fica em data/personalizacao.json.\n */\n\n/** Limites do Discord para cada tipo de texto. */\nexport const LIMITES = {\n  texto: 2000,\n  resposta: 3900,\n  descricao: 4000,\n  conteudo: 2000,\n  titulo: 256,\n  campo: 256,\n  valor: 1024,\n  rodape: 2048,\n  autor: 256,\n  botao: 80,\n  rotulo: 45,\n  placeholder: 150,\n  opcao: 100,\n  motivo: 500,\n  canal: 100,\n};\n\nexport const EMOJIS_PADRAO = { sucesso: '✅', erro: '❌', aviso: '⚠️', info: 'ℹ️' };\nexport const CORES_PADRAO = { padrao: '', sucesso: '#22c55e', erro: '#ef4444', aviso: '#f59e0b' };\nexport const PRESENCA_TIPOS = ['personalizado', 'jogando', 'ouvindo', 'assistindo', 'competindo'];\nexport const PRESENCA_STATUS = ['online', 'idle', 'dnd'];\n\nconst ARQUIVO = path.join(fileURLToPath(new URL('../../data', import.meta.url)), 'personalizacao.json');\n\n/** chave completa (\"moderacao.banido\") → { modulo, padrao, tipo, vars } */\nconst catalogo = new Map();\n/** chave completa (\"boasvindas.entrada\") → { modulo, nome, padrao: { cor, imagem, miniatura, rodape }, vars } */\nconst catalogoVisuais = new Map();\nconst nomesModulos = new Map([['geral', 'Comandos gerais (/ajuda, /config…)']]);\n/** chave completa (\"tickets.fechar\") → { modulo, chave, nome, rotulo, emoji, estilo, ocultavel, emojiFixo, rotuloInfo } */\nconst catalogoBotoes = new Map();\n/** chave completa (\"sugestoes.motivo\") → { modulo, nome, textos: [chaves de texto do modal] } */\nconst catalogoModais = new Map();\n\nconst vazio = () => ({ textos: {}, visuais: {}, emojis: {}, cores: {}, presenca: {}, botoes: {}, criados: { paineis: [], formularios: [] } });\nlet valores = vazio();\nlet ativo = false;\n\nconst varsDe = (s) => [...new Set([...String(s).matchAll(/\\{(\\w+)\\}/g)].map((m) => m[1]))];\n\n/** Troca {chave} pelos valores. Chaves desconhecidas ficam como estão. */\nexport const preencher = (modelo, vars = {}) =>\n  String(modelo ?? '').replace(/\\{(\\w+)\\}/g, (m, k) => (k in vars && vars[k] != null ? String(vars[k]) : m));\n\nconst cortarEm = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);\n\n/**\n * Registra os textos de um módulo e devolve a função t(chave, variáveis).\n * Cada texto é uma string ou [string, tipo] (o tipo define o limite do Discord; padrão \"texto\").\n */\nexport function textos(modulo, padroes) {\n  for (const [chave, v] of Object.entries(padroes)) {\n    const [padrao, tipo = 'texto'] = Array.isArray(v) ? v : [v];\n    catalogo.set(`${modulo}.${chave}`, { modulo, chave, padrao, tipo, vars: varsDe(padrao) });\n  }\n  return (chave, vars) => texto(`${modulo}.${chave}`, vars);\n}\n\n/** Um texto pela chave completa (\"moderacao.banido\"). */\nexport function texto(chaveCompleta, vars = {}) {\n  const item = catalogo.get(chaveCompleta);\n  if (!item) return chaveCompleta;\n  const personalizado = ativo ? valores.textos[chaveCompleta] : undefined;\n  const modelo = typeof personalizado === 'string' && personalizado.trim() ? personalizado : item.padrao;\n  return cortarEm(preencher(modelo, vars), LIMITES[item.tipo] ?? LIMITES.texto);\n}\n\n/**\n * Registra a aparência personalizável de embeds importantes (cor, imagem, miniatura, rodapé)\n * e devolve aplicar(embed, chave, variáveis).\n */\nexport function visuais(modulo, lista) {\n  for (const [chave, v] of Object.entries(lista)) {\n    const { nome, vars = [], ...padrao } = v;\n    catalogoVisuais.set(`${modulo}.${chave}`, { modulo, chave, nome, vars, padrao });\n  }\n  return (e, chave, vars) => aplicarVisual(e, `${modulo}.${chave}`, vars);\n}\n\nconst ehUrl = (s) => /^https?:\\/\\/\\S+$/i.test(s);\n\n/** Aplica o que o dono personalizou neste embed. \"-\" remove o item. */\nexport function aplicarVisual(e, chaveCompleta, vars = {}) {\n  if (!ativo) return e;\n  const v = valores.visuais[chaveCompleta];\n  if (!v) return e;\n  if (v.cor && /^#[0-9a-f]{6}$/i.test(v.cor)) e.setColor(parseInt(v.cor.slice(1), 16));\n  for (const [campo, fn] of [\n    ['imagem', (x) => e.setImage(x)],\n    ['miniatura', (x) => e.setThumbnail(x)],\n  ]) {\n    if (!v[campo]) continue;\n    if (v[campo] === '-') fn(null);\n    else {\n      const url = preencher(v[campo], vars).trim();\n      if (ehUrl(url)) fn(url);\n    }\n  }\n  if (v.rodape === '-') e.setFooter(null);\n  else if (v.rodape) e.setFooter({ text: cortarEm(preencher(v.rodape, vars), LIMITES.rodape) });\n  return e;\n}\n\n// ---------------- botões ----------------\nexport const ESTILOS = ['Primary', 'Secondary', 'Success', 'Danger'];\n/** Emoji que o Discord aceita num botão: emoji normal ou <a:nome:id> / <:nome:id>. */\nexport const emojiDeBotaoOk = (e) =>\n  typeof e === 'string' &&\n  e.length <= 64 &&\n  (/^<a?:\\w{2,32}:\\d{15,22}>$/.test(e) || (/^[\\p{Extended_Pictographic}\\p{Regional_Indicator}\\p{Emoji_Modifier}\\u200d\\ufe0f\\u20e3#*0-9]+$/u.test(e) && /[\\p{Extended_Pictographic}\\p{Regional_Indicator}\\u20e3]/u.test(e)));\n\n/**\n * Registra os botões de um módulo e devolve bt(chave, extra) → ButtonBuilder (ou null, se o dono escondeu).\n * Cada botão: { nome, rotulo?: chave de texto do módulo, emoji?, estilo: Primary|Secondary|Success|Danger|Link,\n *               ocultavel?: o dono pode esconder, emojiFixo?: o emoji não muda (ex.: letras da enquete), rotuloInfo?: explica rótulos automáticos }\n * extra: { rotulo, emoji, estilo } do momento (ex.: contagem de votos). O personalizado vence o estilo; o extra vence o rótulo e o emoji.\n */\nexport function botoes(modulo, defs) {\n  for (const [chave, d] of Object.entries(defs)) catalogoBotoes.set(`${modulo}.${chave}`, { modulo, chave, ...d });\n  return (chave, extra) => criarBotao(`${modulo}.${chave}`, extra);\n}\n\nexport function criarBotao(chaveCompleta, extra = {}) {\n  const d = catalogoBotoes.get(chaveCompleta);\n  if (!d) throw new Error(`botão desconhecido: ${chaveCompleta}`);\n  const v = (ativo && valores.botoes[chaveCompleta]) || {};\n  if (d.ocultavel && v.oculto) return null;\n  const b = new ButtonBuilder();\n  const rotulo = extra.rotulo ?? (d.rotulo ? texto(`${d.modulo}.${d.rotulo}`) : '');\n  if (rotulo) b.setLabel(cortarEm(String(rotulo), LIMITES.botao));\n  let emoji = d.emojiFixo ? extra.emoji ?? d.emoji : extra.emoji ?? v.emoji ?? d.emoji;\n  if (emoji === '-') emoji = null;\n  if (!rotulo && !emoji) emoji = extra.emoji || d.emoji || '▫️'; // o Discord exige texto ou emoji\n  if (emoji) b.setEmoji(emoji);\n  const estilo = d.estilo === 'Link' ? 'Link' : v.estilo || extra.estilo || d.estilo || 'Secondary';\n  b.setStyle(ButtonStyle[estilo] ?? ButtonStyle.Secondary);\n  return b;\n}\n\n/** Uma fileira com os botões que sobraram (sem os escondidos). Devolve null se ficou vazia. */\nexport function fileira(...lista) {\n  const bs = lista.flat().filter(Boolean);\n  return bs.length ? new ActionRowBuilder().addComponents(bs.slice(0, 5)) : null;\n}\n/** Lista de fileiras sem as vazias (para components: [...]). */\nexport const fileiras = (...lista) => lista.flat().filter(Boolean);\n\n/** Registra os modais (formulários) de um módulo, só para o painel agrupar os textos deles. */\nexport function modais(modulo, defs) {\n  for (const [chave, d] of Object.entries(defs)) catalogoModais.set(`${modulo}.${chave}`, { modulo, chave, nome: d.nome, textos: d.textos.map((k) => `${modulo}.${k}`) });\n}\n\n/** Painéis e formulários criados pelo dono no Personalizar bot.html. */\nexport const criados = () => (ativo ? valores.criados : { paineis: [], formularios: [] });\n\n/** Emoji das respostas rápidas (sucesso, erro, aviso, info). */\nexport const emojiTipo = (tipo) => (ativo && valores.emojis[tipo]) || EMOJIS_PADRAO[tipo] || '';\n\n/** Cor personalizada (\"padrao\", \"sucesso\", \"erro\", \"aviso\") como número, ou null. */\nexport function corPersonalizada(tipo) {\n  const c = (ativo && valores.cores[tipo]) || CORES_PADRAO[tipo];\n  return c && /^#[0-9a-f]{6}$/i.test(c) ? parseInt(c.slice(1), 16) : null;\n}\n\nexport const registrarNomeModulo = (id, nome) => nomesModulos.set(id, nome);\n\n// ---------------- arquivo data/personalizacao.json ----------------\nfunction carregar() {\n  try {\n    const dados = JSON.parse(fs.readFileSync(ARQUIVO, 'utf8'));\n    valores = { ...vazio(), ...(dados.valores ?? dados) };\n  } catch (e) {\n    if (e.code !== 'ENOENT') console.error('[personalização] não consegui ler data/personalizacao.json:', e.message);\n    valores = vazio();\n  }\n}\n\nfunction gravar() {\n  fs.mkdirSync(path.dirname(ARQUIVO), { recursive: true });\n  const tmp = `${ARQUIVO}.tmp`;\n  fs.writeFileSync(tmp, JSON.stringify({ formato: 'byteup-personalizacao', versao: 1, valores }, null, 2));\n  fs.renameSync(tmp, ARQUIVO);\n}\n\n/** Liga a personalização (o módulo Personalização chama isto ao carregar). */\nexport function ativarPersonalizacao() {\n  ativo = true;\n  carregar();\n}\nexport const personalizacaoAtiva = () => ativo;\nexport const valoresAtuais = () => structuredClone(valores);\n\n/** Status do bot (o que aparece embaixo do nome). */\nexport function presenca(padraoTexto) {\n  const p = ativo ? valores.presenca : {};\n  return {\n    texto: p.texto?.trim() || padraoTexto || '',\n    tipo: PRESENCA_TIPOS.includes(p.tipo) ? p.tipo : 'personalizado',\n    status: PRESENCA_STATUS.includes(p.status) ? p.status : 'online',\n  };\n}\n\n/** O arquivo que o painel abre: catálogo (textos padrão) + o que já foi personalizado. */\nexport function exportar({ nomeBot, modulos, servidores = [] }) {\n  const ordem = new Map((modulos ?? []).map((m, n) => [m.id, n]));\n  const grupos = [...nomesModulos].map(([id, nome]) => ({ id, nome })).sort((a, b) => (ordem.get(a.id) ?? -1) - (ordem.get(b.id) ?? -1));\n  return {\n    formato: 'byteup-personalizacao',\n    versao: 1,\n    bot: nomeBot,\n    gerado: new Date().toISOString(),\n    modulos: grupos,\n    limites: LIMITES,\n    catalogo: {\n      textos: Object.fromEntries([...catalogo].map(([k, v]) => [k, { modulo: v.modulo, padrao: v.padrao, tipo: v.tipo, vars: v.vars }])),\n      visuais: Object.fromEntries([...catalogoVisuais].map(([k, v]) => [k, { modulo: v.modulo, nome: v.nome, vars: v.vars, padrao: v.padrao }])),\n      botoes: Object.fromEntries([...catalogoBotoes].map(([k, v]) => [k, { modulo: v.modulo, nome: v.nome, rotulo: v.rotulo ? `${v.modulo}.${v.rotulo}` : null, rotuloInfo: v.rotuloInfo ?? null, emoji: v.emoji ?? null, estilo: v.estilo, ocultavel: !!v.ocultavel, emojiFixo: !!v.emojiFixo }])),\n      modais: Object.fromEntries([...catalogoModais].map(([k, v]) => [k, { modulo: v.modulo, nome: v.nome, textos: v.textos }])),\n      emojis: EMOJIS_PADRAO,\n      cores: CORES_PADRAO,\n      presenca: { tipos: PRESENCA_TIPOS, status: PRESENCA_STATUS },\n    },\n    servidores,\n    valores: structuredClone(valores),\n  };\n}\n\nconst HEX = /^#[0-9a-f]{6}$/i;\nconst EMOJI_OK = (s) => typeof s === 'string' && s.length <= 100 && (/^<a?:\\w{2,32}:\\d{15,22}>$/.test(s) || !/[<>@#]/.test(s));\n\n/**\n * Confere um arquivo enviado pelo /personalizar aplicar e grava.\n * Devolve { ok, erro?, avisos, total }.\n */\nexport function importar(arquivo) {\n  if (!arquivo || typeof arquivo !== 'object') return { ok: false, erro: 'O arquivo não é um JSON válido.' };\n  if (arquivo.formato !== 'byteup-personalizacao') return { ok: false, erro: 'Esse arquivo não é de personalização (salve pelo \"Personalizar bot.html\").' };\n  const v = arquivo.valores ?? {};\n  const novo = vazio();\n  const avisos = [];\n  let total = 0;\n\n  for (const [k, s] of Object.entries(v.textos ?? {})) {\n    const item = catalogo.get(k);\n    if (!item) { avisos.push(`texto \"${k}\" não existe neste bot (ignorado)`); continue; }\n    if (typeof s !== 'string' || !s.trim() || s === item.padrao) continue;\n    if (s.length > 6000) { avisos.push(`texto \"${k}\" grande demais (ignorado)`); continue; }\n    novo.textos[k] = s;\n    total++;\n  }\n  for (const [k, x] of Object.entries(v.visuais ?? {})) {\n    if (!catalogoVisuais.has(k)) { avisos.push(`aparência \"${k}\" não existe neste bot (ignorada)`); continue; }\n    if (!x || typeof x !== 'object') continue;\n    const limpo = {};\n    if (typeof x.cor === 'string' && HEX.test(x.cor)) limpo.cor = x.cor;\n    for (const campo of ['imagem', 'miniatura']) {\n      const u = typeof x[campo] === 'string' ? x[campo].trim() : '';\n      if (!u) continue;\n      if (u === '-' || ehUrl(u) || /^\\{\\w+\\}$/.test(u)) limpo[campo] = u;\n      else avisos.push(`${campo} de \"${k}\" precisa ser um link https:// (ignorado)`);\n    }\n    if (typeof x.rodape === 'string' && x.rodape.trim()) limpo.rodape = x.rodape.slice(0, LIMITES.rodape);\n    if (Object.keys(limpo).length) { novo.visuais[k] = limpo; total++; }\n  }\n  for (const [k, e] of Object.entries(v.emojis ?? {})) {\n    if (!(k in EMOJIS_PADRAO) || !e || e === EMOJIS_PADRAO[k]) continue;\n    if (!EMOJI_OK(e)) { avisos.push(`emoji de \"${k}\" inválido (ignorado)`); continue; }\n    novo.emojis[k] = e;\n    total++;\n  }\n  for (const [k, c] of Object.entries(v.cores ?? {})) {\n    if (!(k in CORES_PADRAO) || !c || c === CORES_PADRAO[k]) continue;\n    if (!HEX.test(c)) { avisos.push(`cor \"${k}\" inválida (use #RRGGBB)`); continue; }\n    novo.cores[k] = c;\n    total++;\n  }\n  for (const [k, x] of Object.entries(v.botoes ?? {})) {\n    const d = catalogoBotoes.get(k);\n    if (!d) { avisos.push(`botão \"${k}\" não existe neste bot (ignorado)`); continue; }\n    if (!x || typeof x !== 'object') continue;\n    const limpo = {};\n    if (x.emoji && !d.emojiFixo) {\n      if (x.emoji === '-' || emojiDeBotaoOk(x.emoji)) limpo.emoji = x.emoji;\n      else avisos.push(`emoji do botão \"${d.nome}\" inválido (use um emoji ou <:nome:id>)`);\n    }\n    if (x.estilo && d.estilo !== 'Link') {\n      if (ESTILOS.includes(x.estilo)) limpo.estilo = x.estilo;\n      else avisos.push(`cor do botão \"${d.nome}\" inválida`);\n    }\n    if (x.oculto === true && d.ocultavel) limpo.oculto = true;\n    if (Object.keys(limpo).length) { novo.botoes[k] = limpo; total++; }\n  }\n  novo.criados = limparCriados(v.criados, avisos);\n  total += novo.criados.paineis.length + novo.criados.formularios.length;\n\n  const p = v.presenca ?? {};\n  if (typeof p.texto === 'string' && p.texto.trim()) { novo.presenca.texto = p.texto.trim().slice(0, 128); total++; }\n  if (PRESENCA_TIPOS.includes(p.tipo) && p.tipo !== 'personalizado') novo.presenca.tipo = p.tipo;\n  if (PRESENCA_STATUS.includes(p.status) && p.status !== 'online') novo.presenca.status = p.status;\n\n  valores = novo;\n  gravar();\n  return { ok: true, avisos, total };\n}\n\n// ---------------- painéis e formulários criados ----------------\nconst ID = /^[a-z0-9-]{1,32}$/;\nconst SNOW = /^\\d{15,22}$/;\nconst str = (x, max) => (typeof x === 'string' ? x.trim().slice(0, max) : '');\nconst snow = (x) => (typeof x === 'string' && SNOW.test(x) ? x : '');\nconst url = (x) => {\n  const u = str(x, 500);\n  return u && (ehUrl(u) || /^\\{\\w+\\}$/.test(u)) ? u : '';\n};\nexport const ACOES = ['cargo', 'mensagem', 'formulario', 'ticket', 'link'];\n\nfunction limparCriados(c, avisos) {\n  const out = { paineis: [], formularios: [] };\n  if (!c || typeof c !== 'object') return out;\n  const idsForm = new Set();\n  for (const f of (Array.isArray(c.formularios) ? c.formularios : []).slice(0, 25)) {\n    if (!f || !ID.test(f.id ?? '') || idsForm.has(f.id)) { avisos.push('um formulário sem identificação válida foi ignorado'); continue; }\n    const titulo = str(f.titulo, 45);\n    const perguntas = (Array.isArray(f.perguntas) ? f.perguntas : []).slice(0, 5).map((q) => {\n      const max = Math.min(4000, Math.max(1, Number(q?.max) || (q?.longa ? 1000 : 200)));\n      return {\n        rotulo: str(q?.rotulo, 45),\n        placeholder: str(q?.placeholder, 100),\n        longa: !!q?.longa,\n        obrigatoria: q?.obrigatoria !== false,\n        min: Math.min(max, Math.max(0, Number(q?.min) || 0)),\n        max,\n      };\n    }).filter((q) => q.rotulo);\n    if (!titulo || !perguntas.length) { avisos.push(`formulário \"${f.id}\" precisa de título e de pelo menos 1 pergunta (ignorado)`); continue; }\n    idsForm.add(f.id);\n    out.formularios.push({\n      id: f.id, titulo, servidor: snow(f.servidor), canal: snow(f.canal), cargo: snow(f.cargo),\n      mensagem: str(f.mensagem, 2000), perguntas,\n    });\n  }\n  const idsPainel = new Set();\n  for (const pn of (Array.isArray(c.paineis) ? c.paineis : []).slice(0, 25)) {\n    if (!pn || !ID.test(pn.id ?? '') || idsPainel.has(pn.id)) { avisos.push('um painel sem identificação válida foi ignorado'); continue; }\n    const menu = pn.tipo === 'menu';\n    const e = pn.embed ?? {};\n    const embed = {\n      titulo: str(e.titulo, 256), descricao: str(e.descricao, 4000), cor: HEX.test(e.cor ?? '') ? e.cor : '',\n      imagem: url(e.imagem), miniatura: url(e.miniatura), rodape: str(e.rodape, 2048),\n    };\n    const conteudo = str(pn.conteudo, 2000);\n    if (!embed.titulo && !embed.descricao && !conteudo) { avisos.push(`painel \"${pn.nome || pn.id}\" precisa de um título ou texto (ignorado)`); continue; }\n    const idsItem = new Set();\n    const itens = [];\n    for (const it of (Array.isArray(pn.itens) ? pn.itens : []).slice(0, 25)) {\n      if (!it || !ID.test(it.id ?? '') || idsItem.has(it.id)) continue;\n      const a = it.acao ?? {};\n      const tipo = ACOES.includes(a.tipo) ? a.tipo : null;\n      if (!tipo || (menu && tipo === 'link')) { avisos.push(`item \"${it.rotulo || it.id}\" do painel \"${pn.nome || pn.id}\" sem ação válida (ignorado)`); continue; }\n      const acao = { tipo };\n      if (tipo === 'cargo') {\n        acao.cargo = snow(a.cargo);\n        acao.modo = ['alternar', 'dar', 'tirar'].includes(a.modo) ? a.modo : 'alternar';\n        if (!acao.cargo) { avisos.push(`item \"${it.rotulo || it.id}\": escolha o cargo (ignorado)`); continue; }\n      }\n      if (tipo === 'formulario') {\n        acao.formulario = ID.test(a.formulario ?? '') && idsForm.has(a.formulario) ? a.formulario : '';\n        if (!acao.formulario) { avisos.push(`item \"${it.rotulo || it.id}\": o formulário escolhido não existe (ignorado)`); continue; }\n      }\n      if (tipo === 'link') {\n        acao.url = ehUrl(str(a.url, 500)) ? str(a.url, 500) : '';\n        if (!acao.url) { avisos.push(`item \"${it.rotulo || it.id}\": link precisa começar com https:// (ignorado)`); continue; }\n      }\n      if (tipo === 'ticket') {\n        acao.assunto = str(a.assunto, 80);\n        acao.categoria = snow(a.categoria);\n        acao.equipe = snow(a.equipe);\n      }\n      acao.mensagem = str(a.mensagem, 2000);\n      const rotulo = str(it.rotulo, menu ? 100 : 80);\n      const emoji = emojiDeBotaoOk(it.emoji) ? it.emoji : '';\n      if (it.emoji && !emoji) avisos.push(`emoji de \"${rotulo || it.id}\" inválido (removido)`);\n      if (!rotulo && (menu || !emoji)) { avisos.push(`item \"${it.id}\" precisa de um nome${menu ? '' : ' ou emoji'} (ignorado)`); continue; }\n      idsItem.add(it.id);\n      itens.push({ id: it.id, rotulo, emoji, descricao: menu ? str(it.descricao, 100) : '', estilo: tipo === 'link' ? 'Link' : ESTILOS.includes(it.estilo) ? it.estilo : 'Secondary', acao });\n    }\n    if (!itens.length) { avisos.push(`painel \"${pn.nome || pn.id}\" ficou sem botões/opções válidos (ignorado)`); continue; }\n    idsPainel.add(pn.id);\n    out.paineis.push({\n      id: pn.id, nome: str(pn.nome, 80) || pn.id, servidor: snow(pn.servidor), tipo: menu ? 'menu' : 'botoes',\n      placeholder: str(pn.placeholder, 150), conteudo, embed, itens,\n    });\n  }\n  return out;\n}\n\n/** Volta tudo ao padrão (apaga a personalização). */\nexport function resetar() {\n  valores = vazio();\n  gravar();\n}\n\n/**\n * Mensagens que cada servidor pode trocar no /config (boas-vindas, nível...).\n * Sem mensagem própria (ou com o texto padrão antigo, salvo por versões anteriores), usa o texto do bot,\n * que o dono pode personalizar.\n */\nexport const modeloOu = (salvo, antigoPadrao, textoDoBot) => (salvo && salvo !== antigoPadrao ? salvo : textoDoBot);\n\n/** Coloca a dica (placeholder) num campo de modal, se o texto não estiver vazio. */\nexport const comDica = (campo, dica) => (dica ? campo.setPlaceholder(cortarEm(String(dica), LIMITES.placeholder)) : campo);\n",
  "src/core/util.js": "import fs from 'node:fs';\nimport { EventEmitter } from 'node:events';\nimport { ActivityType, EmbedBuilder, MessageFlags, PermissionFlagsBits } from 'discord.js';\nimport { colecao } from './db.js';\nimport { textos, preencher, emojiTipo, corPersonalizada, presenca } from './textos.js';\n\nexport { preencher };\n\nconst tx = textos('geral', {\n  voce_mesmo: 'Você não pode usar isso em você mesmo.',\n  dono_servidor: 'Não dá para punir o dono do servidor.',\n  eu_mesmo: 'Não posso fazer isso comigo mesmo.',\n  cargo_maior_seu: 'Esse membro tem um cargo igual ou maior que o seu.',\n  cargo_maior_meu: 'Esse membro tem um cargo igual ou maior que o meu. Suba o meu cargo na lista de cargos.',\n  erro_generico: 'Algo deu errado. Tente de novo em instantes.',\n});\n\n/** config.json: nome do bot, cor padrão e módulos instalados. */\nexport const CONFIG = JSON.parse(fs.readFileSync(new URL('../../config.json', import.meta.url), 'utf8'));\n\n// ---------------- ajustes por servidor ----------------\nconst ajustesDb = colecao('ajustes');\n\n/**\n * Ajustes de um módulo neste servidor. Campos que faltarem recebem o padrão.\n * Altere o objeto devolvido e chame salvarAjustes().\n */\nexport function ajustes(guildId, modulo, padrao = {}) {\n  const g = ajustesDb.de(guildId, modulo);\n  for (const [k, v] of Object.entries(padrao)) {\n    if (!(k in g)) g[k] = structuredClone(v);\n  }\n  return g;\n}\nexport const salvarAjustes = () => ajustesDb.salvar();\n\n// ---------------- aparência ----------------\nexport function cor(guildId) {\n  const c = guildId ? ajustesDb.ler(guildId, 'geral', 'cor') : null;\n  if (c) return parseInt(String(c).replace('#', ''), 16);\n  return corPersonalizada('padrao') ?? parseInt(String(CONFIG.cor || '#5865F2').replace('#', ''), 16);\n}\n\nexport const embed = (guildId) => new EmbedBuilder().setColor(cor(guildId));\n\n/** Cores de sucesso, erro e aviso (o dono pode trocar no Personalizar bot). */\nexport const CORES = {\n  get sucesso() { return corPersonalizada('sucesso') ?? 0x22c55e; },\n  get erro() { return corPersonalizada('erro') ?? 0xef4444; },\n  get aviso() { return corPersonalizada('aviso') ?? 0xf59e0b; },\n};\n\n/** Resposta curta só para quem usou o comando. */\nexport async function responder(i, texto, tipo = 'info') {\n  const icone = emojiTipo(tipo);\n  const e = new EmbedBuilder()\n    .setColor(tipo in CORES ? CORES[tipo] : cor(i.guildId))\n    .setDescription(`${icone} ${texto}`.trim());\n  const payload = { embeds: [e], flags: MessageFlags.Ephemeral };\n  if (i.deferred || i.replied) return i.followUp(payload).catch(() => null);\n  return i.reply(payload).catch(() => null);\n}\n\n// ---------------- texto e números ----------------\nexport const fmt = (n) => Number(n || 0).toLocaleString('pt-BR');\n\nexport const cortar = (t, n) => {\n  const s = String(t ?? '');\n  return s.length > n ? `${s.slice(0, n - 1)}…` : s;\n};\n\n\nexport function barra(fracao, tamanho = 12) {\n  const f = Math.max(0, Math.min(1, fracao || 0));\n  const cheio = Math.round(f * tamanho);\n  return '▰'.repeat(cheio) + '▱'.repeat(tamanho - cheio);\n}\n\n/** \"10m\", \"1h30m\", \"2d\", \"45s\", \"1w\" → milissegundos (null se inválido). */\nexport function lerDuracao(texto) {\n  const s = String(texto || '').toLowerCase().replace(/\\s+/g, '');\n  if (!s) return null;\n  // as palavras mais longas vêm antes (\"min\" antes de \"m\"), senão \"10min\" não seria entendido\n  const re = /(\\d+)(segundos?|seg|minutos?|min|horas?|dias?|semanas?|sem|s|m|h|d|w)/g;\n  const UNIDADE = { s: 1e3, m: 6e4, h: 36e5, d: 864e5, w: 6048e5 };\n  const mult = (u) => UNIDADE[u.startsWith('seg') ? 's' : u.startsWith('min') ? 'm' : u.startsWith('hora') ? 'h' : u.startsWith('dia') ? 'd' : u.startsWith('sem') ? 'w' : u];\n  let total = 0, lido = '';\n  for (const m of s.matchAll(re)) {\n    total += Number(m[1]) * mult(m[2]);\n    lido += m[0];\n  }\n  return lido === s && total > 0 ? total : null;\n}\n\nexport function duracaoTexto(ms) {\n  const s = Math.round(ms / 1000);\n  const partes = [];\n  const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60), seg = s % 60;\n  if (d) partes.push(`${d}d`);\n  if (h) partes.push(`${h}h`);\n  if (m) partes.push(`${m}min`);\n  if (!d && !h && seg) partes.push(`${seg}s`);\n  return partes.join(' ') || '0s';\n}\n\nexport const ts = (ms, estilo = 'R') => `<t:${Math.floor(ms / 1000)}:${estilo}>`;\n\n// ---------------- permissões ----------------\n/** Tem \"Gerenciar servidor\" ou o cargo de staff definido em /config staff? */\nexport function ehStaff(member) {\n  if (!member) return false;\n  if (member.permissions?.has(PermissionFlagsBits.ManageGuild)) return true;\n  const staff = ajustesDb.ler(member.guild.id, 'geral', 'staff');\n  return Boolean(staff && member.roles?.cache?.has(staff));\n}\n\n/**\n * Confere se `autor` pode punir `alvo` (dono, hierarquia de cargos, o próprio bot).\n * Devolve uma mensagem de erro ou null.\n */\nexport function checarHierarquia(autor, alvo, bot) {\n  if (!alvo) return null;\n  if (alvo.id === autor.id) return tx('voce_mesmo');\n  if (alvo.id === alvo.guild.ownerId) return tx('dono_servidor');\n  if (alvo.id === bot.id) return tx('eu_mesmo');\n  if (autor.id !== autor.guild.ownerId && alvo.roles.highest.position >= autor.roles.highest.position) {\n    return tx('cargo_maior_seu');\n  }\n  if (alvo.roles.highest.position >= bot.roles.highest.position) {\n    return tx('cargo_maior_meu');\n  }\n  return null;\n}\n\nexport const sorteio = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;\n\n// ---------------- mensagens apagadas pelo AutoMod ----------------\n// O AutoMod marca o que apagou: assim os Níveis não dão XP por ela e os Logs não registram em dobro.\nconst removidas = new Map(); // id da mensagem -> expira em\nexport function marcarRemovida(id) {\n  const agora = Date.now();\n  removidas.set(id, agora + 60_000);\n  if (removidas.size > 300) for (const [k, t] of removidas) if (t < agora) removidas.delete(k);\n}\nexport const foiRemovida = (id) => (removidas.get(id) ?? 0) > Date.now();\n\n// ---------------- respostas longas ----------------\nconst tamanhoEmbed = (e) => {\n  const d = e.data;\n  return (\n    (d.title?.length ?? 0) +\n    (d.description?.length ?? 0) +\n    (d.footer?.text?.length ?? 0) +\n    (d.author?.name?.length ?? 0) +\n    (d.fields ?? []).reduce((t, f) => t + f.name.length + f.value.length, 0)\n  );\n};\n\n/**\n * Responde com uma lista de campos que pode passar do limite do Discord\n * (6000 caracteres e 25 campos por mensagem): divide em várias mensagens.\n * `base()` deve devolver um EmbedBuilder novo (título, cor, rodapé...).\n */\nexport async function responderCampos(i, base, campos, { efemero = false } = {}) {\n  const partes = [];\n  let atual = base();\n  let n = 0;\n  for (const c of campos) {\n    const campo = { name: cortar(c.name, 256), value: cortar(c.value || '—', 1024), inline: c.inline ?? false };\n    if (n >= 25 || tamanhoEmbed(atual) + campo.name.length + campo.value.length > 5800) {\n      partes.push(atual);\n      atual = base().setTitle(null).setThumbnail(null).setAuthor(null);\n      n = 0;\n    }\n    atual.addFields(campo);\n    n++;\n  }\n  partes.push(atual);\n  const flags = efemero ? MessageFlags.Ephemeral : undefined;\n  await i.reply({ embeds: [partes[0]], flags, allowedMentions: { parse: [] } });\n  for (const e of partes.slice(1)) await i.followUp({ embeds: [e], flags, allowedMentions: { parse: [] } });\n}\n\n// ---------------- avisos entre módulos ----------------\n/**\n * Um módulo avisa, outro escuta (sem um depender do outro).\n * Ex.: o Tickets avisa \"ticketFechado\" e a Avaliação de atendimento pergunta a nota.\n *   sinais.emit('ticketFechado', { guild, dono, atendente, numero })\n *   sinais.on('ticketFechado', (dados) => { ... })\n */\nexport const sinais = new EventEmitter();\nsinais.setMaxListeners(50);\n\n/** Mensagem padrão quando algo dá errado numa interação. */\nexport const erroGenerico = () => `${emojiTipo('erro')} ${tx('erro_generico')}`;\n\n/** Status do bot (o que aparece embaixo do nome). O Personalizar bot pode trocar. */\nexport function aplicarPresenca(c) {\n  const p = presenca(CONFIG.status);\n  if (!p.texto) return c.user.setPresence({ activities: [], status: p.status });\n  const tipos = { jogando: ActivityType.Playing, ouvindo: ActivityType.Listening, assistindo: ActivityType.Watching, competindo: ActivityType.Competing };\n  const atividade = p.tipo === 'personalizado' ? { type: ActivityType.Custom, name: 'status', state: p.texto } : { type: tipos[p.tipo], name: p.texto };\n  c.user.setPresence({ activities: [atividade], status: p.status });\n}\n\n/** Links de imagem que o dono pode usar na aparência dos embeds: {avatar} e {servidor_icone}. */\nexport const imagens = ({ user, guild } = {}) => ({\n  avatar: user?.displayAvatarURL?.({ size: 256 }) ?? '',\n  servidor_icone: guild?.iconURL?.({ size: 256 }) ?? '',\n});\n",
  "src/modules/afk.js": "import { GatewayIntentBits, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { embed, responder, cortar, duracaoTexto, foiRemovida } from '../core/util.js';\nimport { textos } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('afk', {\n  afk: '[AFK] ',\n  em: '• <@{por}> em {link}',\n  te_chamaram_vez_es: '\\nTe chamaram {vezes} vez(es):\\n{lista}',\n  bem_vindo_volta_voce: '👋 Bem-vindo(a) de volta, {autor}! Você ficou AFK por **{duracao}**.{chamados}',\n  esta_afk: ['💤 <@{usuario}> está AFK{motivo} · <t:{desde}:R>', 'conteudo'],\n  voce_esta_afk_quando: ['Você está AFK{motivo}. Quando mandar uma mensagem, o AFK sai sozinho.', 'resposta'],\n  afk_2: 'AFK',\n});\n\n/**\n * AFK: /afk motivo. Quem marcar você recebe o aviso.\n * Quando você volta a falar, o AFK sai sozinho e o bot mostra quem te chamou.\n */\n\nconst afks = colecao('afk'); // guild -> user -> { motivo, desde, apelido, chamados: [] }\nconst avisados = new Map(); // anti-spam: \"canal:user\" -> quando avisou\nconst PREFIXO = tx('afk');\n\nasync function aoMensagem(msg) {\n  if (!msg.inGuild() || msg.author.bot || foiRemovida(msg.id)) return;\n\n  // 1) quem estava AFK voltou\n  const meu = afks.ler(msg.guildId, msg.author.id);\n  if (meu && Date.now() - meu.desde > 5000) {\n    afks.apagar(msg.guildId, msg.author.id);\n    if (msg.member?.manageable && msg.member.nickname?.startsWith(PREFIXO)) {\n      await msg.member.setNickname(meu.apelido ?? null, 'Voltou do AFK').catch(() => {});\n    }\n    const chamados = (meu.chamados ?? []).slice(-5);\n    const texto = tx('bem_vindo_volta_voce', { autor: msg.author, duracao: duracaoTexto(Date.now() - meu.desde), chamados: chamados.length ? tx('te_chamaram_vez_es', { vezes: meu.chamados.length, lista: chamados.map((c) => tx('em', { por: c.por, link: c.link })).join('\\n') }) : '' });\n    const aviso = await msg.reply({ embeds: [embed(msg.guildId).setDescription(texto)], allowedMentions: { users: [] } }).catch(() => null);\n    if (aviso) setTimeout(() => aviso.delete().catch(() => {}), 15_000);\n  }\n\n  // 2) alguém marcou (ou respondeu) quem está AFK\n  const alvos = new Set(msg.mentions.users.keys());\n  if (msg.mentions.repliedUser) alvos.add(msg.mentions.repliedUser.id);\n  alvos.delete(msg.author.id);\n  for (const id of alvos) {\n    const a = afks.ler(msg.guildId, id);\n    if (!a) continue;\n    (a.chamados ??= []).push({ por: msg.author.id, link: msg.url, em: Date.now() });\n    if (a.chamados.length > 20) a.chamados.shift();\n    afks.salvar();\n    const k = `${msg.channelId}:${id}`;\n    if (Date.now() - (avisados.get(k) ?? 0) < 30_000) continue; // um aviso a cada 30 s por canal\n    avisados.set(k, Date.now());\n    await msg\n      .reply({ content: tx('esta_afk', { usuario: id, motivo: a.motivo ? `: ${a.motivo}` : '', desde: Math.floor(a.desde / 1000) }), allowedMentions: { parse: [] } })\n      .catch(() => {});\n  }\n}\n\nconst afk = {\n  data: new SlashCommandBuilder()\n    .setName('afk')\n    .setDescription('Avisa que você está ausente')\n    .addStringOption((o) => o.setName('motivo').setDescription('Ex.: almoçando, dormindo...').setMaxLength(100)),\n  async executar(i) {\n    const motivo = (i.options.getString('motivo') ?? '').replace(/@/g, '@​');\n    const membro = i.member;\n    const apelidoAtual = membro.nickname;\n    afks.de(i.guildId)[i.user.id] = { motivo: cortar(motivo, 100), desde: Date.now(), apelido: apelidoAtual ?? null, chamados: [] };\n    afks.salvar();\n    if (membro.manageable && !(apelidoAtual ?? '').startsWith(PREFIXO)) {\n      await membro.setNickname(`${PREFIXO}${membro.displayName}`.slice(0, 32), 'AFK').catch(() => {});\n    }\n    return responder(i, tx('voce_esta_afk_quando', { motivo: motivo ? `: ${motivo}` : '' }), 'sucesso');\n  },\n};\n\nexport default {\n  id: 'afk',\n  nome: tx('afk_2'),\n  intents: [GatewayIntentBits.GuildMessages],\n  permissoes: [PermissionFlagsBits.ManageNicknames],\n  comandos: [afk],\n  eventos: { messageCreate: aoMensagem },\n};\n",
  "src/modules/aniversarios.js": "import { ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { CONFIG, ajustes, salvarAjustes, embed, responder, preencher, imagens } from '../core/util.js';\nimport { textos, modeloOu, visuais } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('aniversarios', {\n  msg_parabens_padrao: '🎂 Hoje é aniversário de {usuario}! Parabéns! 🎉',\n  america_sao_paulo: 'America/Sao_Paulo',\n  de: '{dia} de {mes}',\n  tem_dia: ['{mes} não tem dia {dia}.', 'resposta'],\n  aniversario_salvo: ['Aniversário salvo: **{data}**. 🎂', 'resposta'],\n  seu_aniversario_foi_apagado: ['Seu aniversário foi apagado.', 'resposta'],\n  voce_ainda_cadastrou_use: 'Você ainda não cadastrou. Use `/aniversario definir`.',\n  ainda_cadastrou_aniversario: '{usuario} ainda não cadastrou o aniversário.',\n  hoje: '**é hoje!** 🎉',\n  faltam_dia: 'faltam {falta} dia(s)',\n  ninguem_cadastrou_aniversario_ainda: ['Ninguém cadastrou o aniversário ainda. Use `/aniversario definir`.', 'resposta'],\n  hoje_2: '**hoje!**',\n  dia: 'em {falta} dia(s)',\n  proximos_aniversarios: ['🎂 Próximos aniversários', 'titulo'],\n  so_quem_tem_gerenciar: ['Só quem tem **Gerenciar servidor** pode configurar.', 'resposta'],\n  escolha_cargo_comum_sem: ['Escolha um cargo comum (sem administrador).', 'resposta'],\n  meu_cargo_precisa_ficar: ['Meu cargo precisa ficar acima de {cargo}.', 'resposta'],\n  escolha_pelo_menos_opcao: ['Escolha pelo menos uma opção (canal, cargo ou mensagem).', 'resposta'],\n  escolha_canal: '— (escolha um canal)',\n  cargo_dia: ' · cargo do dia <@&{cargo}>',\n  aniversarios_parabens: ['Aniversários: parabéns em {canal}{cargo}.', 'resposta'],\n  aniversarios: 'Aniversários',\n  definido_aniversario_configurar: 'não definido (`/aniversario configurar`)',\n  parabens: 'Parabéns em: {canal}',\n  nenhum: 'nenhum',\n  cargo_dia_2: 'Cargo do dia: {cargo}',\n  aniversario_cadastrado: '{total} aniversário(s) cadastrado(s)',\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('aniversarios', {\n  parabens: { nome: \"Parabéns no aniversário\", vars: ['avatar', 'servidor_icone'], miniatura: \"{avatar}\" },\n});\n\n/**\n * Aniversários: cada membro cadastra o dia com /aniversario definir.\n * No dia, o bot dá parabéns no canal escolhido e (opcional) um cargo que dura 24 h.\n * O fuso é o do Brasil (America/Sao_Paulo); dá para trocar com \"fuso\" no config.json.\n */\n\nconst datas = colecao('aniversarios'); // guild -> user -> { dia, mes }\nconst PADRAO = { canal: null, cargo: null, mensagem: null, anunciados: {}, cargosAtivos: {} };\nconst cfg = (guildId) => ajustes(guildId, 'aniversarios', PADRAO);\nconst ANTIGA = '🎂 Hoje é aniversário de {usuario}! Parabéns! 🎉'; // padrão de versões anteriores\nconst msgParabens = (c) => modeloOu(c.mensagem, ANTIGA, tx('msg_parabens_padrao'));\nconst FUSO = CONFIG.fuso || tx('america_sao_paulo');\nconst MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];\nconst DIAS_NO_MES = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];\n\n/** Dia, mês e ano de hoje no fuso configurado. */\nfunction hoje() {\n  const p = Object.fromEntries(\n    new Intl.DateTimeFormat('en-US', { timeZone: FUSO, year: 'numeric', month: 'numeric', day: 'numeric' }).formatToParts(new Date()).map((x) => [x.type, x.value])\n  );\n  return { dia: Number(p.day), mes: Number(p.month), ano: Number(p.year) };\n}\nconst bissexto = (a) => (a % 4 === 0 && a % 100 !== 0) || a % 400 === 0;\n/** Quem nasceu em 29/02 comemora em 28/02 nos anos que não são bissextos. */\nconst fazHoje = (d, h) => (d.dia === h.dia && d.mes === h.mes) || (d.dia === 29 && d.mes === 2 && !bissexto(h.ano) && h.dia === 28 && h.mes === 2);\nconst dataTexto = (d) => tx('de', { dia: d.dia, mes: MESES[d.mes - 1] });\n\nfunction diasAte(d, h) {\n  const base = Date.UTC(h.ano, h.mes - 1, h.dia);\n  let alvo = Date.UTC(h.ano, d.mes - 1, Math.min(d.dia, d.mes === 2 && !bissexto(h.ano) ? 28 : d.dia));\n  if (alvo < base) alvo = Date.UTC(h.ano + 1, d.mes - 1, Math.min(d.dia, d.mes === 2 && !bissexto(h.ano + 1) ? 28 : d.dia));\n  return Math.round((alvo - base) / 86400e3);\n}\n\nconst aniversario = {\n  data: new SlashCommandBuilder()\n    .setName('aniversario')\n    .setDescription('Aniversários do servidor')\n    .addSubcommand((s) =>\n      s\n        .setName('definir')\n        .setDescription('Cadastra o dia do seu aniversário')\n        .addIntegerOption((o) => o.setName('dia').setDescription('Dia').setRequired(true).setMinValue(1).setMaxValue(31))\n        .addIntegerOption((o) =>\n          o\n            .setName('mes')\n            .setDescription('Mês')\n            .setRequired(true)\n            .addChoices(...MESES.map((m, n) => ({ name: m, value: n + 1 })))\n        )\n    )\n    .addSubcommand((s) => s.setName('remover').setDescription('Apaga o seu aniversário'))\n    .addSubcommand((s) =>\n      s\n        .setName('ver')\n        .setDescription('Mostra o aniversário de alguém')\n        .addUserOption((o) => o.setName('usuario').setDescription('De quem (padrão: você)'))\n    )\n    .addSubcommand((s) => s.setName('proximos').setDescription('Os próximos aniversários do servidor'))\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('(Equipe) Canal dos parabéns, cargo do dia e mensagem')\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde dar os parabéns').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Cargo que o aniversariante ganha por 24 h'))\n        .addStringOption((o) => o.setName('mensagem').setDescription('Mensagem. Variáveis: {usuario} {nome} {servidor}').setMaxLength(500))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    const h = hoje();\n\n    if (sub === 'definir') {\n      const dia = i.options.getInteger('dia');\n      const mes = i.options.getInteger('mes');\n      if (dia > DIAS_NO_MES[mes - 1]) return responder(i, tx('tem_dia', { mes: MESES[mes - 1], dia }), 'erro');\n      datas.de(i.guildId)[i.user.id] = { dia, mes };\n      datas.salvar();\n      return responder(i, tx('aniversario_salvo', { data: dataTexto({ dia, mes }) }), 'sucesso');\n    }\n    if (sub === 'remover') {\n      datas.apagar(i.guildId, i.user.id);\n      return responder(i, tx('seu_aniversario_foi_apagado'), 'sucesso');\n    }\n    if (sub === 'ver') {\n      const u = i.options.getUser('usuario') ?? i.user;\n      const d = datas.ler(i.guildId, u.id);\n      if (!d) return responder(i, u.id === i.user.id ? tx('voce_ainda_cadastrou_use') : tx('ainda_cadastrou_aniversario', { usuario: u }), 'aviso');\n      const falta = diasAte(d, h);\n      return responder(i, `🎂 ${u}: **${dataTexto(d)}** · ${falta === 0 ? tx('hoje') : tx('faltam_dia', { falta })}`, 'info');\n    }\n    if (sub === 'proximos') {\n      const todos = Object.entries(datas.ler(i.guildId) ?? {})\n        .map(([id, d]) => ({ id, d, falta: diasAte(d, h) }))\n        .sort((a, b) => a.falta - b.falta)\n        .slice(0, 15);\n      if (!todos.length) return responder(i, tx('ninguem_cadastrou_aniversario_ainda'), 'aviso');\n      const linhas = todos.map((x) => `${x.falta === 0 ? '🎉' : '🎂'} <@${x.id}> · ${dataTexto(x.d)} · ${x.falta === 0 ? tx('hoje_2') : tx('dia', { falta: x.falta })}`);\n      return i.reply({ embeds: [embed(i.guildId).setTitle(tx('proximos_aniversarios')).setDescription(linhas.join('\\n'))], allowedMentions: { parse: [] } });\n    }\n\n    // configurar (só equipe)\n    if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, tx('so_quem_tem_gerenciar'), 'erro');\n    const c = cfg(i.guildId);\n    const canal = i.options.getChannel('canal');\n    const cargo = i.options.getRole('cargo');\n    const msg = i.options.getString('mensagem');\n    if (cargo) {\n      if (cargo.managed || cargo.id === i.guildId || cargo.permissions.has(PermissionFlagsBits.Administrator)) return responder(i, tx('escolha_cargo_comum_sem'), 'erro');\n      if (!cargo.editable) return responder(i, tx('meu_cargo_precisa_ficar', { cargo }), 'erro');\n      c.cargo = cargo.id;\n    }\n    if (canal) c.canal = canal.id;\n    if (msg) c.mensagem = msg;\n    if (!canal && !cargo && !msg) return responder(i, tx('escolha_pelo_menos_opcao'), 'aviso');\n    salvarAjustes();\n    return responder(i, tx('aniversarios_parabens', { canal: c.canal ? `<#${c.canal}>` : tx('escolha_canal'), cargo: c.cargo ? tx('cargo_dia', { cargo: c.cargo }) : '' }), 'sucesso');\n  },\n};\n\n/** Dá os parabéns de hoje e tira o cargo de quem já passou das 24 h. Roda a cada 10 minutos. */\nasync function verificar(client) {\n  const h = hoje();\n  const chaveHoje = `${h.ano}-${h.mes}-${h.dia}`;\n  for (const guild of client.guilds.cache.values()) {\n    const c = cfg(guild.id);\n    let mudou = false;\n\n    // tira os cargos vencidos\n    for (const [userId, ate] of Object.entries(c.cargosAtivos)) {\n      if (ate > Date.now()) continue;\n      delete c.cargosAtivos[userId];\n      mudou = true;\n      const membro = await guild.members.fetch(userId).catch(() => null);\n      if (membro && c.cargo) await membro.roles.remove(c.cargo, 'Fim do dia de aniversário').catch(() => {});\n    }\n\n    if (c.canal || c.cargo) {\n      const canal = c.canal && guild.channels.cache.get(c.canal);\n      for (const [userId, d] of Object.entries(datas.ler(guild.id) ?? {})) {\n        if (!fazHoje(d, h) || c.anunciados[userId] === chaveHoje) continue;\n        const membro = await guild.members.fetch(userId).catch(() => null);\n        c.anunciados[userId] = chaveHoje;\n        mudou = true;\n        if (!membro) continue; // saiu do servidor\n        if (canal?.isTextBased()) {\n          const texto = preencher(msgParabens(c), { usuario: `${membro}`, nome: membro.displayName, servidor: guild.name });\n          await canal\n            .send({ embeds: [vis(embed(guild.id).setDescription(texto).setThumbnail(membro.displayAvatarURL()), 'parabens', imagens({ user: membro.user, guild }))], content: `${membro}`, allowedMentions: { users: [userId] } })\n            .catch(() => {});\n        }\n        if (c.cargo) {\n          const ok = await membro.roles.add(c.cargo, 'Aniversário').then(() => true, () => false);\n          if (ok) c.cargosAtivos[userId] = Date.now() + 24 * 3600e3;\n        }\n      }\n    }\n    if (mudou) salvarAjustes();\n  }\n}\n\nexport default {\n  id: 'aniversarios',\n  nome: tx('aniversarios'),\n  comandos: [aniversario],\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  aoIniciar(client) {\n    verificar(client).catch((e) => console.error('[aniversários]', e.message));\n    setInterval(() => verificar(client).catch((e) => console.error('[aniversários]', e.message)), 10 * 60_000);\n  },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      const n = Object.keys(datas.ler(guild.id) ?? {}).length;\n      return [\n        tx('parabens', { canal: c.canal ? `<#${c.canal}>` : tx('definido_aniversario_configurar') }),\n        tx('cargo_dia_2', { cargo: c.cargo ? `<@&${c.cargo}>` : tx('nenhum') }),\n        tx('aniversario_cadastrado', { total: n }),\n      ];\n    },\n  },\n};\n",
  "src/modules/antiraid.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, GatewayIntentBits, GuildVerificationLevel, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, ehStaff, duracaoTexto, marcarRemovida, CORES } from '../core/util.js';\nimport { textos, botoes } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('antiraid', {\n  encerrar_modo_raid: ['Encerrar modo raid', 'botao'],\n  anti_raid: 'Anti-raid',\n  nivel_verificacao_maximo_precisa: 'nível de verificação no **máximo** (precisa de telefone verificado)',\n  convites_pausados: '**convites pausados**',\n  fiz: 'Fiz: {feitos}.',\n  consegui_mudar_servidor_preciso: 'Não consegui mudar o servidor (preciso de **Gerenciar servidor**).',\n  so_registro: 'só registro',\n  modo_raid_ativado_entraram: '🚨 **Modo raid ativado!** Entraram **{quantos}** pessoas em {segundos}s.\\n{feitos}\\nQuem entrar agora: **{acao}**. Encerra sozinho em {duracao} ou pelo botão.',\n  fim_modo_raid: 'Fim do modo raid',\n  por: ' por <@{por}>',\n  automaticamente: ' automaticamente',\n  modo_raid_encerrado_servidor: '✅ Modo raid encerrado{por}. O servidor voltou ao normal.',\n  voce_pode_entrar_agora: 'Você não pôde entrar em **{servidor}** agora ({motivo}). Tente de novo mais tarde.',\n  sua_conta_nova_demais: 'Sua conta é nova demais para entrar em **{servidor}** (mínimo: {idadeMinima} dia(s)).',\n  expulsei_conta_dia: '👶 Expulsei {tag} (`{id}`): conta com {dias} dia(s).',\n  modo_raid: 'modo raid',\n  so_equipe_pode_encerrar: ['Só a equipe pode encerrar o modo raid.', 'resposta'],\n  modo_raid_encerrado: 'Modo raid encerrado.',\n  modo_raid_ja_tinha: 'O modo raid já tinha acabado.',\n  anti_raid_desligado: ['Anti-raid desligado.', 'resposta'],\n  servidor_esta_modo_raid: 'O servidor não está em modo raid.',\n  configure_primeiro_antiraid_configur: ['Configure primeiro com `/antiraid configurar`.', 'resposta'],\n  modo_raid_ja_esta: ['O modo raid já está ligado.', 'resposta'],\n  modo_raid_ligado_encerre: '🚨 Modo raid ligado. Encerre com `/antiraid encerrar` ou pelo botão no canal de alerta.',\n  gerenciar_servidor: 'Gerenciar servidor',\n  expulsar_membros: 'Expulsar membros',\n  castigar_membros: 'Castigar membros',\n  contas_menos_dia_sao: ' Contas com menos de {idadeMinima} dia(s) são expulsas.',\n  me_falta: '\\n⚠️ Me falta: {faltam}.',\n  anti_raid_ligado_entradas: ['Anti-raid ligado: **{limite}** entradas em **{segundos}s** ativam o modo raid (ação: {acao}). Avisos em <#{alerta}>.{idadeMinima}{faltam}', 'resposta'],\n  desligado_antiraid_configurar: 'Desligado (`/antiraid configurar`)',\n  modo_raid_2: ' · 🚨 **EM MODO RAID**',\n  entradas_acao_alerta: '{limite} entradas em {segundos}s · ação: {acao} · alerta em <#{alerta}>{modo_raid}',\n});\n\n// Botões (texto, emoji e cor personalizáveis; alguns podem ser escondidos)\nconst bt = botoes('antiraid', {\n  fim: { nome: \"Encerrar modo raid\", rotulo: 'encerrar_modo_raid', emoji: '✅', estilo: 'Success' },\n});\n\n/**\n * Anti-raid: se entrar gente demais em pouco tempo, o bot ativa o \"modo raid\":\n * sobe o nível de verificação do servidor, pausa os convites (se der) e\n * expulsa ou castiga quem entrar enquanto durar. Avisa a equipe com um botão para encerrar.\n * Também pode barrar contas novas demais o tempo todo.\n */\n\nconst PADRAO = {\n  ativo: false,\n  limite: 10, // entradas...\n  segundos: 30, // ...nesse intervalo\n  acao: 'expulsar', // o que fazer com quem entra durante o raid: expulsar | castigo | nada\n  alerta: null, // canal\n  cargoAlerta: null,\n  idadeMinima: 0, // dias; 0 = não barra contas novas\n  emRaid: false,\n  inicio: null,\n  nivelAntes: null,\n  convitesPausados: false,\n};\nconst cfg = (guildId) => ajustes(guildId, 'antiraid', PADRAO);\nconst entradas = new Map(); // guildId -> [timestamps]\nconst DURACAO_RAID = 30 * 60_000;\n\nasync function alertar(guild, texto, botao = false) {\n  const c = cfg(guild.id);\n  const canal = c.alerta && guild.channels.cache.get(c.alerta);\n  if (!canal?.isTextBased()) return;\n  await canal\n    .send({\n      content: c.cargoAlerta ? `<@&${c.cargoAlerta}>` : undefined,\n      embeds: [embed(guild.id).setColor(CORES.erro).setDescription(texto).setTimestamp()],\n      components: botao ? [new ActionRowBuilder().addComponents(bt('fim').setCustomId('ar:fim'))] : [],\n      allowedMentions: { roles: c.cargoAlerta ? [c.cargoAlerta] : [] },\n    })\n    .catch(() => {});\n}\n\nasync function iniciarRaid(guild, quantos) {\n  const c = cfg(guild.id);\n  c.emRaid = true;\n  c.inicio = Date.now();\n  c.nivelAntes = guild.verificationLevel;\n  const feitos = [];\n  if (guild.verificationLevel < GuildVerificationLevel.VeryHigh) {\n    const ok = await guild.setVerificationLevel(GuildVerificationLevel.VeryHigh, tx('anti_raid')).then(() => true, () => false);\n    if (ok) feitos.push(tx('nivel_verificacao_maximo_precisa'));\n  }\n  const pausou = await guild.disableInvites(true).then(() => true, () => false);\n  c.convitesPausados = pausou;\n  if (pausou) feitos.push(tx('convites_pausados'));\n  salvarAjustes();\n  await alertar(\n    guild,\n    tx('modo_raid_ativado_entraram', { quantos, segundos: c.segundos, feitos: feitos.length ? tx('fiz', { feitos: feitos.join(' e ') }) : tx('consegui_mudar_servidor_preciso'), acao: c.acao === 'nada' ? tx('so_registro') : c.acao, duracao: duracaoTexto(DURACAO_RAID) }),\n    true\n  );\n}\n\nasync function encerrarRaid(guild, por) {\n  const c = cfg(guild.id);\n  if (!c.emRaid) return false;\n  if (c.nivelAntes != null && guild.verificationLevel !== c.nivelAntes) await guild.setVerificationLevel(c.nivelAntes, tx('fim_modo_raid')).catch(() => {});\n  if (c.convitesPausados) await guild.disableInvites(false).catch(() => {});\n  Object.assign(c, { emRaid: false, inicio: null, nivelAntes: null, convitesPausados: false });\n  salvarAjustes();\n  await alertar(guild, tx('modo_raid_encerrado_servidor', { por: por ? tx('por', { por }) : tx('automaticamente') }));\n  return true;\n}\n\n/** Avisa os outros módulos (ex.: Boas-vindas) que esta pessoa foi barrada. */\nconst barrar = (member) => marcarRemovida(`membro:${member.guild.id}:${member.id}`);\n\nasync function punir(member, motivo) {\n  barrar(member);\n  const c = cfg(member.guild.id);\n  await member.send(tx('voce_pode_entrar_agora', { servidor: member.guild.name, motivo })).catch(() => {});\n  if (c.acao === 'castigo' && member.moderatable) return member.timeout(60 * 60_000, `Anti-raid: ${motivo}`).catch(() => {});\n  if (member.kickable) return member.kick(`Anti-raid: ${motivo}`).catch(() => {});\n}\n\nasync function aoEntrar(member) {\n  const guild = member.guild;\n  const c = cfg(guild.id);\n  if (!c.ativo || member.user.bot) return;\n\n  // contas novas demais\n  const dias = (Date.now() - member.user.createdTimestamp) / 86400e3;\n  if (c.idadeMinima && dias < c.idadeMinima) {\n    if (member.kickable) {\n      barrar(member);\n      await member.send(tx('sua_conta_nova_demais', { servidor: guild.name, idadeMinima: c.idadeMinima })).catch(() => {});\n      await member.kick(`Anti-raid: conta com ${Math.floor(dias)} dia(s)`).catch(() => {});\n      await alertar(guild, tx('expulsei_conta_dia', { tag: member.user.tag, id: member.id, dias: Math.floor(dias) }));\n    }\n    return;\n  }\n\n  // modo raid ligado: aplica a ação em quem entra\n  if (c.emRaid) {\n    if (Date.now() - c.inicio > DURACAO_RAID) await encerrarRaid(guild, null);\n    else if (c.acao !== 'nada') return punir(member, tx('modo_raid'));\n  }\n\n  // conta as entradas recentes\n  const agora = Date.now();\n  const lista = (entradas.get(guild.id) ?? []).filter((t) => agora - t < c.segundos * 1000);\n  lista.push(agora);\n  entradas.set(guild.id, lista);\n  if (!c.emRaid && lista.length >= c.limite) {\n    entradas.set(guild.id, []);\n    await iniciarRaid(guild, lista.length);\n    if (c.acao !== 'nada') await punir(member, tx('modo_raid')); // quem disparou também faz parte do raid\n  }\n}\n\nconst componentes = {\n  async ar(i, [acao]) {\n    if (acao !== 'fim') return;\n    if (!ehStaff(i.member)) return responder(i, tx('so_equipe_pode_encerrar'), 'erro');\n    const ok = await encerrarRaid(i.guild, i.user.id);\n    await i.message.edit({ components: [] }).catch(() => {});\n    return responder(i, ok ? tx('modo_raid_encerrado') : tx('modo_raid_ja_tinha'), ok ? 'sucesso' : 'aviso');\n  },\n};\n\nconst antiraid = {\n  data: new SlashCommandBuilder()\n    .setName('antiraid')\n    .setDescription('Proteção contra raids (muita gente entrando de uma vez)')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('Liga e ajusta o anti-raid')\n        .addChannelOption((o) => o.setName('alerta').setDescription('Canal onde a equipe é avisada').setRequired(true).addChannelTypes(ChannelType.GuildText))\n        .addIntegerOption((o) => o.setName('limite').setDescription('Quantas entradas disparam o modo raid (padrão 10)').setMinValue(3).setMaxValue(100))\n        .addIntegerOption((o) => o.setName('segundos').setDescription('Em quantos segundos (padrão 30)').setMinValue(5).setMaxValue(600))\n        .addStringOption((o) =>\n          o\n            .setName('acao')\n            .setDescription('O que fazer com quem entra durante o raid (padrão: expulsar)')\n            .addChoices({ name: 'Expulsar', value: 'expulsar' }, { name: 'Castigo de 1 hora', value: 'castigo' }, { name: 'Nada (só travar o servidor)', value: 'nada' })\n        )\n        .addRoleOption((o) => o.setName('cargo-alerta').setDescription('Cargo marcado no aviso (opcional)'))\n        .addIntegerOption((o) => o.setName('idade-minima').setDescription('Expulsa contas com menos dias que isso, sempre (0 = não)').setMinValue(0).setMaxValue(60))\n    )\n    .addSubcommand((s) => s.setName('desligar').setDescription('Desliga o anti-raid'))\n    .addSubcommand((s) => s.setName('encerrar').setDescription('Encerra o modo raid agora'))\n    .addSubcommand((s) => s.setName('ativar-raid').setDescription('Liga o modo raid manualmente (trava o servidor)')),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const sub = i.options.getSubcommand();\n    if (sub === 'desligar') {\n      if (c.emRaid) await encerrarRaid(i.guild, i.user.id);\n      c.ativo = false;\n      salvarAjustes();\n      return responder(i, tx('anti_raid_desligado'), 'sucesso');\n    }\n    if (sub === 'encerrar') return responder(i, (await encerrarRaid(i.guild, i.user.id)) ? tx('modo_raid_encerrado') : tx('servidor_esta_modo_raid'), 'sucesso');\n    if (sub === 'ativar-raid') {\n      if (!c.ativo) return responder(i, tx('configure_primeiro_antiraid_configur'), 'erro');\n      if (c.emRaid) return responder(i, tx('modo_raid_ja_esta'), 'aviso');\n      await i.deferReply({ flags: 64 });\n      await iniciarRaid(i.guild, 0);\n      return i.editReply(tx('modo_raid_ligado_encerre'));\n    }\n    c.ativo = true;\n    c.alerta = i.options.getChannel('alerta').id;\n    for (const [opcao, campo] of [['limite', 'limite'], ['segundos', 'segundos'], ['idade-minima', 'idadeMinima']]) {\n      const v = i.options.getInteger(opcao);\n      if (v !== null) c[campo] = v;\n    }\n    const acao = i.options.getString('acao');\n    if (acao) c.acao = acao;\n    const cargo = i.options.getRole('cargo-alerta');\n    if (cargo) c.cargoAlerta = cargo.id;\n    salvarAjustes();\n    const me = i.guild.members.me.permissions;\n    const faltam = [\n      [PermissionFlagsBits.ManageGuild, tx('gerenciar_servidor')],\n      [PermissionFlagsBits.KickMembers, tx('expulsar_membros')],\n      [PermissionFlagsBits.ModerateMembers, tx('castigar_membros')],\n    ]\n      .filter(([p]) => !me.has(p))\n      .map(([, n]) => n);\n    return responder(\n      i,\n      tx('anti_raid_ligado_entradas', { limite: c.limite, segundos: c.segundos, acao: c.acao, alerta: c.alerta, idadeMinima: c.idadeMinima ? tx('contas_menos_dia_sao', { idadeMinima: c.idadeMinima }) : '', faltam: faltam.length ? tx('me_falta', { faltam: faltam.join(', ') }) : '' }),\n      faltam.length ? 'aviso' : 'sucesso'\n    );\n  },\n};\n\nexport default {\n  id: 'antiraid',\n  nome: tx('anti_raid'),\n  prioridade: 1, // antes das boas-vindas: quem é expulso nem recebe a mensagem\n  intents: [GatewayIntentBits.GuildMembers],\n  permissoes: [PermissionFlagsBits.ManageGuild, PermissionFlagsBits.KickMembers, PermissionFlagsBits.ModerateMembers],\n  comandos: [antiraid],\n  componentes,\n  eventos: { guildMemberAdd: aoEntrar },\n  aoIniciar(client) {\n    // encerra modos raid esquecidos (ex.: bot ficou desligado)\n    setInterval(() => {\n      for (const guild of client.guilds.cache.values()) {\n        const c = cfg(guild.id);\n        if (c.emRaid && Date.now() - c.inicio > DURACAO_RAID) encerrarRaid(guild, null).catch(() => {});\n      }\n    }, 60_000);\n  },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      if (!c.ativo) return [tx('desligado_antiraid_configurar')];\n      return [tx('entradas_acao_alerta', { limite: c.limite, segundos: c.segundos, acao: c.acao, alerta: c.alerta, modo_raid: c.emRaid ? tx('modo_raid_2') : '' })];\n    },\n  },\n};\n",
  "src/modules/anuncios.js": "import { ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { CONFIG, embed, responder, cortar, lerDuracao, duracaoTexto, ts } from '../core/util.js';\nimport { textos, visuais } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('anuncios', {\n  america_sao_paulo: 'America/Sao_Paulo',\n  nenhum_anuncio_agendado_use: ['Nenhum anúncio agendado. Use `/anuncio criar`.', 'resposta'],\n  cada: ' · a cada {duracao}',\n  anuncios_agendados: ['📣 Anúncios agendados', 'titulo'],\n  anuncio_encontrado_escolha_lista: ['Anúncio não encontrado. Escolha na lista enquanto digita.', 'resposta'],\n  enviado: 'Enviado em <#{canal}>.',\n  consegui_enviar_confira_minhas: 'Não consegui enviar. Confira as minhas permissões no canal.',\n  anuncio_cancelado: ['Anúncio cancelado.', 'resposta'],\n  maximo_anuncios_agendados: ['No máximo {limite} anúncios agendados.', 'resposta'],\n  essa_data_ja_passou: ['Essa data já passou. Confira o dia e o horário.', 'resposta'],\n  entendi_data_use_algo: ['Não entendi a data. Use algo como **25/12 09:00**, **18:30**, **9h** ou **em 2h**.', 'resposta'],\n  entendi_repetir_use_algo: ['Não entendi o \"repetir\". Use algo como **12h**, **1d** ou **7d**.', 'resposta'],\n  virar_spam_intervalo_minimo: ['Para não virar spam, o intervalo mínimo é de 10 minutos.', 'resposta'],\n  link_imagem_precisa_comecar: ['O link da imagem precisa começar com https://', 'resposta'],\n  depois_cada: ' e depois a cada **{duracao}**',\n  anuncio_agendado: ['Anúncio agendado para {quando} ({relativo}){duracao} em <#{canal}>.', 'resposta'],\n  anuncios_agendados_2: 'Anúncios agendados',\n  anuncio_agendado_anuncio_lista: '{total} anúncio(s) agendado(s) (`/anuncio lista`)',\n  nenhum_anuncio_criar: 'Nenhum (`/anuncio criar`)',\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('anuncios', {\n  anuncio: { nome: \"Anúncio agendado\", vars: [] },\n});\n\n/**\n * Anúncios agendados: mensagens que saem numa data marcada ou que repetem\n * de tempos em tempos (ex.: lembrar as regras toda segunda às 9h).\n */\n\nconst anuncios = colecao('anuncios'); // guild -> { lista: [...] }\nconst LIMITE = 20;\nconst MIN_INTERVALO = 10 * 60_000;\nconst FUSO = CONFIG.fuso || tx('america_sao_paulo');\nconst lista = (guildId) => (anuncios.de(guildId).lista ??= []);\n\n/** Diferença (ms) entre o fuso escolhido e o UTC num instante. */\nfunction offsetFuso(data) {\n  const p = Object.fromEntries(\n    new Intl.DateTimeFormat('en-US', { timeZone: FUSO, hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric', second: 'numeric' })\n      .formatToParts(data)\n      .map((x) => [x.type, x.value])\n  );\n  return Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) - data.getTime();\n}\n\n/**\n * \"25/12 09:00\", \"25/12/2026 9h\", \"09:30\" ou \"9h\" (hoje, ou amanhã se já passou)\n * e \"em 2h\" / \"em 30min\" / \"em 1d\" (daqui a). null se não entender.\n */\nexport function lerQuando(texto) {\n  if (!texto) return Date.now();\n  const t = texto.trim().toLowerCase();\n  if (t.startsWith('em ')) {\n    const rel = lerDuracao(t.slice(3).trim());\n    return rel ? Date.now() + rel : null;\n  }\n  const m = /^(?:(\\d{1,2})\\/(\\d{1,2})(?:\\/(\\d{2,4}))?\\s*)?(?:às\\s*|as\\s*)?(\\d{1,2})(?:[:h](\\d{2})?)?h?$/.exec(t);\n  if (!m) return null;\n  const agora = new Date();\n  const local = new Date(agora.getTime() + offsetFuso(agora)); // \"relógio\" do fuso, em UTC\n  let [dia, mes, ano] = [m[1] ? Number(m[1]) : local.getUTCDate(), m[2] ? Number(m[2]) : local.getUTCMonth() + 1, m[3] ? Number(m[3]) : local.getUTCFullYear()];\n  if (ano < 100) ano += 2000;\n  const hora = Number(m[4]);\n  const minuto = Number(m[5] ?? 0);\n  if (mes < 1 || mes > 12 || dia < 1 || dia > 31 || hora > 23 || minuto > 59) return null;\n  let quando = Date.UTC(ano, mes - 1, dia, hora, minuto);\n  if (new Date(quando).getUTCDate() !== dia) return null; // ex.: 31/02\n  quando -= offsetFuso(new Date(quando));\n  if (!m[1] && quando < Date.now()) quando += 86400e3; // só a hora e já passou: amanhã\n  if (m[1] && quando < Date.now() - 60_000) {\n    // data sem ano que passou faz tempo (ex.: 1/1): é a do ano que vem\n    if (!m[3] && quando < Date.now() - 86400e3) {\n      quando = Date.UTC(ano + 1, mes - 1, dia, hora, minuto);\n      return quando - offsetFuso(new Date(quando));\n    }\n    return -1; // passou há pouco (provável engano)\n  }\n  return quando;\n}\n\nfunction mensagem(guildId, a) {\n  const e = embed(guildId).setDescription(a.texto);\n  if (a.titulo) e.setTitle(a.titulo);\n  vis(e, 'anuncio', {}); // a imagem do próprio anúncio vem depois e tem prioridade\n  if (a.imagem) e.setImage(a.imagem);\n  return { content: a.cargo ? (a.cargo === guildId ? '@everyone' : `<@&${a.cargo}>`) : undefined, embeds: [e], allowedMentions: { parse: a.cargo === guildId ? ['everyone'] : [], roles: a.cargo && a.cargo !== guildId ? [a.cargo] : [] } };\n}\n\nasync function enviar(client, guildId, a) {\n  const canal = await client.channels.fetch(a.canal).catch(() => null);\n  if (!canal?.isTextBased()) return false;\n  return canal.send(mensagem(guildId, a)).then(() => true, () => false);\n}\n\nasync function verificar(client) {\n  const agora = Date.now();\n  for (const [guildId, g] of Object.entries(anuncios.raiz)) {\n    if (!client.guilds.cache.has(guildId) || !g.lista?.length) continue;\n    let mudou = false;\n    for (const a of [...g.lista]) {\n      if (a.proximo > agora) continue;\n      await enviar(client, guildId, a);\n      mudou = true;\n      if (a.intervalo) {\n        // pula os horários perdidos enquanto o bot estava desligado\n        while (a.proximo <= agora) a.proximo += a.intervalo;\n      } else g.lista = g.lista.filter((x) => x.id !== a.id);\n    }\n    if (mudou) anuncios.salvar();\n  }\n}\n\nconst anuncio = {\n  data: new SlashCommandBuilder()\n    .setName('anuncio')\n    .setDescription('Anúncios agendados e repetidos')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('criar')\n        .setDescription('Agenda um anúncio')\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde enviar').setRequired(true).addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n        .addStringOption((o) => o.setName('mensagem').setDescription('Texto do anúncio (use \\\\n para pular linha)').setRequired(true).setMaxLength(1900))\n        .addStringOption((o) => o.setName('quando').setDescription('Ex.: \"25/12 09:00\", \"18:30\", \"9h\" ou \"em 2h\". Vazio = agora'))\n        .addStringOption((o) => o.setName('repetir').setDescription('Repetir a cada... ex.: \"1d\", \"12h\", \"7d\" (vazio = uma vez só)'))\n        .addStringOption((o) => o.setName('titulo').setDescription('Título (opcional)').setMaxLength(200))\n        .addRoleOption((o) => o.setName('mencionar').setDescription('Cargo para marcar (opcional)'))\n        .addStringOption((o) => o.setName('imagem').setDescription('Link de uma imagem (opcional)'))\n    )\n    .addSubcommand((s) => s.setName('lista').setDescription('Mostra os anúncios agendados'))\n    .addSubcommand((s) =>\n      s\n        .setName('apagar')\n        .setDescription('Cancela um anúncio')\n        .addStringOption((o) => o.setName('anuncio').setDescription('Qual').setRequired(true).setAutocomplete(true))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('testar')\n        .setDescription('Envia um anúncio agora (sem mudar o agendamento)')\n        .addStringOption((o) => o.setName('anuncio').setDescription('Qual').setRequired(true).setAutocomplete(true))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    const l = lista(i.guildId);\n    if (sub === 'lista') {\n      if (!l.length) return responder(i, tx('nenhum_anuncio_agendado_use'), 'aviso');\n      const linhas = l.map((a) => `\\`${a.id}\\` · <#${a.canal}> · ${ts(a.proximo, 'f')}${a.intervalo ? tx('cada', { duracao: duracaoTexto(a.intervalo) }) : ''}\\n> ${cortar(a.titulo || a.texto.replace(/\\n/g, ' '), 80)}`);\n      return i.reply({ embeds: [embed(i.guildId).setTitle(tx('anuncios_agendados')).setDescription(cortar(linhas.join('\\n'), 4000))], flags: 64 });\n    }\n    if (sub === 'apagar' || sub === 'testar') {\n      const a = l.find((x) => x.id === i.options.getString('anuncio'));\n      if (!a) return responder(i, tx('anuncio_encontrado_escolha_lista'), 'erro');\n      if (sub === 'testar') return responder(i, (await enviar(i.client, i.guildId, a)) ? tx('enviado', { canal: a.canal }) : tx('consegui_enviar_confira_minhas'), 'sucesso');\n      anuncios.de(i.guildId).lista = l.filter((x) => x.id !== a.id);\n      anuncios.salvar();\n      return responder(i, tx('anuncio_cancelado'), 'sucesso');\n    }\n    // criar\n    if (l.length >= LIMITE) return responder(i, tx('maximo_anuncios_agendados', { limite: LIMITE }), 'erro');\n    const quando = lerQuando(i.options.getString('quando'));\n    if (quando === -1) return responder(i, tx('essa_data_ja_passou'), 'erro');\n    if (!quando) return responder(i, tx('entendi_data_use_algo'), 'erro');\n    const repetir = i.options.getString('repetir');\n    const intervalo = repetir ? lerDuracao(repetir) : null;\n    if (repetir && !intervalo) return responder(i, tx('entendi_repetir_use_algo'), 'erro');\n    if (intervalo && intervalo < MIN_INTERVALO) return responder(i, tx('virar_spam_intervalo_minimo'), 'erro');\n    const imagem = i.options.getString('imagem');\n    if (imagem && !/^https?:\\/\\/\\S+$/i.test(imagem)) return responder(i, tx('link_imagem_precisa_comecar'), 'erro');\n    const a = {\n      id: Date.now().toString(36).slice(-6),\n      canal: i.options.getChannel('canal').id,\n      texto: i.options.getString('mensagem').replace(/\\\\n/g, '\\n'),\n      titulo: i.options.getString('titulo') ?? null,\n      cargo: i.options.getRole('mencionar')?.id ?? null,\n      imagem: imagem ?? null,\n      proximo: Math.max(quando, Date.now() + 5000),\n      intervalo,\n    };\n    l.push(a);\n    anuncios.salvar();\n    return responder(i, tx('anuncio_agendado', { quando: ts(a.proximo, 'f'), relativo: ts(a.proximo), duracao: intervalo ? tx('depois_cada', { duracao: duracaoTexto(intervalo) }) : '', canal: a.canal }), 'sucesso');\n  },\n  async autocompletar(i) {\n    const foco = (i.options.getFocused() || '').toLowerCase();\n    await i.respond(\n      (anuncios.ler(i.guildId, 'lista') ?? [])\n        .filter((a) => `${a.id} ${a.titulo ?? ''} ${a.texto}`.toLowerCase().includes(foco))\n        .slice(0, 25)\n        .map((a) => ({ name: cortar(`${a.id} · ${a.titulo || a.texto.replace(/\\n/g, ' ')}`, 100), value: a.id }))\n    );\n  },\n};\n\nexport default {\n  id: 'anuncios',\n  nome: tx('anuncios_agendados_2'),\n  permissoes: [PermissionFlagsBits.MentionEveryone],\n  comandos: [anuncio],\n  aoIniciar(client) {\n    verificar(client).catch((e) => console.error('[anúncios]', e.message));\n    setInterval(() => verificar(client).catch((e) => console.error('[anúncios]', e.message)), 30_000);\n  },\n  config: {\n    resumo(guild) {\n      const n = anuncios.ler(guild.id, 'lista')?.length ?? 0;\n      return [n ? tx('anuncio_agendado_anuncio_lista', { total: n }) : tx('nenhum_anuncio_criar')];\n    },\n  },\n};\n",
  "src/modules/automod.js": "import { ChannelType, GatewayIntentBits, PermissionFlagsBits } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, lerDuracao, duracaoTexto, cortar, marcarRemovida, CORES } from '../core/util.js';\nimport { textos } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('automod', {\n  convite_outro_servidor: 'Convite de outro servidor',\n  link_permitido: 'Link não permitido',\n  palavra_proibida: 'Palavra proibida',\n  mencoes_massa: 'Menções em massa ({limite})',\n  excesso_letras_maiusculas: 'Excesso de letras maiúsculas',\n  flood_mensagens_rapidas_demais: 'Flood (mensagens rápidas demais)',\n  automod: ['🛡️ AutoMod', 'titulo'],\n  membro: ['Membro', 'campo'],\n  canal: ['Canal', 'campo'],\n  motivo: ['Motivo', 'campo'],\n  mensagem: ['Mensagem', 'campo'],\n  sem_texto: '(sem texto)',\n  consegui_apagar_me_permissao: '{motivo} (não consegui apagar: me dê a permissão Gerenciar mensagens)',\n  sua_mensagem_foi_apagada: '{autor}, sua mensagem foi apagada: **{motivo}**.',\n  castigo: ' Castigo de {duracao}.',\n  automod_ligado_ajuste_filtros: 'AutoMod **ligado**. Ajuste os filtros com os outros /config automod.',\n  automod_desligado: 'AutoMod **desligado**.',\n  links_bloqueados_exceto_sites: 'Links bloqueados (exceto os sites liberados).',\n  links_liberados: 'Links liberados.',\n  links_liberados_2: 'Links de **{site}** liberados.',\n  links_bloqueados_novo: 'Links de **{site}** bloqueados de novo.',\n  convites_outros_servidores_bloqueado: 'Convites de outros servidores bloqueados.',\n  convites_liberados: 'Convites liberados.',\n  palavra_adicionada_total: 'Palavra adicionada ({palavras_total} no total).',\n  palavra_removida_total: 'Palavra removida ({palavras_total} no total).',\n  flood_maximo_mensagens_cada: 'Flood: no máximo **{spam}** mensagens a cada 5 segundos.',\n  filtro_flood_desligado: 'Filtro de flood desligado.',\n  mensagens_caps_serao_apagadas: 'Mensagens em CAPS serão apagadas.',\n  filtro_caps_desligado: 'Filtro de CAPS desligado.',\n  mensagens_ou_mais_mencoes: 'Mensagens com **{mencoes}** ou mais menções serão apagadas.',\n  filtro_mencoes_desligado: 'Filtro de menções desligado.',\n  duracao_invalida_ex_5m: ['Duração inválida (ex.: 5m, 1h).', 'resposta'],\n  alem_apagar_castigo: 'Além de apagar, castigo de **{duracao}**.',\n  automod_so_vai_apagar: 'O AutoMod só vai apagar as mensagens.',\n  agora_imune_automod: '{cargo} agora é imune ao AutoMod.',\n  mais_imune: '{cargo} não é mais imune.',\n  automod_vai_ignorar: 'O AutoMod vai ignorar {canal}.',\n  automod_volta_vigiar: 'O AutoMod volta a vigiar {canal}.',\n  automod_vai_registrar: 'O AutoMod vai registrar em {canal}.',\n  registro_automod_desligado: 'Registro do AutoMod desligado.',\n  desligado_use_config_automod: 'Desligado (use /config automod ativar)',\n  liberados: ' (liberados: {dominiosPermitidos})',\n  links: 'links{dominiosPermitidos}',\n  palavra: '{palavras_total} palavra(s)',\n  flood_5s: 'flood > {spam}/5s',\n  caps: 'CAPS',\n  mencoes: '{mencoes}+ menções',\n  nenhum: 'nenhum',\n  filtros: 'Filtros: {filtros}',\n  apagar_castigo: 'apagar + castigo de {duracao}',\n  apagar: 'apagar',\n  punicao: 'Punição: {duracao}',\n  desligado: 'desligado',\n  registro: 'Registro: {registro}',\n});\n\n/**\n * AutoMod: apaga sozinho links, convites, palavras proibidas, flood, CAPS e menções em massa.\n * Quem tem \"Gerenciar mensagens\", os cargos imunes e os canais ignorados ficam de fora.\n */\n\nconst PADRAO = {\n  ativo: false,\n  links: false,\n  dominiosPermitidos: [],\n  convites: true,\n  palavras: [],\n  spam: 0, // mensagens em 5 s (0 = desligado)\n  maiusculas: false,\n  mencoes: 0, // menções numa mensagem (0 = desligado)\n  acao: 'apagar', // apagar | castigo\n  duracao: 300_000,\n  imunes: [],\n  ignorados: [],\n  canalLog: null,\n};\nconst cfg = (guildId) => ajustes(guildId, 'automod', PADRAO);\n\nconst RE_LINK = /\\bhttps?:\\/\\/([^\\s/$.?#]+\\.[^\\s/?#]+)[^\\s]*/gi;\nconst RE_CONVITE = /(discord\\.gg|discord(?:app)?\\.com\\/invite|dsc\\.gg)\\/[\\w-]+/i;\n\n// controle de flood: guildId:userId -> horários das últimas mensagens\nconst recentes = new Map();\nsetInterval(() => {\n  const limite = Date.now() - 10_000;\n  for (const [k, lista] of recentes) if (!lista.length || lista.at(-1) < limite) recentes.delete(k);\n}, 60_000).unref();\n\nconst normalizar = (s) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');\n\nfunction verificar(msg, c) {\n  const texto = msg.content || '';\n  if (c.convites && RE_CONVITE.test(texto)) return tx('convite_outro_servidor');\n  if (c.links) {\n    for (const m of texto.matchAll(RE_LINK)) {\n      const dominio = m[1].toLowerCase().replace(/^www\\./, '');\n      const liberado = c.dominiosPermitidos.some((d) => dominio === d || dominio.endsWith(`.${d}`));\n      if (!liberado) return tx('link_permitido');\n    }\n  }\n  if (c.palavras.length) {\n    const t = normalizar(texto);\n    const achou = c.palavras.find((p) => new RegExp(`(^|[^\\\\p{L}\\\\p{N}])${normalizar(p).replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')}($|[^\\\\p{L}\\\\p{N}])`, 'u').test(t));\n    if (achou) return tx('palavra_proibida');\n  }\n  if (c.mencoes > 0) {\n    const n = msg.mentions.users.size + msg.mentions.roles.size;\n    if (n >= c.mencoes) return tx('mencoes_massa', { limite: n });\n  }\n  if (c.maiusculas) {\n    const letras = texto.replace(/[^a-zA-ZÀ-ÿ]/g, '');\n    if (letras.length >= 12 && letras.replace(/[^A-ZÀ-Þ]/g, '').length / letras.length > 0.7) return tx('excesso_letras_maiusculas');\n  }\n  if (c.spam > 0) {\n    const k = `${msg.guildId}:${msg.author.id}`;\n    const agora = Date.now();\n    const lista = (recentes.get(k) ?? []).filter((t) => agora - t < 5000);\n    lista.push(agora);\n    recentes.set(k, lista);\n    if (lista.length > c.spam) return tx('flood_mensagens_rapidas_demais');\n  }\n  return null;\n}\n\nasync function registrar(msg, motivo, c) {\n  if (!c.canalLog) return;\n  const canal = msg.guild.channels.cache.get(c.canalLog);\n  if (!canal?.isTextBased()) return;\n  await canal\n    .send({\n      embeds: [\n        embed(msg.guildId)\n          .setColor(CORES.aviso)\n          .setTitle(tx('automod'))\n          .addFields(\n            { name: tx('membro'), value: `${msg.author} (${msg.author.tag})`, inline: true },\n            { name: tx('canal'), value: `${msg.channel}`, inline: true },\n            { name: tx('motivo'), value: motivo },\n            { name: tx('mensagem'), value: cortar(msg.content || tx('sem_texto'), 1000) },\n          )\n          .setTimestamp(),\n      ],\n    })\n    .catch(() => {});\n}\n\nasync function aoMensagem(msg) {\n  if (!msg.inGuild() || msg.author.bot || !msg.member) return;\n  const c = cfg(msg.guildId);\n  if (!c.ativo) return;\n  if (msg.member.permissions.has(PermissionFlagsBits.ManageMessages)) return;\n  if (c.ignorados.includes(msg.channelId) || c.ignorados.includes(msg.channel.parentId)) return;\n  if (c.imunes.some((r) => msg.member.roles.cache.has(r))) return;\n\n  const motivo = verificar(msg, c);\n  if (!motivo) return;\n\n  marcarRemovida(msg.id); // os outros módulos ignoram esta mensagem\n  const apagou = await msg.delete().then(() => true, () => false);\n  if (!apagou) {\n    // sem a permissão \"Gerenciar mensagens\" neste canal: só registra\n    return registrar(msg, tx('consegui_apagar_me_permissao', { motivo }), c);\n  }\n  let texto = tx('sua_mensagem_foi_apagada', { autor: msg.author, motivo });\n  if (c.acao === 'castigo' && msg.member.moderatable) {\n    const ok = await msg.member.timeout(c.duracao, `AutoMod: ${motivo}`).then(() => true, () => false);\n    if (ok) texto += tx('castigo', { duracao: duracaoTexto(c.duracao) });\n  }\n  const aviso = await msg.channel.send({ content: texto, allowedMentions: { users: [msg.author.id] } }).catch(() => null);\n  if (aviso) setTimeout(() => aviso.delete().catch(() => {}), 8000);\n  await registrar(msg, motivo, c);\n}\n\n// ---------------- /config automod ----------------\nconst config = {\n  grupo: 'automod',\n  montar: (g) =>\n    g\n      .setDescription('AutoMod: filtros automáticos de mensagens')\n      .addSubcommand((s) => s.setName('ativar').setDescription('Liga ou desliga o AutoMod').addBooleanOption((o) => o.setName('ligado').setDescription('Ligado?').setRequired(true)))\n      .addSubcommand((s) => s.setName('links').setDescription('Bloquear links').addBooleanOption((o) => o.setName('bloquear').setDescription('Bloquear?').setRequired(true)))\n      .addSubcommand((s) =>\n        s.setName('permitir-site').setDescription('Libera (ou bloqueia de novo) links de um site').addStringOption((o) => o.setName('site').setDescription('Ex.: youtube.com').setRequired(true).setMaxLength(100))\n      )\n      .addSubcommand((s) => s.setName('convites').setDescription('Bloquear convites de outros servidores').addBooleanOption((o) => o.setName('bloquear').setDescription('Bloquear?').setRequired(true)))\n      .addSubcommand((s) =>\n        s.setName('palavra').setDescription('Adiciona ou remove uma palavra proibida').addStringOption((o) => o.setName('palavra').setDescription('A palavra').setRequired(true).setMaxLength(60))\n      )\n      .addSubcommand((s) =>\n        s.setName('flood').setDescription('Mensagens permitidas em 5 segundos').addIntegerOption((o) => o.setName('limite').setDescription('0 desliga').setRequired(true).setMinValue(0).setMaxValue(20))\n      )\n      .addSubcommand((s) => s.setName('maiusculas').setDescription('Apagar mensagens quase todas em CAPS').addBooleanOption((o) => o.setName('ligado').setDescription('Ligado?').setRequired(true)))\n      .addSubcommand((s) =>\n        s.setName('mencoes').setDescription('Máximo de menções numa mensagem').addIntegerOption((o) => o.setName('limite').setDescription('0 desliga').setRequired(true).setMinValue(0).setMaxValue(50))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('punicao')\n          .setDescription('O que fazer além de apagar')\n          .addStringOption((o) =>\n            o.setName('acao').setDescription('Ação').setRequired(true).addChoices({ name: 'Só apagar', value: 'apagar' }, { name: 'Apagar e dar castigo', value: 'castigo' })\n          )\n          .addStringOption((o) => o.setName('duracao').setDescription('Duração do castigo, ex.: 5m').setMaxLength(20))\n      )\n      .addSubcommand((s) => s.setName('imune').setDescription('Cargo que o AutoMod ignora (usar de novo remove)').addRoleOption((o) => o.setName('cargo').setDescription('Cargo').setRequired(true)))\n      .addSubcommand((s) =>\n        s\n          .setName('ignorar-canal')\n          .setDescription('Canal ou categoria que o AutoMod ignora (usar de novo remove)')\n          .addChannelOption((o) => o.setName('canal').setDescription('Canal').setRequired(true).addChannelTypes(ChannelType.GuildText, ChannelType.GuildCategory, ChannelType.GuildAnnouncement))\n      )\n      .addSubcommand((s) =>\n        s.setName('registro').setDescription('Canal onde o AutoMod registra o que apagou').addChannelOption((o) => o.setName('canal').setDescription('Vazio desliga').addChannelTypes(ChannelType.GuildText))\n      ),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    const alternar = (lista, valor) => {\n      const idx = lista.indexOf(valor);\n      if (idx >= 0) lista.splice(idx, 1);\n      else lista.push(valor);\n      return idx < 0;\n    };\n    let msg;\n    switch (sub) {\n      case 'ativar':\n        c.ativo = i.options.getBoolean('ligado');\n        msg = c.ativo ? tx('automod_ligado_ajuste_filtros') : tx('automod_desligado');\n        break;\n      case 'links':\n        c.links = i.options.getBoolean('bloquear');\n        msg = c.links ? tx('links_bloqueados_exceto_sites') : tx('links_liberados');\n        break;\n      case 'permitir-site': {\n        const site = i.options.getString('site').toLowerCase().replace(/^https?:\\/\\//, '').replace(/^www\\./, '').split('/')[0];\n        msg = alternar(c.dominiosPermitidos, site) ? tx('links_liberados_2', { site }) : tx('links_bloqueados_novo', { site });\n        break;\n      }\n      case 'convites':\n        c.convites = i.options.getBoolean('bloquear');\n        msg = c.convites ? tx('convites_outros_servidores_bloqueado') : tx('convites_liberados');\n        break;\n      case 'palavra': {\n        const p = i.options.getString('palavra').trim().toLowerCase();\n        msg = alternar(c.palavras, p) ? tx('palavra_adicionada_total', { palavras_total: c.palavras.length }) : tx('palavra_removida_total', { palavras_total: c.palavras.length });\n        break;\n      }\n      case 'flood':\n        c.spam = i.options.getInteger('limite');\n        msg = c.spam ? tx('flood_maximo_mensagens_cada', { spam: c.spam }) : tx('filtro_flood_desligado');\n        break;\n      case 'maiusculas':\n        c.maiusculas = i.options.getBoolean('ligado');\n        msg = c.maiusculas ? tx('mensagens_caps_serao_apagadas') : tx('filtro_caps_desligado');\n        break;\n      case 'mencoes':\n        c.mencoes = i.options.getInteger('limite');\n        msg = c.mencoes ? tx('mensagens_ou_mais_mencoes', { mencoes: c.mencoes }) : tx('filtro_mencoes_desligado');\n        break;\n      case 'punicao': {\n        c.acao = i.options.getString('acao');\n        const d = i.options.getString('duracao');\n        if (d) {\n          const ms = lerDuracao(d);\n          if (!ms || ms > 28 * 86_400_000) return responder(i, tx('duracao_invalida_ex_5m'), 'erro');\n          c.duracao = ms;\n        }\n        msg = c.acao === 'castigo' ? tx('alem_apagar_castigo', { duracao: duracaoTexto(c.duracao) }) : tx('automod_so_vai_apagar');\n        break;\n      }\n      case 'imune': {\n        const r = i.options.getRole('cargo');\n        msg = alternar(c.imunes, r.id) ? tx('agora_imune_automod', { cargo: r }) : tx('mais_imune', { cargo: r });\n        break;\n      }\n      case 'ignorar-canal': {\n        const ch = i.options.getChannel('canal');\n        msg = alternar(c.ignorados, ch.id) ? tx('automod_vai_ignorar', { canal: ch }) : tx('automod_volta_vigiar', { canal: ch });\n        break;\n      }\n      case 'registro': {\n        const ch = i.options.getChannel('canal');\n        c.canalLog = ch?.id ?? null;\n        msg = ch ? tx('automod_vai_registrar', { canal: ch }) : tx('registro_automod_desligado');\n        break;\n      }\n    }\n    salvarAjustes();\n    return responder(i, msg, 'sucesso');\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    if (!c.ativo) return [tx('desligado_use_config_automod')];\n    const f = [];\n    if (c.convites) f.push('convites');\n    if (c.links) f.push(tx('links', { dominiosPermitidos: c.dominiosPermitidos.length ? tx('liberados', { dominiosPermitidos: c.dominiosPermitidos.join(', ') }) : '' }));\n    if (c.palavras.length) f.push(tx('palavra', { palavras_total: c.palavras.length }));\n    if (c.spam) f.push(tx('flood_5s', { spam: c.spam }));\n    if (c.maiusculas) f.push(tx('caps'));\n    if (c.mencoes) f.push(tx('mencoes', { mencoes: c.mencoes }));\n    return [\n      tx('filtros', { filtros: f.length ? f.join(', ') : tx('nenhum') }),\n      tx('punicao', { duracao: c.acao === 'castigo' ? tx('apagar_castigo', { duracao: duracaoTexto(c.duracao) }) : tx('apagar') }),\n      tx('registro', { registro: c.canalLog ? `<#${c.canalLog}>` : tx('desligado') }),\n    ];\n  },\n};\n\nexport default {\n  id: 'automod',\n  nome: 'AutoMod',\n  prioridade: 0, // roda antes dos outros módulos nas mensagens novas\n  intents: [GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent],\n  permissoes: [PermissionFlagsBits.ManageMessages, PermissionFlagsBits.ModerateMembers],\n  eventos: { messageCreate: aoMensagem },\n  config,\n};\n",
  "src/modules/autorespostas.js": "import { GatewayIntentBits, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { embed, responder, preencher, cortar, foiRemovida } from '../core/util.js';\nimport { textos } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('autorespostas', {\n  contem_palavra: 'contém a palavra',\n  exatamente: 'é exatamente',\n  comeca: 'começa com',\n  gatilho_precisa_ter_pelo: ['O gatilho precisa ter pelo menos 2 letras.', 'resposta'],\n  limite_respostas_automaticas_apague: ['Limite de {limite} respostas automáticas. Apague alguma antes.', 'resposta'],\n  atualizada: 'Atualizada',\n  criada: 'Criada',\n  quando_mensagem_eu_respondo: ['{acao}: quando a mensagem **{modo}** `{gatilho}`, eu respondo. Também dá para usar `/tag {gatilho}`.', 'resposta'],\n  achei_essa_resposta_automatica: ['Não achei essa resposta automática.', 'resposta'],\n  resposta_automatica_apagada: ['Resposta automática apagada.', 'resposta'],\n  nenhuma_resposta_automatica_ainda: ['Nenhuma resposta automática ainda. Use `/autoresposta adicionar`.', 'resposta'],\n  respostas_automaticas: ['💬 Respostas automáticas ({total})', 'titulo'],\n  achei_essa_resposta_veja: ['Não achei essa resposta. Veja as opções enquanto digita.', 'resposta'],\n  respostas_automaticas_2: 'Respostas automáticas',\n  resposta_automatica_autoresposta_lis: '{total} resposta(s) automática(s) (`/autoresposta lista`)',\n  nenhuma_ainda_autoresposta_adicionar: 'Nenhuma ainda (`/autoresposta adicionar`)',\n});\n\n/**\n * Respostas automáticas: quando alguém escreve um gatilho, o bot responde.\n * Também viram atalhos: /tag nome:regras mostra a resposta salva.\n * Variáveis na resposta: {usuario} {nome} {servidor} {canal}\n */\n\nconst respostas = colecao('autorespostas');\nconst LIMITE = 50;\nconst MODOS = { contem: tx('contem_palavra'), igual: tx('exatamente'), comeca: tx('comeca') };\nconst recentes = new Map(); // anti-spam: \"canal:gatilho\" -> quando respondeu\n\nconst normalizar = (t) =>\n  String(t ?? '')\n    .normalize('NFD')\n    .replace(/[̀-ͯ]/g, '')\n    .toLowerCase()\n    .trim();\nconst escapar = (t) => t.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\nconst lista = (guildId) => respostas.de(guildId, 'itens').lista ?? (respostas.de(guildId, 'itens').lista = []);\n\nfunction bate(item, texto) {\n  const g = normalizar(item.gatilho);\n  if (item.modo === 'igual') return texto === g;\n  if (item.modo === 'comeca') return texto.startsWith(g);\n  return new RegExp(`(^|[^\\\\p{L}\\\\p{N}])${escapar(g)}($|[^\\\\p{L}\\\\p{N}])`, 'u').test(texto);\n}\n\nconst vars = (guild, user, canal) => ({ usuario: `${user}`, nome: user.displayName ?? user.username, servidor: guild.name, canal: `${canal}` });\n\nasync function aoMensagem(msg) {\n  if (!msg.inGuild() || msg.author.bot || !msg.content) return;\n  if (foiRemovida(msg.id)) return; // apagada pelo AutoMod\n  const itens = respostas.ler(msg.guildId, 'itens')?.lista;\n  if (!itens?.length) return;\n  const texto = normalizar(msg.content);\n  const item = itens.find((it) => bate(it, texto));\n  if (!item) return;\n  const k = `${msg.channelId}:${item.gatilho}`;\n  if (Date.now() - (recentes.get(k) ?? 0) < 10_000) return; // no máximo uma vez a cada 10 s por canal\n  recentes.set(k, Date.now());\n  await msg.reply({ content: preencher(item.resposta, vars(msg.guild, msg.author, msg.channel)), allowedMentions: { users: [msg.author.id], repliedUser: false } }).catch(() => {});\n}\n\nconst autoresposta = {\n  data: new SlashCommandBuilder()\n    .setName('autoresposta')\n    .setDescription('Gerencia as respostas automáticas')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('adicionar')\n        .setDescription('Cria (ou troca) uma resposta automática')\n        .addStringOption((o) => o.setName('gatilho').setDescription('Palavra ou frase que dispara a resposta').setRequired(true).setMaxLength(60))\n        .addStringOption((o) => o.setName('resposta').setDescription('O que o bot responde. Variáveis: {usuario} {nome} {servidor} {canal}').setRequired(true).setMaxLength(1800))\n        .addStringOption((o) =>\n          o\n            .setName('modo')\n            .setDescription('Quando responder (padrão: quando a mensagem contém a palavra)')\n            .addChoices({ name: 'contém a palavra', value: 'contem' }, { name: 'é exatamente', value: 'igual' }, { name: 'começa com', value: 'comeca' })\n        )\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('remover')\n        .setDescription('Apaga uma resposta automática')\n        .addStringOption((o) => o.setName('gatilho').setDescription('Qual apagar').setRequired(true).setAutocomplete(true))\n    )\n    .addSubcommand((s) => s.setName('lista').setDescription('Mostra todas as respostas automáticas')),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    const itens = lista(i.guildId);\n    if (sub === 'adicionar') {\n      const gatilho = i.options.getString('gatilho').trim();\n      if (normalizar(gatilho).length < 2) return responder(i, tx('gatilho_precisa_ter_pelo'), 'erro');\n      const existente = itens.find((x) => normalizar(x.gatilho) === normalizar(gatilho));\n      if (!existente && itens.length >= LIMITE) return responder(i, tx('limite_respostas_automaticas_apague', { limite: LIMITE }), 'erro');\n      const item = { gatilho, resposta: i.options.getString('resposta'), modo: i.options.getString('modo') ?? 'contem' };\n      if (existente) Object.assign(existente, item);\n      else itens.push(item);\n      respostas.salvar();\n      return responder(i, tx('quando_mensagem_eu_respondo', { acao: existente ? tx('atualizada') : tx('criada'), modo: MODOS[item.modo], gatilho }), 'sucesso');\n    }\n    if (sub === 'remover') {\n      const g = normalizar(i.options.getString('gatilho'));\n      const antes = itens.length;\n      const restantes = itens.filter((x) => normalizar(x.gatilho) !== g);\n      if (restantes.length === antes) return responder(i, tx('achei_essa_resposta_automatica'), 'erro');\n      respostas.de(i.guildId, 'itens').lista = restantes;\n      respostas.salvar();\n      return responder(i, tx('resposta_automatica_apagada'), 'sucesso');\n    }\n    if (!itens.length) return responder(i, tx('nenhuma_resposta_automatica_ainda'), 'aviso');\n    const linhas = itens.map((x) => `• \\`${x.gatilho}\\` (${MODOS[x.modo] ?? MODOS.contem}) → ${cortar(x.resposta.replace(/\\n/g, ' '), 60)}`);\n    return i.reply({ embeds: [embed(i.guildId).setTitle(tx('respostas_automaticas', { total: itens.length })).setDescription(cortar(linhas.join('\\n'), 4000))], flags: 64 });\n  },\n  async autocompletar(i) {\n    const foco = normalizar(i.options.getFocused());\n    const itens = respostas.ler(i.guildId, 'itens')?.lista ?? [];\n    await i.respond(itens.filter((x) => normalizar(x.gatilho).includes(foco)).slice(0, 25).map((x) => ({ name: x.gatilho, value: x.gatilho })));\n  },\n};\n\nconst tag = {\n  data: new SlashCommandBuilder()\n    .setName('tag')\n    .setDescription('Mostra uma resposta salva (atalho)')\n    .addStringOption((o) => o.setName('nome').setDescription('Qual resposta').setRequired(true).setAutocomplete(true))\n    .addUserOption((o) => o.setName('para').setDescription('Marcar alguém junto')),\n  async executar(i) {\n    const nome = normalizar(i.options.getString('nome'));\n    const item = (respostas.ler(i.guildId, 'itens')?.lista ?? []).find((x) => normalizar(x.gatilho) === nome);\n    if (!item) return responder(i, tx('achei_essa_resposta_veja'), 'erro');\n    const para = i.options.getUser('para');\n    const texto = preencher(item.resposta, vars(i.guild, para ?? i.user, i.channel));\n    return i.reply({ content: para ? `${para} ${texto}` : texto, allowedMentions: { users: para ? [para.id] : [] } });\n  },\n  autocompletar: autoresposta.autocompletar,\n};\n\nexport default {\n  id: 'autorespostas',\n  nome: tx('respostas_automaticas_2'),\n  intents: [GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent],\n  comandos: [autoresposta, tag],\n  eventos: { messageCreate: aoMensagem },\n  config: {\n    resumo(guild) {\n      const n = respostas.ler(guild.id, 'itens')?.lista?.length ?? 0;\n      return [n ? tx('resposta_automatica_autoresposta_lis', { total: n }) : tx('nenhuma_ainda_autoresposta_adicionar')];\n    },\n  },\n};\n",
  "src/modules/avaliacoes.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, EmbedBuilder, ModalBuilder, PermissionFlagsBits, SlashCommandBuilder, TextInputBuilder, TextInputStyle } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, cor, embed, responder, cortar, sinais, CORES, imagens } from '../core/util.js';\nimport { textos, visuais, botoes, fileira, fileiras, comDica, modais } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('avaliacoes', {\n  dica_comentario: ['', 'placeholder'],\n  como_foi_seu_atendimento: ['⭐ Como foi o seu atendimento?', 'titulo'],\n  atendente: ' (atendente: <@{atendente}>)',\n  seu_ticket_foi_fechado: ['Seu ticket **#{numero}** em **{servidor}** foi fechado{atendente}.\\nDê uma nota de 1 a 5:', 'descricao'],\n  ticket: ['{estrelas}  Ticket #{numero}', 'titulo'],\n  atendente_2: ['Atendente', 'campo'],\n  cliente: ['Cliente', 'campo'],\n  esta_avaliacao_expirou_obrigado: 'Esta avaliação expirou. Obrigado mesmo assim!',\n  voce_ja_avaliou_este: 'Você já avaliou este atendimento com {estrelas}. Obrigado!',\n  obrigado_voce_deu_ticket: ['Obrigado! Você deu **{estrelas}** para o ticket #{numero}.\\nQuer deixar um comentário?', 'descricao'],\n  comentar: ['Comentar', 'botao'],\n  ticket_2: ['Ticket #{numero}', 'rotulo'],\n  achou_atendimento: ['O que achou do atendimento?', 'rotulo'],\n  comentario_ticket: ['💬 Comentário · Ticket #{numero}', 'titulo'],\n  nota: ['Nota', 'campo'],\n  obrigado_pelo_comentario: '💜 Obrigado pelo comentário!',\n  so_quem_tem_gerenciar: ['Só quem tem **Gerenciar servidor** pode configurar.', 'resposta'],\n  ligadas: 'ligadas',\n  desligadas: 'desligadas',\n  aparecem: ' · aparecem em <#{canal}>',\n  avaliacoes: ['Avaliações {estado}{canal}.', 'resposta'],\n  ainda_ha_avaliacoes: ['Ainda não há avaliações.', 'resposta'],\n  avaliacao_oes: '**{posicao}.** <@{atendente}> · {media} ⭐ ({avaliacoes} avaliação(ões))',\n  ranking_atendimento: ['🏆 Ranking de atendimento', 'titulo'],\n  sem_atendentes_avaliados: 'Sem atendentes avaliados.',\n  media_geral_avaliacao_oes: ['Média geral: {media} ⭐ em {total} avaliação(ões)', 'rodape'],\n  ainda_tem_avaliacoes: ['{usuario} ainda não tem avaliações.', 'resposta'],\n  media_avaliacao_oes: ['Média **{media}** em {total} avaliação(ões)\\n\\n{ultimas}', 'descricao'],\n  avaliacao_atendimento: 'Avaliação de atendimento',\n  ligadas_2: 'Ligadas',\n  desligadas_2: 'Desligadas',\n  nenhum: 'nenhum',\n  canal_avaliacao_oes: '{estado} · canal: {canal} · {total} avaliação(ões)',\n});\n\nmodais('avaliacoes', { comentario: { nome: 'Comentário da avaliação', textos: ['ticket_2', 'achou_atendimento', 'dica_comentario'] } });\n\n// Botões (texto, emoji e cor personalizáveis; alguns podem ser escondidos)\nconst bt = botoes('avaliacoes', {\n  nota: { nome: \"Botões de nota (1 a 5)\", emoji: '⭐', estilo: 'Secondary', rotuloInfo: \"O texto é o número da nota. Sem cor escolhida: 4 e 5 verdes, 3 cinza, 1 e 2 vermelhos.\" },\n  comentar: { nome: \"Deixar comentário\", rotulo: 'comentar', emoji: '💬', estilo: 'Primary', ocultavel: true },\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('avaliacoes', {\n  pedido: { nome: \"Pedido de avaliação na DM\", vars: ['servidor_icone'] },\n});\n\n/**\n * Avaliação de atendimento (complemento do módulo Tickets).\n * Quando um ticket fecha, quem abriu recebe na DM: \"Como foi o atendimento?\" (1 a 5 estrelas)\n * e pode deixar um comentário. As notas vão para um canal e viram ranking dos atendentes.\n */\n\nconst pendentes = colecao('avaliacoes_pendentes'); // id -> { guildId, numero, atendente, dono, criado }\nconst notas = colecao('avaliacoes'); // guild -> { lista: [...] }\nconst PADRAO = { ativo: true, canal: null };\nconst cfg = (guildId) => ajustes(guildId, 'avaliacoes', PADRAO);\nconst estrelas = (n) => '⭐'.repeat(n) + '☆'.repeat(5 - n);\nconst VALIDADE = 7 * 86400e3;\n\n// respostas na DM (lá não tem servidor, então não dá para usar o \"responder\" de sempre)\nconst respostaDM = (guildId, texto, tipo) => ({\n  embeds: [new EmbedBuilder().setColor(tipo === 'erro' ? CORES.erro : guildId ? cor(guildId) : 0x5865f2).setDescription(texto)],\n  components: [],\n});\n\nsinais.on('ticketFechado', async ({ guild, client, dono, atendente, numero }) => {\n  const c = cfg(guild.id);\n  if (!c.ativo || !dono || dono === atendente) return;\n  const id = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;\n  pendentes.raiz[id] = { guildId: guild.id, numero, atendente: atendente ?? null, dono, criado: Date.now() };\n  pendentes.salvar();\n  const user = await client.users.fetch(dono).catch(() => null);\n  await user\n    ?.send({\n      embeds: [\n        vis(\n          embed(guild.id)\n          .setTitle(tx('como_foi_seu_atendimento'))\n          .setDescription(tx('seu_ticket_foi_fechado', { numero, servidor: guild.name, atendente: atendente ? tx('atendente', { atendente }) : '' })),\n          'pedido',\n          imagens({ guild }),\n        ),\n      ],\n      components: [\n        new ActionRowBuilder().addComponents(\n          [1, 2, 3, 4, 5].map((n) => bt('nota', { rotulo: String(n), estilo: n >= 4 ? 'Success' : n === 3 ? 'Secondary' : 'Danger' }).setCustomId(`av:nota:${id}:${n}`))\n        ),\n      ],\n    })\n    .catch(() => {});\n});\n\nasync function registrar(client, p, nota, comentario) {\n  const guild = client.guilds.cache.get(p.guildId);\n  const lista = (notas.de(p.guildId).lista ??= []);\n  lista.push({ numero: p.numero, atendente: p.atendente, dono: p.dono, nota, comentario: comentario || null, em: Date.now() });\n  if (lista.length > 5000) lista.splice(0, lista.length - 5000);\n  notas.salvar();\n  const canalId = cfg(p.guildId).canal;\n  const canal = guild && canalId && guild.channels.cache.get(canalId);\n  if (canal?.isTextBased()) {\n    const e = embed(p.guildId)\n      .setTitle(tx('ticket', { estrelas: estrelas(nota), numero: p.numero }))\n      .addFields({ name: tx('atendente_2'), value: p.atendente ? `<@${p.atendente}>` : '—', inline: true }, { name: tx('cliente'), value: `<@${p.dono}>`, inline: true })\n      .setTimestamp();\n    if (comentario) e.setDescription(cortar(comentario, 1000));\n    await canal.send({ embeds: [e], allowedMentions: { parse: [] } }).catch(() => {});\n  }\n}\n\nconst componentes = {\n  async av(i, [acao, id, valor]) {\n    const p = pendentes.raiz[id];\n    if (!p || Date.now() - p.criado > VALIDADE) {\n      return i.update(respostaDM(p?.guildId, tx('esta_avaliacao_expirou_obrigado'), 'erro')).catch(() => {});\n    }\n    if (i.user.id !== p.dono) return;\n\n    if (acao === 'nota') {\n      if (p.nota) return i.update(respostaDM(p.guildId, tx('voce_ja_avaliou_este', { estrelas: estrelas(p.nota) })));\n      const nota = Math.min(5, Math.max(1, Number(valor) || 0));\n      p.nota = nota;\n      pendentes.salvar();\n      await registrar(i.client, p, nota, null);\n      return i.update({\n        embeds: [new EmbedBuilder().setColor(cor(p.guildId)).setDescription(tx('obrigado_voce_deu_ticket', { estrelas: estrelas(nota), numero: p.numero }))],\n        components: fileiras(fileira(bt('comentar')?.setCustomId(`av:comentar:${id}`))),\n      });\n    }\n    if (acao === 'comentar') {\n      return i.showModal(\n        new ModalBuilder()\n          .setCustomId(`av:texto:${id}`)\n          .setTitle(tx('ticket_2', { numero: p.numero }))\n          .addComponents(\n            new ActionRowBuilder().addComponents(\n              comDica(new TextInputBuilder().setCustomId('texto').setLabel(tx('achou_atendimento')).setStyle(TextInputStyle.Paragraph).setRequired(true).setMaxLength(800), tx('dica_comentario'))\n            )\n          )\n      );\n    }\n    if (acao === 'texto' && i.isModalSubmit()) {\n      const texto = i.fields.getTextInputValue('texto').trim();\n      // troca a última nota (sem comentário) pela mesma nota com comentário\n      const lista = notas.ler(p.guildId, 'lista') ?? [];\n      const ultima = [...lista].reverse().find((x) => x.numero === p.numero && x.dono === p.dono && !x.comentario);\n      if (ultima) {\n        ultima.comentario = texto;\n        notas.salvar();\n        const guild = i.client.guilds.cache.get(p.guildId);\n        const canal = guild && cfg(p.guildId).canal && guild.channels.cache.get(cfg(p.guildId).canal);\n        if (canal?.isTextBased()) {\n          await canal\n            .send({ embeds: [embed(p.guildId).setTitle(tx('comentario_ticket', { numero: p.numero })).setDescription(cortar(texto, 1000)).addFields({ name: tx('nota'), value: estrelas(ultima.nota), inline: true })], allowedMentions: { parse: [] } })\n            .catch(() => {});\n        }\n      }\n      delete pendentes.raiz[id];\n      pendentes.salvar();\n      const fim = respostaDM(p.guildId, tx('obrigado_pelo_comentario'));\n      return i.update(fim).catch(() => i.reply(fim));\n    }\n  },\n};\n\nconst avaliacoes = {\n  data: new SlashCommandBuilder()\n    .setName('avaliacoes')\n    .setDescription('Avaliações dos atendimentos (tickets)')\n    .addSubcommand((s) => s.setName('ranking').setDescription('Ranking dos atendentes pela nota média'))\n    .addSubcommand((s) =>\n      s\n        .setName('atendente')\n        .setDescription('Notas de um atendente')\n        .addUserOption((o) => o.setName('usuario').setDescription('Atendente').setRequired(true))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('(Equipe) Canal das avaliações e ligar/desligar')\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde mostrar as avaliações').addChannelTypes(ChannelType.GuildText))\n        .addBooleanOption((o) => o.setName('ativo').setDescription('Pedir avaliação ao fechar ticket'))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    const lista = notas.ler(i.guildId, 'lista') ?? [];\n    if (sub === 'configurar') {\n      if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, tx('so_quem_tem_gerenciar'), 'erro');\n      const c = cfg(i.guildId);\n      const canal = i.options.getChannel('canal');\n      const ativo = i.options.getBoolean('ativo');\n      if (canal) c.canal = canal.id;\n      if (ativo !== null) c.ativo = ativo;\n      salvarAjustes();\n      return responder(i, tx('avaliacoes', { estado: c.ativo ? tx('ligadas') : tx('desligadas'), canal: c.canal ? tx('aparecem', { canal: c.canal }) : '' }), 'sucesso');\n    }\n    if (!lista.length) return responder(i, tx('ainda_ha_avaliacoes'), 'aviso');\n    if (sub === 'ranking') {\n      const por = {};\n      for (const x of lista) if (x.atendente) (por[x.atendente] ??= []).push(x.nota);\n      const linhas = Object.entries(por)\n        .map(([id, ns]) => ({ id, media: ns.reduce((a, b) => a + b, 0) / ns.length, n: ns.length }))\n        .sort((a, b) => b.media - a.media || b.n - a.n)\n        .slice(0, 15)\n        .map((x, k) => tx('avaliacao_oes', { posicao: k + 1, atendente: x.id, media: x.media.toFixed(1).replace('.', ','), avaliacoes: x.n }));\n      const geral = lista.reduce((a, b) => a + b.nota, 0) / lista.length;\n      return i.reply({\n        embeds: [embed(i.guildId).setTitle(tx('ranking_atendimento')).setDescription(linhas.join('\\n') || tx('sem_atendentes_avaliados')).setFooter({ text: tx('media_geral_avaliacao_oes', { media: geral.toFixed(1), total: lista.length }) })],\n        allowedMentions: { parse: [] },\n      });\n    }\n    const u = i.options.getUser('usuario');\n    const deles = lista.filter((x) => x.atendente === u.id);\n    if (!deles.length) return responder(i, tx('ainda_tem_avaliacoes', { usuario: u }), 'aviso');\n    const media = deles.reduce((a, b) => a + b.nota, 0) / deles.length;\n    const ultimas = deles\n      .slice(-8)\n      .reverse()\n      .map((x) => `${estrelas(x.nota)} · #${x.numero}${x.comentario ? ` · \"${cortar(x.comentario, 80)}\"` : ''}`);\n    return i.reply({\n      embeds: [embed(i.guildId).setTitle(`⭐ ${u.username}`).setDescription(tx('media_avaliacao_oes', { media: media.toFixed(1).replace('.', ','), total: deles.length, ultimas: ultimas.join('\\n') }))],\n      flags: 64,\n    });\n  },\n};\n\nexport default {\n  id: 'avaliacoes',\n  nome: tx('avaliacao_atendimento'),\n  comandos: [avaliacoes],\n  componentes,\n  componentesDM: ['av'],\n  aoIniciar() {\n    // limpa pedidos de avaliação vencidos\n    const limpar = () => {\n      for (const [id, p] of Object.entries(pendentes.raiz)) if (Date.now() - p.criado > VALIDADE) delete pendentes.raiz[id];\n      pendentes.salvar();\n    };\n    limpar();\n    setInterval(limpar, 6 * 3600e3);\n  },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      const n = notas.ler(guild.id, 'lista')?.length ?? 0;\n      return [tx('canal_avaliacao_oes', { estado: c.ativo ? tx('ligadas_2') : tx('desligadas_2'), canal: c.canal ? `<#${c.canal}>` : tx('nenhum'), total: n })];\n    },\n  },\n};\n",
  "src/modules/boasvindas.js": "import { ChannelType, GatewayIntentBits, Partials, PermissionFlagsBits } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, preencher, cortar, foiRemovida, imagens } from '../core/util.js';\nimport { textos, modeloOu, visuais } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('boasvindas', {\n  msg_entrada_padrao: 'Seja bem-vindo(a) ao **{servidor}**, {usuario}! Agora somos **{membros}** membros. 🎉',\n  msg_saida_padrao: '**{tag}** saiu do servidor. Agora somos **{membros}** membros.',\n  alguem: 'alguém',\n  mensagem: 'Mensagem de {nome} em {canal}.',\n  mensagem_desligada: 'Mensagem de {nome} desligada.',\n  mensagem_dm_definida: 'Mensagem na DM definida.',\n  mensagem_dm_desligada: 'Mensagem na DM desligada.',\n  esse_cargo_pode_ser: ['Esse cargo não pode ser dado manualmente.', 'resposta'],\n  sera_mais_dado_automaticamente: ['{cargo} não será mais dado automaticamente.', 'resposta'],\n  maximo_cargos_automaticos: ['No máximo 5 cargos automáticos.', 'resposta'],\n  meu_cargo_esta_abaixo: ' ⚠️ O meu cargo está abaixo dele: suba o meu cargo na lista para funcionar.',\n  sera_dado_quem_entrar: ['{cargo} será dado a quem entrar.{aviso}', 'resposta'],\n  defina_antes_canal_config: ['Defina antes o canal com /config boasvindas entrada.', 'resposta'],\n  mensagem_teste_enviada: 'Mensagem de teste enviada em <#{canal}>.',\n  consegui_enviar_canal_configurado: 'Não consegui enviar no canal configurado: confira as minhas permissões.',\n  desligada: 'desligada',\n  entrada: 'Entrada: {entrada}',\n  saida: 'Saída: {saida}',\n  ligada: 'ligada',\n  dm: 'DM: {dm}',\n  nenhum: 'nenhum',\n  cargos_automaticos: 'Cargos automáticos: {cargos}',\n  boas_vindas: 'Boas-vindas',\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('boasvindas', {\n  entrada: { nome: \"Mensagem de entrada\", vars: ['avatar', 'servidor_icone'], miniatura: \"{avatar}\" },\n  saida: { nome: \"Mensagem de saída\", vars: ['avatar', 'servidor_icone'], miniatura: \"{avatar}\" },\n  dm: { nome: \"Mensagem na DM de quem entra\", vars: ['avatar', 'servidor_icone'] },\n});\n\n/**\n * Boas-vindas: mensagem quando alguém entra e sai, mensagem na DM e cargos automáticos.\n * Variáveis nas mensagens: {usuario} (menção), {nome}, {tag}, {servidor}, {membros}\n */\n\nconst PADRAO = {\n  entradaCanal: null,\n  entradaMensagem: null, // vazio = texto do bot (personalizável)\n  saidaCanal: null,\n  saidaMensagem: null,\n  dmMensagem: null,\n  cargos: [],\n};\nconst cfg = (guildId) => ajustes(guildId, 'boasvindas', PADRAO);\n// mensagens padrão de versões anteriores (gravadas nos dados): contam como \"sem mensagem própria\"\nconst ANTIGA_ENTRADA = 'Seja bem-vindo(a) ao **{servidor}**, {usuario}! Agora somos **{membros}** membros. 🎉';\nconst ANTIGA_SAIDA = '**{tag}** saiu do servidor. Agora somos **{membros}** membros.';\nconst msgEntrada = (c) => modeloOu(c.entradaMensagem, ANTIGA_ENTRADA, tx('msg_entrada_padrao'));\nconst msgSaida = (c) => modeloOu(c.saidaMensagem, ANTIGA_SAIDA, tx('msg_saida_padrao'));\n\nconst variaveis = (member) => ({\n  usuario: `<@${member.id}>`,\n  nome: member.displayName ?? member.user?.username ?? tx('alguem'),\n  tag: member.user?.tag ?? member.user?.username ?? member.id,\n  servidor: member.guild.name,\n  membros: member.guild.memberCount,\n});\n\nasync function enviarEntrada(member, canalId, mensagem) {\n  const canal = member.guild.channels.cache.get(canalId);\n  if (!canal?.isTextBased()) return false;\n  const e = embed(member.guild.id)\n    .setAuthor({ name: member.user.tag, iconURL: member.user.displayAvatarURL() })\n    .setDescription(cortar(preencher(mensagem, variaveis(member)), 4000))\n    .setThumbnail(member.user.displayAvatarURL({ size: 256 }))\n    .setTimestamp();\n  vis(e, 'entrada', imagens({ user: member.user, guild: member.guild }));\n  await canal.send({ content: `<@${member.id}>`, embeds: [e], allowedMentions: { users: [member.id] } });\n  return true;\n}\n\nasync function aoEntrar(member) {\n  if (foiRemovida(`membro:${member.guild.id}:${member.id}`)) return; // barrado pelo anti-raid\n  const c = cfg(member.guild.id);\n  if (c.entradaCanal) await enviarEntrada(member, c.entradaCanal, msgEntrada(c)).catch(() => {});\n  if (c.dmMensagem && !member.user.bot) {\n    await member.send({ embeds: [vis(embed(member.guild.id).setTitle(member.guild.name).setDescription(preencher(c.dmMensagem, variaveis(member))), 'dm', imagens({ user: member.user, guild: member.guild }))] }).catch(() => {});\n  }\n  const cargos = c.cargos.filter((id) => member.guild.roles.cache.get(id)?.editable);\n  if (cargos.length) await member.roles.add(cargos, 'Cargo automático').catch(() => {});\n}\n\nasync function aoSair(member) {\n  if (foiRemovida(`membro:${member.guild.id}:${member.id}`)) return; // expulso pelo anti-raid: sem \"saiu\"\n  const c = cfg(member.guild.id);\n  if (!c.saidaCanal) return;\n  const canal = member.guild.channels.cache.get(c.saidaCanal);\n  if (!canal?.isTextBased()) return;\n  const e = embed(member.guild.id)\n    .setDescription(cortar(preencher(msgSaida(c), variaveis(member)), 4000))\n    .setThumbnail(member.user?.displayAvatarURL?.() ?? null);\n  vis(e, 'saida', imagens({ user: member.user, guild: member.guild }));\n  await canal.send({ embeds: [e], allowedMentions: { parse: [] } }).catch(() => {});\n}\n\n// ---------------- /config boasvindas ----------------\nconst opMensagem = (o) =>\n  o.setName('mensagem').setDescription('Variáveis: {usuario} {nome} {tag} {servidor} {membros}').setMaxLength(1500);\n\nconst config = {\n  grupo: 'boasvindas',\n  montar: (g) =>\n    g\n      .setDescription('Boas-vindas, saída e cargos automáticos')\n      .addSubcommand((s) =>\n        s\n          .setName('entrada')\n          .setDescription('Canal e mensagem quando alguém entra')\n          .addChannelOption((o) => o.setName('canal').setDescription('Vazio desliga').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n          .addStringOption(opMensagem)\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('saida')\n          .setDescription('Canal e mensagem quando alguém sai')\n          .addChannelOption((o) => o.setName('canal').setDescription('Vazio desliga').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n          .addStringOption(opMensagem)\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('dm')\n          .setDescription('Mensagem enviada na DM de quem entra')\n          .addStringOption((o) => o.setName('mensagem').setDescription('Vazio desliga. Variáveis: {usuario} {nome} {servidor}').setMaxLength(1500))\n      )\n      .addSubcommand((s) =>\n        s.setName('cargo').setDescription('Cargo dado automaticamente a quem entra (usar de novo remove)').addRoleOption((o) => o.setName('cargo').setDescription('Cargo').setRequired(true))\n      )\n      .addSubcommand((s) => s.setName('testar').setDescription('Simula a sua entrada para ver como fica')),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    if (sub === 'entrada' || sub === 'saida') {\n      const canal = i.options.getChannel('canal');\n      const mensagem = i.options.getString('mensagem');\n      c[`${sub}Canal`] = canal?.id ?? null;\n      if (mensagem) c[`${sub}Mensagem`] = mensagem;\n      salvarAjustes();\n      const nome = sub === 'entrada' ? 'entrada' : 'saída';\n      return responder(i, canal ? tx('mensagem', { nome, canal }) : tx('mensagem_desligada', { nome }), 'sucesso');\n    }\n    if (sub === 'dm') {\n      c.dmMensagem = i.options.getString('mensagem') || null;\n      salvarAjustes();\n      return responder(i, c.dmMensagem ? tx('mensagem_dm_definida') : tx('mensagem_dm_desligada'), 'sucesso');\n    }\n    if (sub === 'cargo') {\n      const r = i.options.getRole('cargo');\n      if (r.managed || r.id === i.guildId) return responder(i, tx('esse_cargo_pode_ser'), 'erro');\n      const idx = c.cargos.indexOf(r.id);\n      if (idx >= 0) {\n        c.cargos.splice(idx, 1);\n        salvarAjustes();\n        return responder(i, tx('sera_mais_dado_automaticamente', { cargo: r }), 'sucesso');\n      }\n      if (c.cargos.length >= 5) return responder(i, tx('maximo_cargos_automaticos'), 'erro');\n      c.cargos.push(r.id);\n      salvarAjustes();\n      const aviso = r.editable ? '' : tx('meu_cargo_esta_abaixo');\n      return responder(i, tx('sera_dado_quem_entrar', { cargo: r, aviso }), 'sucesso');\n    }\n    if (sub === 'testar') {\n      if (!c.entradaCanal) return responder(i, tx('defina_antes_canal_config'), 'aviso');\n      const ok = await enviarEntrada(i.member, c.entradaCanal, msgEntrada(c)).catch(() => false);\n      return responder(i, ok ? tx('mensagem_teste_enviada', { canal: c.entradaCanal }) : tx('consegui_enviar_canal_configurado'), ok ? 'sucesso' : 'erro');\n    }\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    return [\n      tx('entrada', { entrada: c.entradaCanal ? `<#${c.entradaCanal}>` : tx('desligada') }),\n      tx('saida', { saida: c.saidaCanal ? `<#${c.saidaCanal}>` : tx('desligada') }),\n      tx('dm', { dm: c.dmMensagem ? tx('ligada') : tx('desligada') }),\n      tx('cargos_automaticos', { cargos: c.cargos.length ? c.cargos.map((r) => `<@&${r}>`).join(' ') : tx('nenhum') }),\n    ];\n  },\n};\n\nexport default {\n  id: 'boasvindas',\n  nome: tx('boas_vindas'),\n  intents: [GatewayIntentBits.GuildMembers],\n  partials: [Partials.GuildMember, Partials.User],\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  eventos: { guildMemberAdd: aoEntrar, guildMemberRemove: aoSair },\n  config,\n};\n",
  "src/modules/callstemp.js": "import { ChannelType, GatewayIntentBits, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, responder, preencher } from '../core/util.js';\nimport { textos, modeloOu } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('callstemp', {\n  nome_sala_padrao: 'Sala de {nome}',\n  aguarde_criar_outra_sala: 'Aguarde para criar outra sala',\n  sala_temporaria: 'Sala temporária',\n  entre_sua_sala_temporaria: ['Entre na sua sala temporária para usar este comando.', 'resposta'],\n  voce_ja_dono_desta: ['Você já é o dono desta sala.', 'resposta'],\n  dono_ainda_esta_sala: ['O dono (<@{dono}>) ainda está na sala.', 'resposta'],\n  agora_sala_sua_use: ['Agora a sala é sua. Use /sala para controlar.', 'resposta'],\n  so_dono_sala_pode: ['Só o dono da sala (<@{dono}>) pode fazer isso.', 'resposta'],\n  consegui_confira_minhas_permissoes: 'Não consegui. Confira as minhas permissões (Gerenciar canais e Gerenciar cargos).',\n  sala_renomeada: '✅ Sala renomeada para **{nome}**.',\n  consegui_renomear_agora_discord: '❌ Não consegui renomear agora (o Discord limita a 2 vezes a cada 10 minutos).',\n  limite_pessoa: 'Limite: **{limite}** pessoa(s).',\n  sala_sem_limite: 'Sala sem limite.',\n  sala_trancada: '🔒 Sala trancada.',\n  sala_liberada: '🔓 Sala liberada.',\n  escolha_outra_pessoa: ['Escolha outra pessoa.', 'resposta'],\n  pode_entrar_sala: '{usuario} pode entrar na sala.',\n  expulso_sala_temporaria: 'Expulso da sala temporária',\n  foi_tirado_sala_pode: '{usuario} foi tirado(a) da sala e não pode voltar.',\n  calls_temporarias_desligadas: ['Calls temporárias desligadas.', 'resposta'],\n  criar_sala: ['➕ Criar sala', 'campo'],\n  consegui_criar_call_preciso: ['Não consegui criar a call. Preciso da permissão **Gerenciar canais**.', 'resposta'],\n  pronto_quem_entrar_ganha: ['Pronto! Quem entrar em {canal} ganha uma sala própria (nome: \"{nome}\"). O dono controla com `/sala`.', 'resposta'],\n  calls_temporarias: 'Calls temporárias',\n  criar_sala_nome_sala: 'Criar sala: <#{criador}> · nome \"{nome}\" · {total} sala(s) aberta(s)',\n  desligado_salas_configurar: 'Desligado (`/salas configurar`)',\n});\n\n/**\n * Calls temporárias: quem entra na call \"➕ Criar sala\" ganha uma call só dele,\n * que é apagada quando fica vazia. O dono controla a sala com /sala.\n */\n\nconst salas = colecao('salas_temporarias'); // guild -> canalId -> { dono, criada }\nconst PADRAO = { criador: null, categoria: null, nome: null, limite: 0 };\nconst cfg = (guildId) => ajustes(guildId, 'callstemp', PADRAO);\nconst nomeSala = (c) => modeloOu(c.nome, 'Sala de {nome}', tx('nome_sala_padrao'));\nconst espera = new Map(); // anti-spam: userId -> quando criou a última\n\nconst salaDe = (guildId, canalId) => salas.ler(guildId, canalId);\n\nasync function criarSala(state) {\n  const c = cfg(state.guild.id);\n  const membro = state.member;\n  if (Date.now() - (espera.get(membro.id) ?? 0) < 10_000) {\n    await membro.voice.disconnect(tx('aguarde_criar_outra_sala')).catch(() => {});\n    return;\n  }\n  espera.set(membro.id, Date.now());\n  const parent = (c.categoria && state.guild.channels.cache.get(c.categoria)?.id) || state.channel.parentId || undefined;\n  const nome = preencher(nomeSala(c), { nome: membro.displayName, usuario: membro.user.username }).slice(0, 100);\n  let canal;\n  try {\n    // sem permissões próprias: a sala herda as da categoria (se a categoria é privada, a sala também é)\n    canal = await state.guild.channels.create({\n      name: nome,\n      type: ChannelType.GuildVoice,\n      parent,\n      userLimit: c.limite || undefined,\n      reason: `Sala temporária de ${membro.user.tag}`,\n    });\n  } catch (e) {\n    console.error('[calls temporárias] não consegui criar a sala:', e.message);\n    return;\n  }\n  // o dono sempre entra, mesmo se trancar a sala\n  await canal.permissionOverwrites.edit(membro.id, { ViewChannel: true, Connect: true, Speak: true }).catch(() => {});\n  salas.de(state.guild.id)[canal.id] = { dono: membro.id, criada: Date.now() };\n  salas.salvar();\n  const ok = await membro.voice.setChannel(canal, tx('sala_temporaria')).then(() => true, () => false);\n  if (!ok) await apagarSeVazia(state.guild, canal.id); // a pessoa saiu antes de ser movida\n}\n\nasync function apagarSeVazia(guild, canalId) {\n  if (!salaDe(guild.id, canalId)) return;\n  const canal = guild.channels.cache.get(canalId);\n  if (canal && canal.members.size > 0) return;\n  salas.apagar(guild.id, canalId);\n  if (canal) await canal.delete('Sala temporária vazia').catch(() => {});\n}\n\nasync function aoMudarVoz(antes, depois) {\n  const guild = depois.guild ?? antes.guild;\n  const c = cfg(guild.id);\n  if (depois.channelId && depois.channelId === c.criador && depois.member && !depois.member.user.bot) await criarSala(depois);\n  if (antes.channelId && antes.channelId !== depois.channelId) await apagarSeVazia(guild, antes.channelId);\n}\n\n// ---------------- /sala (para o dono) ----------------\nconst sala = {\n  data: new SlashCommandBuilder()\n    .setName('sala')\n    .setDescription('Controla a sua sala temporária (entre nela antes)')\n    .addSubcommand((s) => s.setName('nome').setDescription('Muda o nome da sala').addStringOption((o) => o.setName('nome').setDescription('Novo nome').setRequired(true).setMaxLength(90)))\n    .addSubcommand((s) => s.setName('limite').setDescription('Máximo de pessoas (0 = sem limite)').addIntegerOption((o) => o.setName('pessoas').setDescription('0 a 99').setRequired(true).setMinValue(0).setMaxValue(99)))\n    .addSubcommand((s) => s.setName('trancar').setDescription('Ninguém novo entra (só quem você permitir)'))\n    .addSubcommand((s) => s.setName('destrancar').setDescription('Libera a entrada de novo'))\n    .addSubcommand((s) => s.setName('permitir').setDescription('Deixa alguém entrar mesmo trancada').addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true)))\n    .addSubcommand((s) => s.setName('expulsar').setDescription('Tira alguém e impede de voltar').addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true)))\n    .addSubcommand((s) => s.setName('reivindicar').setDescription('Vira dono da sala se o dono saiu')),\n  async executar(i) {\n    const canal = i.member.voice?.channel;\n    const s = canal && salaDe(i.guildId, canal.id);\n    if (!s) return responder(i, tx('entre_sua_sala_temporaria'), 'erro');\n    const sub = i.options.getSubcommand();\n\n    if (sub === 'reivindicar') {\n      if (s.dono === i.user.id) return responder(i, tx('voce_ja_dono_desta'), 'aviso');\n      if (canal.members.has(s.dono)) return responder(i, tx('dono_ainda_esta_sala', { dono: s.dono }), 'erro');\n      s.dono = i.user.id;\n      salas.salvar();\n      await canal.permissionOverwrites.edit(i.user.id, { ViewChannel: true, Connect: true, Speak: true }).catch(() => {});\n      return responder(i, tx('agora_sala_sua_use'), 'sucesso');\n    }\n    if (s.dono !== i.user.id) return responder(i, tx('so_dono_sala_pode', { dono: s.dono }), 'erro');\n\n    const tentar = async (fn, ok) => {\n      const deu = await fn().then(() => true, () => false);\n      return responder(i, deu ? ok : tx('consegui_confira_minhas_permissoes'), deu ? 'sucesso' : 'erro');\n    };\n    if (sub === 'nome') {\n      const nome = i.options.getString('nome');\n      // o Discord só deixa renomear 2 vezes a cada 10 minutos: responde antes de esperar\n      await i.deferReply({ flags: 64 });\n      const ok = await canal.setName(nome).then(() => true, () => false);\n      return i.editReply(ok ? tx('sala_renomeada', { nome }) : tx('consegui_renomear_agora_discord'));\n    }\n    if (sub === 'limite') {\n      const n = i.options.getInteger('pessoas');\n      return tentar(() => canal.setUserLimit(n), n ? tx('limite_pessoa', { limite: n }) : tx('sala_sem_limite'));\n    }\n    if (sub === 'trancar') return tentar(() => canal.permissionOverwrites.edit(i.guild.roles.everyone, { Connect: false }), tx('sala_trancada'));\n    if (sub === 'destrancar') return tentar(() => canal.permissionOverwrites.edit(i.guild.roles.everyone, { Connect: null }), tx('sala_liberada'));\n    const u = i.options.getUser('usuario');\n    if (u.id === i.user.id) return responder(i, tx('escolha_outra_pessoa'), 'erro');\n    if (sub === 'permitir') return tentar(() => canal.permissionOverwrites.edit(u.id, { ViewChannel: true, Connect: true }), tx('pode_entrar_sala', { usuario: u }));\n    // expulsar\n    return tentar(async () => {\n      await canal.permissionOverwrites.edit(u.id, { Connect: false });\n      const m = canal.members.get(u.id);\n      if (m) await m.voice.disconnect(tx('expulso_sala_temporaria'));\n    }, tx('foi_tirado_sala_pode', { usuario: u }));\n  },\n};\n\n// ---------------- /salas (equipe) ----------------\nconst salasCmd = {\n  data: new SlashCommandBuilder()\n    .setName('salas')\n    .setDescription('Configura as calls temporárias')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('Escolhe a call \"Criar sala\" (ou cria uma)')\n        .addChannelOption((o) => o.setName('canal').setDescription('Call que cria as salas (vazio = eu crio uma)').addChannelTypes(ChannelType.GuildVoice))\n        .addChannelOption((o) => o.setName('categoria').setDescription('Onde as salas aparecem (padrão: a mesma da call)').addChannelTypes(ChannelType.GuildCategory))\n        .addStringOption((o) => o.setName('nome').setDescription('Nome das salas. Variáveis: {nome} {usuario}').setMaxLength(80))\n        .addIntegerOption((o) => o.setName('limite').setDescription('Limite padrão de pessoas (0 = sem limite)').setMinValue(0).setMaxValue(99))\n    )\n    .addSubcommand((s) => s.setName('desligar').setDescription('Para de criar salas (as abertas continuam até esvaziar)')),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    if (i.options.getSubcommand() === 'desligar') {\n      c.criador = null;\n      salvarAjustes();\n      return responder(i, tx('calls_temporarias_desligadas'), 'sucesso');\n    }\n    let canal = i.options.getChannel('canal');\n    const categoria = i.options.getChannel('categoria');\n    if (!canal) {\n      canal = await i.guild.channels\n        .create({ name: tx('criar_sala'), type: ChannelType.GuildVoice, parent: categoria?.id, reason: 'Calls temporárias' })\n        .catch(() => null);\n      if (!canal) return responder(i, tx('consegui_criar_call_preciso'), 'erro');\n    }\n    c.criador = canal.id;\n    if (categoria) c.categoria = categoria.id;\n    const nome = i.options.getString('nome');\n    if (nome) c.nome = nome;\n    const limite = i.options.getInteger('limite');\n    if (limite !== null) c.limite = limite;\n    salvarAjustes();\n    return responder(i, tx('pronto_quem_entrar_ganha', { canal, nome: nomeSala(c) }), 'sucesso');\n  },\n};\n\nexport default {\n  id: 'callstemp',\n  nome: tx('calls_temporarias'),\n  intents: [GatewayIntentBits.GuildVoiceStates],\n  permissoes: [PermissionFlagsBits.ManageChannels, PermissionFlagsBits.ManageRoles, PermissionFlagsBits.MoveMembers, PermissionFlagsBits.Connect],\n  comandos: [salasCmd, sala],\n  eventos: { voiceStateUpdate: aoMudarVoz },\n  async aoIniciar(client) {\n    // salas que ficaram vazias enquanto o bot estava desligado\n    for (const [guildId, lista] of Object.entries(salas.raiz)) {\n      const guild = client.guilds.cache.get(guildId);\n      if (!guild) continue;\n      for (const canalId of Object.keys(lista)) await apagarSeVazia(guild, canalId);\n    }\n  },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      const n = Object.keys(salas.ler(guild.id) ?? {}).length;\n      return [c.criador ? tx('criar_sala_nome_sala', { criador: c.criador, nome: nomeSala(c), total: n }) : tx('desligado_salas_configurar')];\n    },\n  },\n};\n",
  "src/modules/cargos.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { embed, responder, cortar, imagens } from '../core/util.js';\nimport { textos, visuais, botoes as registrarBotoes } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('cargos', {\n  clique_nos_botoes_pegar: 'Clique nos botões para pegar ou tirar cargos.',\n  consegui_enviar_mensagens_confira: ['Não consegui enviar mensagens em {canal}. Confira as minhas permissões.', 'resposta'],\n  painel_criado_agora_use: ['Painel criado em {canal}. Agora use **/cargos adicionar painel:{mensagem_id}** para colocar os cargos.', 'resposta'],\n  painel_encontrado_use_id: ['Painel não encontrado. Use o ID ou o link da mensagem do painel.', 'resposta'],\n  esse_cargo_pode_ser: ['Esse cargo não pode ser dado por botão.', 'resposta'],\n  consigo_dar_suba_meu: ['Não consigo dar {cargo}: suba o meu cargo acima dele na lista de cargos.', 'resposta'],\n  seguranca_cargos_permissoes_administ: ['Por segurança, cargos com permissões de administração não podem ir para painéis.', 'resposta'],\n  esse_cargo_ja_esta: ['Esse cargo já está no painel.', 'resposta'],\n  painel_aceita_maximo_25: ['Um painel aceita no máximo 25 cargos.', 'resposta'],\n  consegui_atualizar_painel_confira: ['Não consegui atualizar o painel. Confira se o emoji é válido.', 'resposta'],\n  adicionado_painel: ['{cargo} adicionado ao painel.', 'resposta'],\n  esse_cargo_esta_painel: ['Esse cargo não está no painel.', 'resposta'],\n  removido_painel: ['{cargo} removido do painel.', 'resposta'],\n  este_botao_esta_mais: ['Este botão não está mais ativo.', 'resposta'],\n  esse_cargo_existe_mais: ['Esse cargo não existe mais. Avise a equipe.', 'resposta'],\n  consigo_dar_esse_cargo: ['Não consigo dar esse cargo agora (o meu cargo está abaixo dele). Avise a equipe.', 'resposta'],\n  consegui_mudar_seu_cargo: ['Não consegui mudar o seu cargo agora. Avise a equipe.', 'resposta'],\n  cargo_removido: 'Cargo {cargo} removido.',\n  voce_recebeu: 'Você recebeu {cargo}!',\n  cargos_botao: 'Cargos por botão',\n});\n\n// Botões (texto, emoji e cor personalizáveis; alguns podem ser escondidos)\nconst bt = registrarBotoes('cargos', {\n  cargo: { nome: \"Botões do painel de cargos\", estilo: 'Secondary', rotuloInfo: \"O texto e o emoji de cada botão vêm do /cargos. Aqui você muda a cor de todos.\" },\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('cargos', {\n  painel: { nome: \"Painel de cargos\", vars: ['servidor_icone'] },\n});\n\n/**\n * Cargos por botão: painéis onde cada membro pega ou tira cargos sozinho\n * (cores, notificações, jogos, pronomes...). Até 25 cargos por painel.\n */\n\nconst paineis = colecao('paineis_cargos');\n\nfunction componentes(p) {\n  const rows = [];\n  p.cargos.forEach((c, n) => {\n    if (n % 5 === 0) rows.push(new ActionRowBuilder());\n    const b = bt('cargo', { rotulo: cortar(c.rotulo, 80), emoji: c.emoji || undefined }).setCustomId(`cr:${c.id}`);\n    if (c.emoji) b.setEmoji(c.emoji);\n    rows.at(-1).addComponents(b);\n  });\n  return rows;\n}\n\nconst idDaMensagem = (t) => String(t).split('/').pop().replace(/\\D/g, '');\n\nasync function buscarPainel(i, ref) {\n  const id = idDaMensagem(ref);\n  const p = paineis.ler(i.guildId, id);\n  if (!p) return [null, null];\n  const canal = await i.guild.channels.fetch(p.canal).catch(() => null);\n  const msg = await canal?.messages.fetch(id).catch(() => null);\n  return [p, msg];\n}\n\nconst cargos = {\n  data: new SlashCommandBuilder()\n    .setName('cargos')\n    .setDescription('Painéis de cargos por botão')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageRoles)\n    .addSubcommand((s) =>\n      s\n        .setName('painel')\n        .setDescription('Cria um painel novo (depois adicione cargos nele)')\n        .addStringOption((o) => o.setName('titulo').setDescription('Título').setRequired(true).setMaxLength(100))\n        .addStringOption((o) => o.setName('descricao').setDescription('Texto do painel').setMaxLength(1500))\n        .addChannelOption((o) => o.setName('canal').setDescription('Padrão: este canal').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('adicionar')\n        .setDescription('Coloca um cargo num painel')\n        .addStringOption((o) => o.setName('painel').setDescription('ID ou link da mensagem do painel').setRequired(true).setMaxLength(120))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Cargo').setRequired(true))\n        .addStringOption((o) => o.setName('rotulo').setDescription('Texto do botão (padrão: nome do cargo)').setMaxLength(80))\n        .addStringOption((o) => o.setName('emoji').setDescription('Emoji do botão').setMaxLength(60))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('remover')\n        .setDescription('Tira um cargo de um painel')\n        .addStringOption((o) => o.setName('painel').setDescription('ID ou link da mensagem do painel').setRequired(true).setMaxLength(120))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Cargo').setRequired(true))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    if (sub === 'painel') {\n      const canal = i.options.getChannel('canal') ?? i.channel;\n      const e = embed(i.guildId)\n        .setTitle(i.options.getString('titulo'))\n        .setDescription(i.options.getString('descricao') || tx('clique_nos_botoes_pegar'));\n      vis(e, 'painel', imagens({ guild: i.guild }));\n      const msg = await canal.send({ embeds: [e] }).catch(() => null);\n      if (!msg) return responder(i, tx('consegui_enviar_mensagens_confira', { canal }), 'erro');\n      paineis.de(i.guildId)[msg.id] = { canal: canal.id, cargos: [] };\n      paineis.salvar();\n      return responder(i, tx('painel_criado_agora_use', { canal, mensagem_id: msg.id }), 'sucesso');\n    }\n\n    const [p, msg] = await buscarPainel(i, i.options.getString('painel'));\n    if (!p || !msg) return responder(i, tx('painel_encontrado_use_id'), 'erro');\n    const r = i.options.getRole('cargo');\n\n    if (sub === 'adicionar') {\n      if (r.managed || r.id === i.guildId) return responder(i, tx('esse_cargo_pode_ser'), 'erro');\n      if (!r.editable) return responder(i, tx('consigo_dar_suba_meu', { cargo: r }), 'erro');\n      if (r.permissions.has(PermissionFlagsBits.Administrator) || r.permissions.has(PermissionFlagsBits.ManageGuild)) {\n        return responder(i, tx('seguranca_cargos_permissoes_administ'), 'erro');\n      }\n      if (p.cargos.some((c) => c.id === r.id)) return responder(i, tx('esse_cargo_ja_esta'), 'aviso');\n      if (p.cargos.length >= 25) return responder(i, tx('painel_aceita_maximo_25'), 'erro');\n      const emoji = i.options.getString('emoji')?.trim() || null;\n      p.cargos.push({ id: r.id, rotulo: i.options.getString('rotulo') || r.name, emoji });\n      try {\n        await msg.edit({ components: componentes(p) });\n      } catch {\n        p.cargos.pop();\n        return responder(i, tx('consegui_atualizar_painel_confira'), 'erro');\n      }\n      paineis.salvar();\n      return responder(i, tx('adicionado_painel', { cargo: r }), 'sucesso');\n    }\n    if (sub === 'remover') {\n      const antes = p.cargos.length;\n      p.cargos = p.cargos.filter((c) => c.id !== r.id);\n      if (p.cargos.length === antes) return responder(i, tx('esse_cargo_esta_painel'), 'aviso');\n      await msg.edit({ components: componentes(p) }).catch(() => {});\n      paineis.salvar();\n      return responder(i, tx('removido_painel', { cargo: r }), 'sucesso');\n    }\n  },\n};\n\nconst botoes = {\n  async cr(i, [cargoId]) {\n    // o cargo precisa estar mesmo neste painel\n    const p = paineis.ler(i.guildId, i.message?.id);\n    if (!p?.cargos.some((c) => c.id === cargoId)) return responder(i, tx('este_botao_esta_mais'), 'erro');\n    const r = i.guild.roles.cache.get(cargoId);\n    if (!r) return responder(i, tx('esse_cargo_existe_mais'), 'erro');\n    if (!r.editable) return responder(i, tx('consigo_dar_esse_cargo'), 'erro');\n    const tem = i.member.roles.cache.has(r.id);\n    const ok = await (tem ? i.member.roles.remove(r, 'Painel de cargos') : i.member.roles.add(r, 'Painel de cargos')).then(() => true, () => false);\n    if (!ok) return responder(i, tx('consegui_mudar_seu_cargo'), 'erro');\n    return responder(i, tem ? tx('cargo_removido', { cargo: r }) : tx('voce_recebeu', { cargo: r }), 'sucesso');\n  },\n};\n\nexport default {\n  id: 'cargos',\n  nome: tx('cargos_botao'),\n  comandos: [cargos],\n  componentes: botoes,\n  permissoes: [PermissionFlagsBits.ManageRoles],\n};\n",
  "src/modules/cargostemp.js": "import { ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, lerDuracao, duracaoTexto, ts, cortar } from '../core/util.js';\nimport { textos } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('cargostemp', {\n  tirei: 'Tirei',\n  consegui_tirar: 'Não consegui tirar',\n  fim_prazo: '⏳ {resultado} <@&{cargo}> de <@{usuario}> (fim do prazo).',\n  canal_registro_salvo: ['Canal de registro salvo.', 'resposta'],\n  nenhum_cargo_temporario_ativo: ['Nenhum cargo temporário ativo.', 'resposta'],\n  sai: '<@{usuario}> · <@&{cargo}> · sai {quando}',\n  cargos_temporarios: ['⏳ Cargos temporários', 'titulo'],\n  essa_pessoa_esta_servidor: ['Essa pessoa não está no servidor.', 'resposta'],\n  tirei_2: 'Tirei {cargo} de {usuario}.',\n  consegui_tirar_cargo_confira: 'Não consegui tirar o cargo (confira a minha posição na lista de cargos).',\n  duracao_invalida_use_algo: ['Duração inválida. Use algo como **7d**, **30d** ou **12h** (máximo 365d).', 'resposta'],\n  esse_cargo_pode_ser: ['Esse cargo não pode ser dado.', 'resposta'],\n  meu_cargo_precisa_ficar: ['Meu cargo precisa ficar acima de {cargo}.', 'resposta'],\n  voce_so_pode_dar: ['Você só pode dar cargos abaixo do seu.', 'resposta'],\n  consegui_dar_cargo: ['Não consegui dar o cargo.', 'resposta'],\n  deu_ate: '⏳ {autor} deu <@&{cargo_id}> para {usuario} até {quando}{motivo}',\n  prazo_renovado: ' (prazo renovado)',\n  recebeu_ate: ['{usuario} recebeu {cargo} até {quando} ({relativo}).{renovado}', 'resposta'],\n  cargos_temporarios_2: 'Cargos temporários',\n  registro: ' · registro em <#{registro}>',\n  cargo_temporario_ativo: '{total} cargo(s) temporário(s) ativo(s){registro}',\n});\n\n/**\n * Cargos temporários: /cargotemp dar @pessoa @VIP 30d. O cargo sai sozinho no fim do prazo\n * (mesmo se o bot reiniciar). Dar de novo o mesmo cargo renova o prazo.\n */\n\nconst temps = colecao('cargos_temporarios'); // guild -> { lista: [{ user, cargo, ate, por, motivo }] }\nconst cfg = (guildId) => ajustes(guildId, 'cargostemp', { registro: null });\nconst lista = (guildId) => (temps.de(guildId).lista ??= []);\nconst MAX = 365 * 86400e3;\n\nasync function registrar(guild, texto) {\n  const id = cfg(guild.id).registro;\n  const canal = id && guild.channels.cache.get(id);\n  if (canal?.isTextBased()) await canal.send({ embeds: [embed(guild.id).setDescription(texto).setTimestamp()], allowedMentions: { parse: [] } }).catch(() => {});\n}\n\nasync function verificar(client) {\n  const agora = Date.now();\n  for (const [guildId, g] of Object.entries(temps.raiz)) {\n    const guild = client.guilds.cache.get(guildId);\n    if (!guild || !g.lista?.length) continue;\n    const vencidos = g.lista.filter((x) => x.ate <= agora);\n    if (!vencidos.length) continue;\n    g.lista = g.lista.filter((x) => x.ate > agora);\n    temps.salvar();\n    for (const x of vencidos) {\n      const membro = await guild.members.fetch(x.user).catch(() => null);\n      if (membro?.roles.cache.has(x.cargo)) {\n        const ok = await membro.roles.remove(x.cargo, 'Fim do cargo temporário').then(() => true, () => false);\n        await registrar(guild, tx('fim_prazo', { resultado: ok ? tx('tirei') : tx('consegui_tirar'), cargo: x.cargo, usuario: x.user }));\n      }\n    }\n  }\n}\n\nconst cargotemp = {\n  data: new SlashCommandBuilder()\n    .setName('cargotemp')\n    .setDescription('Cargos que saem sozinhos depois de um tempo')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageRoles)\n    .addSubcommand((s) =>\n      s\n        .setName('dar')\n        .setDescription('Dá um cargo por um tempo')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Qual cargo').setRequired(true))\n        .addStringOption((o) => o.setName('duracao').setDescription('Ex.: 7d, 30d, 12h (máximo 365d)').setRequired(true))\n        .addStringOption((o) => o.setName('motivo').setDescription('Opcional').setMaxLength(200))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('tirar')\n        .setDescription('Tira o cargo agora')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Qual cargo').setRequired(true))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('lista')\n        .setDescription('Cargos temporários ativos')\n        .addUserOption((o) => o.setName('usuario').setDescription('Só de uma pessoa (opcional)'))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('registro')\n        .setDescription('Canal que registra quando o cargo sai')\n        .addChannelOption((o) => o.setName('canal').setDescription('Canal').setRequired(true).addChannelTypes(ChannelType.GuildText))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    const l = lista(i.guildId);\n    if (sub === 'registro') {\n      cfg(i.guildId).registro = i.options.getChannel('canal').id;\n      salvarAjustes();\n      return responder(i, tx('canal_registro_salvo'), 'sucesso');\n    }\n    if (sub === 'lista') {\n      const u = i.options.getUser('usuario');\n      const ativos = l.filter((x) => !u || x.user === u.id).sort((a, b) => a.ate - b.ate);\n      if (!ativos.length) return responder(i, tx('nenhum_cargo_temporario_ativo'), 'aviso');\n      const linhas = ativos.slice(0, 40).map((x) => tx('sai', { usuario: x.user, cargo: x.cargo, quando: ts(x.ate) }));\n      return i.reply({ embeds: [embed(i.guildId).setTitle(tx('cargos_temporarios')).setDescription(cortar(linhas.join('\\n'), 4000))], flags: 64, allowedMentions: { parse: [] } });\n    }\n    const u = i.options.getUser('usuario');\n    const cargo = i.options.getRole('cargo');\n    const membro = await i.guild.members.fetch(u.id).catch(() => null);\n    if (!membro) return responder(i, tx('essa_pessoa_esta_servidor'), 'erro');\n    if (sub === 'tirar') {\n      temps.de(i.guildId).lista = l.filter((x) => !(x.user === u.id && x.cargo === cargo.id));\n      temps.salvar();\n      const ok = await membro.roles.remove(cargo, `Cargo temporário tirado por ${i.user.tag}`).then(() => true, () => false);\n      return responder(i, ok ? tx('tirei_2', { cargo, usuario: u }) : tx('consegui_tirar_cargo_confira'), ok ? 'sucesso' : 'erro');\n    }\n    // dar\n    const ms = lerDuracao(i.options.getString('duracao'));\n    if (!ms || ms > MAX) return responder(i, tx('duracao_invalida_use_algo'), 'erro');\n    if (cargo.managed || cargo.id === i.guildId) return responder(i, tx('esse_cargo_pode_ser'), 'erro');\n    if (!cargo.editable) return responder(i, tx('meu_cargo_precisa_ficar', { cargo }), 'erro');\n    if (i.user.id !== i.guild.ownerId && cargo.position >= i.member.roles.highest.position) return responder(i, tx('voce_so_pode_dar'), 'erro');\n    const ok = await membro.roles.add(cargo, `Cargo temporário (${duracaoTexto(ms)}) por ${i.user.tag}`).then(() => true, () => false);\n    if (!ok) return responder(i, tx('consegui_dar_cargo'), 'erro');\n    const existente = l.find((x) => x.user === u.id && x.cargo === cargo.id);\n    const ate = Date.now() + ms;\n    const motivo = i.options.getString('motivo') ?? null;\n    if (existente) Object.assign(existente, { ate, por: i.user.id, motivo });\n    else l.push({ user: u.id, cargo: cargo.id, ate, por: i.user.id, motivo });\n    temps.salvar();\n    await registrar(i.guild, tx('deu_ate', { autor: i.user, cargo_id: cargo.id, usuario: u, quando: ts(ate, 'f'), motivo: motivo ? ` · ${cortar(motivo, 200)}` : '' }));\n    return responder(i, tx('recebeu_ate', { usuario: u, cargo, quando: ts(ate, 'f'), relativo: ts(ate), renovado: existente ? tx('prazo_renovado') : '' }), 'sucesso');\n  },\n};\n\nexport default {\n  id: 'cargostemp',\n  nome: tx('cargos_temporarios_2'),\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  comandos: [cargotemp],\n  aoIniciar(client) {\n    verificar(client).catch((e) => console.error('[cargos temporários]', e.message));\n    setInterval(() => verificar(client).catch((e) => console.error('[cargos temporários]', e.message)), 60_000);\n  },\n  config: {\n    resumo(guild) {\n      const n = temps.ler(guild.id, 'lista')?.length ?? 0;\n      return [tx('cargo_temporario_ativo', { total: n, registro: cfg(guild.id).registro ? tx('registro', { registro: cfg(guild.id).registro }) : '' })];\n    },\n  },\n};\n",
  "src/modules/contadores.js": "import { ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, fmt } from '../core/util.js';\nimport { textos } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('contadores', {\n  membros: 'Membros',\n  membros_2: '👥 Membros: {n}',\n  online_agora: 'Online agora',\n  online: '🟢 Online: {n}',\n  boosts: 'Boosts',\n  boosts_2: '🚀 Boosts: {n}',\n  canais: 'Canais',\n  canais_2: '💬 Canais: {n}',\n  cargos: 'Cargos',\n  cargos_2: '🎭 Cargos: {n}',\n  nenhum_contador_use_contadores: ['Nenhum contador. Use `/contadores criar`.', 'resposta'],\n  contadores: ['📈 Contadores', 'titulo'],\n  esse_canal_contador: ['Esse canal não é um contador.', 'resposta'],\n  contador_removido: ['Contador removido.', 'resposta'],\n  maximo_contadores: ['No máximo {limite} contadores.', 'resposta'],\n  consegui_criar_canal_preciso: '❌ Não consegui criar o canal. Preciso das permissões **Gerenciar canais** e **Conectar**.',\n  contador_criado_ele_atualiza: '✅ Contador criado: {canal}. Ele se atualiza a cada 10 minutos.',\n  contadores_2: 'Contadores',\n  nenhum_contadores_criar: 'Nenhum (`/contadores criar`)',\n});\n\n/**\n * Contadores: calls trancadas cujo nome mostra um número do servidor\n * (\"👥 Membros: 1.234\"). Atualizam sozinhos a cada 10 minutos\n * (o Discord só deixa renomear um canal 2 vezes a cada 10 minutos).\n */\n\nconst TIPOS = {\n  membros: { nome: tx('membros'), modelo: tx('membros_2') },\n  online: { nome: tx('online_agora'), modelo: tx('online') },\n  boosts: { nome: tx('boosts'), modelo: tx('boosts_2') },\n  canais: { nome: tx('canais'), modelo: tx('canais_2') },\n  cargos: { nome: tx('cargos'), modelo: tx('cargos_2') },\n};\nconst LIMITE = 5;\nconst cfg = (guildId) => ajustes(guildId, 'contadores', { lista: [] });\n\n/** Números do servidor. Membros e online vêm da API (não precisa de intent especial). */\nasync function numeros(guild) {\n  const g = await guild.client.guilds.fetch({ guild: guild.id, withCounts: true, force: true }).catch(() => guild);\n  return {\n    membros: g.approximateMemberCount ?? guild.memberCount ?? 0,\n    online: g.approximatePresenceCount ?? 0,\n    boosts: g.premiumSubscriptionCount ?? guild.premiumSubscriptionCount ?? 0,\n    canais: guild.channels.cache.filter((c) => c.type !== ChannelType.GuildCategory && !c.isThread()).size,\n    cargos: guild.roles.cache.size - 1,\n  };\n}\nconst nomeDo = (item, n) => item.modelo.replace('{n}', fmt(n[item.tipo])).slice(0, 100);\n\nasync function atualizar(guild) {\n  const c = cfg(guild.id);\n  if (!c.lista.length) return;\n  const n = await numeros(guild);\n  let mudou = false;\n  for (const item of [...c.lista]) {\n    const canal = guild.channels.cache.get(item.canal);\n    if (!canal) {\n      c.lista = c.lista.filter((x) => x.canal !== item.canal); // apagaram o canal\n      mudou = true;\n      continue;\n    }\n    const nome = nomeDo(item, n);\n    if (canal.name !== nome) await canal.setName(nome, 'Contador').catch(() => {});\n  }\n  if (mudou) salvarAjustes();\n}\n\nconst contadores = {\n  data: new SlashCommandBuilder()\n    .setName('contadores')\n    .setDescription('Canais que mostram números do servidor')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('criar')\n        .setDescription('Cria um contador')\n        .addStringOption((o) =>\n          o\n            .setName('tipo')\n            .setDescription('O que contar')\n            .setRequired(true)\n            .addChoices(...Object.entries(TIPOS).map(([value, t]) => ({ name: t.nome, value })))\n        )\n        .addStringOption((o) => o.setName('nome').setDescription('Nome do canal; {n} vira o número (ex.: \"👥 Galera: {n}\")').setMaxLength(80))\n        .addChannelOption((o) => o.setName('categoria').setDescription('Categoria onde criar').addChannelTypes(ChannelType.GuildCategory))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('remover')\n        .setDescription('Apaga um contador')\n        .addChannelOption((o) => o.setName('canal').setDescription('O canal do contador').setRequired(true).addChannelTypes(ChannelType.GuildVoice))\n    )\n    .addSubcommand((s) => s.setName('lista').setDescription('Mostra os contadores')),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const sub = i.options.getSubcommand();\n    if (sub === 'lista') {\n      if (!c.lista.length) return responder(i, tx('nenhum_contador_use_contadores'), 'aviso');\n      return i.reply({ embeds: [embed(i.guildId).setTitle(tx('contadores')).setDescription(c.lista.map((x) => `<#${x.canal}> · ${TIPOS[x.tipo].nome}`).join('\\n'))], flags: 64 });\n    }\n    if (sub === 'remover') {\n      const canal = i.options.getChannel('canal');\n      if (!c.lista.some((x) => x.canal === canal.id)) return responder(i, tx('esse_canal_contador'), 'erro');\n      c.lista = c.lista.filter((x) => x.canal !== canal.id);\n      salvarAjustes();\n      await canal.delete('Contador removido').catch(() => {});\n      return responder(i, tx('contador_removido'), 'sucesso');\n    }\n    // criar\n    if (c.lista.length >= LIMITE) return responder(i, tx('maximo_contadores', { limite: LIMITE }), 'erro');\n    const tipo = i.options.getString('tipo');\n    let modelo = i.options.getString('nome') || TIPOS[tipo].modelo;\n    if (!modelo.includes('{n}')) modelo += ': {n}';\n    await i.deferReply({ flags: 64 });\n    const n = await numeros(i.guild);\n    const canal = await i.guild.channels\n      .create({\n        name: nomeDo({ tipo, modelo }, n),\n        type: ChannelType.GuildVoice,\n        parent: i.options.getChannel('categoria')?.id,\n        position: 0,\n        permissionOverwrites: [\n          { id: i.guild.roles.everyone.id, deny: [PermissionFlagsBits.Connect] },\n          { id: i.guild.members.me.id, allow: [PermissionFlagsBits.ViewChannel, PermissionFlagsBits.Connect, PermissionFlagsBits.ManageChannels] },\n        ],\n        reason: 'Contador',\n      })\n      .catch((e) => {\n        console.error('[contadores]', e.message);\n        return null;\n      });\n    if (!canal) return i.editReply(tx('consegui_criar_canal_preciso'));\n    c.lista.push({ canal: canal.id, tipo, modelo });\n    salvarAjustes();\n    return i.editReply(tx('contador_criado_ele_atualiza', { canal }));\n  },\n};\n\nexport default {\n  id: 'contadores',\n  nome: tx('contadores_2'),\n  comandos: [contadores],\n  permissoes: [PermissionFlagsBits.ManageChannels, PermissionFlagsBits.Connect],\n  aoIniciar(client) {\n    const rodar = async () => {\n      for (const guild of client.guilds.cache.values()) await atualizar(guild).catch((e) => console.error('[contadores]', e.message));\n    };\n    rodar();\n    setInterval(rodar, 10 * 60_000);\n  },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      return [c.lista.length ? c.lista.map((x) => `<#${x.canal}> (${TIPOS[x.tipo].nome})`).join(' · ') : tx('nenhum_contadores_criar')];\n    },\n  },\n};\n",
  "src/modules/contagem.js": "import { ChannelType, GatewayIntentBits, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, fmt, foiRemovida } from '../core/util.js';\nimport { textos } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('contagem', {\n  proximo_era: 'O próximo era **{esperado}**.',\n  vale_contar_duas_vezes: 'Não vale contar duas vezes seguidas.',\n  errou_voces_chegaram_recomecando: ['💥 {autor} errou! {erro}\\nVocês chegaram a **{chegou}**. Recomeçando do **1**. (Recorde: {recorde})', 'descricao'],\n  novo_recorde_voces_passaram: ['🏆 **Novo recorde!** Vocês passaram de {recorde_anterior}.', 'descricao'],\n  jogo_contar_esta_ligado: ['O jogo de contar não está ligado.', 'resposta'],\n  estamos_proximo_recorde: ['🔢 Em <#{canal}>: estamos no **{atual}** (próximo: {proximo}).\\n🏆 Recorde: **{recorde}**{quando_recorde}', 'resposta'],\n  so_quem_tem_gerenciar: ['Só quem tem **Gerenciar servidor** pode fazer isso.', 'resposta'],\n  contagem_zerada_proximo_numero: ['Contagem zerada. O próximo número é 1.', 'resposta'],\n  jogo_contar: ['🔢 Jogo de contar', 'titulo'],\n  contem_partir_numero_mensagem: ['Contem a partir do **1**, um número por mensagem.\\nA mesma pessoa não pode contar duas vezes seguidas. Errou, volta para o 1!', 'descricao'],\n  jogo_contar_ligado: ['Jogo de contar ligado em {canal}.', 'resposta'],\n  jogo_contar_2: 'Jogo de contar',\n  atual_recorde: '<#{canal}> · atual {atual} · recorde {recorde}',\n  desligado_contagem_canal: 'Desligado (`/contagem canal`)',\n});\n\n/**\n * Jogo de contar: num canal, todo mundo conta 1, 2, 3...\n * A mesma pessoa não pode contar duas vezes seguidas. Errou, volta para o 1.\n * Guarda o recorde do servidor.\n */\n\nconst PADRAO = { canal: null, atual: 0, ultimo: null, recorde: 0, recordeEm: null, recordeDaRodada: 0 }; // recordeDaRodada: o recorde quando a rodada começou\nconst cfg = (guildId) => ajustes(guildId, 'contagem', PADRAO);\n\nasync function aoMensagem(msg) {\n  if (!msg.inGuild() || msg.author.bot) return;\n  const c = cfg(msg.guildId);\n  if (msg.channelId !== c.canal || foiRemovida(msg.id)) return;\n  const texto = msg.content.trim().replace(/\\./g, '');\n  if (!/^\\d{1,9}$/.test(texto)) return; // conversa normal: ignora\n  const n = Number(texto);\n  const esperado = c.atual + 1;\n\n  const erro = n !== esperado ? tx('proximo_era', { esperado: fmt(esperado) }) : msg.author.id === c.ultimo ? tx('vale_contar_duas_vezes') : null;\n  if (erro) {\n    const chegou = c.atual;\n    c.atual = 0;\n    c.ultimo = null;\n    c.recordeDaRodada = c.recorde;\n    salvarAjustes();\n    await msg.react('❌').catch(() => {});\n    await msg\n      .reply({\n        embeds: [embed(msg.guildId).setColor(0xef4444).setDescription(tx('errou_voces_chegaram_recomecando', { autor: msg.author, erro, chegou: fmt(chegou), recorde: fmt(c.recorde) }))],\n        allowedMentions: { users: [] },\n      })\n      .catch(() => {});\n    return;\n  }\n  c.atual = n;\n  c.ultimo = msg.author.id;\n  // 🏆 só no número que passa o recorde anterior (não em todos os números de uma rodada nova)\n  const bateuRecorde = c.recordeDaRodada > 0 && n === c.recordeDaRodada + 1;\n  if (n > c.recorde) {\n    c.recorde = n;\n    c.recordeEm = Date.now();\n  }\n  salvarAjustes();\n  await msg.react(bateuRecorde ? '🏆' : '✅').catch(() => {});\n  if (bateuRecorde) await msg.channel.send({ embeds: [embed(msg.guildId).setDescription(tx('novo_recorde_voces_passaram', { recorde_anterior: fmt(n - 1) }))] }).catch(() => {});\n}\n\nconst contagem = {\n  data: new SlashCommandBuilder()\n    .setName('contagem')\n    .setDescription('Jogo de contar')\n    .addSubcommand((s) => s.setName('status').setDescription('Número atual e recorde'))\n    .addSubcommand((s) =>\n      s\n        .setName('canal')\n        .setDescription('(Equipe) Escolhe o canal do jogo')\n        .addChannelOption((o) => o.setName('canal').setDescription('Canal da contagem').setRequired(true).addChannelTypes(ChannelType.GuildText))\n    )\n    .addSubcommand((s) => s.setName('zerar').setDescription('(Equipe) Volta a contagem para 0')),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const sub = i.options.getSubcommand();\n    if (sub === 'status') {\n      if (!c.canal) return responder(i, tx('jogo_contar_esta_ligado'), 'aviso');\n      return responder(\n        i,\n        tx('estamos_proximo_recorde', { canal: c.canal, atual: fmt(c.atual), proximo: fmt(c.atual + 1), recorde: fmt(c.recorde), quando_recorde: c.recordeEm ? ` (<t:${Math.floor(c.recordeEm / 1000)}:R>)` : '' }),\n        'info'\n      );\n    }\n    if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, tx('so_quem_tem_gerenciar'), 'erro');\n    if (sub === 'zerar') {\n      c.atual = 0;\n      c.ultimo = null;\n      c.recordeDaRodada = c.recorde;\n      salvarAjustes();\n      return responder(i, tx('contagem_zerada_proximo_numero'), 'sucesso');\n    }\n    const canal = i.options.getChannel('canal');\n    c.canal = canal.id;\n    c.atual = 0;\n    c.ultimo = null;\n    c.recordeDaRodada = c.recorde;\n    salvarAjustes();\n    await canal.send({ embeds: [embed(i.guildId).setTitle(tx('jogo_contar')).setDescription(tx('contem_partir_numero_mensagem'))] }).catch(() => {});\n    return responder(i, tx('jogo_contar_ligado', { canal }), 'sucesso');\n  },\n};\n\nexport default {\n  id: 'contagem',\n  nome: tx('jogo_contar_2'),\n  intents: [GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent],\n  comandos: [contagem],\n  eventos: { messageCreate: aoMensagem },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      return [c.canal ? tx('atual_recorde', { canal: c.canal, atual: fmt(c.atual), recorde: fmt(c.recorde) }) : tx('desligado_contagem_canal')];\n    },\n  },\n};\n",
  "src/modules/convites.js": "import { ChannelType, GatewayIntentBits, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, fmt, preencher } from '../core/util.js';\nimport { textos, modeloOu } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('convites', {\n  msg_entrada_padrao: '📥 {usuario} entrou · convidado(a) por {convidou} ({convites} convite(s))',\n  link_personalizado_servidor: 'link personalizado do servidor',\n  convite_desconhecido: 'convite desconhecido',\n  conta_nova: ' ⚠️ conta nova',\n  so_quem_tem_gerenciar: ['Só quem tem **Gerenciar servidor** pode configurar.', 'resposta'],\n  avisos: ': avisos em <#{canal}>',\n  consigo_ler_convites_me: '\\n⚠️ Não consigo ler os convites: me dê a permissão **Gerenciar servidor**.',\n  rastreio_convites_configurado: ['Rastreio de convites configurado{canal}.{aviso}', 'resposta'],\n  ninguem_convidou_ninguem_ainda: ['Ninguém convidou ninguém ainda (desde que o bot entrou).', 'resposta'],\n  entraram_sairam_falsos: '**{posicao}.** <@{usuario}> · **{validos}** ({total} entraram, {saiu} saíram, {falsos} falsos)',\n  ranking_convites: ['📨 Ranking de convites', 'titulo'],\n  sei_como_entrou_foi: ['Não sei como {usuario} entrou (foi antes do bot começar a rastrear).', 'resposta'],\n  link_personalizado_servidor_2: 'o link personalizado do servidor',\n  convite_consegui_identificar: 'um convite que não consegui identificar',\n  convite: ' (convite `{codigo}`)',\n  ja_saiu: ' · já saiu',\n  entrou: ['{usuario} entrou por {por}{codigo} · <t:{em}:R>{saiu}.', 'resposta'],\n  convite_valido: ['**{validos}** convite(s) válido(s)', 'descricao'],\n  entraram: ['Entraram', 'campo'],\n  sairam: ['Saíram', 'campo'],\n  contas_falsas: ['Contas falsas', 'campo'],\n  rastreio_convites: 'Rastreio de convites',\n  nenhum_canal: 'nenhum canal',\n  avisos_entrada_rastreada: 'Avisos: {canal} · {total} entrada(s) rastreada(s)',\n});\n\n/**\n * Rastreio de convites: descobre por qual convite cada pessoa entrou e quem convidou.\n * Conta entradas, saídas e contas falsas (muito novas), com ranking.\n * Precisa da \"Server Members Intent\" e da permissão Gerenciar servidor (para ler os convites).\n */\n\nconst dados = colecao('convites'); // guild -> { membros: {userId: {por, codigo, em, saiu}}, contas: {inviterId: {total, saiu, falsos}} }\nconst PADRAO = { canal: null, mensagem: null, diasFalso: 7 };\nconst cfg = (guildId) => ajustes(guildId, 'convites', PADRAO);\nconst msgEntrada = (c) => modeloOu(c.mensagem, '📥 {usuario} entrou · convidado(a) por {convidou} ({convites} convite(s))', tx('msg_entrada_padrao'));\nconst usos = new Map(); // guildId -> Map(codigo -> { usos, dono })\nconst mapa = (lista) => new Map(lista.map((inv) => [inv.code, { usos: inv.uses ?? 0, dono: inv.inviterId ?? inv.inviter?.id ?? null }]));\n\nasync function carregarConvites(guild) {\n  if (!guild.members.me?.permissions.has(PermissionFlagsBits.ManageGuild)) return false;\n  const lista = await guild.invites.fetch().catch(() => null);\n  if (!lista) return false;\n  usos.set(guild.id, mapa(lista));\n  return true;\n}\n\nconst conta = (guildId, id) => {\n  const c = dados.de(guildId, 'contas', id);\n  c.total ??= 0;\n  c.saiu ??= 0;\n  c.falsos ??= 0;\n  return c;\n};\nconst validos = (c) => Math.max(0, (c?.total ?? 0) - (c?.saiu ?? 0) - (c?.falsos ?? 0));\n\nasync function aoEntrar(member) {\n  if (member.user.bot) return;\n  const guild = member.guild;\n  const antes = usos.get(guild.id) ?? new Map();\n  const agora = await guild.invites.fetch().catch(() => null);\n  let codigo = null;\n  let por = null;\n  if (agora) {\n    for (const inv of agora.values()) {\n      if ((inv.uses ?? 0) > (antes.get(inv.code)?.usos ?? 0)) {\n        codigo = inv.code;\n        por = inv.inviterId ?? inv.inviter?.id ?? null;\n        break;\n      }\n    }\n    // convite de uso único some depois de usado: o que sumiu da lista foi o usado\n    if (!codigo) {\n      const sumiu = [...antes.keys()].find((k) => !agora.has(k));\n      if (sumiu) {\n        codigo = sumiu;\n        por = antes.get(sumiu).dono;\n      }\n    }\n    usos.set(guild.id, mapa(agora));\n  }\n  if (!codigo && guild.vanityURLCode) codigo = 'personalizado';\n\n  const membros = dados.de(guild.id, 'membros');\n  const anterior = membros[member.id];\n  if (anterior?.saiu && anterior.por) conta(guild.id, anterior.por).saiu = Math.max(0, conta(guild.id, anterior.por).saiu - 1); // voltou\n  const falso = Date.now() - member.user.createdTimestamp < cfg(guild.id).diasFalso * 86400e3;\n  membros[member.id] = { por, codigo, em: Date.now(), saiu: false, falso };\n  if (por && por !== member.id && !(anterior && anterior.por === por)) {\n    const c = conta(guild.id, por);\n    c.total += 1;\n    if (falso) c.falsos += 1;\n  }\n  dados.salvar();\n\n  const canalId = cfg(guild.id).canal;\n  const canal = canalId && guild.channels.cache.get(canalId);\n  if (canal?.isTextBased()) {\n    const convidou = por ? `<@${por}>` : codigo === 'personalizado' ? tx('link_personalizado_servidor') : tx('convite_desconhecido');\n    const texto = preencher(msgEntrada(cfg(guild.id)), { usuario: `${member}`, nome: member.displayName, convidou, convites: fmt(validos(dados.ler(guild.id, 'contas', por))), codigo: codigo ?? '?' });\n    await canal.send({ content: texto + (falso ? tx('conta_nova') : ''), allowedMentions: { parse: [] } }).catch(() => {});\n  }\n}\n\nasync function aoSair(member) {\n  const m = dados.ler(member.guild.id, 'membros', member.id);\n  if (!m || m.saiu) return;\n  m.saiu = true;\n  if (m.por) conta(member.guild.id, m.por).saiu += 1;\n  dados.salvar();\n}\n\nconst convites = {\n  data: new SlashCommandBuilder()\n    .setName('convites')\n    .setDescription('Quem convidou quem')\n    .addSubcommand((s) =>\n      s\n        .setName('ver')\n        .setDescription('Convites de alguém')\n        .addUserOption((o) => o.setName('usuario').setDescription('De quem (padrão: você)'))\n    )\n    .addSubcommand((s) => s.setName('ranking').setDescription('Quem mais convidou'))\n    .addSubcommand((s) =>\n      s\n        .setName('quem')\n        .setDescription('Quem convidou uma pessoa')\n        .addUserOption((o) => o.setName('usuario').setDescription('A pessoa').setRequired(true))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('(Equipe) Canal que avisa quem entrou e por qual convite')\n        .addChannelOption((o) => o.setName('canal').setDescription('Canal dos avisos').addChannelTypes(ChannelType.GuildText))\n        .addStringOption((o) => o.setName('mensagem').setDescription('Variáveis: {usuario} {nome} {convidou} {convites} {codigo}').setMaxLength(300))\n        .addIntegerOption((o) => o.setName('dias-falso').setDescription('Conta com menos dias que isso conta como falsa (padrão 7)').setMinValue(0).setMaxValue(90))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    if (sub === 'configurar') {\n      if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, tx('so_quem_tem_gerenciar'), 'erro');\n      const c = cfg(i.guildId);\n      const canal = i.options.getChannel('canal');\n      const msg = i.options.getString('mensagem');\n      const dias = i.options.getInteger('dias-falso');\n      if (canal) c.canal = canal.id;\n      if (msg) c.mensagem = msg;\n      if (dias !== null) c.diasFalso = dias;\n      salvarAjustes();\n      const ok = await carregarConvites(i.guild);\n      return responder(\n        i,\n        tx('rastreio_convites_configurado', { canal: c.canal ? tx('avisos', { canal: c.canal }) : '', aviso: ok ? '' : tx('consigo_ler_convites_me') }),\n        ok ? 'sucesso' : 'aviso'\n      );\n    }\n    if (sub === 'ranking') {\n      const contas = Object.entries(dados.ler(i.guildId, 'contas') ?? {})\n        .map(([id, c]) => ({ id, v: validos(c), c }))\n        .filter((x) => x.c.total > 0)\n        .sort((a, b) => b.v - a.v || b.c.total - a.c.total)\n        .slice(0, 15);\n      if (!contas.length) return responder(i, tx('ninguem_convidou_ninguem_ainda'), 'aviso');\n      const linhas = contas.map((x, k) => tx('entraram_sairam_falsos', { posicao: k + 1, usuario: x.id, validos: fmt(x.v), total: x.c.total, saiu: x.c.saiu, falsos: x.c.falsos }));\n      return i.reply({ embeds: [embed(i.guildId).setTitle(tx('ranking_convites')).setDescription(linhas.join('\\n'))], allowedMentions: { parse: [] } });\n    }\n    if (sub === 'quem') {\n      const u = i.options.getUser('usuario');\n      const m = dados.ler(i.guildId, 'membros', u.id);\n      if (!m) return responder(i, tx('sei_como_entrou_foi', { usuario: u }), 'aviso');\n      const por = m.por ? `<@${m.por}>` : m.codigo === 'personalizado' ? tx('link_personalizado_servidor_2') : tx('convite_consegui_identificar');\n      return responder(i, tx('entrou', { usuario: u, por, codigo: m.codigo && m.codigo !== 'personalizado' ? tx('convite', { codigo: m.codigo }) : '', em: Math.floor(m.em / 1000), saiu: m.saiu ? tx('ja_saiu') : '' }), 'info');\n    }\n    const u = i.options.getUser('usuario') ?? i.user;\n    const c = dados.ler(i.guildId, 'contas', u.id);\n    return i.reply({\n      embeds: [\n        embed(i.guildId)\n          .setAuthor({ name: u.username, iconURL: u.displayAvatarURL() })\n          .setDescription(tx('convite_valido', { validos: fmt(validos(c)) }))\n          .addFields(\n            { name: tx('entraram'), value: fmt(c?.total ?? 0), inline: true },\n            { name: tx('sairam'), value: fmt(c?.saiu ?? 0), inline: true },\n            { name: tx('contas_falsas'), value: fmt(c?.falsos ?? 0), inline: true }\n          ),\n      ],\n    });\n  },\n};\n\nexport default {\n  id: 'convites',\n  nome: tx('rastreio_convites'),\n  intents: [GatewayIntentBits.GuildMembers, GatewayIntentBits.GuildInvites],\n  permissoes: [PermissionFlagsBits.ManageGuild],\n  comandos: [convites],\n  eventos: {\n    guildMemberAdd: aoEntrar,\n    guildMemberRemove: aoSair,\n    inviteCreate: (inv) => inv.guild && usos.get(inv.guild.id)?.set(inv.code, { usos: inv.uses ?? 0, dono: inv.inviterId ?? inv.inviter?.id ?? null }),\n    // convite apagado: espera um pouco (se foi de uso único, a entrada da pessoa ainda precisa dele)\n    inviteDelete: (inv) => inv.guild && setTimeout(() => usos.get(inv.guild.id)?.delete(inv.code), 15_000),\n    guildCreate: (guild) => carregarConvites(guild),\n  },\n  async aoIniciar(client) {\n    for (const guild of client.guilds.cache.values()) await carregarConvites(guild);\n  },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      const n = Object.keys(dados.ler(guild.id, 'membros') ?? {}).length;\n      return [tx('avisos_entrada_rastreada', { canal: c.canal ? `<#${c.canal}>` : tx('nenhum_canal'), total: n })];\n    },\n  },\n};\n",
  "src/modules/destaques.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, GatewayIntentBits, Partials, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, cortar, imagens } from '../core/util.js';\nimport { textos, visuais, botoes, fileira, fileiras } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('destaques', {\n  anexos: ['Anexos', 'campo'],\n  ver_mensagem: ['Ver mensagem', 'botao'],\n  destaques_desligados: ['Destaques desligados.', 'resposta'],\n  destaques_ligados_mensagens_vao: ['Destaques ligados: mensagens com **{minimo}** {mostra} vão para {canal}.', 'resposta'],\n  destaques: 'Destaques',\n  reacao_oes: '<#{canal}> · {minimo} reação(ões)',\n  desligado_destaques_configurar: 'Desligado (`/destaques configurar`)',\n});\n\n// Botões (texto, emoji e cor personalizáveis; alguns podem ser escondidos)\nconst bt = botoes('destaques', {\n  ver: { nome: 'Ver mensagem original (link)', rotulo: 'ver_mensagem', emoji: '-', estilo: 'Link', ocultavel: true },\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('destaques', {\n  destaque: { nome: \"Mensagem em destaque\", vars: ['avatar', 'servidor_icone'] },\n});\n\n/**\n * Destaques (starboard): mensagem que juntar N reações ⭐ vai para o canal de destaques.\n * O contador do destaque acompanha as reações.\n */\n\nconst postados = colecao('destaques'); // guild -> msgOriginal -> idDoDestaque\nconst PADRAO = { canal: null, emoji: '⭐', minimo: 3 };\nconst cfg = (guildId) => ajustes(guildId, 'destaques', PADRAO);\n\nconst mesmoEmoji = (reacao, emoji) => reacao.emoji.id === emoji || reacao.emoji.name === emoji || reacao.emoji.toString() === emoji;\n\nasync function aoReagir(reacao) {\n  if (reacao.partial) reacao = await reacao.fetch().catch(() => null);\n  if (!reacao) return;\n  const msg = reacao.message.partial ? await reacao.message.fetch().catch(() => null) : reacao.message;\n  if (!msg?.guild) return;\n  const c = cfg(msg.guild.id);\n  if (!c.canal || msg.channelId === c.canal || msg.author?.bot || !mesmoEmoji(reacao, c.emoji)) return;\n  const canal = msg.guild.channels.cache.get(c.canal);\n  if (!canal?.isTextBased()) return;\n\n  // não vale reagir na própria mensagem\n  const usuarios = await reacao.users.fetch().catch(() => null);\n  const total = usuarios ? usuarios.filter((u) => u.id !== msg.author.id && !u.bot).size : reacao.count;\n  const jaPostado = postados.ler(msg.guild.id, msg.id);\n  const cabecalho = `${c.emoji} **${total}** · ${msg.channel}`;\n\n  if (jaPostado) {\n    const destaque = await canal.messages.fetch(jaPostado).catch(() => null);\n    if (destaque) await destaque.edit({ content: cabecalho }).catch(() => {});\n    return;\n  }\n  if (total < c.minimo) return;\n\n  const e = embed(msg.guild.id)\n    .setAuthor({ name: msg.member?.displayName ?? msg.author.username, iconURL: msg.author.displayAvatarURL() })\n    .setDescription(cortar(msg.content || '', 4000) || null)\n    .setTimestamp(msg.createdAt);\n  const imagem = msg.attachments.find((a) => a.contentType?.startsWith('image/')) ?? null;\n  if (imagem) e.setImage(imagem.url);\n  else if (msg.embeds[0]?.image?.url) e.setImage(msg.embeds[0].image.url);\n  const outros = msg.attachments.filter((a) => a !== imagem).map((a) => `[${a.name}](${a.url})`);\n  if (outros.length) e.addFields({ name: tx('anexos'), value: cortar(outros.join('\\n'), 1024) });\n  vis(e, 'destaque', imagens({ user: msg.author, guild: msg.guild }));\n\n  const enviado = await canal\n    .send({\n      content: cabecalho,\n      embeds: [e],\n      components: fileiras(fileira(bt('ver')?.setURL(msg.url))),\n      allowedMentions: { parse: [] },\n    })\n    .catch(() => null);\n  if (enviado) {\n    postados.de(msg.guild.id)[msg.id] = enviado.id;\n    postados.salvar();\n  }\n}\n\nconst destaques = {\n  data: new SlashCommandBuilder()\n    .setName('destaques')\n    .setDescription('Canal de destaques (mensagens com muitas ⭐)')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('Liga os destaques')\n        .addChannelOption((o) => o.setName('canal').setDescription('Canal dos destaques').setRequired(true).addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n        .addIntegerOption((o) => o.setName('minimo').setDescription('Quantas reações para ir ao destaque (padrão 3)').setMinValue(1).setMaxValue(100))\n        .addStringOption((o) => o.setName('emoji').setDescription('Emoji que conta (padrão ⭐)').setMaxLength(60))\n    )\n    .addSubcommand((s) => s.setName('desligar').setDescription('Desliga os destaques')),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    if (i.options.getSubcommand() === 'desligar') {\n      c.canal = null;\n      salvarAjustes();\n      return responder(i, tx('destaques_desligados'), 'sucesso');\n    }\n    const canal = i.options.getChannel('canal');\n    c.canal = canal.id;\n    const minimo = i.options.getInteger('minimo');\n    if (minimo) c.minimo = minimo;\n    const emoji = i.options.getString('emoji')?.trim();\n    if (emoji) {\n      const custom = /<a?:\\w+:(\\d+)>/.exec(emoji);\n      c.emoji = custom ? custom[1] : emoji;\n    }\n    salvarAjustes();\n    const mostra = /^\\d+$/.test(c.emoji) ? (i.guild.emojis.cache.get(c.emoji)?.toString() ?? c.emoji) : c.emoji;\n    return responder(i, tx('destaques_ligados_mensagens_vao', { minimo: c.minimo, mostra, canal }), 'sucesso');\n  },\n};\n\nexport default {\n  id: 'destaques',\n  nome: tx('destaques'),\n  intents: [GatewayIntentBits.GuildMessages, GatewayIntentBits.GuildMessageReactions, GatewayIntentBits.MessageContent],\n  partials: [Partials.Message, Partials.Reaction, Partials.User, Partials.Channel],\n  comandos: [destaques],\n  eventos: { messageReactionAdd: aoReagir, messageReactionRemove: aoReagir },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      return [c.canal ? tx('reacao_oes', { canal: c.canal, minimo: c.minimo }) : tx('desligado_destaques_configurar')];\n    },\n  },\n};\n",
  "src/modules/diversao.js": "import { SlashCommandBuilder } from 'discord.js';\nimport { embed, responder, sorteio, barra } from '../core/util.js';\nimport { textos } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('diversao', {\n  cara: 'Cara',\n  coroa: 'Coroa',\n  moeda_girou_girou_deu: ['🪙 A moeda girou, girou… e deu **{lado}**!', 'descricao'],\n  saiu: 'Saiu **{total}**!',\n  certeza: 'Com certeza!',\n  sem_duvida: 'Sem dúvida.',\n  pode_apostar: 'Pode apostar.',\n  sim: 'Sim.',\n  tudo_indica_sim: 'Tudo indica que sim.',\n  parece_sim: 'Parece que sim.',\n  pergunta_novo_mais_tarde: 'Pergunta de novo mais tarde.',\n  melhor_te_contar_agora: 'Melhor não te contar agora.',\n  consigo_prever_agora: 'Não consigo prever agora.',\n  concentra_pergunta_novo: 'Concentra e pergunta de novo.',\n  nem_pensar: 'Nem pensar.',\n  minha_resposta: 'Minha resposta é não.',\n  minhas_fontes_dizem: 'Minhas fontes dizem que não.',\n  acho_dificil: 'Acho difícil.',\n  muito_duvidoso: 'Muito duvidoso.',\n  bola: ['🎱 Bola 8', 'titulo'],\n  pergunta: ['Pergunta', 'campo'],\n  resposta: ['Resposta', 'campo'],\n  coloque_pelo_menos_opcoes: ['Coloque pelo menos 2 opções separadas por **|**.', 'resposta'],\n  entre_eu_escolho: ['🤔 Entre {opcoes}…\\nEu escolho: **{escolha}**!', 'descricao'],\n  casal_perfeito: 'Casal perfeito! 💞',\n  tem_muito_futuro: 'Tem muito futuro! 💖',\n  pode_dar_certo: 'Pode dar certo… 💗',\n  melhor_como_amigos: 'Melhor como amigos. 🤝',\n  nem_tenta: 'Nem tenta. 💔',\n  diversao: 'Diversão',\n});\n\n/** Diversão: cara ou coroa, dados, bola 8, escolher e ship. Nada depende de sites de fora. */\n\nconst caracoroa = {\n  data: new SlashCommandBuilder().setName('caracoroa').setDescription('Joga uma moeda'),\n  async executar(i) {\n    const lado = Math.random() < 0.5 ? tx('cara') : tx('coroa');\n    await i.reply({ embeds: [embed(i.guildId).setDescription(tx('moeda_girou_girou_deu', { lado }))] });\n  },\n};\n\nconst dado = {\n  data: new SlashCommandBuilder()\n    .setName('dado')\n    .setDescription('Rola dados')\n    .addIntegerOption((o) => o.setName('lados').setDescription('Lados de cada dado (padrão 6)').setMinValue(2).setMaxValue(1000))\n    .addIntegerOption((o) => o.setName('quantidade').setDescription('Quantos dados (padrão 1)').setMinValue(1).setMaxValue(20)),\n  async executar(i) {\n    const lados = i.options.getInteger('lados') ?? 6;\n    const qtd = i.options.getInteger('quantidade') ?? 1;\n    const r = Array.from({ length: qtd }, () => sorteio(1, lados));\n    const total = r.reduce((a, b) => a + b, 0);\n    await i.reply({\n      embeds: [embed(i.guildId).setTitle(`🎲 ${qtd}d${lados}`).setDescription(qtd > 1 ? `${r.map((n) => `\\`${n}\\``).join(' + ')} = **${total}**` : tx('saiu', { total }))],\n    });\n  },\n};\n\nconst RESPOSTAS = [\n  tx('certeza'), tx('sem_duvida'), tx('pode_apostar'), tx('sim'), tx('tudo_indica_sim'), tx('parece_sim'),\n  tx('pergunta_novo_mais_tarde'), tx('melhor_te_contar_agora'), tx('consigo_prever_agora'), tx('concentra_pergunta_novo'),\n  tx('nem_pensar'), tx('minha_resposta'), tx('minhas_fontes_dizem'), tx('acho_dificil'), tx('muito_duvidoso'),\n];\nconst bola8 = {\n  data: new SlashCommandBuilder()\n    .setName('8ball')\n    .setDescription('Faça uma pergunta de sim ou não para a bola 8')\n    .addStringOption((o) => o.setName('pergunta').setDescription('A pergunta').setRequired(true).setMaxLength(200)),\n  async executar(i) {\n    await i.reply({\n      embeds: [embed(i.guildId).setTitle(tx('bola')).addFields({ name: tx('pergunta'), value: i.options.getString('pergunta') }, { name: tx('resposta'), value: RESPOSTAS[sorteio(0, RESPOSTAS.length - 1)] })],\n    });\n  },\n};\n\nconst escolher = {\n  data: new SlashCommandBuilder()\n    .setName('escolher')\n    .setDescription('O bot escolhe por você')\n    .addStringOption((o) => o.setName('opcoes').setDescription('Opções separadas por | (ex.: pizza | hambúrguer | sushi)').setRequired(true).setMaxLength(500)),\n  async executar(i) {\n    const ops = i.options.getString('opcoes').split('|').map((s) => s.trim()).filter(Boolean);\n    if (ops.length < 2) return responder(i, tx('coloque_pelo_menos_opcoes'), 'erro');\n    await i.reply({ embeds: [embed(i.guildId).setDescription(tx('entre_eu_escolho', { opcoes: ops.map((o) => `**${o}**`).join(', '), escolha: ops[sorteio(0, ops.length - 1)] }))] });\n  },\n};\n\n// o resultado é sempre o mesmo para o mesmo par (não muda a cada vez)\nfunction porcentagem(a, b) {\n  const [x, y] = [a, b].sort();\n  let h = 0;\n  for (const ch of `${x}:${y}`) h = (h * 31 + ch.charCodeAt(0)) >>> 0;\n  return h % 101;\n}\nconst ship = {\n  data: new SlashCommandBuilder()\n    .setName('ship')\n    .setDescription('Calcula a compatibilidade entre duas pessoas')\n    .addUserOption((o) => o.setName('pessoa1').setDescription('Primeira pessoa').setRequired(true))\n    .addUserOption((o) => o.setName('pessoa2').setDescription('Segunda pessoa (padrão: você)')),\n  async executar(i) {\n    const a = i.options.getUser('pessoa1');\n    const b = i.options.getUser('pessoa2') ?? i.user;\n    const p = porcentagem(a.id, b.id);\n    const nome = a.username.slice(0, Math.ceil(a.username.length / 2)) + b.username.slice(Math.floor(b.username.length / 2));\n    const frase = p >= 90 ? tx('casal_perfeito') : p >= 70 ? tx('tem_muito_futuro') : p >= 45 ? tx('pode_dar_certo') : p >= 20 ? tx('melhor_como_amigos') : tx('nem_tenta');\n    await i.reply({\n      embeds: [embed(i.guildId).setTitle(`💘 ${a.username} + ${b.username}`).setDescription(`**${nome}**\\n${barra(p / 100, 14)} **${p}%**\\n${frase}`)],\n    });\n  },\n};\n\nexport default {\n  id: 'diversao',\n  nome: tx('diversao'),\n  comandos: [caracoroa, dado, bola8, escolher, ship],\n};\n",
  "src/modules/economia.js": "import { PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, fmt, ts, sorteio, lerDuracao, duracaoTexto, cortar } from '../core/util.js';\nimport { textos } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('economia', {\n  ajudou_organizar_evento_servidor: 'ajudou a organizar um evento do servidor',\n  consertou_computador_vizinho: 'consertou o computador de um vizinho',\n  entregou_pizzas_noite_toda: 'entregou pizzas a noite toda',\n  programou_site_loja: 'programou um site para uma loja',\n  deu_aulas_particulares: 'deu aulas particulares',\n  editou_videos_criador_conteudo: 'editou vídeos para um criador de conteúdo',\n  cuidou_jardim: 'cuidou de um jardim',\n  trabalhou_garcom_num_casamento: 'trabalhou de garçom num casamento',\n  vendeu_artesanato_feira: 'vendeu artesanato na feira',\n  fez_faxina_caprichada: 'fez uma faxina caprichada',\n  valor_ou_tudo: 'Valor (ou \"tudo\")',\n  carteira: ['Carteira', 'campo'],\n  banco: ['Banco', 'campo'],\n  total: ['Total', 'campo'],\n  voce_ja_pegou_hoje: ['Você já pegou hoje. Volte {quando}.', 'resposta'],\n  voce_recebeu_volte_pegar: ['🎁 Você recebeu {dinheiro}!\\nVolte {quando} para pegar de novo.', 'descricao'],\n  voce_esta_cansado_pode: ['Você está cansado(a). Pode trabalhar de novo {quando}.', 'resposta'],\n  voce_ganhou: ['💼 Você {oque} e ganhou {dinheiro}.', 'descricao'],\n  escolha_outra_pessoa_seja: ['Escolha outra pessoa (que não seja bot).', 'resposta'],\n  valor_invalido: ['Valor inválido.', 'resposta'],\n  voce_so_tem_carteira: ['Você só tem {dinheiro} na carteira.', 'resposta'],\n  enviou: ['💸 {usuario} enviou {dinheiro} para {alvo}.', 'descricao'],\n  carteira_2: 'na carteira',\n  banco_2: 'no banco',\n  voce_so_tem: ['Você só tem {dinheiro} {onde}.', 'resposta'],\n  depositou: '🏦 Depositou',\n  sacou: '👛 Sacou',\n  aposta_maxima: ['A aposta máxima é {dinheiro}.', 'resposta'],\n  deu: ['🪙 Deu {caiu}!', 'titulo'],\n  voce_ganhou_2: 'Você ganhou {dinheiro}!',\n  voce_perdeu: 'Você perdeu {dinheiro}.',\n  carteira_3: ['Carteira: {carteira} {moeda}', 'rodape'],\n  ninguem_tem_dinheiro_ainda: ['Ninguém tem dinheiro ainda. Use /diario!', 'resposta'],\n  mais_ricos: ['💰 Mais ricos de {servidor}', 'titulo'],\n  loja_esta_vazia_equipe: ['A loja está vazia. A equipe pode adicionar itens com /config economia loja-adicionar.', 'resposta'],\n  loja: ['🛒 Loja de {servidor}', 'titulo'],\n  comprar_comprar: ['Para comprar: /comprar', 'rodape'],\n  cargo: '{descricao}Cargo: <@&{cargo}>',\n  item_encontrado_veja_loja: ['Item não encontrado. Veja a /loja.', 'resposta'],\n  cargo_deste_item_existe: ['O cargo deste item não existe mais. Avise a equipe.', 'resposta'],\n  voce_ja_tem_esse: ['Você já tem esse cargo.', 'resposta'],\n  consigo_dar_esse_cargo: ['Não consigo dar esse cargo (o meu cargo está abaixo dele). Avise a equipe.', 'resposta'],\n  faltam_carteira: ['Faltam {dinheiro} na carteira.', 'resposta'],\n  consegui_te_dar_cargo: ['Não consegui te dar o cargo, então nada foi cobrado. Avise a equipe.', 'resposta'],\n  comprou_ganhou: ['🛍️ {usuario} comprou **{nome}** por {dinheiro} e ganhou {cargo}!', 'descricao'],\n  bots_tem_conta: ['Bots não têm conta.', 'resposta'],\n  carteira_banco: ['**{tag}**: carteira {dinheiro} · banco {banco}.', 'resposta'],\n  moeda: 'Moeda: {emoji} **{moeda}**.',\n  intervalo_invalido_ex_1h: ['Intervalo inválido (ex.: 1h, 30m).', 'resposta'],\n  sem_limite: 'sem limite',\n  diario_trabalhar_cada_aposta: '/diario: **{diario}** · /trabalhar: **{trabalhoMin}–{trabalhoMax}** a cada {duracao} · aposta máxima: {apostaMax}.',\n  esse_cargo_pode_ser: ['Esse cargo não pode ser vendido.', 'resposta'],\n  loja_aceita_maximo_25: ['A loja aceita no máximo 25 itens.', 'resposta'],\n  ja_existe_item_esse: ['Já existe um item com esse nome.', 'resposta'],\n  suba_meu_cargo_acima: ' ⚠️ Suba o meu cargo acima dele, senão não consigo entregar.',\n  esta_venda: '**{nome}** está à venda.{aviso}',\n  achei_item_esse_nome: ['Não achei um item com esse nome.', 'resposta'],\n  item_removido_loja: 'Item removido da loja.',\n  moeda_2: 'Moeda: {emoji} {moeda}',\n  diario_trabalhar_cada: '/diario: {diario} · /trabalhar: {trabalhoMin}–{trabalhoMax} (a cada {duracao})',\n  loja_item_ns: 'Loja: {loja_total} item(ns)',\n  economia: 'Economia',\n});\n\n/**\n * Economia: moeda do servidor com carteira e banco, recompensa diária, trabalho,\n * transferências, apostas, ranking e uma loja de cargos.\n */\n\nconst eco = colecao('economia');\nconst PADRAO = {\n  moeda: 'moedas',\n  emoji: '🪙',\n  diario: 500,\n  trabalhoMin: 100,\n  trabalhoMax: 300,\n  trabalhoIntervalo: 3_600_000,\n  apostaMax: 0, // 0 = sem limite\n  loja: [], // { id, nome, preco, cargo, descricao }\n};\nconst cfg = (guildId) => ajustes(guildId, 'economia', PADRAO);\nconst conta = (guildId, userId) => {\n  const d = eco.de(guildId, userId);\n  d.carteira ??= 0;\n  d.banco ??= 0;\n  return d;\n};\nconst dinheiro = (c, v) => `${c.emoji} **${fmt(v)}** ${c.moeda}`;\nconst DIA = 86_400_000;\n\nconst TRABALHOS = [\n  tx('ajudou_organizar_evento_servidor'),\n  tx('consertou_computador_vizinho'),\n  tx('entregou_pizzas_noite_toda'),\n  tx('programou_site_loja'),\n  tx('deu_aulas_particulares'),\n  tx('editou_videos_criador_conteudo'),\n  tx('cuidou_jardim'),\n  tx('trabalhou_garcom_num_casamento'),\n  tx('vendeu_artesanato_feira'),\n  tx('fez_faxina_caprichada'),\n];\n\n/** Lê \"500\", \"1.000\", \"tudo\" ou \"metade\". */\nfunction lerQuantia(texto, maximo) {\n  const t = String(texto).trim().toLowerCase();\n  if (['tudo', 'all', 'max'].includes(t)) return maximo;\n  if (t === 'metade') return Math.floor(maximo / 2);\n  const n = Number(t.replace(/\\./g, '').replace(',', '.'));\n  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : null;\n}\n\nconst opQuantia = (o, desc = tx('valor_ou_tudo')) => o.setName('quantia').setDescription(desc).setRequired(true).setMaxLength(15);\n\n// ---------------- comandos ----------------\nconst saldo = {\n  data: new SlashCommandBuilder()\n    .setName('saldo')\n    .setDescription('Mostra o seu dinheiro')\n    .addUserOption((o) => o.setName('usuario').setDescription('Ver de outra pessoa')),\n  async executar(i) {\n    const user = i.options.getUser('usuario') ?? i.user;\n    const c = cfg(i.guildId);\n    const d = conta(i.guildId, user.id);\n    await i.reply({\n      embeds: [\n        embed(i.guildId)\n          .setAuthor({ name: user.tag, iconURL: user.displayAvatarURL() })\n          .addFields(\n            { name: tx('carteira'), value: dinheiro(c, d.carteira), inline: true },\n            { name: tx('banco'), value: dinheiro(c, d.banco), inline: true },\n            { name: tx('total'), value: dinheiro(c, d.carteira + d.banco), inline: true },\n          ),\n      ],\n    });\n  },\n};\n\nconst diario = {\n  data: new SlashCommandBuilder().setName('diario').setDescription('Pega a sua recompensa diária'),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const d = conta(i.guildId, i.user.id);\n    const prox = (d.diario ?? 0) + DIA;\n    if (Date.now() < prox) return responder(i, tx('voce_ja_pegou_hoje', { quando: ts(prox) }), 'aviso');\n    d.diario = Date.now();\n    d.carteira += c.diario;\n    eco.salvar();\n    return i.reply({ embeds: [embed(i.guildId).setDescription(tx('voce_recebeu_volte_pegar', { dinheiro: dinheiro(c, c.diario), quando: ts(Date.now() + DIA) }))] });\n  },\n};\n\nconst trabalhar = {\n  data: new SlashCommandBuilder().setName('trabalhar').setDescription('Trabalha para ganhar dinheiro'),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const d = conta(i.guildId, i.user.id);\n    const prox = (d.trabalho ?? 0) + c.trabalhoIntervalo;\n    if (Date.now() < prox) return responder(i, tx('voce_esta_cansado_pode', { quando: ts(prox) }), 'aviso');\n    const ganho = sorteio(c.trabalhoMin, c.trabalhoMax);\n    d.trabalho = Date.now();\n    d.carteira += ganho;\n    eco.salvar();\n    const oque = TRABALHOS[sorteio(0, TRABALHOS.length - 1)];\n    return i.reply({ embeds: [embed(i.guildId).setDescription(tx('voce_ganhou', { oque, dinheiro: dinheiro(c, ganho) }))] });\n  },\n};\n\nconst pagar = {\n  data: new SlashCommandBuilder()\n    .setName('pagar')\n    .setDescription('Transfere dinheiro da sua carteira para alguém')\n    .addUserOption((o) => o.setName('usuario').setDescription('Para quem').setRequired(true))\n    .addStringOption((o) => opQuantia(o, 'Valor')),\n  async executar(i) {\n    const alvo = i.options.getUser('usuario');\n    if (alvo.bot || alvo.id === i.user.id) return responder(i, tx('escolha_outra_pessoa_seja'), 'erro');\n    const c = cfg(i.guildId);\n    const d = conta(i.guildId, i.user.id);\n    const q = lerQuantia(i.options.getString('quantia'), d.carteira);\n    if (q === null) return responder(i, tx('valor_invalido'), 'erro');\n    if (!q || q > d.carteira) return responder(i, tx('voce_so_tem_carteira', { dinheiro: dinheiro(c, d.carteira) }), 'erro');\n    d.carteira -= q;\n    conta(i.guildId, alvo.id).carteira += q;\n    eco.salvar();\n    return i.reply({ embeds: [embed(i.guildId).setDescription(tx('enviou', { usuario: i.user, dinheiro: dinheiro(c, q), alvo }))] });\n  },\n};\n\nfunction movimentar(de, para, titulo) {\n  return {\n    data: new SlashCommandBuilder()\n      .setName(titulo === 'depositar' ? 'depositar' : 'sacar')\n      .setDescription(titulo === 'depositar' ? 'Guarda dinheiro da carteira no banco' : 'Tira dinheiro do banco para a carteira')\n      .addStringOption((o) => opQuantia(o)),\n    async executar(i) {\n      const c = cfg(i.guildId);\n      const d = conta(i.guildId, i.user.id);\n      const q = lerQuantia(i.options.getString('quantia'), d[de]);\n      if (q === null) return responder(i, tx('valor_invalido'), 'erro');\n      if (!q || q > d[de]) return responder(i, tx('voce_so_tem', { dinheiro: dinheiro(c, d[de]), onde: de === 'carteira' ? tx('carteira_2') : tx('banco_2') }), 'erro');\n      d[de] -= q;\n      d[para] += q;\n      eco.salvar();\n      return responder(i, `${titulo === 'depositar' ? tx('depositou') : tx('sacou')} ${dinheiro(c, q)}.`, 'sucesso');\n    },\n  };\n}\n\nconst apostar = {\n  data: new SlashCommandBuilder()\n    .setName('apostar')\n    .setDescription('Aposta no cara ou coroa: dobra ou perde')\n    .addStringOption((o) => opQuantia(o, 'Quanto apostar (ou \"tudo\")'))\n    .addStringOption((o) =>\n      o.setName('lado').setDescription('Cara ou coroa').setRequired(true).addChoices({ name: 'Cara', value: 'cara' }, { name: 'Coroa', value: 'coroa' })\n    ),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const d = conta(i.guildId, i.user.id);\n    const q = lerQuantia(i.options.getString('quantia'), d.carteira);\n    if (q === null) return responder(i, tx('valor_invalido'), 'erro');\n    if (!q || q > d.carteira) return responder(i, tx('voce_so_tem_carteira', { dinheiro: dinheiro(c, d.carteira) }), 'erro');\n    if (c.apostaMax > 0 && q > c.apostaMax) return responder(i, tx('aposta_maxima', { dinheiro: dinheiro(c, c.apostaMax) }), 'erro');\n    const lado = i.options.getString('lado');\n    const caiu = Math.random() < 0.5 ? 'cara' : 'coroa';\n    const ganhou = caiu === lado;\n    d.carteira += ganhou ? q : -q;\n    eco.salvar();\n    return i.reply({\n      embeds: [\n        embed(i.guildId)\n          .setColor(ganhou ? 0x22c55e : 0xef4444)\n          .setTitle(tx('deu', { caiu }))\n          .setDescription(ganhou ? tx('voce_ganhou_2', { dinheiro: dinheiro(c, q) }) : tx('voce_perdeu', { dinheiro: dinheiro(c, q) }))\n          .setFooter({ text: tx('carteira_3', { carteira: fmt(d.carteira), moeda: c.moeda }) }),\n      ],\n    });\n  },\n};\n\nconst ricos = {\n  data: new SlashCommandBuilder().setName('ricos').setDescription('Ranking dos mais ricos do servidor'),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const lista = Object.entries(eco.ler(i.guildId) ?? {})\n      .map(([id, d]) => [id, (d.carteira ?? 0) + (d.banco ?? 0)])\n      .filter(([, t]) => t > 0)\n      .sort((a, b) => b[1] - a[1])\n      .slice(0, 10);\n    if (!lista.length) return responder(i, tx('ninguem_tem_dinheiro_ainda'), 'info');\n    const medalhas = ['🥇', '🥈', '🥉'];\n    await i.reply({\n      embeds: [embed(i.guildId).setTitle(tx('mais_ricos', { servidor: i.guild.name })).setDescription(lista.map(([id, t], n) => `${medalhas[n] ?? `**${n + 1}.**`} <@${id}> · ${dinheiro(c, t)}`).join('\\n'))],\n      allowedMentions: { parse: [] },\n    });\n  },\n};\n\nconst loja = {\n  data: new SlashCommandBuilder().setName('loja').setDescription('Mostra os cargos à venda'),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    if (!c.loja.length) return responder(i, tx('loja_esta_vazia_equipe'), 'info');\n    const e = embed(i.guildId).setTitle(tx('loja', { servidor: i.guild.name })).setFooter({ text: tx('comprar_comprar') });\n    for (const it of c.loja.slice(0, 25)) {\n      e.addFields({ name: `${it.nome} · ${c.emoji} ${fmt(it.preco)}`, value: tx('cargo', { descricao: it.descricao ? `${cortar(it.descricao, 200)}\\n` : '', cargo: it.cargo }) });\n    }\n    await i.reply({ embeds: [e], allowedMentions: { parse: [] } });\n  },\n};\n\nconst comprar = {\n  data: new SlashCommandBuilder()\n    .setName('comprar')\n    .setDescription('Compra um cargo da loja')\n    .addStringOption((o) => o.setName('item').setDescription('Item da loja').setRequired(true).setAutocomplete(true)),\n  async autocompletar(i) {\n    const c = cfg(i.guildId);\n    const busca = i.options.getFocused().toLowerCase();\n    await i.respond(\n      c.loja\n        .filter((it) => it.nome.toLowerCase().includes(busca))\n        .slice(0, 25)\n        .map((it) => ({ name: cortar(`${it.nome} · ${fmt(it.preco)} ${c.moeda}`, 100), value: it.id }))\n    );\n  },\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const v = i.options.getString('item');\n    const it = c.loja.find((x) => x.id === v || x.nome.toLowerCase() === v.toLowerCase());\n    if (!it) return responder(i, tx('item_encontrado_veja_loja'), 'erro');\n    const cargo = i.guild.roles.cache.get(it.cargo);\n    if (!cargo) return responder(i, tx('cargo_deste_item_existe'), 'erro');\n    if (i.member.roles.cache.has(cargo.id)) return responder(i, tx('voce_ja_tem_esse'), 'aviso');\n    if (!cargo.editable) return responder(i, tx('consigo_dar_esse_cargo'), 'erro');\n    const d = conta(i.guildId, i.user.id);\n    if (d.carteira < it.preco) return responder(i, tx('faltam_carteira', { dinheiro: dinheiro(c, it.preco - d.carteira) }), 'erro');\n    d.carteira -= it.preco;\n    const ok = await i.member.roles.add(cargo, 'Comprado na loja').then(() => true, () => false);\n    if (!ok) {\n      d.carteira += it.preco; // devolve\n      return responder(i, tx('consegui_te_dar_cargo'), 'erro');\n    }\n    eco.salvar();\n    return i.reply({ embeds: [embed(i.guildId).setDescription(tx('comprou_ganhou', { usuario: i.user, nome: it.nome, dinheiro: dinheiro(c, it.preco), cargo }))], allowedMentions: { users: [i.user.id] } });\n  },\n};\n\nconst ecoAdmin = {\n  data: new SlashCommandBuilder()\n    .setName('eco')\n    .setDescription('Gerencia o dinheiro dos membros')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('dar')\n        .setDescription('Dá dinheiro a um membro')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addIntegerOption((o) => o.setName('quantia').setDescription('Valor').setRequired(true).setMinValue(1).setMaxValue(1_000_000_000))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('tirar')\n        .setDescription('Tira dinheiro da carteira de um membro')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addIntegerOption((o) => o.setName('quantia').setDescription('Valor').setRequired(true).setMinValue(1).setMaxValue(1_000_000_000))\n    )\n    .addSubcommand((s) => s.setName('zerar').setDescription('Zera carteira e banco de um membro').addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const sub = i.options.getSubcommand();\n    const user = i.options.getUser('usuario');\n    if (user.bot) return responder(i, tx('bots_tem_conta'), 'erro');\n    const d = conta(i.guildId, user.id);\n    const q = i.options.getInteger('quantia') ?? 0;\n    if (sub === 'dar') d.carteira += q;\n    if (sub === 'tirar') d.carteira = Math.max(0, d.carteira - q);\n    if (sub === 'zerar') d.carteira = d.banco = 0;\n    eco.salvar();\n    return responder(i, tx('carteira_banco', { tag: user.tag, dinheiro: dinheiro(c, d.carteira), banco: dinheiro(c, d.banco) }), 'sucesso');\n  },\n};\n\n// ---------------- /config economia ----------------\nconst config = {\n  grupo: 'economia',\n  montar: (g) =>\n    g\n      .setDescription('Moeda, recompensas e loja de cargos')\n      .addSubcommand((s) =>\n        s\n          .setName('moeda')\n          .setDescription('Nome e emoji da moeda')\n          .addStringOption((o) => o.setName('nome').setDescription('Ex.: moedas, coins, reais').setRequired(true).setMaxLength(20))\n          .addStringOption((o) => o.setName('emoji').setDescription('Ex.: 🪙').setMaxLength(60))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('ganhos')\n          .setDescription('Valores do /diario e do /trabalhar')\n          .addIntegerOption((o) => o.setName('diario').setDescription('Valor do /diario').setMinValue(0).setMaxValue(1_000_000))\n          .addIntegerOption((o) => o.setName('trabalho_min').setDescription('Mínimo do /trabalhar').setMinValue(0).setMaxValue(1_000_000))\n          .addIntegerOption((o) => o.setName('trabalho_max').setDescription('Máximo do /trabalhar').setMinValue(0).setMaxValue(1_000_000))\n          .addStringOption((o) => o.setName('intervalo').setDescription('Tempo entre /trabalhar, ex.: 1h, 30m').setMaxLength(20))\n          .addIntegerOption((o) => o.setName('aposta_max').setDescription('Aposta máxima (0 = sem limite)').setMinValue(0).setMaxValue(1_000_000_000))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('loja-adicionar')\n          .setDescription('Coloca um cargo à venda')\n          .addStringOption((o) => o.setName('nome').setDescription('Nome do item').setRequired(true).setMaxLength(60))\n          .addIntegerOption((o) => o.setName('preco').setDescription('Preço').setRequired(true).setMinValue(1).setMaxValue(1_000_000_000))\n          .addRoleOption((o) => o.setName('cargo').setDescription('Cargo que a pessoa ganha').setRequired(true))\n          .addStringOption((o) => o.setName('descricao').setDescription('Descrição').setMaxLength(200))\n      )\n      .addSubcommand((s) =>\n        s.setName('loja-remover').setDescription('Tira um item da loja').addStringOption((o) => o.setName('nome').setDescription('Nome do item').setRequired(true).setMaxLength(60))\n      ),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    let msg;\n    if (sub === 'moeda') {\n      c.moeda = i.options.getString('nome');\n      c.emoji = i.options.getString('emoji') || c.emoji;\n      msg = tx('moeda', { emoji: c.emoji, moeda: c.moeda });\n    } else if (sub === 'ganhos') {\n      const v = (n) => i.options.getInteger(n);\n      if (v('diario') !== null) c.diario = v('diario');\n      if (v('trabalho_min') !== null) c.trabalhoMin = v('trabalho_min');\n      if (v('trabalho_max') !== null) c.trabalhoMax = v('trabalho_max');\n      if (c.trabalhoMin > c.trabalhoMax) [c.trabalhoMin, c.trabalhoMax] = [c.trabalhoMax, c.trabalhoMin];\n      const iv = i.options.getString('intervalo');\n      if (iv) {\n        const ms = lerDuracao(iv);\n        if (!ms) return responder(i, tx('intervalo_invalido_ex_1h'), 'erro');\n        c.trabalhoIntervalo = ms;\n      }\n      if (v('aposta_max') !== null) c.apostaMax = v('aposta_max');\n      msg = tx('diario_trabalhar_cada_aposta', { diario: fmt(c.diario), trabalhoMin: fmt(c.trabalhoMin), trabalhoMax: fmt(c.trabalhoMax), duracao: duracaoTexto(c.trabalhoIntervalo), apostaMax: c.apostaMax ? fmt(c.apostaMax) : tx('sem_limite') });\n    } else if (sub === 'loja-adicionar') {\n      const r = i.options.getRole('cargo');\n      if (r.managed || r.id === i.guildId) return responder(i, tx('esse_cargo_pode_ser'), 'erro');\n      if (c.loja.length >= 25) return responder(i, tx('loja_aceita_maximo_25'), 'erro');\n      const nome = i.options.getString('nome');\n      if (c.loja.some((x) => x.nome.toLowerCase() === nome.toLowerCase())) return responder(i, tx('ja_existe_item_esse'), 'erro');\n      c.loja.push({ id: Date.now().toString(36), nome, preco: i.options.getInteger('preco'), cargo: r.id, descricao: i.options.getString('descricao') || '' });\n      msg = tx('esta_venda', { nome, aviso: r.editable ? '' : tx('suba_meu_cargo_acima') });\n    } else if (sub === 'loja-remover') {\n      const nome = i.options.getString('nome').toLowerCase();\n      const antes = c.loja.length;\n      c.loja = c.loja.filter((x) => x.nome.toLowerCase() !== nome);\n      if (c.loja.length === antes) return responder(i, tx('achei_item_esse_nome'), 'erro');\n      msg = tx('item_removido_loja');\n    }\n    salvarAjustes();\n    return responder(i, msg, 'sucesso');\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    return [\n      tx('moeda_2', { emoji: c.emoji, moeda: c.moeda }),\n      tx('diario_trabalhar_cada', { diario: fmt(c.diario), trabalhoMin: fmt(c.trabalhoMin), trabalhoMax: fmt(c.trabalhoMax), duracao: duracaoTexto(c.trabalhoIntervalo) }),\n      tx('loja_item_ns', { loja_total: c.loja.length }),\n    ];\n  },\n};\n\nexport default {\n  id: 'economia',\n  nome: tx('economia'),\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  comandos: [saldo, diario, trabalhar, pagar, movimentar('carteira', 'banco', 'depositar'), movimentar('banco', 'carteira', 'sacar'), apostar, ricos, loja, comprar, ecoAdmin],\n  config,\n};\n",
  "src/modules/embeds.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, EmbedBuilder, ModalBuilder, PermissionFlagsBits, SlashCommandBuilder, TextInputBuilder, TextInputStyle } from 'discord.js';\nimport { cor, responder } from '../core/util.js';\nimport { textos, modais } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('embeds', {\n  criador_embed: ['Criador de embed', 'rotulo'],\n  titulo: 'Título',\n  texto_aceita_negrito_listas: 'Texto (aceita **negrito**, listas, links...)',\n  cor_ex_5865f2: 'Cor (ex.: #5865F2)',\n  link_imagem_grande_opcional: 'Link da imagem grande (opcional)',\n  rodape_opcional: 'Rodapé (opcional)',\n  formulario_expirou_use_comando: ['O formulário expirou. Use o comando de novo.', 'resposta'],\n  ignorei: '\\n⚠️ Ignorei: {erros}.',\n  embed_enviado: 'Embed enviado em {canal}.{aviso}',\n  consegui_enviar_confira_minhas: 'Não consegui enviar. Confira as minhas permissões no canal.',\n  achei_mais_mensagem: ['Não achei mais a mensagem.', 'resposta'],\n  embed_atualizado: 'Embed atualizado.{aviso}',\n  consegui_editar: 'Não consegui editar.',\n  botao_precisa_ser_assim: ['O botão {numero} precisa ser assim: **Texto | https://link**', 'resposta'],\n  cole_link_mensagem_botao: ['Cole o **link** da mensagem (botão direito na mensagem → Copiar link da mensagem).', 'resposta'],\n  achei_essa_mensagem_neste: ['Não achei essa mensagem neste servidor.', 'resposta'],\n  so_editar_embeds_enviados: ['Só dá para editar embeds enviados por mim.', 'resposta'],\n  criador_embeds: 'Criador de embeds',\n  cor_invalida_use_rrggbb: 'cor inválida (use #RRGGBB)',\n  link_imagem_precisa_comecar: 'o link da imagem precisa começar com https://',\n});\n\nmodais('embeds', { criador: { nome: 'Criador de embed (/embed)', textos: ['criador_embed', 'titulo', 'texto_aceita_negrito_listas', 'cor_ex_5865f2', 'link_imagem_grande_opcional', 'rodape_opcional'] } });\n\n/**\n * Criador de embeds: mensagens bonitas (título, texto, cor, imagem, rodapé e botões de link)\n * sem saber programar. /embed criar abre um formulário; /embed editar muda uma já enviada.\n */\n\n// o formulário não tem lugar para o canal e os botões: guardamos aqui entre o comando e o envio\nconst rascunhos = new Map(); // userId -> { canal, botoes, mensagem?, expira }\nconst URL_OK = /^https?:\\/\\/\\S+$/i;\n\nfunction formulario(id, atual = {}) {\n  const campo = (customId, label, estilo, max, valor, obrigatorio = false) => {\n    const t = new TextInputBuilder().setCustomId(customId).setLabel(label).setStyle(estilo).setMaxLength(max).setRequired(obrigatorio);\n    if (valor) t.setValue(String(valor).slice(0, max));\n    return new ActionRowBuilder().addComponents(t);\n  };\n  return new ModalBuilder()\n    .setCustomId(id)\n    .setTitle(tx('criador_embed'))\n    .addComponents(\n      campo('titulo', tx('titulo'), TextInputStyle.Short, 256, atual.title),\n      campo('texto', tx('texto_aceita_negrito_listas'), TextInputStyle.Paragraph, 4000, atual.description, true),\n      campo('cor', tx('cor_ex_5865f2'), TextInputStyle.Short, 7, atual.color != null ? `#${atual.color.toString(16).padStart(6, '0')}` : ''),\n      campo('imagem', tx('link_imagem_grande_opcional'), TextInputStyle.Short, 500, atual.image?.url),\n      campo('rodape', tx('rodape_opcional'), TextInputStyle.Short, 2048, atual.footer?.text)\n    );\n}\n\nfunction montar(i, guildId) {\n  const f = (k) => i.fields.getTextInputValue(k).trim();\n  const erros = [];\n  const e = new EmbedBuilder().setDescription(f('texto'));\n  if (f('titulo')) e.setTitle(f('titulo'));\n  const c = f('cor');\n  if (c) {\n    const m = /^#?([0-9a-f]{6})$/i.exec(c);\n    if (m) e.setColor(parseInt(m[1], 16));\n    else erros.push(tx('cor_invalida_use_rrggbb'));\n  }\n  if (!c || erros.length) e.setColor(cor(guildId));\n  const img = f('imagem');\n  if (img) {\n    if (URL_OK.test(img)) e.setImage(img);\n    else erros.push(tx('link_imagem_precisa_comecar'));\n  }\n  if (f('rodape')) e.setFooter({ text: f('rodape') });\n  return { e, erros };\n}\n\nconst linhaBotoes = (botoes) =>\n  botoes.length ? [new ActionRowBuilder().addComponents(botoes.map((b) => new ButtonBuilder().setStyle(ButtonStyle.Link).setLabel(b.texto).setURL(b.link)))] : [];\n\nconst componentes = {\n  async eb(i, [acao]) {\n    if (!i.isModalSubmit()) return;\n    const r = rascunhos.get(i.user.id);\n    rascunhos.delete(i.user.id);\n    if (!r || r.expira < Date.now()) return responder(i, tx('formulario_expirou_use_comando'), 'erro');\n    const { e, erros } = montar(i, i.guildId);\n    const aviso = erros.length ? tx('ignorei', { erros: erros.join('; ') }) : '';\n    if (acao === 'criar') {\n      const canal = i.guild.channels.cache.get(r.canal);\n      const ok = canal ? await canal.send({ embeds: [e], components: linhaBotoes(r.botoes) }).then(() => true, () => false) : false;\n      return responder(i, ok ? tx('embed_enviado', { canal, aviso }) : tx('consegui_enviar_confira_minhas'), ok ? 'sucesso' : 'erro');\n    }\n    if (acao === 'editar') {\n      const canal = i.guild.channels.cache.get(r.canal);\n      const msg = await canal?.messages.fetch(r.mensagem).catch(() => null);\n      if (!msg) return responder(i, tx('achei_mais_mensagem'), 'erro');\n      const ok = await msg.edit({ embeds: [e] }).then(() => true, () => false);\n      return responder(i, ok ? tx('embed_atualizado', { aviso }) : tx('consegui_editar'), ok ? 'sucesso' : 'erro');\n    }\n  },\n};\n\nconst embedCmd = {\n  data: new SlashCommandBuilder()\n    .setName('embed')\n    .setDescription('Cria mensagens bonitas (embeds)')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageMessages)\n    .addSubcommand((s) => {\n      s.setName('criar')\n        .setDescription('Abre o formulário para criar um embed')\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde enviar (padrão: aqui)').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement));\n      for (const n of [1, 2, 3]) {\n        s.addStringOption((o) => o.setName(`botao${n}`).setDescription(`Botão de link ${n}: \"Texto | https://link\" (opcional)`).setMaxLength(300));\n      }\n      return s;\n    })\n    .addSubcommand((s) =>\n      s\n        .setName('editar')\n        .setDescription('Edita um embed que eu enviei')\n        .addStringOption((o) => o.setName('mensagem').setDescription('Link da mensagem (botão direito → Copiar link)').setRequired(true))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    if (sub === 'criar') {\n      const canal = i.options.getChannel('canal') ?? i.channel;\n      const botoes = [];\n      for (const n of [1, 2, 3]) {\n        const v = i.options.getString(`botao${n}`);\n        if (!v) continue;\n        const [texto, link] = v.split('|').map((x) => x.trim());\n        if (!texto || !URL_OK.test(link ?? '')) return responder(i, tx('botao_precisa_ser_assim', { numero: n }), 'erro');\n        botoes.push({ texto: texto.slice(0, 80), link });\n      }\n      rascunhos.set(i.user.id, { canal: canal.id, botoes, expira: Date.now() + 15 * 60_000 });\n      return i.showModal(formulario('eb:criar'));\n    }\n    // editar\n    const m = /(\\d{17,20})\\/(\\d{17,20})\\/?$/.exec(i.options.getString('mensagem').trim());\n    if (!m) return responder(i, tx('cole_link_mensagem_botao'), 'erro');\n    const canal = i.guild.channels.cache.get(m[1]);\n    const msg = await canal?.messages.fetch(m[2]).catch(() => null);\n    if (!msg) return responder(i, tx('achei_essa_mensagem_neste'), 'erro');\n    if (msg.author.id !== i.client.user.id || !msg.embeds.length) return responder(i, tx('so_editar_embeds_enviados'), 'erro');\n    rascunhos.set(i.user.id, { canal: canal.id, mensagem: msg.id, botoes: [], expira: Date.now() + 15 * 60_000 });\n    return i.showModal(formulario('eb:editar', msg.embeds[0].toJSON?.() ?? msg.embeds[0].data ?? msg.embeds[0]));\n  },\n};\n\nexport default {\n  id: 'embeds',\n  nome: tx('criador_embeds'),\n  comandos: [embedCmd],\n  componentes,\n};\n",
  "src/modules/enquetes.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { embed, responder, lerDuracao, barra, ts, cortar, ehStaff } from '../core/util.js';\nimport { textos, visuais, botoes } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('enquetes', {\n  ninguem_votou: 'Ninguém votou.',\n  empate_entre: 'Empate entre {lideres}',\n  vencedora: 'Vencedora: {lideres}',\n  coloque_pelo_menos_opcoes: ['Coloque pelo menos 2 opções separadas por **|**.', 'resposta'],\n  duracao_invalida_ex_30m: ['Duração inválida (ex.: 30m, 1h, 2d; máximo 30d).', 'resposta'],\n  enquete_encontrada: ['Enquete não encontrada.', 'resposta'],\n  so_quem_criou_ou: ['Só quem criou ou a equipe pode encerrar.', 'resposta'],\n  enquete_encerrada: ['Enquete encerrada.', 'resposta'],\n  esta_enquete_ja_foi: ['Esta enquete já foi encerrada.', 'resposta'],\n  enquetes: 'Enquetes',\n  pode_votar_mais: ' · pode votar em mais de uma',\n  voto: ['{total} voto(s){multipla}', 'rodape'],\n  encerrada: ['Encerrada', 'campo'],\n  termina: ['Termina', 'campo'],\n});\n\n// Botões (texto, emoji e cor personalizáveis; alguns podem ser escondidos)\nconst bt = botoes('enquetes', {\n  votar: { nome: 'Botões das opções', estilo: 'Secondary', rotuloInfo: 'O texto é a opção da enquete e o emoji é a letra (🇦, 🇧…). Aqui você muda a cor.', emojiFixo: true },\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('enquetes', {\n  enquete: { nome: \"Mensagem da enquete\", vars: [] },\n});\n\n/**\n * Enquetes: até 5 opções com botões, resultado ao vivo e encerramento automático.\n * Cada pessoa vota uma vez (pode trocar o voto) ou várias, se a enquete permitir.\n */\n\nconst enquetes = colecao('enquetes');\nconst LETRAS = ['🇦', '🇧', '🇨', '🇩', '🇪'];\n\nfunction resultado(e, total) {\n  if (!total) return tx('ninguem_votou');\n  const maior = Math.max(...e.votos.map((v) => v.length));\n  const lideres = e.opcoes.filter((_, n) => e.votos[n].length === maior).map((op) => `**${op}**`);\n  return lideres.length > 1 ? tx('empate_entre', { lideres: lideres.join(' e ') }) : tx('vencedora', { lideres: lideres[0] });\n}\n\nfunction montar(guildId, e, encerrada = false) {\n  const total = e.votos.reduce((t, v) => t + v.length, 0);\n  const linhas = e.opcoes.map((op, n) => {\n    const q = e.votos[n].length;\n    const f = total ? q / total : 0;\n    return `${LETRAS[n]} **${op}**\\n${barra(f, 14)} ${Math.round(f * 100)}% (${q})`;\n  });\n  const emb = embed(guildId)\n    .setTitle(`📊 ${e.pergunta}`)\n    .setDescription(linhas.join('\\n\\n'))\n    .setFooter({ text: tx('voto', { total, multipla: e.multipla ? tx('pode_votar_mais') : '' }) });\n  vis(emb, 'enquete', {});\n  if (encerrada) emb.addFields({ name: tx('encerrada'), value: resultado(e, total) });\n  else if (e.fim) emb.addFields({ name: tx('termina'), value: ts(e.fim) });\n  const row = new ActionRowBuilder().addComponents(\n    e.opcoes.map((op, n) =>\n      bt('votar', { rotulo: cortar(op, 70), emoji: LETRAS[n] }).setCustomId(`eq:votar:${n}`).setDisabled(encerrada)\n    )\n  );\n  return { embeds: [emb], components: [row] };\n}\n\nasync function encerrar(client, guildId, msgId) {\n  const e = enquetes.ler(guildId, msgId);\n  if (!e || e.encerrada) return;\n  e.encerrada = true;\n  e.encerradaEm = Date.now();\n  enquetes.salvar();\n  const canal = await client.channels.fetch(e.canal).catch(() => null);\n  const msg = await canal?.messages.fetch(msgId).catch(() => null);\n  if (msg) await msg.edit(montar(guildId, e, true)).catch(() => {});\n}\n\nconst enquete = {\n  data: new SlashCommandBuilder()\n    .setName('enquete')\n    .setDescription('Cria uma enquete')\n    .addStringOption((o) => o.setName('pergunta').setDescription('A pergunta').setRequired(true).setMaxLength(200))\n    .addStringOption((o) => o.setName('opcoes').setDescription('De 2 a 5 opções separadas por | (ex.: Sim | Não | Talvez)').setRequired(true).setMaxLength(500))\n    .addStringOption((o) => o.setName('duracao').setDescription('Encerra sozinha depois de: 30m, 1h, 2d (vazio = não encerra)').setMaxLength(20))\n    .addBooleanOption((o) => o.setName('varias').setDescription('Permitir votar em mais de uma opção')),\n  async executar(i) {\n    const opcoes = i.options\n      .getString('opcoes')\n      .split('|')\n      .map((s) => s.trim())\n      .filter(Boolean)\n      .slice(0, 5);\n    if (opcoes.length < 2) return responder(i, tx('coloque_pelo_menos_opcoes'), 'erro');\n    const d = i.options.getString('duracao');\n    const ms = d ? lerDuracao(d) : null;\n    if (d && (!ms || ms > 30 * 86_400_000)) return responder(i, tx('duracao_invalida_ex_30m'), 'erro');\n\n    const e = {\n      pergunta: i.options.getString('pergunta'),\n      opcoes,\n      votos: opcoes.map(() => []),\n      multipla: i.options.getBoolean('varias') ?? false,\n      fim: ms ? Date.now() + ms : null,\n      canal: i.channelId,\n      autor: i.user.id,\n      encerrada: false,\n    };\n    await i.reply(montar(i.guildId, e));\n    const msg = await i.fetchReply();\n    enquetes.de(i.guildId)[msg.id] = e;\n    enquetes.salvar();\n  },\n};\n\nconst encerrarCmd = {\n  data: new SlashCommandBuilder()\n    .setName('encerrarenquete')\n    .setDescription('Encerra uma enquete agora')\n    .addStringOption((o) => o.setName('mensagem').setDescription('ID ou link da mensagem da enquete').setRequired(true).setMaxLength(120)),\n  async executar(i) {\n    const id = i.options.getString('mensagem').split('/').pop().replace(/\\D/g, '');\n    const e = enquetes.ler(i.guildId, id);\n    if (!e) return responder(i, tx('enquete_encontrada'), 'erro');\n    if (e.autor !== i.user.id && !ehStaff(i.member)) return responder(i, tx('so_quem_criou_ou'), 'erro');\n    await encerrar(i.client, i.guildId, id);\n    return responder(i, tx('enquete_encerrada'), 'sucesso');\n  },\n};\n\nconst componentes = {\n  async eq(i, [acao, num]) {\n    if (acao !== 'votar') return;\n    const e = enquetes.ler(i.guildId, i.message.id);\n    if (!e || e.encerrada) return responder(i, tx('esta_enquete_ja_foi'), 'aviso');\n    const n = Number(num);\n    const id = i.user.id;\n    const jaVotou = e.votos[n].includes(id);\n    if (!e.multipla) e.votos = e.votos.map((v) => v.filter((x) => x !== id));\n    else e.votos[n] = e.votos[n].filter((x) => x !== id);\n    if (!jaVotou) e.votos[n].push(id);\n    enquetes.salvar();\n    await i.update(montar(i.guildId, e));\n  },\n};\n\nexport default {\n  id: 'enquetes',\n  nome: tx('enquetes'),\n  comandos: [enquete, encerrarCmd],\n  componentes,\n  // confere a cada 20 s se alguma enquete passou do horário\n  aoIniciar(client) {\n    const checar = async () => {\n      const agora = Date.now();\n      for (const [guildId, lista] of Object.entries(enquetes.raiz)) {\n        for (const [msgId, e] of Object.entries(lista)) {\n          if (!e.encerrada && e.fim && e.fim <= agora) await encerrar(client, guildId, msgId);\n          // limpa enquetes encerradas há mais de 30 dias\n          if (e.encerrada && agora - (e.encerradaEm ?? e.fim ?? agora) > 30 * 86_400_000) delete lista[msgId];\n        }\n      }\n    };\n    checar();\n    setInterval(checar, 20_000);\n  },\n};\n\n",
  "src/modules/formularios.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, EmbedBuilder, ModalBuilder, PermissionFlagsBits, SlashCommandBuilder, TextInputBuilder, TextInputStyle } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, ehStaff, cortar, CORES, imagens } from '../core/util.js';\nimport { textos, visuais, botoes, comDica, modais } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('formularios', {\n  dica_motivo: ['', 'placeholder'],\n  pergunta: '{titulo} ({perguntas_total} pergunta(s))',\n  aprovar: ['Aprovar', 'botao'],\n  recusar: ['Recusar', 'botao'],\n  esta_resposta_esta_mais: ['Esta resposta não está mais no sistema.', 'resposta'],\n  ja_foi: ['Já foi {status}.', 'resposta'],\n  recebeu: ' · recebeu {cargo}',\n  consegui_dar_cargo: ' · (não consegui dar o cargo)',\n  pessoa_saiu_servidor: ' · (a pessoa saiu do servidor)',\n  aprovada: '✅ Aprovada',\n  recusada: '❌ Recusada',\n  motivo: '\\n**Motivo:** {motivo}',\n  por: 'por {usuario}{extra}{motivo}',\n  aprovado: 'aprovado',\n  recusado: 'recusado',\n  seu_formulario_foi: ['Seu formulário **{titulo}** em **{servidor}** foi **{resultado}**.{motivo}', 'descricao'],\n  resposta: ['Resposta {status}{extra}.', 'resposta'],\n  este_formulario_esta_mais: ['Este formulário não está mais disponível.', 'resposta'],\n  este_formulario_ainda_tem: ['Este formulário ainda não tem canal de respostas. Avise a equipe.', 'resposta'],\n  voce_ja_enviou_este: ['Você já enviou este formulário e ele ainda está sendo analisado.', 'resposta'],\n  achei_canal_respostas_avise: ['Não achei o canal de respostas. Avise a equipe.', 'resposta'],\n  conta_criada: ['Conta criada', 'campo'],\n  consegui_enviar_avise_equipe: ['Não consegui enviar. Avise a equipe para conferir as minhas permissões.', 'resposta'],\n  formulario_enviado_voce_recebe: ['Formulário enviado! Você recebe a resposta na DM.', 'resposta'],\n  so_equipe_pode_decidir: ['Só a equipe pode decidir.', 'resposta'],\n  motivo_vai_dm_pessoa: ['Motivo (vai na DM da pessoa)', 'rotulo'],\n  achei_mensagem: ['Não achei a mensagem.', 'resposta'],\n  nenhum_formulario_use_formulario: ['Nenhum formulário. Use `/formulario criar`.', 'resposta'],\n  formularios: ['📝 Formulários', 'titulo'],\n  aprovado_ganha: ' · aprovado ganha <@&{cargo}>',\n  respostas: 'Respostas em <#{canal}>{cargo}',\n  longa: ' (longa)',\n  opcional: ' (opcional)',\n  sem_perguntas: 'Sem perguntas',\n  maximo_formularios: ['No máximo {limite} formulários.', 'resposta'],\n  cargo_aprovacao_pode_ser: ['O cargo de aprovação não pode ser de administrador nem de bot.', 'resposta'],\n  meu_cargo_precisa_ficar: ['Meu cargo precisa ficar acima de {cargo}.', 'resposta'],\n  formulario_criado_agora_adicione: ['Formulário **{titulo}** criado. Agora adicione as perguntas com `/formulario pergunta` (até 5) e envie o painel com `/formulario painel`.', 'resposta'],\n  formulario_encontrado_escolha_lista: ['Formulário não encontrado. Escolha na lista enquanto digita.', 'resposta'],\n  discord_aceita_maximo_perguntas: ['O Discord aceita no máximo 5 perguntas por formulário.', 'resposta'],\n  pergunta_adicionada: ['Pergunta {perguntas_total}/5 adicionada em **{titulo}**.', 'resposta'],\n  este_formulario_tem_pergunta: ['Este formulário tem {perguntas_total} pergunta(s).', 'resposta'],\n  pergunta_removida: ['Pergunta {numero} removida.', 'resposta'],\n  formulario_apagado_paineis_ja: ['Formulário **{titulo}** apagado. (Painéis já enviados param de funcionar.)', 'resposta'],\n  adicione_pelo_menos_pergunta: ['Adicione pelo menos uma pergunta antes (`/formulario pergunta`).', 'resposta'],\n  clique_botao_abaixo_preencher: 'Clique no botão abaixo para preencher.',\n  preencher: ['Preencher', 'botao'],\n  consegui_enviar_confira_minhas: ['Não consegui enviar em {canal}. Confira as minhas permissões.', 'resposta'],\n  painel_enviado: ['Painel enviado em {canal}.', 'resposta'],\n  formularios_2: 'Formulários',\n  formulario_resposta_esperando_equipe: '{total} formulário(s) · {pendentes} resposta(s) esperando a equipe',\n  nenhum_formulario_criar: 'Nenhum (`/formulario criar`)',\n});\n\n// Botões (texto, emoji e cor personalizáveis; alguns podem ser escondidos)\nconst bt = botoes('formularios', {\n  aprovar: { nome: 'Aprovar resposta', rotulo: 'aprovar', emoji: '✅', estilo: 'Success' },\n  recusar: { nome: 'Recusar resposta', rotulo: 'recusar', emoji: '❌', estilo: 'Danger' },\n  preencher: { nome: 'Preencher formulário (painel)', rotulo: 'preencher', emoji: '📝', estilo: 'Primary' },\n});\nmodais('formularios', {\n  recusa: { nome: 'Motivo da recusa', textos: ['recusar', 'motivo_vai_dm_pessoa', 'dica_motivo'] },\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('formularios', {\n  painel: { nome: \"Painel com o botão de preencher\", vars: ['servidor_icone'] },\n});\n\n/**\n * Formulários: candidatura para a equipe, parceria, denúncia...\n * Cada formulário tem até 5 perguntas (limite do Discord), um painel com botão,\n * um canal onde as respostas chegam e botões para a equipe aprovar ou recusar.\n */\n\nconst respostas = colecao('formularios_respostas'); // guild -> msgId -> { form, user, status }\nconst cfg = (guildId) => ajustes(guildId, 'formularios', { lista: {} });\nconst LIMITE_FORMS = 10;\nconst slug = (t) =>\n  t\n    .normalize('NFD')\n    .replace(/[̀-ͯ]/g, '')\n    .toLowerCase()\n    .replace(/[^a-z0-9]+/g, '-')\n    .replace(/^-|-$/g, '')\n    .slice(0, 20);\n\nconst formDe = (guildId, id) => cfg(guildId).lista[id];\n\nasync function autocompletarForm(i) {\n  const foco = slug(i.options.getFocused() || '');\n  const forms = Object.entries(cfg(i.guildId).lista);\n  await i.respond(forms.filter(([id, f]) => id.includes(foco) || slug(f.titulo).includes(foco)).slice(0, 25).map(([id, f]) => ({ name: tx('pergunta', { titulo: f.titulo, perguntas_total: f.perguntas.length }).slice(0, 100), value: id })));\n}\n\nfunction botoesEquipe(desligar = false) {\n  return [\n    new ActionRowBuilder().addComponents(\n      bt('aprovar').setCustomId('fm:aprovar').setDisabled(desligar),\n      bt('recusar').setCustomId('fm:recusar').setDisabled(desligar)\n    ),\n  ];\n}\n\nasync function decidir(i, msg, aprovado, motivo) {\n  const r = respostas.ler(i.guildId, msg.id);\n  if (!r) return responder(i, tx('esta_resposta_esta_mais'), 'erro');\n  if (r.status !== 'pendente') return responder(i, tx('ja_foi', { status: r.status }), 'aviso');\n  r.status = aprovado ? 'aprovada' : 'recusada';\n  r.por = i.user.id;\n  respostas.salvar();\n  const f = formDe(i.guildId, r.form);\n  let extra = '';\n  if (aprovado && f?.cargo) {\n    const membro = await i.guild.members.fetch(r.user).catch(() => null);\n    const cargo = i.guild.roles.cache.get(f.cargo);\n    if (membro && cargo?.editable) {\n      const ok = await membro.roles.add(cargo, `Formulário ${f.titulo} aprovado`).then(() => true, () => false);\n      extra = ok ? tx('recebeu', { cargo }) : tx('consegui_dar_cargo');\n    } else extra = membro ? tx('consegui_dar_cargo') : tx('pessoa_saiu_servidor');\n  }\n  const e = EmbedBuilder.from(msg.embeds[0])\n    .setColor(aprovado ? CORES.sucesso : CORES.erro)\n    .addFields({ name: aprovado ? tx('aprovada') : tx('recusada'), value: tx('por', { usuario: i.user, extra, motivo: motivo ? tx('motivo', { motivo: cortar(motivo, 900) }) : '' }) });\n  await msg.edit({ embeds: [e], components: botoesEquipe(true) }).catch(() => {});\n  const user = await i.client.users.fetch(r.user).catch(() => null);\n  await user\n    ?.send({\n      embeds: [\n        embed(i.guildId)\n          .setColor(aprovado ? CORES.sucesso : CORES.erro)\n          .setDescription(tx('seu_formulario_foi', { titulo: f?.titulo ?? r.form, servidor: i.guild.name, resultado: aprovado ? tx('aprovado') : tx('recusado'), motivo: motivo ? tx('motivo', { motivo }) : '' })),\n      ],\n    })\n    .catch(() => {});\n  return responder(i, tx('resposta', { status: r.status, extra }), 'sucesso');\n}\n\nconst componentes = {\n  async fm(i, [acao, alvo]) {\n    // membro clicou no botão do painel\n    if (acao === 'abrir') {\n      const f = formDe(i.guildId, alvo);\n      if (!f || !f.perguntas.length) return responder(i, tx('este_formulario_esta_mais'), 'erro');\n      if (!f.canal) return responder(i, tx('este_formulario_ainda_tem'), 'erro');\n      const pendente = Object.values(respostas.ler(i.guildId) ?? {}).some((r) => r.form === alvo && r.user === i.user.id && r.status === 'pendente');\n      if (pendente) return responder(i, tx('voce_ja_enviou_este'), 'aviso');\n      return i.showModal(\n        new ModalBuilder()\n          .setCustomId(`fm:enviar:${alvo}`)\n          .setTitle(cortar(f.titulo, 45))\n          .addComponents(\n            f.perguntas.map((p, n) =>\n              new ActionRowBuilder().addComponents(\n                new TextInputBuilder()\n                  .setCustomId(`p${n}`)\n                  .setLabel(p.texto)\n                  .setStyle(p.longa ? TextInputStyle.Paragraph : TextInputStyle.Short)\n                  .setRequired(p.obrigatoria)\n                  .setMaxLength(p.longa ? 1000 : 200)\n              )\n            )\n          )\n      );\n    }\n    // respostas enviadas\n    if (acao === 'enviar' && i.isModalSubmit()) {\n      const f = formDe(i.guildId, alvo);\n      const canal = f?.canal && i.guild.channels.cache.get(f.canal);\n      if (!canal?.isTextBased()) return responder(i, tx('achei_canal_respostas_avise'), 'erro');\n      const e = embed(i.guildId)\n        .setAuthor({ name: `${i.user.tag} (${i.user.id})`, iconURL: i.user.displayAvatarURL() })\n        .setTitle(`📝 ${f.titulo}`)\n        .addFields(f.perguntas.map((p, n) => ({ name: cortar(p.texto, 256), value: cortar(i.fields.getTextInputValue(`p${n}`) || '—', 1024) })))\n        .addFields({ name: tx('conta_criada'), value: `<t:${Math.floor(i.user.createdTimestamp / 1000)}:R>`, inline: true })\n        .setTimestamp();\n      const msg = await canal.send({ content: f.mencionar ? `<@&${f.mencionar}>` : undefined, embeds: [e], components: botoesEquipe(), allowedMentions: { roles: f.mencionar ? [f.mencionar] : [] } }).catch(() => null);\n      if (!msg) return responder(i, tx('consegui_enviar_avise_equipe'), 'erro');\n      respostas.de(i.guildId)[msg.id] = { form: alvo, user: i.user.id, status: 'pendente', em: Date.now() };\n      respostas.salvar();\n      return responder(i, tx('formulario_enviado_voce_recebe'), 'sucesso');\n    }\n    // equipe\n    if (acao === 'aprovar' || acao === 'recusar') {\n      if (!ehStaff(i.member)) return responder(i, tx('so_equipe_pode_decidir'), 'erro');\n      if (acao === 'aprovar') return decidir(i, i.message, true, null);\n      return i.showModal(\n        new ModalBuilder()\n          .setCustomId(`fm:motivo:${i.message.id}`)\n          .setTitle(tx('recusar'))\n          .addComponents(new ActionRowBuilder().addComponents(comDica(new TextInputBuilder().setCustomId('motivo').setLabel(tx('motivo_vai_dm_pessoa')).setStyle(TextInputStyle.Paragraph).setRequired(false).setMaxLength(500), tx('dica_motivo'))))\n      );\n    }\n    if (acao === 'motivo' && i.isModalSubmit()) {\n      if (!ehStaff(i.member)) return responder(i, tx('so_equipe_pode_decidir'), 'erro');\n      const msg = await i.channel.messages.fetch(alvo).catch(() => null);\n      if (!msg) return responder(i, tx('achei_mensagem'), 'erro');\n      return decidir(i, msg, false, i.fields.getTextInputValue('motivo').trim());\n    }\n  },\n};\n\nconst formulario = {\n  data: new SlashCommandBuilder()\n    .setName('formulario')\n    .setDescription('Formulários (candidatura, parceria, denúncia...)')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('criar')\n        .setDescription('Cria um formulário')\n        .addStringOption((o) => o.setName('titulo').setDescription('Ex.: Candidatura para a equipe').setRequired(true).setMaxLength(45))\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde as respostas chegam (só a equipe deve ver)').setRequired(true).addChannelTypes(ChannelType.GuildText))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Cargo dado quando aprovado (opcional)'))\n        .addRoleOption((o) => o.setName('mencionar').setDescription('Cargo avisado a cada resposta nova (opcional)'))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('pergunta')\n        .setDescription('Adiciona uma pergunta (máximo 5)')\n        .addStringOption((o) => o.setName('formulario').setDescription('Qual formulário').setRequired(true).setAutocomplete(true))\n        .addStringOption((o) => o.setName('texto').setDescription('A pergunta (até 45 letras)').setRequired(true).setMaxLength(45))\n        .addBooleanOption((o) => o.setName('longa').setDescription('Resposta longa (vários parágrafos)?'))\n        .addBooleanOption((o) => o.setName('obrigatoria').setDescription('Obrigatória? (padrão: sim)'))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('tirar-pergunta')\n        .setDescription('Remove uma pergunta')\n        .addStringOption((o) => o.setName('formulario').setDescription('Qual formulário').setRequired(true).setAutocomplete(true))\n        .addIntegerOption((o) => o.setName('numero').setDescription('Número da pergunta (veja em /formulario lista)').setRequired(true).setMinValue(1).setMaxValue(5))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('painel')\n        .setDescription('Envia o painel com o botão para responder')\n        .addStringOption((o) => o.setName('formulario').setDescription('Qual formulário').setRequired(true).setAutocomplete(true))\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde enviar (padrão: aqui)').addChannelTypes(ChannelType.GuildText))\n        .addStringOption((o) => o.setName('mensagem').setDescription('Texto do painel').setMaxLength(1500))\n    )\n    .addSubcommand((s) => s.setName('lista').setDescription('Mostra os formulários e as perguntas'))\n    .addSubcommand((s) =>\n      s\n        .setName('apagar')\n        .setDescription('Apaga um formulário')\n        .addStringOption((o) => o.setName('formulario').setDescription('Qual formulário').setRequired(true).setAutocomplete(true))\n    ),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const sub = i.options.getSubcommand();\n    if (sub === 'lista') {\n      const forms = Object.entries(c.lista);\n      if (!forms.length) return responder(i, tx('nenhum_formulario_use_formulario'), 'aviso');\n      const e = embed(i.guildId).setTitle(tx('formularios'));\n      for (const [id, f] of forms) {\n        e.addFields({\n          name: `${f.titulo} · \\`${id}\\``,\n          value: cortar(\n            [tx('respostas', { canal: f.canal, cargo: f.cargo ? tx('aprovado_ganha', { cargo: f.cargo }) : '' }), ...f.perguntas.map((p, n) => `${n + 1}. ${p.texto}${p.longa ? tx('longa') : ''}${p.obrigatoria ? '' : tx('opcional')}`)].join('\\n') ||\n              tx('sem_perguntas'),\n            1024\n          ),\n        });\n      }\n      return i.reply({ embeds: [e], flags: 64 });\n    }\n    if (sub === 'criar') {\n      if (Object.keys(c.lista).length >= LIMITE_FORMS) return responder(i, tx('maximo_formularios', { limite: LIMITE_FORMS }), 'erro');\n      const titulo = i.options.getString('titulo').trim();\n      let id = slug(titulo) || 'form';\n      while (c.lista[id]) id = `${id.slice(0, 17)}-${Math.floor(Math.random() * 90 + 10)}`;\n      const cargo = i.options.getRole('cargo');\n      if (cargo && (cargo.permissions.has(PermissionFlagsBits.Administrator) || cargo.managed)) return responder(i, tx('cargo_aprovacao_pode_ser'), 'erro');\n      if (cargo && !cargo.editable) return responder(i, tx('meu_cargo_precisa_ficar', { cargo }), 'erro');\n      c.lista[id] = { titulo, canal: i.options.getChannel('canal').id, cargo: cargo?.id ?? null, mencionar: i.options.getRole('mencionar')?.id ?? null, perguntas: [] };\n      salvarAjustes();\n      return responder(i, tx('formulario_criado_agora_adicione', { titulo }), 'sucesso');\n    }\n    const id = i.options.getString('formulario');\n    const f = c.lista[id];\n    if (!f) return responder(i, tx('formulario_encontrado_escolha_lista'), 'erro');\n    if (sub === 'pergunta') {\n      if (f.perguntas.length >= 5) return responder(i, tx('discord_aceita_maximo_perguntas'), 'erro');\n      f.perguntas.push({ texto: i.options.getString('texto').trim(), longa: i.options.getBoolean('longa') ?? false, obrigatoria: i.options.getBoolean('obrigatoria') ?? true });\n      salvarAjustes();\n      return responder(i, tx('pergunta_adicionada', { perguntas_total: f.perguntas.length, titulo: f.titulo }), 'sucesso');\n    }\n    if (sub === 'tirar-pergunta') {\n      const n = i.options.getInteger('numero');\n      if (n > f.perguntas.length) return responder(i, tx('este_formulario_tem_pergunta', { perguntas_total: f.perguntas.length }), 'erro');\n      f.perguntas.splice(n - 1, 1);\n      salvarAjustes();\n      return responder(i, tx('pergunta_removida', { numero: n }), 'sucesso');\n    }\n    if (sub === 'apagar') {\n      delete c.lista[id];\n      salvarAjustes();\n      return responder(i, tx('formulario_apagado_paineis_ja', { titulo: f.titulo }), 'sucesso');\n    }\n    // painel\n    if (!f.perguntas.length) return responder(i, tx('adicione_pelo_menos_pergunta'), 'erro');\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    const msg = await canal\n      .send({\n        embeds: [vis(embed(i.guildId).setTitle(`📝 ${f.titulo}`).setDescription(i.options.getString('mensagem') || tx('clique_botao_abaixo_preencher')), 'painel', imagens({ guild: i.guild }))],\n        components: [new ActionRowBuilder().addComponents(bt('preencher').setCustomId(`fm:abrir:${id}`))],\n      })\n      .catch(() => null);\n    if (!msg) return responder(i, tx('consegui_enviar_confira_minhas', { canal }), 'erro');\n    return responder(i, tx('painel_enviado', { canal }), 'sucesso');\n  },\n  autocompletar: autocompletarForm,\n};\n\nexport default {\n  id: 'formularios',\n  nome: tx('formularios_2'),\n  comandos: [formulario],\n  componentes,\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  config: {\n    resumo(guild) {\n      const n = Object.keys(cfg(guild.id).lista).length;\n      const pend = Object.values(respostas.ler(guild.id) ?? {}).filter((r) => r.status === 'pendente').length;\n      return [n ? tx('formulario_resposta_esperando_equipe', { total: n, pendentes: pend }) : tx('nenhum_formulario_criar')];\n    },\n  },\n};\n",
  "src/modules/logs.js": "import { AuditLogEvent, ChannelType, GatewayIntentBits, Partials, PermissionFlagsBits } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, cortar, foiRemovida, CORES } from '../core/util.js';\nimport { textos } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('logs', {\n  mensagens_apagadas_editadas: 'Mensagens apagadas e editadas',\n  entradas_saidas_apelidos_cargos: 'Entradas, saídas, apelidos e cargos',\n  banimentos: 'Banimentos',\n  canais_criados_apagados: 'Canais criados e apagados',\n  entradas_saidas_canais_voz: 'Entradas e saídas de canais de voz',\n  mensagem_apagada: ['🗑️ Mensagem apagada', 'titulo'],\n  autor: ['Autor', 'campo'],\n  canal: ['Canal', 'campo'],\n  conteudo: ['Conteúdo', 'campo'],\n  mensagem_antiga_fora_memoria: '(mensagem antiga, fora da memória do bot)',\n  sem_texto: '(sem texto)',\n  anexos: ['Anexos', 'campo'],\n  mensagens_apagadas_massa: ['🧹 Mensagens apagadas em massa', 'titulo'],\n  quantidade: ['Quantidade', 'campo'],\n  algumas_delas: ['Algumas delas', 'campo'],\n  mensagem_editada: ['✏️ Mensagem editada', 'titulo'],\n  antes: ['Antes', 'campo'],\n  vazio: '(vazio)',\n  depois: ['Depois', 'campo'],\n  membro_entrou: ['📥 Membro entrou', 'titulo'],\n  membro: ['Membro', 'campo'],\n  conta_criada: ['Conta criada', 'campo'],\n  conta_nova: ' ⚠️ conta nova',\n  membros_agora: ['Membros agora', 'campo'],\n  membro_saiu: ['📤 Membro saiu', 'titulo'],\n  cargos: ['Cargos', 'campo'],\n  apelido_alterado: ['🏷️ Apelido alterado', 'titulo'],\n  nenhum: '(nenhum)',\n  cargos_alterados: ['🎭 Cargos alterados', 'titulo'],\n  recebeu: ['➕ Recebeu', 'campo'],\n  perdeu: ['➖ Perdeu', 'campo'],\n  membro_banido: ['🔨 Membro banido', 'titulo'],\n  por: ['Por', 'campo'],\n  desconhecido: 'desconhecido',\n  motivo: ['Motivo', 'campo'],\n  sem_motivo: 'Sem motivo',\n  banimento_removido: ['🔓 Banimento removido', 'titulo'],\n  canal_criado: ['📁 Canal criado', 'titulo'],\n  canal_apagado: ['📁 Canal apagado', 'titulo'],\n  entrou_call: '🎤 Entrou na call',\n  saiu_call: '🔇 Saiu da call',\n  trocou_call: '🔄 Trocou de call',\n  registros_vao: 'Os registros vão para {canal}.',\n  registros_desligados: 'Registros desligados.',\n  registrando: 'registrando',\n  registrando_2: 'não registrando',\n  desligado_use_config_logs: 'Desligado (use /config logs canal)',\n  canal_2: 'Canal: <#{canal}>',\n  nada: 'nada',\n  registrando_3: 'Registrando: {tipos}',\n  logs: 'Logs',\n});\n\n/**\n * Logs: registra num canal o que acontece no servidor.\n * Tipos: mensagens (apagadas/editadas), membros (entrou, saiu, apelido, cargos),\n * moderacao (banimentos), canais (criados/apagados) e voz (entrou, saiu, trocou).\n */\n\nconst TIPOS = {\n  mensagens: tx('mensagens_apagadas_editadas'),\n  membros: tx('entradas_saidas_apelidos_cargos'),\n  moderacao: tx('banimentos'),\n  canais: tx('canais_criados_apagados'),\n  voz: tx('entradas_saidas_canais_voz'),\n};\nconst PADRAO = { canal: null, tipos: Object.keys(TIPOS) };\nconst cfg = (guildId) => ajustes(guildId, 'logs', PADRAO);\n\nasync function enviar(guild, tipo, montar) {\n  if (!guild) return;\n  const c = cfg(guild.id);\n  if (!c.canal || !c.tipos.includes(tipo)) return;\n  const canal = guild.channels.cache.get(c.canal);\n  if (!canal?.isTextBased()) return;\n  const e = embed(guild.id).setTimestamp();\n  montar(e);\n  await canal.send({ embeds: [e], allowedMentions: { parse: [] } }).catch(() => {});\n}\n\nconst quem = (u) => (u ? `${u} (${u.tag ?? u.username ?? u.id})` : 'desconhecido');\n\nconst eventos = {\n  async messageDelete(msg) {\n    if (!msg.guild || msg.author?.bot) return;\n    if (foiRemovida(msg.id)) return; // o AutoMod já registra o que ele apaga\n    if (msg.channelId === cfg(msg.guild.id).canal) return;\n    await enviar(msg.guild, 'mensagens', (e) => {\n      e.setColor(CORES.erro)\n        .setTitle(tx('mensagem_apagada'))\n        .addFields(\n          { name: tx('autor'), value: quem(msg.author), inline: true },\n          { name: tx('canal'), value: `${msg.channel}`, inline: true },\n          { name: tx('conteudo'), value: cortar(msg.content || (msg.partial ? tx('mensagem_antiga_fora_memoria') : tx('sem_texto')), 1000) },\n        );\n      if (msg.attachments?.size) e.addFields({ name: tx('anexos'), value: cortar([...msg.attachments.values()].map((a) => a.name).join(', '), 1000) });\n    });\n  },\n  async messageDeleteBulk(msgs, canal) {\n    if (!canal.guild || canal.id === cfg(canal.guild.id).canal) return;\n    const linhas = [...msgs.values()]\n      .filter((m) => !m.partial && m.author && !m.author.bot)\n      .sort((a, b) => a.createdTimestamp - b.createdTimestamp)\n      .map((m) => `${m.author.tag}: ${cortar(m.content || tx('sem_texto'), 120)}`);\n    await enviar(canal.guild, 'mensagens', (e) => {\n      e.setColor(CORES.erro)\n        .setTitle(tx('mensagens_apagadas_massa'))\n        .addFields({ name: tx('canal'), value: `${canal}`, inline: true }, { name: tx('quantidade'), value: String(msgs.size), inline: true });\n      if (linhas.length) e.addFields({ name: tx('algumas_delas'), value: cortar(linhas.join('\\n'), 1000) });\n    });\n  },\n  async messageUpdate(antes, depois) {\n    if (!depois.guild || depois.author?.bot) return;\n    if (antes.content === depois.content || antes.partial) return; // só mudanças de texto que o bot viu\n    await enviar(depois.guild, 'mensagens', (e) =>\n      e\n        .setColor(CORES.aviso)\n        .setTitle(tx('mensagem_editada'))\n        .setURL(depois.url)\n        .addFields(\n          { name: tx('autor'), value: quem(depois.author), inline: true },\n          { name: tx('canal'), value: `${depois.channel}`, inline: true },\n          { name: tx('antes'), value: cortar(antes.content || tx('vazio'), 1000) },\n          { name: tx('depois'), value: cortar(depois.content || tx('vazio'), 1000) },\n        )\n    );\n  },\n  async guildMemberAdd(m) {\n    const idade = Math.floor((Date.now() - m.user.createdTimestamp) / 86_400_000);\n    await enviar(m.guild, 'membros', (e) =>\n      e\n        .setColor(CORES.sucesso)\n        .setTitle(tx('membro_entrou'))\n        .setThumbnail(m.user.displayAvatarURL())\n        .addFields(\n          { name: tx('membro'), value: quem(m.user) },\n          { name: tx('conta_criada'), value: `<t:${Math.floor(m.user.createdTimestamp / 1000)}:R>${idade < 7 ? tx('conta_nova') : ''}`, inline: true },\n          { name: tx('membros_agora'), value: String(m.guild.memberCount), inline: true },\n        )\n    );\n  },\n  async guildMemberRemove(m) {\n    const cargos = m.roles?.cache?.filter((r) => r.id !== m.guild.id).map((r) => `${r}`) ?? [];\n    await enviar(m.guild, 'membros', (e) =>\n      e\n        .setColor(CORES.erro)\n        .setTitle(tx('membro_saiu'))\n        .setThumbnail(m.user?.displayAvatarURL?.() ?? null)\n        .addFields(\n          { name: tx('membro'), value: quem(m.user) },\n          { name: tx('cargos'), value: cortar(cargos.join(' ') || 'nenhum', 1000) },\n        )\n    );\n  },\n  async guildMemberUpdate(antes, depois) {\n    if (antes.partial) return;\n    if (antes.nickname !== depois.nickname) {\n      await enviar(depois.guild, 'membros', (e) =>\n        e\n          .setTitle(tx('apelido_alterado'))\n          .addFields(\n            { name: tx('membro'), value: quem(depois.user) },\n            { name: tx('antes'), value: antes.nickname || tx('nenhum'), inline: true },\n            { name: tx('depois'), value: depois.nickname || tx('nenhum'), inline: true },\n          )\n      );\n    }\n    const ganhou = depois.roles.cache.filter((r) => !antes.roles.cache.has(r.id));\n    const perdeu = antes.roles.cache.filter((r) => !depois.roles.cache.has(r.id));\n    if (ganhou.size || perdeu.size) {\n      await enviar(depois.guild, 'membros', (e) => {\n        e.setTitle(tx('cargos_alterados')).addFields({ name: tx('membro'), value: quem(depois.user) });\n        if (ganhou.size) e.addFields({ name: tx('recebeu'), value: cortar(ganhou.map((r) => `${r}`).join(' '), 1000) });\n        if (perdeu.size) e.addFields({ name: tx('perdeu'), value: cortar(perdeu.map((r) => `${r}`).join(' '), 1000) });\n      });\n    }\n  },\n  async guildBanAdd(ban) {\n    let motivo = ban.reason;\n    let autor = null;\n    const auditoria = await ban.guild.fetchAuditLogs({ type: AuditLogEvent.MemberBanAdd, limit: 3 }).catch(() => null);\n    const entrada = auditoria?.entries.find((x) => x.target?.id === ban.user.id);\n    if (entrada) {\n      autor = entrada.executor;\n      motivo ??= entrada.reason;\n    }\n    await enviar(ban.guild, 'moderacao', (e) =>\n      e\n        .setColor(CORES.erro)\n        .setTitle(tx('membro_banido'))\n        .setThumbnail(ban.user.displayAvatarURL())\n        .addFields(\n          { name: tx('membro'), value: quem(ban.user), inline: true },\n          { name: tx('por'), value: autor ? quem(autor) : tx('desconhecido'), inline: true },\n          { name: tx('motivo'), value: cortar(motivo || tx('sem_motivo'), 1000) },\n        )\n    );\n  },\n  async guildBanRemove(ban) {\n    await enviar(ban.guild, 'moderacao', (e) => e.setColor(CORES.sucesso).setTitle(tx('banimento_removido')).addFields({ name: tx('membro'), value: quem(ban.user) }));\n  },\n  async channelCreate(ch) {\n    if (!ch.guild) return;\n    await enviar(ch.guild, 'canais', (e) => e.setColor(CORES.sucesso).setTitle(tx('canal_criado')).addFields({ name: tx('canal'), value: `${ch} (${ch.name})` }));\n  },\n  async channelDelete(ch) {\n    if (!ch.guild) return;\n    await enviar(ch.guild, 'canais', (e) => e.setColor(CORES.erro).setTitle(tx('canal_apagado')).addFields({ name: tx('canal'), value: `#${ch.name}` }));\n  },\n  async voiceStateUpdate(antes, depois) {\n    const membro = depois.member ?? antes.member;\n    if (!membro || membro.user.bot || antes.channelId === depois.channelId) return;\n    let titulo, texto;\n    if (!antes.channelId) [titulo, texto] = [tx('entrou_call'), `${depois.channel}`];\n    else if (!depois.channelId) [titulo, texto] = [tx('saiu_call'), `${antes.channel}`];\n    else [titulo, texto] = [tx('trocou_call'), `${antes.channel} → ${depois.channel}`];\n    await enviar(depois.guild, 'voz', (e) => e.setTitle(titulo).addFields({ name: tx('membro'), value: quem(membro.user), inline: true }, { name: tx('canal'), value: texto, inline: true }));\n  },\n};\n\n// ---------------- /config logs ----------------\nconst config = {\n  grupo: 'logs',\n  montar: (g) =>\n    g\n      .setDescription('Registro do que acontece no servidor')\n      .addSubcommand((s) =>\n        s.setName('canal').setDescription('Canal dos registros').addChannelOption((o) => o.setName('canal').setDescription('Vazio desliga').addChannelTypes(ChannelType.GuildText))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('tipo')\n          .setDescription('Liga ou desliga um tipo de registro')\n          .addStringOption((o) =>\n            o.setName('tipo').setDescription('Tipo').setRequired(true).addChoices(...Object.entries(TIPOS).map(([value, name]) => ({ name, value })))\n          )\n          .addBooleanOption((o) => o.setName('ligado').setDescription('Registrar?').setRequired(true))\n      ),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    if (sub === 'canal') {\n      const canal = i.options.getChannel('canal');\n      c.canal = canal?.id ?? null;\n      salvarAjustes();\n      return responder(i, canal ? tx('registros_vao', { canal }) : tx('registros_desligados'), 'sucesso');\n    }\n    if (sub === 'tipo') {\n      const tipo = i.options.getString('tipo');\n      const ligado = i.options.getBoolean('ligado');\n      c.tipos = c.tipos.filter((t) => t !== tipo);\n      if (ligado) c.tipos.push(tipo);\n      salvarAjustes();\n      return responder(i, `${TIPOS[tipo]}: **${ligado ? tx('registrando') : tx('registrando_2')}**.`, 'sucesso');\n    }\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    if (!c.canal) return [tx('desligado_use_config_logs')];\n    return [tx('canal_2', { canal: c.canal }), tx('registrando_3', { tipos: c.tipos.map((t) => t).join(', ') || tx('nada') })];\n  },\n};\n\nexport default {\n  id: 'logs',\n  nome: tx('logs'),\n  intents: [\n    GatewayIntentBits.GuildMembers,\n    GatewayIntentBits.GuildMessages,\n    GatewayIntentBits.MessageContent,\n    GatewayIntentBits.GuildModeration,\n    GatewayIntentBits.GuildVoiceStates,\n  ],\n  partials: [Partials.Message, Partials.Channel, Partials.GuildMember, Partials.User],\n  permissoes: [PermissionFlagsBits.ViewAuditLog],\n  eventos,\n  config,\n};\n",
  "src/modules/minecraft.js": "import net from 'node:net';\nimport dns from 'node:dns/promises';\nimport { AttachmentBuilder, ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, cortar, fmt, CORES } from '../core/util.js';\nimport { textos, visuais } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('minecraft', {\n  endereco_invalido: ['❌ Endereço inválido: `{endereco}`', 'descricao'],\n  jogadores: ['Jogadores', 'campo'],\n  versao: ['Versão', 'campo'],\n  ping: ['Ping', 'campo'],\n  ms: '{latencia} ms',\n  atualizado: ['Atualizado', 'rodape'],\n  online_agora: ['Online agora', 'campo'],\n  servidor_offline_ou_respondeu: ['Servidor **offline** ou não respondeu.', 'descricao'],\n  so_quem_tem_gerenciar: ['Só quem tem **Gerenciar servidor** pode criar painéis.', 'resposta'],\n  maximo_paineis_apague_mensagem: ['No máximo {limite} painéis. Apague a mensagem de um para liberar.', 'resposta'],\n  consegui_enviar_nesse_canal: '❌ Não consegui enviar nesse canal.',\n  painel_criado_ele_atualiza: '✅ Painel criado em {canal}. Ele se atualiza a cada 2 minutos (para tirar, apague a mensagem).',\n  status_minecraft: 'Status Minecraft',\n  em: '`{endereco}` em <#{canal}>',\n  nenhum_painel_minecraft_painel: 'Nenhum painel (`/minecraft painel`)',\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('minecraft', {\n  status: { nome: \"Painel de status (online)\", vars: [], miniatura: \"ícone do servidor de Minecraft\" },\n});\n\n/**\n * Status de servidor de Minecraft (Java): online/offline, jogadores, versão e mensagem do servidor.\n * Consulta o servidor direto pelo protocolo do Minecraft (sem site de terceiros).\n * /minecraft status ip:jogar.exemplo.com · /minecraft painel: mensagem que se atualiza sozinha.\n */\n\nconst cfg = (guildId) => ajustes(guildId, 'minecraft', { paineis: [] }); // [{ endereco, canal, msg }]\nconst LIMITE_PAINEIS = 3;\n\n// ---------------- protocolo (Server List Ping) ----------------\nfunction varint(n) {\n  const out = [];\n  do {\n    let b = n & 0x7f;\n    n >>>= 7;\n    if (n) b |= 0x80;\n    out.push(b);\n  } while (n);\n  return Buffer.from(out);\n}\nfunction lerVarint(buf, pos) {\n  let n = 0;\n  let shift = 0;\n  for (let k = 0; k < 5; k++) {\n    if (pos + k >= buf.length) return null;\n    const b = buf[pos + k];\n    n |= (b & 0x7f) << shift;\n    if (!(b & 0x80)) return { valor: n >>> 0, tamanho: k + 1 };\n    shift += 7;\n  }\n  throw new Error('resposta inválida');\n}\nconst pacote = (...partes) => {\n  const corpo = Buffer.concat(partes);\n  return Buffer.concat([varint(corpo.length), corpo]);\n};\n\n/** \"jogar.exemplo.com\", \"1.2.3.4:25570\" -> { host, porta }, seguindo o registro SRV se houver. */\nexport async function resolverEndereco(endereco) {\n  const [host, portaTxt] = endereco.trim().toLowerCase().split(':');\n  if (!host || !/^[a-z0-9.-]+$/.test(host)) return null;\n  if (portaTxt) {\n    const porta = Number(portaTxt);\n    return porta > 0 && porta < 65536 ? { host, porta } : null;\n  }\n  if (!/^\\d+\\.\\d+\\.\\d+\\.\\d+$/.test(host)) {\n    const srv = await dns.resolveSrv(`_minecraft._tcp.${host}`).catch(() => null);\n    if (srv?.length) return { host: srv[0].name, porta: srv[0].port };\n  }\n  return { host, porta: 25565 };\n}\n\n/** Pergunta o status ao servidor. Devolve o JSON do Minecraft + latência, ou lança erro. */\nexport function consultar(host, porta, tempo = 5000) {\n  return new Promise((resolve, reject) => {\n    const inicio = Date.now();\n    const sock = net.createConnection({ host, port: porta });\n    let buf = Buffer.alloc(0);\n    let latencia = null;\n    const fim = (erro, dados) => {\n      sock.destroy();\n      clearTimeout(timer);\n      erro ? reject(erro) : resolve(dados);\n    };\n    const timer = setTimeout(() => fim(new Error('sem resposta')), tempo);\n    sock.on('error', (e) => fim(e));\n    sock.on('connect', () => {\n      latencia = Date.now() - inicio;\n      const hostBuf = Buffer.from(host, 'utf8');\n      const portaBuf = Buffer.alloc(2);\n      portaBuf.writeUInt16BE(porta);\n      // handshake (protocolo -1 = \"qualquer versão\", próximo estado 1 = status) + pedido de status\n      sock.write(pacote(varint(0), varint(-1), varint(hostBuf.length), hostBuf, portaBuf, varint(1)));\n      sock.write(pacote(varint(0)));\n    });\n    sock.on('data', (d) => {\n      buf = Buffer.concat([buf, d]);\n      try {\n        const tam = lerVarint(buf, 0);\n        if (!tam || buf.length < tam.tamanho + tam.valor) return; // ainda chegando\n        let pos = tam.tamanho;\n        const id = lerVarint(buf, pos);\n        pos += id.tamanho;\n        const len = lerVarint(buf, pos);\n        pos += len.tamanho;\n        const json = JSON.parse(buf.subarray(pos, pos + len.valor).toString('utf8'));\n        fim(null, { ...json, latencia });\n      } catch (e) {\n        fim(e);\n      }\n    });\n  });\n}\n\n/** Texto do \"motd\" (pode vir como texto ou como componentes coloridos). */\nfunction textoMotd(d) {\n  const juntar = (c) => (typeof c === 'string' ? c : (c?.text ?? '') + (c?.extra ?? []).map(juntar).join(''));\n  return juntar(d)\n    .replace(/§[0-9a-fk-or]/gi, '')\n    .trim();\n}\n\nasync function statusEmbed(guildId, endereco) {\n  const alvo = await resolverEndereco(endereco);\n  if (!alvo) return { e: embed(guildId).setColor(CORES.erro).setDescription(tx('endereco_invalido', { endereco })) };\n  try {\n    const s = await consultar(alvo.host, alvo.porta);\n    const nomes = (s.players?.sample ?? []).map((p) => p.name).filter((n) => n && !n.includes('§'));\n    const e = embed(guildId)\n      .setColor(CORES.sucesso)\n      .setTitle(`🟢 ${endereco}`)\n      .setDescription(cortar(textoMotd(s.description), 500) || null)\n      .addFields(\n        { name: tx('jogadores'), value: `**${fmt(s.players?.online ?? 0)}** / ${fmt(s.players?.max ?? 0)}`, inline: true },\n        { name: tx('versao'), value: cortar(String(s.version?.name ?? '?').replace(/§[0-9a-fk-or]/gi, ''), 100), inline: true },\n        { name: tx('ping'), value: tx('ms', { latencia: s.latencia }), inline: true }\n      )\n      .setFooter({ text: tx('atualizado') })\n      .setTimestamp();\n    if (nomes.length) e.addFields({ name: tx('online_agora'), value: cortar(nomes.slice(0, 20).join(', '), 1024) });\n    let arquivo = null;\n    const icone = /^data:image\\/png;base64,(.+)$/.exec(s.favicon ?? '');\n    if (icone) {\n      arquivo = new AttachmentBuilder(Buffer.from(icone[1], 'base64'), { name: 'icone.png' });\n      e.setThumbnail('attachment://icone.png');\n    }\n    vis(e, 'status', {});\n    return { e, arquivo, online: true };\n  } catch {\n    return {\n      e: embed(guildId).setColor(CORES.erro).setTitle(`🔴 ${endereco}`).setDescription(tx('servidor_offline_ou_respondeu')).setFooter({ text: tx('atualizado') }).setTimestamp(),\n      online: false,\n    };\n  }\n}\n\nasync function atualizarPaineis(client) {\n  for (const guild of client.guilds.cache.values()) {\n    const c = cfg(guild.id);\n    if (!c.paineis.length) continue;\n    let mudou = false;\n    for (const p of [...c.paineis]) {\n      const canal = guild.channels.cache.get(p.canal);\n      const msg = await canal?.messages.fetch(p.msg).catch(() => null);\n      if (!msg) {\n        c.paineis = c.paineis.filter((x) => x !== p); // apagaram a mensagem\n        mudou = true;\n        continue;\n      }\n      const { e } = await statusEmbed(guild.id, p.endereco);\n      await msg.edit({ embeds: [e], attachments: [] }).catch(() => {});\n    }\n    if (mudou) salvarAjustes();\n  }\n}\n\nconst minecraft = {\n  data: new SlashCommandBuilder()\n    .setName('minecraft')\n    .setDescription('Status de servidor de Minecraft (Java)')\n    .addSubcommand((s) =>\n      s\n        .setName('status')\n        .setDescription('Mostra se o servidor está online e quantos jogam')\n        .addStringOption((o) => o.setName('ip').setDescription('Ex.: jogar.exemplo.com ou 1.2.3.4:25565').setRequired(true).setMaxLength(100))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('painel')\n        .setDescription('(Equipe) Mensagem com o status que se atualiza a cada 2 minutos')\n        .addStringOption((o) => o.setName('ip').setDescription('Endereço do servidor').setRequired(true).setMaxLength(100))\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde enviar (padrão: aqui)').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n    ),\n  async executar(i) {\n    const endereco = i.options.getString('ip').trim();\n    if (i.options.getSubcommand() === 'status') {\n      await i.deferReply();\n      const { e, arquivo } = await statusEmbed(i.guildId, endereco);\n      return i.editReply({ embeds: [e], files: arquivo ? [arquivo] : [] });\n    }\n    if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, tx('so_quem_tem_gerenciar'), 'erro');\n    const c = cfg(i.guildId);\n    if (c.paineis.length >= LIMITE_PAINEIS) return responder(i, tx('maximo_paineis_apague_mensagem', { limite: LIMITE_PAINEIS }), 'erro');\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    await i.deferReply({ flags: 64 });\n    const { e } = await statusEmbed(i.guildId, endereco);\n    const msg = await canal.send({ embeds: [e] }).catch(() => null);\n    if (!msg) return i.editReply(tx('consegui_enviar_nesse_canal'));\n    c.paineis.push({ endereco, canal: canal.id, msg: msg.id });\n    salvarAjustes();\n    return i.editReply(tx('painel_criado_ele_atualiza', { canal }));\n  },\n};\n\nexport default {\n  id: 'minecraft',\n  nome: tx('status_minecraft'),\n  comandos: [minecraft],\n  aoIniciar(client) {\n    atualizarPaineis(client).catch(() => {});\n    setInterval(() => atualizarPaineis(client).catch(() => {}), 2 * 60_000);\n  },\n  config: {\n    resumo(guild) {\n      const p = cfg(guild.id).paineis;\n      return [p.length ? p.map((x) => tx('em', { endereco: x.endereco, canal: x.canal })).join(' · ') : tx('nenhum_painel_minecraft_painel')];\n    },\n  },\n};\n",
  "src/modules/moderacao.js": "import { ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, checarHierarquia, lerDuracao, duracaoTexto, cortar, CORES, imagens } from '../core/util.js';\nimport { textos, visuais } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('moderacao', {\n  membro: ['Membro', 'campo'],\n  por: ['Por', 'campo'],\n  automatico: 'automático',\n  motivo: ['Motivo', 'campo'],\n  sem_motivo: 'Sem motivo',\n  consegui_confira_eu_tenho: 'Não consegui. Confira se eu tenho a permissão **{perm}** e se o meu cargo está acima do cargo dessa pessoa.',\n  banir_membros: 'Banir membros',\n  voce_foi_banido_motivo: '🔨 Você foi **banido(a)**.\\n**Motivo:** {motivo}',\n  banimento: ['🔨 Banimento', 'titulo'],\n  foi_banido_motivo: ['**{tag}** foi banido(a). Motivo: {motivo}', 'resposta'],\n  informe_id_usuario_so: ['Informe o ID do usuário (só números).', 'resposta'],\n  esse_id_esta_lista: ['Esse ID não está na lista de banidos.', 'resposta'],\n  por_2: '{motivo} (por {tag})',\n  banimento_removido: ['🔓 Banimento removido', 'titulo'],\n  foi_desbanido: ['**{tag}** foi desbanido(a).', 'resposta'],\n  esse_usuario_esta_servidor: ['Esse usuário não está no servidor.', 'resposta'],\n  expulsar_membros: 'Expulsar membros',\n  voce_foi_expulso_motivo: '👢 Você foi **expulso(a)**.\\n**Motivo:** {motivo}',\n  expulsao: ['👢 Expulsão', 'titulo'],\n  foi_expulso: ['**{tag}** foi expulso(a).', 'resposta'],\n  voce_esta_castigo_motivo: '🔇 Você está de **castigo** por {duracao}.\\n**Motivo:** {motivo}',\n  castigo: ['🔇 Castigo', 'titulo'],\n  duracao: ['Duração', 'campo'],\n  castigar_membros: 'Castigar membros',\n  administradores_podem_ficar_castigo: ['{erro} (Administradores não podem ficar de castigo.)', 'resposta'],\n  duracao_invalida_use_algo: ['Duração inválida. Use algo como **10m**, **1h** ou **2d** (no máximo 28d).', 'resposta'],\n  esta_castigo: ['**{tag}** está de castigo por **{duracao}**.', 'resposta'],\n  esse_membro_esta_castigo: ['Esse membro não está de castigo.', 'resposta'],\n  castigo_removido: ['🔊 Castigo removido', 'titulo'],\n  castigo_foi_removido: ['O castigo de **{tag}** foi removido.', 'resposta'],\n  advertir_bots: ['Não dá para advertir bots.', 'resposta'],\n  voce_recebeu_advertencia_total: '⚠️ Você recebeu uma **advertência** ({total} no total).\\n**Motivo:** {motivo}',\n  advertencia: ['⚠️ Advertência', 'titulo'],\n  total: ['Total', 'campo'],\n  chegou_advertencias: 'Chegou a {total} advertências',\n  voce_foi_banido_motivo_2: '🔨 Você foi **banido(a)**.\\n**Motivo:** {motivoAuto}',\n  banimento_automatico: ['🔨 Banimento automático', 'titulo'],\n  punicao_automatica_banimento: '\\nPunição automática: **banimento**.',\n  voce_foi_expulso_motivo_2: '👢 Você foi **expulso(a)**.\\n**Motivo:** {motivoAuto}',\n  expulsao_automatica: ['👢 Expulsão automática', 'titulo'],\n  punicao_automatica_expulsao: '\\nPunição automática: **expulsão**.',\n  punicao_automatica_castigo: '\\nPunição automática: **castigo** de {duracao}.',\n  consegui_aplicar_punicao_automatica: '\\n(Não consegui aplicar a punição automática: confira as minhas permissões.)',\n  recebeu_advertencia_total: ['**{tag}** recebeu uma advertência (**{total}** no total).{extra}', 'resposta'],\n  tem_advertencias: ['**{tag}** não tem advertências.', 'resposta'],\n  por_t_d: '**{numero}.** {motivo} · por <@{por}> · <t:{em}:d>',\n  advertencias: ['⚠️ Advertências de {tag}', 'titulo'],\n  todas_advertencias_foram_apagadas: ['Todas as advertências de **{tag}** foram apagadas.', 'resposta'],\n  so_tem_advertencia: ['**{tag}** só tem {total} advertência(s).', 'resposta'],\n  advertencia_removida_restam: ['Advertência {numero} de **{tag}** removida. Restam {total}.', 'resposta'],\n  apagar_mensagens_aqui: ['Não dá para apagar mensagens aqui.', 'resposta'],\n  achei_mensagens_apagar: 'Não achei mensagens para apagar.',\n  consegui_apagar_preciso_permissao: '❌ Não consegui apagar. Preciso da permissão **Gerenciar mensagens** neste canal.',\n  mensagens_apagadas: ['🧹 Mensagens apagadas', 'titulo'],\n  canal: ['Canal', 'campo'],\n  quantidade: ['Quantidade', 'campo'],\n  so: ['Só de', 'campo'],\n  discord_deixa_apagar_massa: ' (O Discord não deixa apagar em massa mensagens com mais de 14 dias.)',\n  mensagem_ns_apagada: '🧹 {total} mensagem(ns) apagada(s).{aviso}',\n  consegui_trancar_preciso_permissoes: 'Não consegui trancar. Preciso das permissões **Gerenciar canais** e **Gerenciar cargos** nesse canal.',\n  motivo_2: '\\n**Motivo:** {motivo}',\n  canal_trancado_pela_moderacao: ['🔒 Canal trancado pela moderação.{motivo}', 'descricao'],\n  canal_trancado: ['🔒 Canal trancado', 'titulo'],\n  foi_trancado: ['{canal} foi trancado.', 'resposta'],\n  consegui_liberar_preciso_permissoes: 'Não consegui liberar. Preciso das permissões **Gerenciar canais** e **Gerenciar cargos** nesse canal.',\n  canal_liberado: ['🔓 Canal liberado.', 'descricao'],\n  canal_liberado_2: ['🔓 Canal liberado', 'titulo'],\n  foi_liberado: ['{canal} foi liberado.', 'resposta'],\n  por_3: 'por {tag}',\n  consegui_mudar_modo_lento: 'Não consegui mudar o modo lento. Preciso da permissão **Gerenciar canais** nesse canal.',\n  modo_lento: ['🐢 Modo lento', 'titulo'],\n  intervalo: ['Intervalo', 'campo'],\n  desligado: 'desligado',\n  modo_lento_entre_mensagens: 'Modo lento de {canal}: **{duracao}** entre mensagens.',\n  modo_lento_desligado: 'Modo lento de {canal} desligado.',\n  punicoes_serao_registradas: 'As punições serão registradas em {canal}.',\n  registro_punicoes_desligado: 'Registro de punições desligado.',\n  membros_serao_avisados_dm: 'Os membros serão avisados na DM.',\n  aviso_dm_desligado: 'Aviso na DM desligado.',\n  duracao_invalida_ex_30m: ['Duração inválida (ex.: 30m, 1h, 1d; máximo 28d).', 'resposta'],\n  de: ' de {duracao}',\n  cada_advertencias: 'A cada **{limite}** advertências: **{acao}**{duracao}.',\n  punicao_automatica_desligada: 'Punição automática desligada.',\n  registro: 'Registro: {registro}',\n  sim: 'sim',\n  nao: 'não',\n  aviso_dm: 'Aviso na DM: {aviso_dm}',\n  cada_advertencias_2: 'a cada {limite} advertências → {acao}',\n  desligada: 'desligada',\n  punicao_automatica: 'Punição automática: {limite}',\n  moderacao: 'Moderação',\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('moderacao', {\n  dm: { nome: \"Aviso de punição na DM\", vars: ['servidor_icone'] },\n});\n\n/** Moderação: banir, expulsar, castigo, advertências, limpar mensagens, trancar canais. */\n\nconst advertencias = colecao('advertencias');\nconst PADRAO = { canalLog: null, avisarDm: true, limite: 0, acaoLimite: 'castigo', duracaoLimite: 3_600_000 };\nconst cfg = (guildId) => ajustes(guildId, 'moderacao', PADRAO);\nconst MAX_CASTIGO = 28 * 86_400_000;\n\n/**\n * Registra uma ação no canal de registro da moderação.\n * Com `alvo`, mostra Membro / Por / Motivo; sem alvo (ações em canais), só Por + `extra`.\n */\nasync function registrar(guild, { acao, cor = CORES.aviso, alvo, autor, motivo, extra = [] }) {\n  const canalId = cfg(guild.id).canalLog;\n  if (!canalId) return;\n  const canal = guild.channels.cache.get(canalId);\n  if (!canal?.isTextBased()) return;\n  const campos = [];\n  if (alvo) campos.push({ name: tx('membro'), value: `${alvo} (${alvo.tag ?? alvo.user?.tag ?? alvo.id})`, inline: true });\n  campos.push({ name: tx('por'), value: autor ? `${autor}` : tx('automatico'), inline: true });\n  campos.push(...extra);\n  if (motivo !== undefined) campos.push({ name: tx('motivo'), value: cortar(motivo || tx('sem_motivo'), 1000) });\n  const e = embed(guild.id).setColor(cor).setTitle(acao).addFields(campos).setTimestamp();\n  if (alvo?.displayAvatarURL) e.setThumbnail(alvo.displayAvatarURL());\n  await canal.send({ embeds: [e], allowedMentions: { parse: [] } }).catch(() => {});\n}\n\n/** Executa uma ação do Discord; se falhar, responde com uma mensagem clara. */\nasync function tentar(i, acao, erro) {\n  try {\n    await acao();\n    return true;\n  } catch (e) {\n    console.error('[moderação]', e.message);\n    await responder(i, erro, 'erro');\n    return false;\n  }\n}\n\nasync function avisarDm(user, guild, texto) {\n  if (!cfg(guild.id).avisarDm) return;\n  await user.send({ embeds: [vis(embed(guild.id).setTitle(guild.name).setDescription(texto), 'dm', imagens({ guild }))] }).catch(() => {});\n}\n\nconst motivoDe = (i) => i.options.getString('motivo') || tx('sem_motivo');\nconst SEM_PERMISSAO = (perm) => tx('consegui_confira_eu_tenho', { perm });\nconst opMotivo = (o, obrigatorio = false) => o.setName('motivo').setDescription('Motivo').setRequired(obrigatorio).setMaxLength(500);\n\n// ---------------- comandos ----------------\nconst banir = {\n  data: new SlashCommandBuilder()\n    .setName('banir')\n    .setDescription('Bane um membro do servidor')\n    .setDefaultMemberPermissions(PermissionFlagsBits.BanMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('Quem banir').setRequired(true))\n    .addStringOption((o) => opMotivo(o))\n    .addIntegerOption((o) =>\n      o.setName('apagar').setDescription('Apagar mensagens recentes dele').addChoices(\n        { name: 'Não apagar', value: 0 },\n        { name: 'Última hora', value: 3600 },\n        { name: 'Últimas 24 horas', value: 86400 },\n        { name: 'Últimos 7 dias', value: 604800 },\n      )\n    ),\n  async executar(i) {\n    const user = i.options.getUser('usuario');\n    const membro = i.options.getMember('usuario');\n    const motivo = motivoDe(i);\n    if (membro) {\n      const erro = checarHierarquia(i.member, membro, i.guild.members.me);\n      if (erro) return responder(i, erro, 'erro');\n      if (!membro.bannable) return responder(i, SEM_PERMISSAO(tx('banir_membros')), 'erro');\n    } else if (!i.guild.members.me.permissions.has(PermissionFlagsBits.BanMembers)) {\n      return responder(i, SEM_PERMISSAO(tx('banir_membros')), 'erro');\n    }\n    if (membro) await avisarDm(user, i.guild, tx('voce_foi_banido_motivo', { motivo }));\n    const ok = await tentar(\n      i,\n      () => i.guild.members.ban(user, { reason: `${motivo} (por ${i.user.tag})`, deleteMessageSeconds: i.options.getInteger('apagar') ?? 0 }),\n      SEM_PERMISSAO(tx('banir_membros'))\n    );\n    if (!ok) return;\n    await registrar(i.guild, { acao: tx('banimento'), cor: CORES.erro, alvo: user, autor: i.user, motivo });\n    return responder(i, tx('foi_banido_motivo', { tag: user.tag, motivo }), 'sucesso');\n  },\n};\n\nconst desbanir = {\n  data: new SlashCommandBuilder()\n    .setName('desbanir')\n    .setDescription('Remove o banimento de alguém')\n    .setDefaultMemberPermissions(PermissionFlagsBits.BanMembers)\n    .addStringOption((o) => o.setName('id').setDescription('ID do usuário banido').setRequired(true).setMaxLength(22))\n    .addStringOption((o) => opMotivo(o)),\n  async executar(i) {\n    const id = i.options.getString('id').replace(/\\D/g, '');\n    const motivo = motivoDe(i);\n    if (!id) return responder(i, tx('informe_id_usuario_so'), 'erro');\n    const ban = await i.guild.bans.fetch(id).catch(() => null);\n    if (!ban) return responder(i, tx('esse_id_esta_lista'), 'erro');\n    const ok = await tentar(i, () => i.guild.bans.remove(id, tx('por_2', { motivo, tag: i.user.tag })), SEM_PERMISSAO(tx('banir_membros')));\n    if (!ok) return;\n    await registrar(i.guild, { acao: tx('banimento_removido'), cor: CORES.sucesso, alvo: ban.user, autor: i.user, motivo });\n    return responder(i, tx('foi_desbanido', { tag: ban.user.tag }), 'sucesso');\n  },\n};\n\nconst expulsar = {\n  data: new SlashCommandBuilder()\n    .setName('expulsar')\n    .setDescription('Expulsa um membro (ele pode voltar com convite)')\n    .setDefaultMemberPermissions(PermissionFlagsBits.KickMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('Quem expulsar').setRequired(true))\n    .addStringOption((o) => opMotivo(o)),\n  async executar(i) {\n    const membro = i.options.getMember('usuario');\n    if (!membro) return responder(i, tx('esse_usuario_esta_servidor'), 'erro');\n    const erro = checarHierarquia(i.member, membro, i.guild.members.me);\n    if (erro) return responder(i, erro, 'erro');\n    if (!membro.kickable) return responder(i, SEM_PERMISSAO(tx('expulsar_membros')), 'erro');\n    const motivo = motivoDe(i);\n    await avisarDm(membro.user, i.guild, tx('voce_foi_expulso_motivo', { motivo }));\n    const ok = await tentar(i, () => membro.kick(`${motivo} (por ${i.user.tag})`), SEM_PERMISSAO(tx('expulsar_membros')));\n    if (!ok) return;\n    await registrar(i.guild, { acao: tx('expulsao'), cor: CORES.erro, alvo: membro.user, autor: i.user, motivo });\n    return responder(i, tx('foi_expulso', { tag: membro.user.tag }), 'sucesso');\n  },\n};\n\nasync function aplicarCastigo(i, membro, ms, motivo, autor = i.user) {\n  await membro.timeout(ms, `${motivo} (por ${i.user.tag})`);\n  await avisarDm(membro.user, i.guild, tx('voce_esta_castigo_motivo', { duracao: duracaoTexto(ms), motivo }));\n  await registrar(i.guild, {\n    acao: tx('castigo'),\n    alvo: membro.user,\n    autor,\n    motivo,\n    extra: [{ name: tx('duracao'), value: duracaoTexto(ms), inline: true }],\n  });\n}\n\nconst castigo = {\n  data: new SlashCommandBuilder()\n    .setName('castigo')\n    .setDescription('Deixa um membro sem falar por um tempo')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('Quem colocar de castigo').setRequired(true))\n    .addStringOption((o) => o.setName('duracao').setDescription('Ex.: 10m, 1h, 2d (máximo 28d)').setRequired(true).setMaxLength(20))\n    .addStringOption((o) => opMotivo(o)),\n  async executar(i) {\n    const membro = i.options.getMember('usuario');\n    if (!membro) return responder(i, tx('esse_usuario_esta_servidor'), 'erro');\n    const erro = checarHierarquia(i.member, membro, i.guild.members.me);\n    if (erro) return responder(i, erro, 'erro');\n    if (!membro.moderatable) return responder(i, tx('administradores_podem_ficar_castigo', { erro: SEM_PERMISSAO(tx('castigar_membros')) }), 'erro');\n    const ms = lerDuracao(i.options.getString('duracao'));\n    if (!ms || ms > MAX_CASTIGO) return responder(i, tx('duracao_invalida_use_algo'), 'erro');\n    const motivo = motivoDe(i);\n    const ok = await tentar(i, () => aplicarCastigo(i, membro, ms, motivo), SEM_PERMISSAO(tx('castigar_membros')));\n    if (!ok) return;\n    return responder(i, tx('esta_castigo', { tag: membro.user.tag, duracao: duracaoTexto(ms) }), 'sucesso');\n  },\n};\n\nconst removerCastigo = {\n  data: new SlashCommandBuilder()\n    .setName('removercastigo')\n    .setDescription('Tira o castigo de um membro')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('Quem liberar').setRequired(true))\n    .addStringOption((o) => opMotivo(o)),\n  async executar(i) {\n    const membro = i.options.getMember('usuario');\n    if (!membro) return responder(i, tx('esse_usuario_esta_servidor'), 'erro');\n    if (!membro.isCommunicationDisabled()) return responder(i, tx('esse_membro_esta_castigo'), 'aviso');\n    const motivo = motivoDe(i);\n    const ok = await tentar(i, () => membro.timeout(null, `${motivo} (por ${i.user.tag})`), SEM_PERMISSAO(tx('castigar_membros')));\n    if (!ok) return;\n    await registrar(i.guild, { acao: tx('castigo_removido'), cor: CORES.sucesso, alvo: membro.user, autor: i.user, motivo });\n    return responder(i, tx('castigo_foi_removido', { tag: membro.user.tag }), 'sucesso');\n  },\n};\n\nconst advertir = {\n  data: new SlashCommandBuilder()\n    .setName('advertir')\n    .setDescription('Dá uma advertência a um membro')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('Quem advertir').setRequired(true))\n    .addStringOption((o) => opMotivo(o, true)),\n  async executar(i) {\n    const membro = i.options.getMember('usuario');\n    if (!membro) return responder(i, tx('esse_usuario_esta_servidor'), 'erro');\n    if (membro.user.bot) return responder(i, tx('advertir_bots'), 'erro');\n    const erro = checarHierarquia(i.member, membro, i.guild.members.me);\n    if (erro) return responder(i, erro, 'erro');\n    const motivo = motivoDe(i);\n\n    const g = advertencias.de(i.guildId);\n    g[membro.id] ??= [];\n    g[membro.id].push({ motivo, por: i.user.id, em: Date.now() });\n    advertencias.salvar();\n    const total = g[membro.id].length;\n\n    await avisarDm(membro.user, i.guild, tx('voce_recebeu_advertencia_total', { total, motivo }));\n    await registrar(i.guild, { acao: tx('advertencia'), alvo: membro.user, autor: i.user, motivo, extra: [{ name: tx('total'), value: String(total), inline: true }] });\n\n    // punição automática ao chegar no limite\n    const c = cfg(i.guildId);\n    let extra = '';\n    if (c.limite > 0 && total >= c.limite && total % c.limite === 0) {\n      const motivoAuto = tx('chegou_advertencias', { total });\n      try {\n        if (c.acaoLimite === 'banir') {\n          await avisarDm(membro.user, i.guild, tx('voce_foi_banido_motivo_2', { motivoAuto }));\n          await i.guild.members.ban(membro, { reason: motivoAuto });\n          await registrar(i.guild, { acao: tx('banimento_automatico'), cor: CORES.erro, alvo: membro.user, autor: null, motivo: motivoAuto });\n          extra = tx('punicao_automatica_banimento');\n        } else if (c.acaoLimite === 'expulsar') {\n          await avisarDm(membro.user, i.guild, tx('voce_foi_expulso_motivo_2', { motivoAuto }));\n          await membro.kick(motivoAuto);\n          await registrar(i.guild, { acao: tx('expulsao_automatica'), cor: CORES.erro, alvo: membro.user, autor: null, motivo: motivoAuto });\n          extra = tx('punicao_automatica_expulsao');\n        } else {\n          await aplicarCastigo(i, membro, c.duracaoLimite, motivoAuto, null);\n          extra = tx('punicao_automatica_castigo', { duracao: duracaoTexto(c.duracaoLimite) });\n        }\n      } catch {\n        extra = tx('consegui_aplicar_punicao_automatica');\n      }\n    }\n    return responder(i, tx('recebeu_advertencia_total', { tag: membro.user.tag, total, extra }), 'sucesso');\n  },\n};\n\nconst verAdvertencias = {\n  data: new SlashCommandBuilder()\n    .setName('advertencias')\n    .setDescription('Mostra as advertências de um membro')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('De quem').setRequired(true)),\n  async executar(i) {\n    const user = i.options.getUser('usuario');\n    const lista = advertencias.ler(i.guildId, user.id) ?? [];\n    if (!lista.length) return responder(i, tx('tem_advertencias', { tag: user.tag }), 'info');\n    const linhas = lista.map((a, n) => tx('por_t_d', { numero: n + 1, motivo: cortar(a.motivo, 120), por: a.por, em: Math.floor(a.em / 1000) }));\n    return i.reply({\n      embeds: [embed(i.guildId).setTitle(tx('advertencias', { tag: user.tag })).setDescription(linhas.join('\\n').slice(0, 4000)).setThumbnail(user.displayAvatarURL())],\n      flags: 64,\n    });\n  },\n};\n\nconst removerAdvertencia = {\n  data: new SlashCommandBuilder()\n    .setName('removeradvertencia')\n    .setDescription('Remove advertências de um membro')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('De quem').setRequired(true))\n    .addIntegerOption((o) => o.setName('numero').setDescription('Número da advertência (0 = apagar todas)').setRequired(true).setMinValue(0)),\n  async executar(i) {\n    const user = i.options.getUser('usuario');\n    const n = i.options.getInteger('numero');\n    const lista = advertencias.ler(i.guildId, user.id) ?? [];\n    if (!lista.length) return responder(i, tx('tem_advertencias', { tag: user.tag }), 'info');\n    if (n === 0) {\n      advertencias.apagar(i.guildId, user.id);\n      return responder(i, tx('todas_advertencias_foram_apagadas', { tag: user.tag }), 'sucesso');\n    }\n    if (n > lista.length) return responder(i, tx('so_tem_advertencia', { tag: user.tag, total: lista.length }), 'erro');\n    lista.splice(n - 1, 1);\n    advertencias.salvar();\n    return responder(i, tx('advertencia_removida_restam', { numero: n, tag: user.tag, total: lista.length }), 'sucesso');\n  },\n};\n\nconst limpar = {\n  data: new SlashCommandBuilder()\n    .setName('limpar')\n    .setDescription('Apaga mensagens recentes do canal')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageMessages)\n    .addIntegerOption((o) => o.setName('quantidade').setDescription('De 1 a 100').setRequired(true).setMinValue(1).setMaxValue(100))\n    .addUserOption((o) => o.setName('usuario').setDescription('Só as mensagens desta pessoa')),\n  async executar(i) {\n    if (!i.channel?.bulkDelete) return responder(i, tx('apagar_mensagens_aqui'), 'erro');\n    await i.deferReply({ flags: 64 });\n    const qtd = i.options.getInteger('quantidade');\n    const alvo = i.options.getUser('usuario');\n    let msgs = await i.channel.messages.fetch({ limit: 100 });\n    msgs = msgs.filter((m) => !m.pinned && (!alvo || m.author.id === alvo.id)); // mensagens fixadas ficam\n    msgs = [...msgs.values()].slice(0, qtd);\n    if (!msgs.length) return i.editReply(tx('achei_mensagens_apagar'));\n    const apagadas = await i.channel.bulkDelete(msgs, true).catch(() => null);\n    if (!apagadas) return i.editReply(tx('consegui_apagar_preciso_permissao'));\n    const n = apagadas.size;\n    await registrar(i.guild, {\n      acao: tx('mensagens_apagadas'),\n      autor: i.user,\n      extra: [\n        { name: tx('canal'), value: `${i.channel}`, inline: true },\n        { name: tx('quantidade'), value: String(n), inline: true },\n        ...(alvo ? [{ name: tx('so'), value: `${alvo} (${alvo.tag})`, inline: true }] : []),\n      ],\n    });\n    return i.editReply(tx('mensagem_ns_apagada', { total: n, aviso: n < msgs.length ? tx('discord_deixa_apagar_massa') : '' }));\n  },\n};\n\nconst opCanal = (o) => o.setName('canal').setDescription('Padrão: este canal').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement);\n\nconst trancar = {\n  data: new SlashCommandBuilder()\n    .setName('trancar')\n    .setDescription('Impede os membros de falar no canal')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageChannels)\n    .addChannelOption(opCanal)\n    .addStringOption((o) => opMotivo(o)),\n  async executar(i) {\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    const ok = await tentar(\n      i,\n      () => canal.permissionOverwrites.edit(i.guild.roles.everyone, { SendMessages: false, SendMessagesInThreads: false, CreatePublicThreads: false }),\n      tx('consegui_trancar_preciso_permissoes')\n    );\n    if (!ok) return;\n    const motivo = motivoDe(i);\n    await canal.send({ embeds: [embed(i.guildId).setDescription(tx('canal_trancado_pela_moderacao', { motivo: motivo !== tx('sem_motivo') ? tx('motivo_2', { motivo }) : '' }))] }).catch(() => {});\n    await registrar(i.guild, { acao: tx('canal_trancado'), autor: i.user, motivo, extra: [{ name: tx('canal'), value: `${canal}`, inline: true }] });\n    return responder(i, tx('foi_trancado', { canal }), 'sucesso');\n  },\n};\n\nconst destrancar = {\n  data: new SlashCommandBuilder()\n    .setName('destrancar')\n    .setDescription('Libera o canal de novo')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageChannels)\n    .addChannelOption(opCanal),\n  async executar(i) {\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    const ok = await tentar(\n      i,\n      () => canal.permissionOverwrites.edit(i.guild.roles.everyone, { SendMessages: null, SendMessagesInThreads: null, CreatePublicThreads: null }),\n      tx('consegui_liberar_preciso_permissoes')\n    );\n    if (!ok) return;\n    await canal.send({ embeds: [embed(i.guildId).setDescription(tx('canal_liberado'))] }).catch(() => {});\n    await registrar(i.guild, { acao: tx('canal_liberado_2'), cor: CORES.sucesso, autor: i.user, extra: [{ name: tx('canal'), value: `${canal}`, inline: true }] });\n    return responder(i, tx('foi_liberado', { canal }), 'sucesso');\n  },\n};\n\nconst lentidao = {\n  data: new SlashCommandBuilder()\n    .setName('lentidao')\n    .setDescription('Define o modo lento do canal')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageChannels)\n    .addIntegerOption((o) => o.setName('segundos').setDescription('0 desliga (máximo 21600 = 6h)').setRequired(true).setMinValue(0).setMaxValue(21600))\n    .addChannelOption(opCanal),\n  async executar(i) {\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    const s = i.options.getInteger('segundos');\n    const ok = await tentar(i, () => canal.setRateLimitPerUser(s, tx('por_3', { tag: i.user.tag })), tx('consegui_mudar_modo_lento'));\n    if (!ok) return;\n    await registrar(i.guild, {\n      acao: tx('modo_lento'),\n      autor: i.user,\n      extra: [\n        { name: tx('canal'), value: `${canal}`, inline: true },\n        { name: tx('intervalo'), value: s ? duracaoTexto(s * 1000) : tx('desligado'), inline: true },\n      ],\n    });\n    return responder(i, s ? tx('modo_lento_entre_mensagens', { canal, duracao: duracaoTexto(s * 1000) }) : tx('modo_lento_desligado', { canal }), 'sucesso');\n  },\n};\n\n// ---------------- /config moderacao ----------------\nconst config = {\n  grupo: 'moderacao',\n  montar: (g) =>\n    g\n      .setDescription('Moderação: canal de registro, aviso na DM e punição automática')\n      .addSubcommand((s) =>\n        s.setName('canal').setDescription('Canal onde as punições ficam registradas').addChannelOption((o) =>\n          o.setName('canal').setDescription('Deixe vazio para desligar').addChannelTypes(ChannelType.GuildText)\n        )\n      )\n      .addSubcommand((s) =>\n        s.setName('dm').setDescription('Avisar o membro na DM quando for punido').addBooleanOption((o) => o.setName('ativar').setDescription('Ligar ou desligar').setRequired(true))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('limite')\n          .setDescription('Punição automática ao juntar advertências')\n          .addIntegerOption((o) => o.setName('advertencias').setDescription('Quantas advertências (0 desliga)').setRequired(true).setMinValue(0).setMaxValue(20))\n          .addStringOption((o) =>\n            o.setName('acao').setDescription('O que fazer').addChoices(\n              { name: 'Castigo', value: 'castigo' },\n              { name: 'Expulsar', value: 'expulsar' },\n              { name: 'Banir', value: 'banir' },\n            )\n          )\n          .addStringOption((o) => o.setName('duracao').setDescription('Duração do castigo, ex.: 1h (padrão 1h)').setMaxLength(20))\n      ),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    if (sub === 'canal') {\n      const canal = i.options.getChannel('canal');\n      c.canalLog = canal?.id ?? null;\n      salvarAjustes();\n      return responder(i, canal ? tx('punicoes_serao_registradas', { canal }) : tx('registro_punicoes_desligado'), 'sucesso');\n    }\n    if (sub === 'dm') {\n      c.avisarDm = i.options.getBoolean('ativar');\n      salvarAjustes();\n      return responder(i, c.avisarDm ? tx('membros_serao_avisados_dm') : tx('aviso_dm_desligado'), 'sucesso');\n    }\n    if (sub === 'limite') {\n      c.limite = i.options.getInteger('advertencias');\n      c.acaoLimite = i.options.getString('acao') ?? c.acaoLimite;\n      const d = i.options.getString('duracao');\n      if (d) {\n        const ms = lerDuracao(d);\n        if (!ms || ms > MAX_CASTIGO) return responder(i, tx('duracao_invalida_ex_30m'), 'erro');\n        c.duracaoLimite = ms;\n      }\n      salvarAjustes();\n      return responder(\n        i,\n        c.limite ? tx('cada_advertencias', { limite: c.limite, acao: c.acaoLimite, duracao: c.acaoLimite === 'castigo' ? tx('de', { duracao: duracaoTexto(c.duracaoLimite) }) : '' }) : tx('punicao_automatica_desligada'),\n        'sucesso'\n      );\n    }\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    return [\n      tx('registro', { registro: c.canalLog ? `<#${c.canalLog}>` : tx('desligado') }),\n      tx('aviso_dm', { aviso_dm: c.avisarDm ? tx('sim') : tx('nao') }),\n      tx('punicao_automatica', { limite: c.limite ? tx('cada_advertencias_2', { limite: c.limite, acao: c.acaoLimite }) : tx('desligada') }),\n    ];\n  },\n};\n\nexport default {\n  id: 'moderacao',\n  nome: tx('moderacao'),\n  comandos: [banir, desbanir, expulsar, castigo, removerCastigo, advertir, verAdvertencias, removerAdvertencia, limpar, trancar, destrancar, lentidao],\n  permissoes: [\n    PermissionFlagsBits.BanMembers,\n    PermissionFlagsBits.KickMembers,\n    PermissionFlagsBits.ModerateMembers,\n    PermissionFlagsBits.ManageMessages,\n    PermissionFlagsBits.ManageChannels,\n    PermissionFlagsBits.ManageRoles,\n  ],\n  config,\n};\n",
  "src/modules/niveis.js": "import { ChannelType, GatewayIntentBits, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, preencher, barra, fmt, sorteio, foiRemovida, imagens } from '../core/util.js';\nimport { textos, modeloOu, visuais } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('niveis', {\n  msg_nivel_padrao: '🎉 {usuario} subiu para o **nível {nivel}**!',\n  nivel: ['Nível', 'campo'],\n  posicao: ['Posição', 'campo'],\n  xp_total: ['XP total', 'campo'],\n  progresso_nivel: ['Progresso para o nível {nivel}', 'campo'],\n  xp: '{barra}  {atual}/{precisa} XP',\n  ninguem_ganhou_xp_ainda: ['Ninguém ganhou XP ainda. Converse no chat!', 'resposta'],\n  nivel_xp: '{medalhas} <@{usuario}> · nível **{nivel}** · {xp} XP',\n  ranking: ['🏆 Ranking de {servidor}', 'titulo'],\n  sua_posicao: 'Sua posição: #{posicao}',\n  voce_ainda_tem_xp: 'Você ainda não tem XP',\n  bots_tem_xp: ['Bots não têm XP.', 'resposta'],\n  agora_tem_xp_nivel: ['**{tag}** agora tem **{xp} XP** (nível {nivel}).', 'resposta'],\n  ganho_xp_ligado: 'Ganho de XP ligado.',\n  ganho_xp_desligado: 'Ganho de XP desligado.',\n  em: 'em {canal}',\n  mesmo_canal_mensagem: 'no mesmo canal da mensagem',\n  aviso_nivel: 'Aviso de nível {canal}.',\n  esse_cargo_pode_ser: ['Esse cargo não pode ser dado.', 'resposta'],\n  suba_meu_cargo_acima: ' ⚠️ Suba o meu cargo acima dele para funcionar.',\n  chegar_nivel_membro_ganha: 'Ao chegar no nível **{nivel}**, o membro ganha {cargo}.{aviso}',\n  recompensa_nivel_removida: 'Recompensa do nível {nivel} removida.',\n  minimo_pode_ser_maior: ['O mínimo não pode ser maior que o máximo.', 'resposta'],\n  cada_mensagem_vale_xp: 'Cada mensagem vale de **{min} a {max} XP**, uma vez a cada **{intervalo}s**.',\n  volta_dar_xp: '{canal} volta a dar XP.',\n  mais_xp: '{canal} não dá mais XP.',\n  ligado_xp_cada: 'ligado ({xpMin}–{xpMax} XP a cada {intervalo}s)',\n  desligado: 'desligado',\n  ganho_xp: 'Ganho de XP: {xpMin}',\n  mesmo_canal: 'no mesmo canal',\n  aviso: 'Aviso: {canal}',\n  nenhuma: 'nenhuma',\n  recompensas: 'Recompensas: {recompensas}',\n  niveis: 'Níveis',\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('niveis', {\n  rank: { nome: \"/rank (nível do membro)\", vars: ['avatar', 'servidor_icone'], miniatura: \"{avatar}\" },\n});\n\n/**\n * Níveis: membros ganham XP conversando (com intervalo para não valer flood),\n * sobem de nível, recebem cargos de recompensa e aparecem no ranking.\n */\n\nconst xpDb = colecao('niveis');\nconst PADRAO = {\n  ativo: true,\n  xpMin: 15,\n  xpMax: 25,\n  intervalo: 60, // segundos entre mensagens que valem XP\n  canal: null, // null = avisa no mesmo canal\n  mensagem: null,\n  recompensas: {}, // nivel -> cargoId\n  ignorados: [],\n};\nconst cfg = (guildId) => ajustes(guildId, 'niveis', PADRAO);\nconst msgNivel = (c) => modeloOu(c.mensagem, '🎉 {usuario} subiu para o **nível {nivel}**!', tx('msg_nivel_padrao'));\n\n/** XP para passar do nível n para o n+1. */\nexport const xpDoNivel = (n) => 5 * n * n + 50 * n + 100;\n\nfunction nivelDe(xpTotal) {\n  let nivel = 0;\n  let resto = xpTotal;\n  while (resto >= xpDoNivel(nivel)) {\n    resto -= xpDoNivel(nivel);\n    nivel++;\n  }\n  return { nivel, atual: resto, precisa: xpDoNivel(nivel) };\n}\n\nfunction ranking(guildId) {\n  const g = xpDb.ler(guildId) ?? {};\n  return Object.entries(g)\n    .filter(([, d]) => d.xp > 0)\n    .sort((a, b) => b[1].xp - a[1].xp);\n}\n\nasync function darRecompensas(member, nivel) {\n  const c = cfg(member.guild.id);\n  const cargos = Object.entries(c.recompensas)\n    .filter(([n]) => Number(n) <= nivel)\n    .map(([, id]) => id)\n    .filter((id) => !member.roles.cache.has(id) && member.guild.roles.cache.get(id)?.editable);\n  if (cargos.length) await member.roles.add(cargos, `Recompensa de nível ${nivel}`).catch(() => {});\n}\n\nasync function aoMensagem(msg) {\n  if (!msg.inGuild() || msg.author.bot || !msg.member) return;\n  if (foiRemovida(msg.id)) return; // apagada pelo AutoMod: não vale XP\n  const c = cfg(msg.guildId);\n  if (!c.ativo || c.ignorados.includes(msg.channelId)) return;\n\n  const d = xpDb.de(msg.guildId, msg.author.id);\n  const agora = Date.now();\n  if (d.ultima && agora - d.ultima < c.intervalo * 1000) return;\n  d.ultima = agora;\n  const antes = nivelDe(d.xp ?? 0).nivel;\n  d.xp = (d.xp ?? 0) + sorteio(c.xpMin, c.xpMax);\n  xpDb.salvar();\n\n  const depois = nivelDe(d.xp).nivel;\n  if (depois <= antes) return;\n  await darRecompensas(msg.member, depois);\n  const canal = (c.canal && msg.guild.channels.cache.get(c.canal)) || msg.channel;\n  const texto = preencher(msgNivel(c), { usuario: `${msg.author}`, nome: msg.member.displayName, nivel: depois, servidor: msg.guild.name });\n  await canal.send({ content: texto, allowedMentions: { users: [msg.author.id] } }).catch(() => {});\n}\n\n// ---------------- comandos ----------------\nconst rank = {\n  data: new SlashCommandBuilder()\n    .setName('rank')\n    .setDescription('Mostra o seu nível e XP')\n    .addUserOption((o) => o.setName('usuario').setDescription('Ver de outra pessoa')),\n  async executar(i) {\n    const user = i.options.getUser('usuario') ?? i.user;\n    const xp = xpDb.ler(i.guildId, user.id)?.xp ?? 0;\n    const { nivel, atual, precisa } = nivelDe(xp);\n    const pos = ranking(i.guildId).findIndex(([id]) => id === user.id) + 1;\n    await i.reply({\n      embeds: [\n        vis(\n          embed(i.guildId)\n            .setAuthor({ name: user.tag, iconURL: user.displayAvatarURL() })\n            .setThumbnail(user.displayAvatarURL({ size: 256 }))\n            .addFields(\n              { name: tx('nivel'), value: `**${nivel}**`, inline: true },\n              { name: tx('posicao'), value: pos ? `#${pos}` : '—', inline: true },\n              { name: tx('xp_total'), value: fmt(xp), inline: true },\n              { name: tx('progresso_nivel', { nivel: nivel + 1 }), value: tx('xp', { barra: barra(atual / precisa, 14), atual: fmt(atual), precisa: fmt(precisa) }) },\n            ),\n          'rank',\n          imagens({ user, guild: i.guild }),\n        ),\n      ],\n    });\n  },\n};\n\nconst top = {\n  data: new SlashCommandBuilder().setName('top').setDescription('Ranking de XP do servidor'),\n  async executar(i) {\n    const lista = ranking(i.guildId).slice(0, 10);\n    if (!lista.length) return responder(i, tx('ninguem_ganhou_xp_ainda'), 'info');\n    const medalhas = ['🥇', '🥈', '🥉'];\n    const linhas = lista.map(([id, d], n) => tx('nivel_xp', { medalhas: medalhas[n] ?? `**${n + 1}.**`, usuario: id, nivel: nivelDe(d.xp).nivel, xp: fmt(d.xp) }));\n    const minha = ranking(i.guildId).findIndex(([id]) => id === i.user.id) + 1;\n    await i.reply({\n      embeds: [\n        embed(i.guildId)\n          .setTitle(tx('ranking', { servidor: i.guild.name }))\n          .setDescription(linhas.join('\\n'))\n          .setFooter({ text: minha ? tx('sua_posicao', { posicao: minha }) : tx('voce_ainda_tem_xp') }),\n      ],\n      allowedMentions: { parse: [] },\n    });\n  },\n};\n\nconst xpAdmin = {\n  data: new SlashCommandBuilder()\n    .setName('xp')\n    .setDescription('Gerencia o XP dos membros')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('dar')\n        .setDescription('Dá XP a um membro')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addIntegerOption((o) => o.setName('quantidade').setDescription('Quanto XP').setRequired(true).setMinValue(1).setMaxValue(1_000_000))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('tirar')\n        .setDescription('Tira XP de um membro')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addIntegerOption((o) => o.setName('quantidade').setDescription('Quanto XP').setRequired(true).setMinValue(1).setMaxValue(1_000_000))\n    )\n    .addSubcommand((s) => s.setName('zerar').setDescription('Zera o XP de um membro').addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    const user = i.options.getUser('usuario');\n    if (user.bot) return responder(i, tx('bots_tem_xp'), 'erro');\n    const d = xpDb.de(i.guildId, user.id);\n    const q = i.options.getInteger('quantidade') ?? 0;\n    if (sub === 'dar') d.xp = (d.xp ?? 0) + q;\n    if (sub === 'tirar') d.xp = Math.max(0, (d.xp ?? 0) - q);\n    if (sub === 'zerar') d.xp = 0;\n    xpDb.salvar();\n    const { nivel } = nivelDe(d.xp);\n    const membro = i.options.getMember('usuario');\n    if (membro) await darRecompensas(membro, nivel);\n    return responder(i, tx('agora_tem_xp_nivel', { tag: user.tag, xp: fmt(d.xp), nivel }), 'sucesso');\n  },\n};\n\n// ---------------- /config niveis ----------------\nconst config = {\n  grupo: 'niveis',\n  montar: (g) =>\n    g\n      .setDescription('Sistema de níveis e XP')\n      .addSubcommand((s) => s.setName('ativar').setDescription('Liga ou desliga o ganho de XP').addBooleanOption((o) => o.setName('ligado').setDescription('Ligado?').setRequired(true)))\n      .addSubcommand((s) =>\n        s\n          .setName('aviso')\n          .setDescription('Onde e como avisar quando alguém sobe de nível')\n          .addChannelOption((o) => o.setName('canal').setDescription('Vazio = no mesmo canal da mensagem').addChannelTypes(ChannelType.GuildText))\n          .addStringOption((o) => o.setName('mensagem').setDescription('Variáveis: {usuario} {nome} {nivel} {servidor}').setMaxLength(500))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('recompensa')\n          .setDescription('Cargo ganho ao chegar num nível (sem cargo = remove a recompensa)')\n          .addIntegerOption((o) => o.setName('nivel').setDescription('Nível').setRequired(true).setMinValue(1).setMaxValue(500))\n          .addRoleOption((o) => o.setName('cargo').setDescription('Cargo'))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('xp')\n          .setDescription('XP por mensagem e intervalo')\n          .addIntegerOption((o) => o.setName('minimo').setDescription('XP mínimo por mensagem').setRequired(true).setMinValue(1).setMaxValue(500))\n          .addIntegerOption((o) => o.setName('maximo').setDescription('XP máximo por mensagem').setRequired(true).setMinValue(1).setMaxValue(500))\n          .addIntegerOption((o) => o.setName('intervalo').setDescription('Segundos entre mensagens que valem XP (padrão 60)').setMinValue(0).setMaxValue(3600))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('ignorar-canal')\n          .setDescription('Canal onde não se ganha XP (usar de novo remove)')\n          .addChannelOption((o) => o.setName('canal').setDescription('Canal').setRequired(true).addChannelTypes(ChannelType.GuildText))\n      ),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    let msg;\n    if (sub === 'ativar') {\n      c.ativo = i.options.getBoolean('ligado');\n      msg = c.ativo ? tx('ganho_xp_ligado') : tx('ganho_xp_desligado');\n    } else if (sub === 'aviso') {\n      const canal = i.options.getChannel('canal');\n      c.canal = canal?.id ?? null;\n      const m = i.options.getString('mensagem');\n      if (m) c.mensagem = m;\n      msg = tx('aviso_nivel', { canal: canal ? tx('em', { canal }) : tx('mesmo_canal_mensagem') });\n    } else if (sub === 'recompensa') {\n      const n = i.options.getInteger('nivel');\n      const r = i.options.getRole('cargo');\n      if (r) {\n        if (r.managed || r.id === i.guildId) return responder(i, tx('esse_cargo_pode_ser'), 'erro');\n        c.recompensas[n] = r.id;\n        msg = tx('chegar_nivel_membro_ganha', { nivel: n, cargo: r, aviso: r.editable ? '' : tx('suba_meu_cargo_acima') });\n      } else {\n        delete c.recompensas[n];\n        msg = tx('recompensa_nivel_removida', { nivel: n });\n      }\n    } else if (sub === 'xp') {\n      const min = i.options.getInteger('minimo');\n      const max = i.options.getInteger('maximo');\n      if (min > max) return responder(i, tx('minimo_pode_ser_maior'), 'erro');\n      c.xpMin = min;\n      c.xpMax = max;\n      const iv = i.options.getInteger('intervalo');\n      if (iv !== null) c.intervalo = iv;\n      msg = tx('cada_mensagem_vale_xp', { min, max, intervalo: c.intervalo });\n    } else if (sub === 'ignorar-canal') {\n      const ch = i.options.getChannel('canal');\n      const idx = c.ignorados.indexOf(ch.id);\n      if (idx >= 0) c.ignorados.splice(idx, 1);\n      else c.ignorados.push(ch.id);\n      msg = idx >= 0 ? tx('volta_dar_xp', { canal: ch }) : tx('mais_xp', { canal: ch });\n    }\n    salvarAjustes();\n    return responder(i, msg, 'sucesso');\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    const rec = Object.entries(c.recompensas).sort((a, b) => a[0] - b[0]).map(([n, r]) => `${n}: <@&${r}>`);\n    return [\n      tx('ganho_xp', { xpMin: c.ativo ? tx('ligado_xp_cada', { xpMin: c.xpMin, xpMax: c.xpMax, intervalo: c.intervalo }) : tx('desligado') }),\n      tx('aviso', { canal: c.canal ? `<#${c.canal}>` : tx('mesmo_canal') }),\n      tx('recompensas', { recompensas: rec.length ? rec.join(' · ') : tx('nenhuma') }),\n    ];\n  },\n};\n\nexport default {\n  id: 'niveis',\n  nome: tx('niveis'),\n  intents: [GatewayIntentBits.GuildMessages],\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  comandos: [rank, top, xpAdmin],\n  eventos: { messageCreate: aoMensagem },\n  config,\n};\n",
  "src/modules/personalizar.js": "import {\n  ActionRowBuilder,\n  AttachmentBuilder,\n  ButtonBuilder,\n  ButtonStyle,\n  ChannelType,\n  MessageFlags,\n  ModalBuilder,\n  PermissionFlagsBits,\n  SlashCommandBuilder,\n  StringSelectMenuBuilder,\n  TextInputBuilder,\n  TextInputStyle,\n} from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { CONFIG, responder, aplicarPresenca, cortar, embed, imagens } from '../core/util.js';\nimport { textos, botoes, preencher, ativarPersonalizacao, exportar, importar, resetar, valoresAtuais, criados } from '../core/textos.js';\n\n/**\n * Personalização: o dono do bot troca todos os textos, botões (texto, emoji, cor, esconder),\n * modais, cores, emojis das respostas, a aparência dos embeds e o status do bot.\n * Também cria painéis próprios (botões ou menu que dão cargo, respondem, abrem formulário,\n * abrem ticket ou levam a um link) e formulários próprios.\n *\n *   1. /personalizar baixar  → recebe o arquivo personalizacao.json\n *   2. abre o \"Personalizar bot.html\" (vem na pasta do bot), carrega o arquivo, edita e salva\n *   3. /personalizar aplicar arquivo:<o arquivo salvo>  → vale na hora, sem reiniciar\n *   4. /painel enviar painel:<nome>  → publica um painel criado\n *\n * Funciona igual com o bot no PC ou numa hospedagem: o arquivo vai e volta pelo Discord.\n */\n\nativarPersonalizacao();\n\nconst tx = textos('personalizar', {\n  so_dono: ['Só o dono do bot (quem criou a aplicação no Developer Portal) pode personalizar.', 'resposta'],\n  baixar_ok: ['Aqui está o arquivo com todos os textos do bot ({total} personalizado(s) até agora).\\n\\n**Como editar:** abra o **Personalizar bot.html** (está na pasta do bot), clique em **Abrir arquivo** e escolha este arquivo. Depois de salvar, use `/personalizar aplicar`.', 'resposta'],\n  arquivo_json: ['Envie o arquivo **.json** salvo pelo Personalizar bot.html.', 'resposta'],\n  arquivo_grande: ['Esse arquivo é grande demais (máximo 2 MB).', 'resposta'],\n  arquivo_ler: ['Não consegui baixar o arquivo do Discord. Tente de novo.', 'resposta'],\n  arquivo_invalido: ['Esse arquivo não é um JSON válido. Salve de novo pelo Personalizar bot.html.', 'resposta'],\n  aplicado: ['Personalização aplicada: **{total}** item(ns) diferente(s) do padrão. Já está valendo.', 'resposta'],\n  aplicado_paineis: ['\\nOs painéis já enviados estão sendo atualizados.', 'resposta'],\n  avisos: ['\\n\\n⚠️ Ignorei:\\n{lista}', 'resposta'],\n  resetar_pergunta: ['Isto apaga **toda** a personalização (textos, botões, cores, status, painéis e formulários criados) e volta ao padrão. Tem certeza?', 'resposta'],\n  resetar_botao: ['Sim, voltar ao padrão', 'botao'],\n  resetado: ['Pronto: tudo voltou ao padrão.', 'resposta'],\n  ver: ['Personalização atual: **{textos}** texto(s), **{botoes}** botão(ões), **{visuais}** aparência(s) de embed, **{emojis}** emoji(s), **{cores}** cor(es), **{paineis}** painel(éis) e **{formularios}** formulário(s) criados{status}.', 'resposta'],\n  ver_status: [' e o status do bot', 'texto'],\n  // /painel\n  painel_nao_existe: ['Esse painel não existe mais. Crie ou ajuste no Personalizar bot.html.', 'resposta'],\n  item_nao_existe: ['Essa opção não existe mais neste painel.', 'resposta'],\n  painel_enviado: ['Painel **{nome}** enviado em {canal}.', 'resposta'],\n  painel_sem_permissao: ['Não consigo enviar mensagens em {canal}.', 'resposta'],\n  nenhum_painel: ['Nenhum painel criado para este servidor. Crie no **Personalizar bot.html** (aba Painéis) e aplique com `/personalizar aplicar`.', 'resposta'],\n  lista_titulo: ['🧩 Painéis criados', 'titulo'],\n  lista_linha: '**{nome}** · {tipo} · {itens} opção(ões){enviado}',\n  lista_enviado: ' · enviado {vezes}x',\n  tipo_botoes: 'botões',\n  tipo_menu: 'menu',\n  lista_formularios: ['Formulários criados: {total}', 'rodape'],\n  atualizados: ['{total} painel(éis) atualizado(s).', 'resposta'],\n  // ações\n  cargo_nao_existe: ['O cargo deste botão não existe mais. Avise a equipe.', 'resposta'],\n  cargo_acima: ['Não consigo mexer nesse cargo: ele está acima do meu. Avise a equipe.', 'resposta'],\n  cargo_ganhou: ['Você ganhou o cargo {cargo}.', 'resposta'],\n  cargo_perdeu: ['Você saiu do cargo {cargo}.', 'resposta'],\n  cargo_ja_tem: ['Você já tem o cargo {cargo}.', 'resposta'],\n  cargo_nao_tem: ['Você não tem o cargo {cargo}.', 'resposta'],\n  sem_mensagem: ['👍', 'resposta'],\n  formulario_nao_existe: ['Esse formulário não existe mais.', 'resposta'],\n  formulario_enviado: ['Formulário enviado! Obrigado.', 'resposta'],\n  formulario_sem_canal: ['Recebi, mas o canal de respostas não está configurado. Avise a equipe.', 'resposta'],\n  formulario_resposta_titulo: ['📝 {titulo}', 'titulo'],\n  formulario_resposta_rodape: ['ID: {usuario_id}', 'rodape'],\n  ticket_sem_modulo: ['Este bot não tem o módulo de Tickets.', 'resposta'],\n});\n\nconst bt = botoes('personalizar', {\n  resetar: { nome: 'Confirmar reset', rotulo: 'resetar_botao', estilo: 'Danger' },\n});\n\nconst enviados = colecao('paineis_enviados'); // guild → { mensagemId: { painel, canal } }\n\n/** Dono da aplicação (ou membro do time dela) e quem estiver em \"donos\" no config.json. */\nasync function ehDono(i) {\n  if ((CONFIG.donos ?? []).includes(i.user.id)) return true;\n  const app = await i.client.application.fetch().catch(() => null);\n  const dono = app?.owner;\n  if (!dono) return false;\n  if (dono.members) return dono.members.has(i.user.id); // time\n  return dono.id === i.user.id;\n}\n\n/** Cargos e canais dos servidores, para o painel HTML mostrar listas em vez de pedir IDs. */\nfunction servidores(client) {\n  return [...client.guilds.cache.values()].slice(0, 10).map((g) => ({\n    id: g.id,\n    nome: g.name,\n    cargos: [...g.roles.cache.values()]\n      .filter((r) => r.id !== g.id && !r.managed)\n      .sort((a, b) => b.position - a.position)\n      .slice(0, 250)\n      .map((r) => ({ id: r.id, nome: r.name, cor: r.hexColor })),\n    canais: [...g.channels.cache.values()]\n      .filter((c) => [ChannelType.GuildText, ChannelType.GuildAnnouncement, ChannelType.GuildCategory].includes(c.type))\n      .sort((a, b) => a.rawPosition - b.rawPosition)\n      .slice(0, 500)\n      .map((c) => ({ id: c.id, nome: c.name, tipo: c.type === ChannelType.GuildCategory ? 'categoria' : 'texto' })),\n  }));\n}\n\n// ---------------- painéis criados ----------------\nconst paineisDo = (guildId) => criados().paineis.filter((p) => !p.servidor || p.servidor === guildId);\n\n/** Monta a mensagem de um painel criado. */\nexport function montarPainel(guild, pn) {\n  const vars = { servidor: guild.name, membros: guild.memberCount, ...imagens({ guild }) };\n  const t = (s, n) => cortar(preencher(s, vars), n);\n  const e = embed(guild.id);\n  if (pn.embed.titulo) e.setTitle(t(pn.embed.titulo, 256));\n  if (pn.embed.descricao) e.setDescription(t(pn.embed.descricao, 4000));\n  if (pn.embed.cor) e.setColor(parseInt(pn.embed.cor.slice(1), 16));\n  const url = (u) => {\n    const x = preencher(u, vars).trim();\n    return /^https?:\\/\\/\\S+$/i.test(x) ? x : null;\n  };\n  if (pn.embed.imagem && url(pn.embed.imagem)) e.setImage(url(pn.embed.imagem));\n  if (pn.embed.miniatura && url(pn.embed.miniatura)) e.setThumbnail(url(pn.embed.miniatura));\n  if (pn.embed.rodape) e.setFooter({ text: t(pn.embed.rodape, 2048) });\n  const temEmbed = Boolean(pn.embed.titulo || pn.embed.descricao);\n\n  let components;\n  if (pn.tipo === 'menu') {\n    const menu = new StringSelectMenuBuilder()\n      .setCustomId(`pc:${pn.id}`)\n      .addOptions(\n        pn.itens.map((it) => {\n          const op = { label: cortar(it.rotulo, 100), value: it.id };\n          if (it.descricao) op.description = cortar(it.descricao, 100);\n          if (it.emoji) op.emoji = it.emoji;\n          return op;\n        })\n      );\n    if (pn.placeholder) menu.setPlaceholder(cortar(pn.placeholder, 150));\n    components = [new ActionRowBuilder().addComponents(menu)];\n  } else {\n    const bs = pn.itens.map((it) => {\n      const b = new ButtonBuilder();\n      if (it.rotulo) b.setLabel(cortar(it.rotulo, 80));\n      if (it.emoji) b.setEmoji(it.emoji);\n      if (it.acao.tipo === 'link') return b.setStyle(ButtonStyle.Link).setURL(it.acao.url);\n      return b.setStyle(ButtonStyle[it.estilo] ?? ButtonStyle.Secondary).setCustomId(`pc:${pn.id}:${it.id}`);\n    });\n    components = [];\n    for (let n = 0; n < bs.length && components.length < 5; n += 5) components.push(new ActionRowBuilder().addComponents(bs.slice(n, n + 5)));\n  }\n  return {\n    content: pn.conteudo ? t(pn.conteudo, 2000) : undefined,\n    embeds: temEmbed ? [e] : [],\n    components,\n    allowedMentions: { parse: [] },\n  };\n}\n\n/** Atualiza os painéis já enviados (depois de aplicar uma personalização nova). */\nexport async function atualizarPaineis(client, soGuild = null) {\n  let total = 0;\n  for (const guild of client.guilds.cache.values()) {\n    if (soGuild && guild.id !== soGuild) continue;\n    const lista = enviados.de(guild.id);\n    for (const [msgId, reg] of Object.entries(lista)) {\n      const pn = criados().paineis.find((p) => p.id === reg.painel);\n      const canal = guild.channels.cache.get(reg.canal);\n      if (!pn || !canal?.isTextBased()) continue;\n      const msg = await canal.messages.fetch(msgId).catch(() => null);\n      if (!msg) {\n        delete lista[msgId];\n        continue;\n      }\n      const ok = await msg.edit(montarPainel(guild, pn)).then(() => true, () => false);\n      if (ok) total++;\n    }\n  }\n  enviados.salvar();\n  return total;\n}\n\nfunction modalDoFormulario(f) {\n  return new ModalBuilder()\n    .setCustomId(`cf:${f.id}`)\n    .setTitle(cortar(f.titulo, 45))\n    .addComponents(\n      f.perguntas.map((q, n) => {\n        const campo = new TextInputBuilder()\n          .setCustomId(`p${n}`)\n          .setLabel(cortar(q.rotulo, 45))\n          .setStyle(q.longa ? TextInputStyle.Paragraph : TextInputStyle.Short)\n          .setRequired(q.obrigatoria)\n          .setMaxLength(q.max);\n        if (q.min) campo.setMinLength(q.min);\n        if (q.placeholder) campo.setPlaceholder(cortar(q.placeholder, 100));\n        return new ActionRowBuilder().addComponents(campo);\n      })\n    );\n}\n\nasync function acaoDoPainel(i, [painelId, itemId]) {\n  const pn = criados().paineis.find((p) => p.id === painelId);\n  if (!pn) return responder(i, tx('painel_nao_existe'), 'erro');\n  const id = i.isStringSelectMenu() ? i.values[0] : itemId;\n  const it = pn.itens.find((x) => x.id === id);\n  if (!it) return responder(i, tx('item_nao_existe'), 'erro');\n  const a = it.acao;\n  const vars = { usuario: `${i.user}`, nome: i.member?.displayName ?? i.user.username, servidor: i.guild.name };\n  const responderTexto = (texto, tipo = 'sucesso') => responder(i, preencher(texto, vars), tipo);\n\n  if (a.tipo === 'mensagem') {\n    return i.reply({ content: cortar(preencher(a.mensagem || tx('sem_mensagem'), vars), 2000), flags: MessageFlags.Ephemeral, allowedMentions: { parse: [] } });\n  }\n  if (a.tipo === 'cargo') {\n    const cargo = i.guild.roles.cache.get(a.cargo);\n    if (!cargo) return responder(i, tx('cargo_nao_existe'), 'erro');\n    if (!cargo.editable) return responder(i, tx('cargo_acima'), 'erro');\n    const tem = i.member.roles.cache.has(cargo.id);\n    const quer = a.modo === 'dar' ? true : a.modo === 'tirar' ? false : !tem;\n    vars.cargo = `${cargo}`;\n    if (quer && tem) return responderTexto(tx('cargo_ja_tem', vars), 'info');\n    if (!quer && !tem) return responderTexto(tx('cargo_nao_tem', vars), 'info');\n    const ok = await (quer ? i.member.roles.add(cargo, `Painel ${pn.nome}`) : i.member.roles.remove(cargo, `Painel ${pn.nome}`)).then(() => true, () => false);\n    if (!ok) return responder(i, tx('cargo_acima'), 'erro');\n    return responderTexto(a.mensagem || tx(quer ? 'cargo_ganhou' : 'cargo_perdeu', vars));\n  }\n  if (a.tipo === 'formulario') {\n    const f = criados().formularios.find((x) => x.id === a.formulario);\n    if (!f) return responder(i, tx('formulario_nao_existe'), 'erro');\n    return i.showModal(modalDoFormulario(f));\n  }\n  if (a.tipo === 'ticket') {\n    const mod = await import('./tickets.js').catch(() => null);\n    if (!mod?.abrirTicket) return responder(i, tx('ticket_sem_modulo'), 'erro');\n    return mod.abrirTicket(i, { nome: a.assunto || it.rotulo, emoji: it.emoji, categoria: a.categoria, equipe: a.equipe, mensagem: a.mensagem });\n  }\n}\n\nasync function enviarFormulario(i, [formId]) {\n  const f = criados().formularios.find((x) => x.id === formId);\n  if (!f) return responder(i, tx('formulario_nao_existe'), 'erro');\n  const vars = { usuario: `${i.user}`, nome: i.member?.displayName ?? i.user.username, servidor: i.guild.name, titulo: f.titulo };\n  const canal = f.canal && i.guild.channels.cache.get(f.canal);\n  if (canal?.isTextBased()) {\n    const e = embed(i.guildId)\n      .setTitle(tx('formulario_resposta_titulo', { titulo: f.titulo }))\n      .setAuthor({ name: i.user.tag, iconURL: i.user.displayAvatarURL() })\n      .addFields(\n        f.perguntas.map((q, n) => ({ name: cortar(q.rotulo, 256), value: cortar(i.fields.getTextInputValue(`p${n}`) || '—', 1024) }))\n      )\n      .setFooter({ text: tx('formulario_resposta_rodape', { usuario_id: i.user.id }) })\n      .setTimestamp();\n    await canal.send({ content: `${i.user}`, embeds: [e], allowedMentions: { parse: [] } }).catch(() => {});\n  }\n  if (f.cargo) {\n    const cargo = i.guild.roles.cache.get(f.cargo);\n    if (cargo?.editable) await i.member.roles.add(cargo, `Formulário ${f.titulo}`).catch(() => {});\n  }\n  if (!canal?.isTextBased()) return responder(i, tx('formulario_sem_canal'), 'aviso');\n  return responder(i, preencher(f.mensagem || tx('formulario_enviado'), vars), 'sucesso');\n}\n\n// ---------------- /personalizar ----------------\nconst personalizar = {\n  data: new SlashCommandBuilder()\n    .setName('personalizar')\n    .setDescription('Personaliza os textos, botões, cores e status do bot (só o dono do bot)')\n    .setDefaultMemberPermissions(PermissionFlagsBits.Administrator)\n    .addSubcommand((s) => s.setName('baixar').setDescription('Baixa o arquivo para editar no Personalizar bot.html'))\n    .addSubcommand((s) =>\n      s\n        .setName('aplicar')\n        .setDescription('Aplica o arquivo salvo pelo Personalizar bot.html')\n        .addAttachmentOption((o) => o.setName('arquivo').setDescription('O arquivo .json salvo').setRequired(true))\n    )\n    .addSubcommand((s) => s.setName('ver').setDescription('Mostra o que está personalizado'))\n    .addSubcommand((s) => s.setName('resetar').setDescription('Volta tudo ao padrão')),\n  async executar(i) {\n    if (!(await ehDono(i))) return responder(i, tx('so_dono'), 'erro');\n    const sub = i.options.getSubcommand();\n\n    if (sub === 'baixar') {\n      const dados = exportar({ nomeBot: CONFIG.nome || i.client.user.username, servidores: servidores(i.client) });\n      const v = dados.valores;\n      const total = Object.keys(v.textos).length + Object.keys(v.visuais).length + Object.keys(v.botoes).length + v.criados.paineis.length + v.criados.formularios.length;\n      const arquivo = new AttachmentBuilder(Buffer.from(JSON.stringify(dados, null, 1), 'utf8'), { name: 'personalizacao.json' });\n      return i.reply({ content: tx('baixar_ok', { total }), files: [arquivo], flags: MessageFlags.Ephemeral });\n    }\n\n    if (sub === 'aplicar') {\n      const anexo = i.options.getAttachment('arquivo');\n      if (!/\\.json$/i.test(anexo.name)) return responder(i, tx('arquivo_json'), 'erro');\n      if (anexo.size > 2 * 1024 * 1024) return responder(i, tx('arquivo_grande'), 'erro');\n      await i.deferReply({ flags: MessageFlags.Ephemeral });\n      let texto;\n      try {\n        const r = await fetch(anexo.url);\n        if (!r.ok) throw new Error(String(r.status));\n        texto = await r.text();\n      } catch {\n        return responder(i, tx('arquivo_ler'), 'erro');\n      }\n      let json;\n      try {\n        json = JSON.parse(texto.replace(/^﻿/, ''));\n      } catch {\n        return responder(i, tx('arquivo_invalido'), 'erro');\n      }\n      const r = importar(json);\n      if (!r.ok) return responder(i, r.erro, 'erro');\n      aplicarPresenca(i.client);\n      const temEnviados = [...i.client.guilds.cache.keys()].some((g) => Object.keys(enviados.ler(g) ?? {}).length);\n      if (temEnviados) atualizarPaineis(i.client).catch((e) => console.error('[personalizar] painéis:', e.message));\n      const avisos = r.avisos.length ? tx('avisos', { lista: cortar(r.avisos.slice(0, 15).map((a) => `• ${a}`).join('\\n'), 1500) }) : '';\n      return responder(i, tx('aplicado', { total: r.total }) + (temEnviados ? tx('aplicado_paineis') : '') + avisos, r.avisos.length ? 'aviso' : 'sucesso');\n    }\n\n    if (sub === 'ver') {\n      const v = valoresAtuais();\n      const n = (o) => Object.keys(o ?? {}).length;\n      return responder(\n        i,\n        tx('ver', {\n          textos: n(v.textos),\n          botoes: n(v.botoes),\n          visuais: n(v.visuais),\n          emojis: n(v.emojis),\n          cores: n(v.cores),\n          paineis: v.criados?.paineis?.length ?? 0,\n          formularios: v.criados?.formularios?.length ?? 0,\n          status: v.presenca?.texto ? tx('ver_status') : '',\n        }),\n        'info'\n      );\n    }\n\n    if (sub === 'resetar') {\n      return i.reply({ content: tx('resetar_pergunta'), components: [new ActionRowBuilder().addComponents(bt('resetar').setCustomId('pz:resetar'))], flags: MessageFlags.Ephemeral });\n    }\n  },\n};\n\n// ---------------- /painel ----------------\nconst painel = {\n  data: new SlashCommandBuilder()\n    .setName('painel')\n    .setDescription('Painéis criados no Personalizar bot (equipe)')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('enviar')\n        .setDescription('Publica um painel criado')\n        .addStringOption((o) => o.setName('painel').setDescription('Qual painel').setRequired(true).setAutocomplete(true))\n        .addChannelOption((o) => o.setName('canal').setDescription('Padrão: este canal').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n    )\n    .addSubcommand((s) => s.setName('lista').setDescription('Mostra os painéis criados'))\n    .addSubcommand((s) => s.setName('atualizar').setDescription('Atualiza os painéis já enviados neste servidor')),\n  async autocompletar(i) {\n    const busca = i.options.getFocused().toLowerCase();\n    return i.respond(\n      paineisDo(i.guildId)\n        .filter((p) => p.nome.toLowerCase().includes(busca))\n        .slice(0, 25)\n        .map((p) => ({ name: cortar(p.nome, 100), value: p.id }))\n    );\n  },\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    if (sub === 'lista') {\n      const lista = paineisDo(i.guildId);\n      if (!lista.length) return responder(i, tx('nenhum_painel'), 'info');\n      const env = Object.values(enviados.ler(i.guildId) ?? {});\n      const linhas = lista.map((p) => {\n        const vezes = env.filter((x) => x.painel === p.id).length;\n        return tx('lista_linha', { nome: p.nome, tipo: tx(p.tipo === 'menu' ? 'tipo_menu' : 'tipo_botoes'), itens: p.itens.length, enviado: vezes ? tx('lista_enviado', { vezes }) : '' });\n      });\n      return i.reply({\n        embeds: [embed(i.guildId).setTitle(tx('lista_titulo')).setDescription(cortar(linhas.join('\\n'), 4000)).setFooter({ text: tx('lista_formularios', { total: criados().formularios.length }) })],\n        flags: MessageFlags.Ephemeral,\n      });\n    }\n    if (sub === 'atualizar') {\n      await i.deferReply({ flags: MessageFlags.Ephemeral });\n      const total = await atualizarPaineis(i.client, i.guildId);\n      return responder(i, tx('atualizados', { total }), 'sucesso');\n    }\n    // enviar\n    const pn = paineisDo(i.guildId).find((p) => p.id === i.options.getString('painel') || p.nome === i.options.getString('painel'));\n    if (!pn) return responder(i, paineisDo(i.guildId).length ? tx('painel_nao_existe') : tx('nenhum_painel'), 'erro');\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    const msg = await canal.send(montarPainel(i.guild, pn)).catch((e) => {\n      console.error('[personalizar] painel:', e.message);\n      return null;\n    });\n    if (!msg) return responder(i, tx('painel_sem_permissao', { canal }), 'erro');\n    enviados.de(i.guildId)[msg.id] = { painel: pn.id, canal: canal.id };\n    enviados.salvar();\n    return responder(i, tx('painel_enviado', { nome: pn.nome, canal }), 'sucesso');\n  },\n};\n\nasync function botaoReset(i, [acao]) {\n  if (acao !== 'resetar') return;\n  if (!(await ehDono(i))) return responder(i, tx('so_dono'), 'erro');\n  resetar();\n  aplicarPresenca(i.client);\n  return i.update({ content: `✅ ${tx('resetado')}`, components: [] });\n}\n\nexport default {\n  id: 'personalizar',\n  nome: 'Personalização',\n  comandos: [personalizar, painel],\n  componentes: { pz: botaoReset, pc: acaoDoPainel, cf: enviarFormulario },\n};\n",
  "src/modules/reputacao.js": "import { PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, fmt, duracaoTexto, cortar } from '../core/util.js';\nimport { textos } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('reputacao', {\n  dar_reputacao_voce_mesmo: ['Não dá para dar reputação para você mesmo.', 'resposta'],\n  bots_tem_reputacao: ['Bots não têm reputação.', 'resposta'],\n  voce_ja_deu_reputacao: ['Você já deu reputação hoje. Volte em **{duracao}**.', 'resposta'],\n  ganhou: '\\n🎁 Ganhou {novos}',\n  deu_reputacao_agora: ['👍 {usuario} deu **+1 de reputação** para {alvo}! Agora: **{pontos}**{motivo}{novos}', 'descricao'],\n  so_quem_tem_gerenciar: ['Só quem tem **Gerenciar servidor** pode fazer isso.', 'resposta'],\n  agora_tem_reputacao: ['{usuario} agora tem **{pontos}** de reputação.', 'resposta'],\n  recompensa_pontos_removida: ['Recompensa de {pontos} pontos removida.', 'resposta'],\n  escolha_cargo_comum_sem: ['Escolha um cargo comum (sem administrador).', 'resposta'],\n  meu_cargo_precisa_ficar: ['Meu cargo precisa ficar acima de {cargo}.', 'resposta'],\n  reputacao_pessoa_ganha: ['Com **{pontos}** de reputação a pessoa ganha {cargo}.', 'resposta'],\n  ninguem_tem_reputacao_ainda: ['Ninguém tem reputação ainda. Use `/rep`.', 'resposta'],\n  ranking_reputacao: ['👍 Ranking de reputação', 'titulo'],\n  proxima_recompensa: ' Próxima recompensa: <@&{proxima}> com {pontos_proxima}.',\n  tem_reputacao: ['{usuario} tem **{pontos}** de reputação.{proxima}', 'resposta'],\n  reputacao: 'Reputação',\n  recompensas: 'Recompensas: {recompensas}',\n  sem_recompensas_reputacao_recompensa: 'Sem recompensas (`/reputacao recompensa`)',\n});\n\n/**\n * Reputação: cada membro pode dar +1 de reputação para alguém uma vez por dia.\n * Ranking e cargos de recompensa por pontos.\n */\n\nconst rep = colecao('reputacao'); // guild -> user -> { pontos, deuEm }\nconst cfg = (guildId) => ajustes(guildId, 'reputacao', { recompensas: {} }); // pontos -> cargoId\nconst ESPERA = 24 * 3600e3;\nconst de = (guildId, userId) => {\n  const d = rep.de(guildId, userId);\n  d.pontos ??= 0;\n  return d;\n};\n\nasync function darRecompensas(guild, userId, pontos) {\n  const r = cfg(guild.id).recompensas;\n  const ganhar = Object.entries(r).filter(([p]) => pontos >= Number(p)).map(([, cargo]) => cargo);\n  if (!ganhar.length) return [];\n  const membro = await guild.members.fetch(userId).catch(() => null);\n  if (!membro) return [];\n  const novos = [];\n  for (const id of ganhar) {\n    const cargo = guild.roles.cache.get(id);\n    if (cargo?.editable && !membro.roles.cache.has(id)) {\n      const ok = await membro.roles.add(cargo, 'Recompensa de reputação').then(() => true, () => false);\n      if (ok) novos.push(cargo);\n    }\n  }\n  return novos;\n}\n\nconst repCmd = {\n  data: new SlashCommandBuilder()\n    .setName('rep')\n    .setDescription('Dá +1 de reputação para alguém (1 vez por dia)')\n    .addUserOption((o) => o.setName('usuario').setDescription('Quem merece').setRequired(true))\n    .addStringOption((o) => o.setName('motivo').setDescription('Por quê? (opcional)').setMaxLength(150)),\n  async executar(i) {\n    const alvo = i.options.getUser('usuario');\n    if (alvo.id === i.user.id) return responder(i, tx('dar_reputacao_voce_mesmo'), 'erro');\n    if (alvo.bot) return responder(i, tx('bots_tem_reputacao'), 'erro');\n    const eu = de(i.guildId, i.user.id);\n    const falta = (eu.deuEm ?? 0) + ESPERA - Date.now();\n    if (falta > 0) return responder(i, tx('voce_ja_deu_reputacao', { duracao: duracaoTexto(falta) }), 'aviso');\n    const ele = de(i.guildId, alvo.id);\n    ele.pontos += 1;\n    eu.deuEm = Date.now();\n    rep.salvar();\n    const novos = await darRecompensas(i.guild, alvo.id, ele.pontos);\n    const motivo = i.options.getString('motivo');\n    return i.reply({\n      embeds: [\n        embed(i.guildId).setDescription(\n          tx('deu_reputacao_agora', { usuario: i.user, alvo, pontos: fmt(ele.pontos), motivo: motivo ? `\\n> ${cortar(motivo, 150)}` : '', novos: novos.length ? tx('ganhou', { novos: novos.join(', ') }) : '' })\n        ),\n      ],\n      allowedMentions: { users: [alvo.id] },\n    });\n  },\n};\n\nconst reputacao = {\n  data: new SlashCommandBuilder()\n    .setName('reputacao')\n    .setDescription('Reputação dos membros')\n    .addSubcommand((s) =>\n      s\n        .setName('ver')\n        .setDescription('Pontos de alguém')\n        .addUserOption((o) => o.setName('usuario').setDescription('De quem (padrão: você)'))\n    )\n    .addSubcommand((s) => s.setName('ranking').setDescription('Os mais bem falados do servidor'))\n    .addSubcommand((s) =>\n      s\n        .setName('recompensa')\n        .setDescription('(Equipe) Cargo ao chegar em X pontos (sem cargo = remove)')\n        .addIntegerOption((o) => o.setName('pontos').setDescription('Pontos necessários').setRequired(true).setMinValue(1).setMaxValue(100000))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Cargo dado (deixe vazio para remover)'))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('definir')\n        .setDescription('(Equipe) Muda os pontos de alguém')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addIntegerOption((o) => o.setName('pontos').setDescription('Novo total').setRequired(true).setMinValue(0).setMaxValue(1000000))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    if (sub === 'recompensa' || sub === 'definir') {\n      if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, tx('so_quem_tem_gerenciar'), 'erro');\n      if (sub === 'definir') {\n        const u = i.options.getUser('usuario');\n        if (u.bot) return responder(i, tx('bots_tem_reputacao'), 'erro');\n        de(i.guildId, u.id).pontos = i.options.getInteger('pontos');\n        rep.salvar();\n        await darRecompensas(i.guild, u.id, i.options.getInteger('pontos'));\n        return responder(i, tx('agora_tem_reputacao', { usuario: u, pontos: fmt(i.options.getInteger('pontos')) }), 'sucesso');\n      }\n      const c = cfg(i.guildId);\n      const pontos = String(i.options.getInteger('pontos'));\n      const cargo = i.options.getRole('cargo');\n      if (!cargo) {\n        delete c.recompensas[pontos];\n        salvarAjustes();\n        return responder(i, tx('recompensa_pontos_removida', { pontos }), 'sucesso');\n      }\n      if (cargo.managed || cargo.permissions.has(PermissionFlagsBits.Administrator)) return responder(i, tx('escolha_cargo_comum_sem'), 'erro');\n      if (!cargo.editable) return responder(i, tx('meu_cargo_precisa_ficar', { cargo }), 'erro');\n      c.recompensas[pontos] = cargo.id;\n      salvarAjustes();\n      return responder(i, tx('reputacao_pessoa_ganha', { pontos, cargo }), 'sucesso');\n    }\n    if (sub === 'ranking') {\n      const top = Object.entries(rep.ler(i.guildId) ?? {})\n        .filter(([, d]) => d.pontos > 0)\n        .sort((a, b) => b[1].pontos - a[1].pontos)\n        .slice(0, 15);\n      if (!top.length) return responder(i, tx('ninguem_tem_reputacao_ainda'), 'aviso');\n      return i.reply({\n        embeds: [embed(i.guildId).setTitle(tx('ranking_reputacao')).setDescription(top.map(([id, d], k) => `**${k + 1}.** <@${id}> · ${fmt(d.pontos)}`).join('\\n'))],\n        allowedMentions: { parse: [] },\n      });\n    }\n    const u = i.options.getUser('usuario') ?? i.user;\n    const d = rep.ler(i.guildId, u.id);\n    const r = Object.entries(cfg(i.guildId).recompensas).sort((a, b) => Number(a[0]) - Number(b[0]));\n    const proxima = r.find(([p]) => Number(p) > (d?.pontos ?? 0));\n    return responder(i, tx('tem_reputacao', { usuario: u, pontos: fmt(d?.pontos ?? 0), proxima: proxima ? tx('proxima_recompensa', { proxima: proxima[1], pontos_proxima: proxima[0] }) : '' }), 'info');\n  },\n};\n\nexport default {\n  id: 'reputacao',\n  nome: tx('reputacao'),\n  comandos: [repCmd, reputacao],\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  config: {\n    resumo(guild) {\n      const r = Object.entries(cfg(guild.id).recompensas);\n      return [r.length ? tx('recompensas', { recompensas: r.map(([p, c]) => `${p} → <@&${c}>`).join(' · ') }) : tx('sem_recompensas_reputacao_recompensa')];\n    },\n  },\n};\n",
  "src/modules/sorteios.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { embed, responder, lerDuracao, ts, cortar, CORES } from '../core/util.js';\nimport { textos, visuais, botoes } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('sorteios', {\n  encerrado: 'Encerrado {quando}',\n  termina: 'Termina {quando} ({data})',\n  vencedores: 'Vencedores: **{vencedores}**',\n  so_participa_quem_tem: 'Só participa quem tem <@&{cargo}>',\n  criado: 'Criado por <@{autor}>',\n  participante: ['{participantes_total} participante(s)', 'rodape'],\n  ganhador_es: ['Ganhador(es)', 'campo'],\n  ninguem_participou: 'Ninguém participou.',\n  encerrado_2: 'Encerrado',\n  participar: 'Participar ({participantes_total})',\n  ganharam: 's ganharam',\n  ganhou: ' ganhou',\n  parabens_voce: '🎉 Parabéns {ganhadores}! Você{verbo} **{premio}**!',\n  sorteio_terminou_sem_participantes: '😕 O sorteio de **{premio}** terminou sem participantes.',\n  duracao_invalida_ex_1h: ['Duração inválida (ex.: 1h, 2d; entre 10s e 60d).', 'resposta'],\n  consegui_enviar_mensagens_confira: ['Não consegui enviar mensagens em {canal}. Confira as minhas permissões.', 'resposta'],\n  sorteio_criado_termina: ['Sorteio criado em {canal}! Termina {quando}.', 'resposta'],\n  sorteio_encontrado: ['Sorteio não encontrado.', 'resposta'],\n  esse_sorteio_ja_terminou: ['Esse sorteio já terminou. Use /sorteio refazer para sortear de novo.', 'resposta'],\n  sorteio_encerrado: '✅ Sorteio encerrado.',\n  esse_sorteio_ainda_terminou: ['Esse sorteio ainda não terminou.', 'resposta'],\n  ninguem_participou_desse_sorteio: ['Ninguém participou desse sorteio.', 'resposta'],\n  novo_sorteio: ['🎉 Novo sorteio de **{premio}**: {ganhadores}!', 'conteudo'],\n  nenhum_sorteio_andamento: ['Nenhum sorteio em andamento.', 'resposta'],\n  termina_participante_id: '**{premio}** · <#{canal}> · termina {quando} · {participantes_total} participante(s) · ID `{id}`',\n  sorteios_andamento: ['🎉 Sorteios em andamento', 'titulo'],\n  este_sorteio_ja_terminou: ['Este sorteio já terminou.', 'resposta'],\n  participar_voce_precisa_cargo: ['Para participar você precisa do cargo <@&{cargo}>.', 'resposta'],\n  voce_saiu_sorteio: 'Você saiu do sorteio.',\n  voce_esta_participando_clique: '🎉 Você está participando! Clique de novo para sair.',\n  sorteios: 'Sorteios',\n});\n\n// Botões (texto, emoji e cor personalizáveis; alguns podem ser escondidos)\nconst bt = botoes('sorteios', {\n  entrar: { nome: 'Participar do sorteio', rotulo: 'participar', emoji: '🎉', estilo: 'Primary', rotuloInfo: 'Quando o sorteio acaba, o texto vira o de \"Encerrado\".' },\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('sorteios', {\n  sorteio: { nome: \"Mensagem do sorteio\", vars: [] },\n});\n\n/**\n * Sorteios: botão para participar, cargo obrigatório opcional, sorteio automático\n * no fim, encerrar antes da hora e sortear de novo.\n */\n\nconst sorteios = colecao('sorteios');\n\nfunction painel(guildId, s, encerrado = false) {\n  const e = embed(guildId)\n    .setTitle(`🎉 ${s.premio}`)\n    .setDescription(\n      [\n        s.descricao ? `${s.descricao}\\n` : '',\n        encerrado ? tx('encerrado', { quando: ts(s.fim) }) : tx('termina', { quando: ts(s.fim), data: ts(s.fim, 'f') }),\n        tx('vencedores', { vencedores: s.vencedores }),\n        s.cargo ? tx('so_participa_quem_tem', { cargo: s.cargo }) : '',\n        tx('criado', { autor: s.autor }),\n      ]\n        .filter(Boolean)\n        .join('\\n')\n    )\n    .setFooter({ text: tx('participante', { participantes_total: s.participantes.length }) });\n  if (encerrado) {\n    e.setColor(CORES.sucesso).addFields({ name: tx('ganhador_es'), value: s.ganhadores?.length ? s.ganhadores.map((id) => `<@${id}>`).join(', ') : tx('ninguem_participou') });\n  }\n  vis(e, 'sorteio', {});\n  const row = new ActionRowBuilder().addComponents(\n    bt('entrar', { rotulo: encerrado ? tx('encerrado_2') : tx('participar', { participantes_total: s.participantes.length }) })\n      .setCustomId('sr:entrar')\n      .setDisabled(encerrado)\n  );\n  return { embeds: [e], components: [row] };\n}\n\nfunction sortear(lista, n) {\n  const copia = [...lista];\n  const out = [];\n  while (copia.length && out.length < n) out.push(copia.splice(Math.floor(Math.random() * copia.length), 1)[0]);\n  return out;\n}\n\nasync function finalizar(client, guildId, msgId) {\n  const s = sorteios.ler(guildId, msgId);\n  if (!s || s.encerrado) return;\n  s.encerrado = true;\n  s.fim = Math.min(s.fim, Date.now());\n  s.ganhadores = sortear(s.participantes, s.vencedores);\n  sorteios.salvar();\n  const canal = await client.channels.fetch(s.canal).catch(() => null);\n  const msg = await canal?.messages.fetch(msgId).catch(() => null);\n  if (msg) await msg.edit(painel(guildId, s, true)).catch(() => {});\n  if (canal?.isTextBased()) {\n    const texto = s.ganhadores.length\n      ? tx('parabens_voce', { ganhadores: s.ganhadores.map((id) => `<@${id}>`).join(', '), verbo: s.ganhadores.length > 1 ? tx('ganharam') : tx('ganhou'), premio: s.premio })\n      : tx('sorteio_terminou_sem_participantes', { premio: s.premio });\n    await canal.send({ content: texto, reply: msg ? { messageReference: msg.id, failIfNotExists: false } : undefined, allowedMentions: { users: s.ganhadores } }).catch(() => {});\n  }\n}\n\nconst idDaMensagem = (t) => String(t).split('/').pop().replace(/\\D/g, '');\n\nconst sorteio = {\n  data: new SlashCommandBuilder()\n    .setName('sorteio')\n    .setDescription('Sorteios')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('criar')\n        .setDescription('Cria um sorteio')\n        .addStringOption((o) => o.setName('premio').setDescription('O que será sorteado').setRequired(true).setMaxLength(200))\n        .addStringOption((o) => o.setName('duracao').setDescription('Ex.: 1h, 2d, 1w').setRequired(true).setMaxLength(20))\n        .addIntegerOption((o) => o.setName('vencedores').setDescription('Quantos ganham (padrão 1)').setMinValue(1).setMaxValue(20))\n        .addChannelOption((o) => o.setName('canal').setDescription('Padrão: este canal').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Só quem tem este cargo participa'))\n        .addStringOption((o) => o.setName('descricao').setDescription('Detalhes do sorteio').setMaxLength(1000))\n    )\n    .addSubcommand((s) =>\n      s.setName('encerrar').setDescription('Encerra um sorteio agora').addStringOption((o) => o.setName('mensagem').setDescription('ID ou link da mensagem do sorteio').setRequired(true).setMaxLength(120))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('refazer')\n        .setDescription('Sorteia ganhadores de novo num sorteio encerrado')\n        .addStringOption((o) => o.setName('mensagem').setDescription('ID ou link da mensagem do sorteio').setRequired(true).setMaxLength(120))\n        .addIntegerOption((o) => o.setName('vencedores').setDescription('Quantos (padrão: o mesmo número)').setMinValue(1).setMaxValue(20))\n    )\n    .addSubcommand((s) => s.setName('lista').setDescription('Sorteios em andamento')),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    if (sub === 'criar') {\n      const ms = lerDuracao(i.options.getString('duracao'));\n      if (!ms || ms < 10_000 || ms > 60 * 86_400_000) return responder(i, tx('duracao_invalida_ex_1h'), 'erro');\n      const canal = i.options.getChannel('canal') ?? i.channel;\n      const s = {\n        premio: i.options.getString('premio'),\n        descricao: i.options.getString('descricao') || '',\n        vencedores: i.options.getInteger('vencedores') ?? 1,\n        cargo: i.options.getRole('cargo')?.id ?? null,\n        fim: Date.now() + ms,\n        canal: canal.id,\n        autor: i.user.id,\n        participantes: [],\n        encerrado: false,\n      };\n      const msg = await canal.send(painel(i.guildId, s)).catch(() => null);\n      if (!msg) return responder(i, tx('consegui_enviar_mensagens_confira', { canal }), 'erro');\n      sorteios.de(i.guildId)[msg.id] = s;\n      sorteios.salvar();\n      return responder(i, tx('sorteio_criado_termina', { canal, quando: ts(s.fim) }), 'sucesso');\n    }\n    if (sub === 'encerrar') {\n      const id = idDaMensagem(i.options.getString('mensagem'));\n      const s = sorteios.ler(i.guildId, id);\n      if (!s) return responder(i, tx('sorteio_encontrado'), 'erro');\n      if (s.encerrado) return responder(i, tx('esse_sorteio_ja_terminou'), 'aviso');\n      await i.deferReply({ flags: 64 });\n      await finalizar(i.client, i.guildId, id);\n      return i.editReply(tx('sorteio_encerrado'));\n    }\n    if (sub === 'refazer') {\n      const id = idDaMensagem(i.options.getString('mensagem'));\n      const s = sorteios.ler(i.guildId, id);\n      if (!s) return responder(i, tx('sorteio_encontrado'), 'erro');\n      if (!s.encerrado) return responder(i, tx('esse_sorteio_ainda_terminou'), 'aviso');\n      const n = i.options.getInteger('vencedores') ?? s.vencedores;\n      const novos = sortear(s.participantes, n);\n      if (!novos.length) return responder(i, tx('ninguem_participou_desse_sorteio'), 'aviso');\n      return i.reply({ content: tx('novo_sorteio', { premio: cortar(s.premio, 100), ganhadores: novos.map((u) => `<@${u}>`).join(', ') }), allowedMentions: { users: novos } });\n    }\n    if (sub === 'lista') {\n      const ativos = Object.entries(sorteios.ler(i.guildId) ?? {}).filter(([, s]) => !s.encerrado);\n      if (!ativos.length) return responder(i, tx('nenhum_sorteio_andamento'), 'info');\n      const linhas = ativos.map(([id, s]) => tx('termina_participante_id', { premio: cortar(s.premio, 60), canal: s.canal, quando: ts(s.fim), participantes_total: s.participantes.length, id }));\n      return i.reply({ embeds: [embed(i.guildId).setTitle(tx('sorteios_andamento')).setDescription(linhas.join('\\n'))], flags: 64 });\n    }\n  },\n};\n\nconst componentes = {\n  async sr(i, [acao]) {\n    if (acao !== 'entrar') return;\n    const s = sorteios.ler(i.guildId, i.message.id);\n    if (!s || s.encerrado) return responder(i, tx('este_sorteio_ja_terminou'), 'aviso');\n    if (s.cargo && !i.member.roles.cache.has(s.cargo)) return responder(i, tx('participar_voce_precisa_cargo', { cargo: s.cargo }), 'erro');\n    const idx = s.participantes.indexOf(i.user.id);\n    if (idx >= 0) s.participantes.splice(idx, 1);\n    else s.participantes.push(i.user.id);\n    sorteios.salvar();\n    await i.update(painel(i.guildId, s));\n    await i.followUp({ content: idx >= 0 ? tx('voce_saiu_sorteio') : tx('voce_esta_participando_clique'), flags: 64 });\n  },\n};\n\nexport default {\n  id: 'sorteios',\n  nome: tx('sorteios'),\n  comandos: [sorteio],\n  componentes,\n  aoIniciar(client) {\n    const checar = async () => {\n      const agora = Date.now();\n      for (const [guildId, lista] of Object.entries(sorteios.raiz)) {\n        for (const [msgId, s] of Object.entries(lista)) {\n          if (!s.encerrado && s.fim <= agora) await finalizar(client, guildId, msgId);\n          if (s.encerrado && agora - s.fim > 30 * 86_400_000) delete lista[msgId];\n        }\n      }\n    };\n    checar();\n    setInterval(checar, 15_000);\n  },\n};\n",
  "src/modules/sugestoes.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, EmbedBuilder, MessageFlags, ModalBuilder, PermissionFlagsBits, SlashCommandBuilder, TextInputBuilder, TextInputStyle } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, ehStaff, cortar, CORES, imagens } from '../core/util.js';\nimport { textos, visuais, botoes as registrarBotoes, comDica, modais } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('sugestoes', {\n  dica_motivo: ['', 'placeholder'],\n  equipe: ['Equipe', 'botao'],\n  canal_sugestoes_foi_configurado: ['O canal de sugestões não foi configurado. Avise a equipe (/config sugestoes canal).', 'resposta'],\n  sugestao: ['💡 Sugestão #{numero}', 'titulo'],\n  situacao: ['Situação', 'campo'],\n  votacao: '🕐 Em votação',\n  consegui_enviar_avise_equipe: ['Não consegui enviar em {canal}. Avise a equipe para conferir as minhas permissões.', 'resposta'],\n  sugestao_2: ['Sugestão #{numero}', 'campo'],\n  sugestao_enviada: ['Sugestão enviada em {canal}!', 'resposta'],\n  so_equipe_pode_decidir: ['Só a equipe pode decidir sugestões.', 'resposta'],\n  sugestao_encontrada: ['Sugestão não encontrada.', 'resposta'],\n  esta_sugestao_ja_foi: ['Esta sugestão já foi {status}.', 'resposta'],\n  achei_mensagem_sugestao: ['Não achei a mensagem da sugestão.', 'resposta'],\n  aprovada: '✅ Aprovada por {usuario}',\n  recusada: '❌ Recusada por {usuario}',\n  motivo: ['Motivo', 'campo'],\n  votos: ['Votos', 'campo'],\n  motivo_2: '\\n**Motivo:** {motivo}',\n  sua_sugestao_foi: ['Sua sugestão #{numero} em **{servidor}** foi **{status}**.{motivo}', 'descricao'],\n  sugestao_3: ['Sugestão #{numero} {status}.', 'resposta'],\n  aprovar_sugestao: 'Aprovar sugestão',\n  recusar_sugestao: 'Recusar sugestão',\n  motivo_opcional: ['Motivo (opcional)', 'rotulo'],\n  esta_sugestao_esta_mais: ['Esta sugestão não está mais no sistema.', 'resposta'],\n  votacao_desta_sugestao_ja: ['A votação desta sugestão já terminou.', 'resposta'],\n  so_equipe_pode_usar: ['Só a equipe pode usar este botão.', 'resposta'],\n  fazer_esta_sugestao: ['O que fazer com esta sugestão?', 'conteudo'],\n  aprovar: ['Aprovar', 'botao'],\n  recusar: ['Recusar', 'botao'],\n  sugestoes_serao_publicadas: 'Sugestões serão publicadas em {canal}.',\n  sugestoes_desligadas: 'Sugestões desligadas.',\n  definido: 'não definido',\n  canal: 'Canal: {canal}',\n  sugestoes_enviadas: 'Sugestões enviadas: {contador}',\n  sugestoes: 'Sugestões',\n});\n\n// Botões (texto, emoji e cor personalizáveis; alguns podem ser escondidos)\nconst bt = registrarBotoes('sugestoes', {\n  sim: { nome: 'Votar a favor', emoji: '👍', estilo: 'Success', rotuloInfo: 'O texto é a contagem de votos.' },\n  nao: { nome: 'Votar contra', emoji: '👎', estilo: 'Danger', rotuloInfo: 'O texto é a contagem de votos.' },\n  analisar: { nome: 'Equipe (aprovar/recusar)', rotulo: 'equipe', emoji: '🛡️', estilo: 'Secondary' },\n  aprovar: { nome: 'Aprovar sugestão', rotulo: 'aprovar', emoji: '✅', estilo: 'Success' },\n  recusar: { nome: 'Recusar sugestão', rotulo: 'recusar', emoji: '❌', estilo: 'Danger' },\n});\nmodais('sugestoes', {\n  motivo: { nome: 'Aprovar/recusar com motivo', textos: ['aprovar_sugestao', 'recusar_sugestao', 'motivo_opcional', 'dica_motivo'] },\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('sugestoes', {\n  sugestao: { nome: \"Sugestão publicada\", vars: ['avatar', 'servidor_icone'] },\n});\n\n/**\n * Sugestões: /sugerir publica a ideia num canal com votos 👍/👎.\n * A equipe aprova ou recusa pelos botões, com um motivo.\n */\n\nconst sugestoes = colecao('sugestoes');\nconst PADRAO = { canal: null, contador: 0 };\nconst cfg = (guildId) => ajustes(guildId, 'sugestoes', PADRAO);\n\nfunction botoes(s, encerrada = false) {\n  return [\n    new ActionRowBuilder().addComponents(\n      bt('sim', { rotulo: String(s.sim.length) }).setCustomId('sg:sim').setDisabled(encerrada),\n      bt('nao', { rotulo: String(s.nao.length) }).setCustomId('sg:nao').setDisabled(encerrada),\n      bt('analisar').setCustomId('sg:analisar').setDisabled(encerrada)\n    ),\n  ];\n}\n\nconst sugerir = {\n  data: new SlashCommandBuilder()\n    .setName('sugerir')\n    .setDescription('Envia uma sugestão para o servidor')\n    .addStringOption((o) => o.setName('sugestao').setDescription('A sua ideia').setRequired(true).setMinLength(10).setMaxLength(1500)),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const canal = c.canal && i.guild.channels.cache.get(c.canal);\n    if (!canal?.isTextBased()) return responder(i, tx('canal_sugestoes_foi_configurado'), 'erro');\n    c.contador += 1;\n    salvarAjustes();\n    const s = { autor: i.user.id, sim: [], nao: [], status: 'aberta', numero: c.contador, canal: canal.id };\n    const e = embed(i.guildId)\n      .setAuthor({ name: i.member.displayName, iconURL: i.user.displayAvatarURL() })\n      .setTitle(tx('sugestao', { numero: s.numero }))\n      .setDescription(i.options.getString('sugestao'))\n      .addFields({ name: tx('situacao'), value: tx('votacao') })\n      .setTimestamp();\n    vis(e, 'sugestao', imagens({ user: i.user, guild: i.guild }));\n    const msg = await canal.send({ embeds: [e], components: botoes(s) }).catch(() => null);\n    if (!msg) return responder(i, tx('consegui_enviar_avise_equipe', { canal }), 'erro');\n    sugestoes.de(i.guildId)[msg.id] = s;\n    sugestoes.salvar();\n    if (msg.channel.threads) await msg.startThread({ name: tx('sugestao_2', { numero: s.numero }), autoArchiveDuration: 4320 }).catch(() => {});\n    return responder(i, tx('sugestao_enviada', { canal }), 'sucesso');\n  },\n};\n\nasync function decidir(i, msgId, aprovada, motivo) {\n  if (!ehStaff(i.member)) return responder(i, tx('so_equipe_pode_decidir'), 'erro');\n  const s = sugestoes.ler(i.guildId, msgId);\n  if (!s) return responder(i, tx('sugestao_encontrada'), 'erro');\n  if (s.status !== 'aberta') return responder(i, tx('esta_sugestao_ja_foi', { status: s.status }), 'aviso');\n  const canal = s.canal ? await i.client.channels.fetch(s.canal).catch(() => null) : i.channel;\n  const msg = await canal?.messages.fetch(msgId).catch(() => null);\n  if (!msg) return responder(i, tx('achei_mensagem_sugestao'), 'erro');\n  s.status = aprovada ? 'aprovada' : 'recusada';\n  sugestoes.salvar();\n  const e = EmbedBuilder.from(msg.embeds[0])\n    .setColor(aprovada ? CORES.sucesso : CORES.erro)\n    .setFields(\n      { name: tx('situacao'), value: aprovada ? tx('aprovada', { usuario: i.user }) : tx('recusada', { usuario: i.user }) },\n      ...(motivo ? [{ name: tx('motivo'), value: cortar(motivo, 1000) }] : []),\n      { name: tx('votos'), value: `👍 ${s.sim.length} · 👎 ${s.nao.length}` },\n    );\n  await msg.edit({ embeds: [e], components: botoes(s, true) });\n  const autor = await i.client.users.fetch(s.autor).catch(() => null);\n  await autor\n    ?.send({ embeds: [embed(i.guildId).setDescription(tx('sua_sugestao_foi', { numero: s.numero, servidor: i.guild.name, status: s.status, motivo: motivo ? tx('motivo_2', { motivo }) : '' }))] })\n    .catch(() => {});\n  return responder(i, tx('sugestao_3', { numero: s.numero, status: s.status }), 'sucesso');\n}\n\nconst componentes = {\n  async sg(i, [acao, msgId, decisao]) {\n    // formulário da equipe enviado\n    if (i.isModalSubmit() && acao === 'motivo') {\n      return decidir(i, msgId, decisao === 'aprovar', i.fields.getTextInputValue('motivo').trim());\n    }\n    // botões da equipe (resposta escondida com Aprovar/Recusar)\n    if (acao === 'aprovar' || acao === 'recusar') {\n      if (!ehStaff(i.member)) return responder(i, tx('so_equipe_pode_decidir'), 'erro');\n      return i.showModal(\n        new ModalBuilder()\n          .setCustomId(`sg:motivo:${msgId}:${acao}`)\n          .setTitle(acao === 'aprovar' ? tx('aprovar_sugestao') : tx('recusar_sugestao'))\n          .addComponents(\n            new ActionRowBuilder().addComponents(\n              comDica(new TextInputBuilder().setCustomId('motivo').setLabel(tx('motivo_opcional')).setStyle(TextInputStyle.Paragraph).setRequired(false).setMaxLength(500), tx('dica_motivo'))\n            )\n          )\n      );\n    }\n\n    const s = sugestoes.ler(i.guildId, i.message?.id);\n    if (!s) return responder(i, tx('esta_sugestao_esta_mais'), 'erro');\n    if (s.status !== 'aberta') return responder(i, tx('votacao_desta_sugestao_ja'), 'aviso');\n\n    if (acao === 'analisar') {\n      if (!ehStaff(i.member)) return responder(i, tx('so_equipe_pode_usar'), 'erro');\n      return i.reply({\n        content: tx('fazer_esta_sugestao'),\n        components: [\n          new ActionRowBuilder().addComponents(\n            bt('aprovar').setCustomId(`sg:aprovar:${i.message.id}`),\n            bt('recusar').setCustomId(`sg:recusar:${i.message.id}`)\n          ),\n        ],\n        flags: MessageFlags.Ephemeral,\n      });\n    }\n\n    // voto: clicar de novo tira o voto; votar no outro lado troca\n    const lado = acao === 'sim' ? 'sim' : 'nao';\n    const outro = lado === 'sim' ? 'nao' : 'sim';\n    const id = i.user.id;\n    s[outro] = s[outro].filter((x) => x !== id);\n    if (s[lado].includes(id)) s[lado] = s[lado].filter((x) => x !== id);\n    else s[lado].push(id);\n    sugestoes.salvar();\n    return i.update({ components: botoes(s) });\n  },\n};\n\nconst config = {\n  grupo: 'sugestoes',\n  montar: (g) =>\n    g\n      .setDescription('Canal de sugestões')\n      .addSubcommand((s) =>\n        s.setName('canal').setDescription('Canal onde as sugestões são publicadas').addChannelOption((o) => o.setName('canal').setDescription('Vazio desliga').addChannelTypes(ChannelType.GuildText))\n      ),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const ch = i.options.getChannel('canal');\n    c.canal = ch?.id ?? null;\n    salvarAjustes();\n    return responder(i, ch ? tx('sugestoes_serao_publicadas', { canal: ch }) : tx('sugestoes_desligadas'), 'sucesso');\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    return [tx('canal', { canal: c.canal ? `<#${c.canal}>` : tx('definido') }), tx('sugestoes_enviadas', { contador: c.contador })];\n  },\n};\n\nexport default {\n  id: 'sugestoes',\n  nome: tx('sugestoes'),\n  comandos: [sugerir],\n  componentes,\n  permissoes: [PermissionFlagsBits.CreatePublicThreads],\n  config,\n};\n",
  "src/modules/tickets.js": "import {\n  ActionRowBuilder,\n  AttachmentBuilder,\n  ButtonBuilder,\n  ButtonStyle,\n  ChannelType,\n  EmbedBuilder,\n  GatewayIntentBits,\n  MessageFlags,\n  PermissionFlagsBits,\n  SlashCommandBuilder,\n  StringSelectMenuBuilder,\n} from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, preencher, ehStaff, cortar, CORES, sinais, imagens } from '../core/util.js';\nimport { textos, modeloOu, visuais, botoes, fileira, fileiras, emojiDeBotaoOk } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('tickets', {\n  assunto_campo: ['Assunto', 'campo'],\n  escolha_assunto: ['Escolha o assunto do seu ticket', 'placeholder'],\n  crie_assuntos: ['Crie os assuntos primeiro com `/ticket assunto adicionar`.', 'resposta'],\n  assunto_adicionado: ['Assunto **{nome}** adicionado ({total}/25). Para usar, envie o painel com `/ticket painel modo:Menu`.', 'resposta'],\n  assunto_existe: ['Já existe um assunto com esse nome.', 'resposta'],\n  assunto_limite: ['O Discord aceita no máximo 25 assuntos.', 'resposta'],\n  assunto_removido: ['Assunto **{nome}** removido. Envie o painel de novo para atualizar o menu.', 'resposta'],\n  assunto_nao_existe: ['Não achei esse assunto.', 'resposta'],\n  assunto_emoji_invalido: ['Esse emoji não serve num menu. Use um emoji normal ou um do servidor (<:nome:id>).', 'resposta'],\n  assuntos_titulo: ['📂 Assuntos dos tickets', 'titulo'],\n  assuntos_vazio: ['Nenhum assunto. Crie com `/ticket assunto adicionar`.', 'descricao'],\n  assunto_linha: '{emoji}**{nome}**{descricao}{extras}',\n  assunto_extra_categoria: ' · categoria {categoria}',\n  assunto_extra_equipe: ' · equipe {equipe}',\n  assunto_extra_mensagem: ' · mensagem própria',\n  assunto_indisponivel: ['Esse assunto não existe mais. Peça para a equipe enviar o painel de novo.', 'resposta'],\n  resumo_assuntos: 'Assuntos: {total}',\n  aguardando: ['aguardando', 'valor'],\n  msg_ticket_padrao: 'Olá {usuario}! Descreva o que você precisa com o máximo de detalhes. A equipe já foi avisada e responde assim que puder.',\n  fechar: ['Fechar', 'botao'],\n  assumido: 'Assumido',\n  assumir: 'Assumir',\n  tickets_abertos: 'tickets abertos',\n  ticket_aberto: 'um ticket aberto',\n  voce_ja_tem: 'Você já tem {quantos}: {canais}',\n  preciso_permissao_gerenciar_canais: '❌ Preciso da permissão **Gerenciar canais** para abrir tickets.',\n  ticket: ['ticket-{numero}', 'canal'],\n  ticket_2: 'Ticket de {tag} ({usuario_id})',\n  consegui_criar_canal_ticket: '❌ Não consegui criar o canal do ticket. Avise a equipe: confira as minhas permissões (Gerenciar canais e Gerenciar cargos) e se a categoria não está cheia (máximo de 50 canais).',\n  ticket_3: ['🎫 Ticket #{numero}', 'titulo'],\n  aberto: ['Aberto por', 'campo'],\n  atendente: ['Atendente', 'campo'],\n  ticket_aberto_2: '✅ Ticket aberto: {canal}',\n  anexos: ' [anexos: {anexos}]',\n  embed: ' [embed: {embed}]',\n  sem_motivo: 'Sem motivo',\n  isto_ticket: ['Isto não é um ticket.', 'resposta'],\n  so_quem_abriu_ou: ['Só quem abriu ou a equipe pode fechar.', 'resposta'],\n  este_ticket_ja_esta: ['Este ticket já está sendo fechado.', 'resposta'],\n  ticket_fechado_este_canal: ['🔒 Ticket fechado por {usuario}. Este canal será apagado em 5 segundos.', 'descricao'],\n  ticket_txt: ['ticket-{numero}.txt', 'campo'],\n  ticket_fechado: ['🎫 Ticket #{numero} fechado', 'titulo'],\n  fechado: ['Fechado por', 'campo'],\n  aberto_2: ['Aberto', 'campo'],\n  motivo: ['Motivo', 'campo'],\n  seu_ticket_foi_fechado: ['Seu ticket em **{servidor}** foi fechado. O histórico está em anexo.', 'descricao'],\n  tem_certeza_quer_fechar: ['Tem certeza que quer fechar este ticket?', 'conteudo'],\n  sim_fechar: ['Sim, fechar', 'botao'],\n  fechado_pelo_botao: 'Fechado pelo botão',\n  so_equipe_pode_assumir: ['Só a equipe pode assumir tickets.', 'resposta'],\n  este_ticket_ja: ['Este ticket já é de <@{assumido}>.', 'resposta'],\n  assumiu_este_ticket: ['🙋 {usuario} assumiu este ticket.', 'conteudo'],\n  so_quem_tem_gerenciar: ['Só quem tem Gerenciar servidor pode enviar o painel.', 'resposta'],\n  atendimento: '🎫 Atendimento',\n  precisa_ajuda_clique_botao: 'Precisa de ajuda? Clique no botão abaixo e um canal privado será aberto para você falar com a equipe.',\n  abrir_ticket: 'Abrir ticket',\n  painel_enviado: ['Painel enviado em {canal}.', 'resposta'],\n  use_este_comando_dentro: ['Use este comando dentro de um ticket.', 'resposta'],\n  so_equipe_pode_fazer: ['Só a equipe pode fazer isso.', 'resposta'],\n  consegui_adicionar_preciso_permissao: ['Não consegui adicionar. Preciso da permissão **Gerenciar cargos** para mexer nas permissões do canal.', 'resposta'],\n  foi_adicionado_ticket: ['➕ {usuario} foi adicionado(a) ao ticket por {usuario2}.', 'conteudo'],\n  remover_quem_abriu_ticket: ['Não dá para remover quem abriu o ticket.', 'resposta'],\n  foi_removido_ticket: ['➖ {usuario} foi removido(a) do ticket.', 'conteudo'],\n  ticket_renomeado: '✅ Ticket renomeado para **{nome}**.',\n  consegui_renomear_agora: '❌ Não consegui renomear agora.',\n  tickets_serao_criados: 'Os tickets serão criados em **{categoria}**.',\n  tickets_serao_criados_sem: 'Os tickets serão criados sem categoria.',\n  atende_tickets: '{cargo} atende os tickets.',\n  tickets_usam_cargo_config: 'Os tickets usam o cargo de /config staff.',\n  historico_tickets_vai: 'Histórico dos tickets vai para {canal}.',\n  registro_tickets_desligado: 'Registro de tickets desligado.',\n  mensagem_ticket_atualizada: 'Mensagem do ticket atualizada.',\n  cada_pessoa_pode_ter: 'Cada pessoa pode ter até **{limite}** ticket(s) aberto(s).',\n  nenhuma: 'nenhuma',\n  categoria: 'Categoria: {categoria}',\n  cargo_config_staff: 'cargo de /config staff',\n  equipe: 'Equipe: {equipe}',\n  desligado: 'desligado',\n  registro: 'Registro: {registro}',\n  abertos_agora_limite_pessoa: 'Abertos agora: {abertos} · Limite por pessoa: {limite}',\n  tickets: 'Tickets',\n});\n\n// Botões (texto, emoji e cor personalizáveis; alguns podem ser escondidos)\nconst bt = botoes('tickets', {\n  abrir: { nome: 'Abrir ticket (painel)', rotulo: 'abrir_ticket', emoji: '🎫', estilo: 'Primary' },\n  fechar: { nome: 'Fechar ticket', rotulo: 'fechar', emoji: '🔒', estilo: 'Danger' },\n  assumir: { nome: 'Assumir ticket', rotulo: 'assumir', emoji: '🙋', estilo: 'Primary', rotuloInfo: 'Depois de assumido, o texto vira o de \"Assumido\".', ocultavel: true },\n  confirmar: { nome: 'Confirmar fechamento', rotulo: 'sim_fechar', emoji: '-', estilo: 'Danger' },\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('tickets', {\n  painel: { nome: \"Painel com o botão de abrir ticket\", vars: ['servidor_icone'] },\n  aberto: { nome: \"Mensagem dentro do ticket aberto\", vars: ['avatar', 'servidor_icone'] },\n});\n\n/**\n * Tickets: painel com botão \"Abrir ticket\", canal privado para cada atendimento,\n * botões de fechar e assumir, e histórico (.txt) enviado ao canal de registro ao fechar.\n */\n\nconst tickets = colecao('tickets');\nconst PADRAO = {\n  categoria: null,\n  equipe: null, // se vazio, usa o cargo de /config staff\n  registro: null,\n  mensagem: null,\n  limite: 1,\n  contador: 0,\n  assuntos: [], // { id, nome, emoji, descricao, categoria, equipe, mensagem } (menu do painel)\n};\nconst cfg = (guildId) => ajustes(guildId, 'tickets', PADRAO);\nconst msgTicket = (c) => modeloOu(c.mensagem, 'Olá {usuario}! Descreva o que você precisa com o máximo de detalhes. A equipe já foi avisada e responde assim que puder.', tx('msg_ticket_padrao'));\nconst dados = (guildId, canalId) => tickets.ler(guildId, canalId);\n\nfunction podeAtender(member) {\n  const c = cfg(member.guild.id);\n  return ehStaff(member) || (c.equipe && member.roles.cache.has(c.equipe));\n}\n\nconst botoesTicket = (assumido = false) =>\n  fileira(bt('fechar').setCustomId('tk:fechar'), bt('assumir', assumido ? { rotulo: tx('assumido') } : undefined)?.setCustomId('tk:assumir').setDisabled(assumido));\n\n// ---------------- abrir ----------------\n/**\n * Abre um ticket. assunto (opcional): { nome, emoji, categoria, equipe, mensagem }\n * Usado pelo botão/menu do /ticket painel e pelos painéis criados no Personalizar bot.\n */\nexport async function abrirTicket(i, assunto = null) {\n  return abrir(i, assunto);\n}\n\nasync function abrir(i, assunto = null) {\n  await i.deferReply({ flags: MessageFlags.Ephemeral });\n  const c = cfg(i.guildId);\n  const g = tickets.de(i.guildId);\n\n  // limpa registros de canais que não existem mais\n  for (const canalId of Object.keys(g)) if (!i.guild.channels.cache.has(canalId)) delete g[canalId];\n  const abertos = Object.entries(g).filter(([, t]) => t.dono === i.user.id);\n  if (abertos.length >= c.limite) {\n    return i.editReply(tx('voce_ja_tem', { quantos: abertos.length > 1 ? tx('tickets_abertos') : tx('ticket_aberto'), canais: abertos.map(([id]) => `<#${id}>`).join(' ') }));\n  }\n\n  const me = i.guild.members.me;\n  if (!me.permissions.has(PermissionFlagsBits.ManageChannels)) return i.editReply(tx('preciso_permissao_gerenciar_canais'));\n\n  const equipeGeral = c.equipe || ajustes(i.guildId, 'geral').staff;\n  const equipeAssunto = assunto?.equipe && i.guild.roles.cache.has(assunto.equipe) ? assunto.equipe : null;\n  const equipe = equipeAssunto || equipeGeral; // quem é avisado\n  const ehCategoria = (id) => id && i.guild.channels.cache.get(id)?.type === ChannelType.GuildCategory;\n  const categoria = ehCategoria(assunto?.categoria) ? assunto.categoria : ehCategoria(c.categoria) ? c.categoria : null;\n\n  // o Discord só deixa o bot liberar no canal permissões que ele mesmo tem\n  const soAsMinhas = (lista) => lista.filter((p) => me.permissions.has(p));\n  const permitir = soAsMinhas([\n    PermissionFlagsBits.ViewChannel,\n    PermissionFlagsBits.SendMessages,\n    PermissionFlagsBits.ReadMessageHistory,\n    PermissionFlagsBits.AttachFiles,\n    PermissionFlagsBits.EmbedLinks,\n  ]);\n  const sobrescritas = [\n    { id: i.guild.roles.everyone.id, deny: [PermissionFlagsBits.ViewChannel] },\n    { id: i.user.id, allow: permitir },\n    { id: me.id, allow: soAsMinhas([...permitir, PermissionFlagsBits.ManageChannels, PermissionFlagsBits.ManageMessages]) },\n  ];\n  for (const r of new Set([equipeGeral, equipeAssunto])) {\n    if (r && i.guild.roles.cache.has(r)) sobrescritas.push({ id: r, allow: soAsMinhas([...permitir, PermissionFlagsBits.ManageMessages]) });\n  }\n\n  const numero = String(c.contador + 1).padStart(4, '0');\n  let canal;\n  try {\n    canal = await i.guild.channels.create({\n      name: tx('ticket', { numero }),\n      type: ChannelType.GuildText,\n      parent: categoria ?? undefined,\n      topic: tx('ticket_2', { tag: i.user.tag, usuario_id: i.user.id }),\n      permissionOverwrites: sobrescritas,\n      reason: `Ticket aberto por ${i.user.tag}`,\n    });\n  } catch (e) {\n    console.error('[tickets] não consegui criar o canal:', e.message);\n    return i.editReply(tx('consegui_criar_canal_ticket'));\n  }\n  c.contador += 1;\n  salvarAjustes();\n\n  const nomeAssunto = assunto?.nome ? `${assunto.emoji ? `${assunto.emoji} ` : ''}${assunto.nome}` : null;\n  g[canal.id] = { dono: i.user.id, numero, aberto: Date.now(), assumido: null, assunto: nomeAssunto };\n  tickets.salvar();\n\n  const e = embed(i.guildId)\n    .setTitle(tx('ticket_3', { numero }))\n    .setDescription(preencher(assunto?.mensagem || msgTicket(c), { usuario: `${i.user}`, nome: i.member.displayName, servidor: i.guild.name, assunto: assunto?.nome ?? '' }))\n    .addFields({ name: tx('aberto'), value: `${i.user}`, inline: true }, { name: tx('atendente'), value: tx('aguardando'), inline: true })\n    .setTimestamp();\n  if (nomeAssunto) e.addFields({ name: tx('assunto_campo'), value: nomeAssunto, inline: true }); // 3º campo (o 2º é o atendente)\n  vis(e, 'aberto', imagens({ user: i.user, guild: i.guild }));\n  await canal.send({\n    content: `${i.user}${equipe ? ` <@&${equipe}>` : ''}`,\n    embeds: [e],\n    components: fileiras(botoesTicket()),\n    allowedMentions: { users: [i.user.id], roles: equipe ? [equipe] : [] },\n  });\n  return i.editReply(tx('ticket_aberto_2', { canal }));\n}\n\n// ---------------- fechar ----------------\nasync function historico(canal) {\n  const todas = [];\n  let antes;\n  for (let n = 0; n < 10; n++) {\n    const lote = await canal.messages.fetch({ limit: 100, before: antes }).catch(() => null);\n    if (!lote?.size) break;\n    todas.push(...lote.values());\n    antes = lote.last().id;\n    if (lote.size < 100) break;\n  }\n  todas.reverse();\n  const data = (d) => d.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });\n  return todas\n    .map((m) => {\n      const anexos = m.attachments.size ? tx('anexos', { anexos: [...m.attachments.values()].map((a) => a.url).join(' ') }) : '';\n      const embeds = !m.content && m.embeds.length ? tx('embed', { embed: m.embeds[0].title ?? m.embeds[0].description?.slice(0, 80) ?? '' }) : '';\n      return `[${data(m.createdAt)}] ${m.author.tag}: ${m.content}${anexos}${embeds}`;\n    })\n    .join('\\n');\n}\n\nconst fechando = new Set(); // evita fechar o mesmo ticket duas vezes ao mesmo tempo\n\nasync function fechar(i, motivo = tx('sem_motivo')) {\n  const t = dados(i.guildId, i.channelId);\n  if (!t) return responder(i, tx('isto_ticket'), 'erro');\n  if (i.user.id !== t.dono && !podeAtender(i.member)) return responder(i, tx('so_quem_abriu_ou'), 'erro');\n  if (fechando.has(i.channelId)) return responder(i, tx('este_ticket_ja_esta'), 'aviso');\n  fechando.add(i.channelId);\n  setTimeout(() => fechando.delete(i.channelId), 30_000);\n\n  await i.reply({ embeds: [embed(i.guildId).setColor(CORES.erro).setDescription(tx('ticket_fechado_este_canal', { usuario: i.user }))] });\n\n  const texto = await historico(i.channel);\n  const arquivo = () => new AttachmentBuilder(Buffer.from(texto || '(sem mensagens)', 'utf8'), { name: tx('ticket_txt', { numero: t.numero }) });\n  const resumo = embed(i.guildId)\n    .setTitle(tx('ticket_fechado', { numero: t.numero }))\n    .addFields(\n      { name: tx('aberto'), value: `<@${t.dono}>`, inline: true },\n      { name: tx('fechado'), value: `${i.user}`, inline: true },\n      { name: tx('atendente'), value: t.assumido ? `<@${t.assumido}>` : '—', inline: true },\n      { name: tx('aberto_2'), value: `<t:${Math.floor(t.aberto / 1000)}:f>`, inline: true },\n      ...(t.assunto ? [{ name: tx('assunto_campo'), value: cortar(t.assunto, 1000), inline: true }] : []),\n      { name: tx('motivo'), value: cortar(motivo, 1000) },\n    )\n    .setTimestamp();\n\n  const c = cfg(i.guildId);\n  const reg = c.registro && i.guild.channels.cache.get(c.registro);\n  if (reg?.isTextBased()) await reg.send({ embeds: [resumo], files: [arquivo()], allowedMentions: { parse: [] } }).catch(() => {});\n  const dono = await i.client.users.fetch(t.dono).catch(() => null);\n  if (dono) await dono.send({ embeds: [resumo.setDescription(tx('seu_ticket_foi_fechado', { servidor: i.guild.name }))], files: [arquivo()] }).catch(() => {});\n\n  // outros módulos (ex.: Avaliação de atendimento) ficam sabendo\n  sinais.emit('ticketFechado', { guild: i.guild, client: i.client, dono: t.dono, atendente: t.assumido, fechadoPor: i.user.id, numero: t.numero });\n\n  tickets.apagar(i.guildId, i.channelId);\n  setTimeout(() => i.channel.delete(`Ticket fechado por ${i.user.tag}`).catch(() => {}), 5000);\n}\n\n// ---------------- botões ----------------\nconst componentes = {\n  async tk(i, [acao]) {\n    if (acao === 'abrir') return abrir(i);\n    if (acao === 'assunto' && i.isStringSelectMenu()) {\n      const a = cfg(i.guildId).assuntos.find((x) => x.id === i.values[0]);\n      if (!a) return responder(i, tx('assunto_indisponivel'), 'erro');\n      return abrir(i, a);\n    }\n    if (acao === 'fechar') {\n      const t = dados(i.guildId, i.channelId);\n      if (!t) return responder(i, tx('isto_ticket'), 'erro');\n      return i.reply({\n        content: tx('tem_certeza_quer_fechar'),\n        components: [new ActionRowBuilder().addComponents(bt('confirmar').setCustomId('tk:confirmar'))],\n        flags: MessageFlags.Ephemeral,\n      });\n    }\n    if (acao === 'confirmar') return fechar(i, tx('fechado_pelo_botao'));\n    if (acao === 'assumir') {\n      const t = dados(i.guildId, i.channelId);\n      if (!t) return responder(i, tx('isto_ticket'), 'erro');\n      if (!podeAtender(i.member)) return responder(i, tx('so_equipe_pode_assumir'), 'erro');\n      if (t.assumido) return responder(i, tx('este_ticket_ja', { assumido: t.assumido }), 'aviso');\n      t.assumido = i.user.id;\n      tickets.salvar();\n      const original = i.message.embeds[0];\n      const e = original ? EmbedBuilder.from(original) : embed(i.guildId);\n      if (original) e.setFields(original.fields.map((f, n) => (n === 1 ? { ...f, value: `${i.user}` } : f))); // 2º campo = Atendente (o nome pode ter sido personalizado)\n      await i.update({ embeds: [e], components: fileiras(botoesTicket(true)) });\n      return i.channel.send({ content: tx('assumiu_este_ticket', { usuario: i.user }), allowedMentions: { parse: [] } });\n    }\n  },\n};\n\n// ---------------- comando /ticket ----------------\nconst ticket = {\n  data: new SlashCommandBuilder()\n    .setName('ticket')\n    .setDescription('Sistema de tickets')\n    .addSubcommand((s) =>\n      s\n        .setName('painel')\n        .setDescription('Envia o painel com o botão de abrir ticket (equipe)')\n        .addChannelOption((o) => o.setName('canal').setDescription('Padrão: este canal').addChannelTypes(ChannelType.GuildText))\n        .addStringOption((o) => o.setName('titulo').setDescription('Título do painel').setMaxLength(100))\n        .addStringOption((o) => o.setName('descricao').setDescription('Texto do painel').setMaxLength(1500))\n        .addStringOption((o) => o.setName('botao').setDescription('Texto do botão').setMaxLength(60))\n        .addStringOption((o) =>\n          o.setName('modo').setDescription('Botão (padrão) ou menu com os assuntos').addChoices({ name: 'Botão', value: 'botao' }, { name: 'Menu de assuntos', value: 'menu' })\n        )\n    )\n    .addSubcommandGroup((g) =>\n      g\n        .setName('assunto')\n        .setDescription('Assuntos do menu de tickets (equipe)')\n        .addSubcommand((s) =>\n          s\n            .setName('adicionar')\n            .setDescription('Cria um assunto para o menu do painel')\n            .addStringOption((o) => o.setName('nome').setDescription('Ex.: Suporte, Compras, Denúncia').setRequired(true).setMaxLength(80))\n            .addStringOption((o) => o.setName('emoji').setDescription('Emoji do assunto').setMaxLength(64))\n            .addStringOption((o) => o.setName('descricao').setDescription('Texto pequeno embaixo do nome no menu').setMaxLength(100))\n            .addChannelOption((o) => o.setName('categoria').setDescription('Categoria dos tickets deste assunto').addChannelTypes(ChannelType.GuildCategory))\n            .addRoleOption((o) => o.setName('equipe').setDescription('Cargo que atende este assunto'))\n            .addStringOption((o) => o.setName('mensagem').setDescription('Mensagem de abertura. Variáveis: {usuario} {nome} {servidor} {assunto}').setMaxLength(1500))\n        )\n        .addSubcommand((s) =>\n          s.setName('remover').setDescription('Apaga um assunto').addStringOption((o) => o.setName('nome').setDescription('Assunto').setRequired(true).setAutocomplete(true))\n        )\n        .addSubcommand((s) => s.setName('lista').setDescription('Mostra os assuntos'))\n    )\n    .addSubcommand((s) => s.setName('fechar').setDescription('Fecha este ticket').addStringOption((o) => o.setName('motivo').setDescription('Motivo').setMaxLength(500)))\n    .addSubcommand((s) => s.setName('adicionar').setDescription('Adiciona alguém a este ticket').addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true)))\n    .addSubcommand((s) => s.setName('remover').setDescription('Remove alguém deste ticket').addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true)))\n    .addSubcommand((s) =>\n      s.setName('renomear').setDescription('Muda o nome deste ticket').addStringOption((o) => o.setName('nome').setDescription('Novo nome').setRequired(true).setMaxLength(90))\n    ),\n  async autocompletar(i) {\n    const busca = i.options.getFocused().toLowerCase();\n    const lista = cfg(i.guildId).assuntos.filter((a) => a.nome.toLowerCase().includes(busca)).slice(0, 25);\n    return i.respond(lista.map((a) => ({ name: a.nome, value: a.id })));\n  },\n  async executar(i) {\n    const grupo = i.options.getSubcommandGroup(false);\n    const sub = i.options.getSubcommand();\n    if (grupo === 'assunto') return assuntos(i, sub);\n    if (sub === 'painel') {\n      if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, tx('so_quem_tem_gerenciar'), 'erro');\n      const c = cfg(i.guildId);\n      const menu = i.options.getString('modo') === 'menu';\n      if (menu && !c.assuntos.length) return responder(i, tx('crie_assuntos'), 'erro');\n      const canal = i.options.getChannel('canal') ?? i.channel;\n      const e = embed(i.guildId)\n        .setTitle(i.options.getString('titulo') || tx('atendimento'))\n        .setDescription(i.options.getString('descricao') || tx('precisa_ajuda_clique_botao'));\n      vis(e, 'painel', imagens({ guild: i.guild }));\n      const row = menu\n        ? new ActionRowBuilder().addComponents(\n            new StringSelectMenuBuilder()\n              .setCustomId('tk:assunto')\n              .setPlaceholder(tx('escolha_assunto'))\n              .addOptions(\n                c.assuntos.slice(0, 25).map((a) => {\n                  const op = { label: cortar(a.nome, 100), value: a.id };\n                  if (a.descricao) op.description = cortar(a.descricao, 100);\n                  if (a.emoji) op.emoji = a.emoji;\n                  return op;\n                })\n              )\n          )\n        : new ActionRowBuilder().addComponents(bt('abrir', i.options.getString('botao') ? { rotulo: i.options.getString('botao') } : undefined).setCustomId('tk:abrir'));\n      await canal.send({ embeds: [e], components: [row] });\n      return responder(i, tx('painel_enviado', { canal }), 'sucesso');\n    }\n    if (sub === 'fechar') return fechar(i, i.options.getString('motivo') || tx('sem_motivo'));\n\n    const t = dados(i.guildId, i.channelId);\n    if (!t) return responder(i, tx('use_este_comando_dentro'), 'erro');\n    if (!podeAtender(i.member)) return responder(i, tx('so_equipe_pode_fazer'), 'erro');\n    if (sub === 'adicionar') {\n      const u = i.options.getUser('usuario');\n      const ok = await i.channel.permissionOverwrites\n        .edit(u.id, { ViewChannel: true, SendMessages: true, ReadMessageHistory: true, AttachFiles: true })\n        .then(() => true, () => false);\n      if (!ok) return responder(i, tx('consegui_adicionar_preciso_permissao'), 'erro');\n      return i.reply({ content: tx('foi_adicionado_ticket', { usuario: u, usuario2: i.user }), allowedMentions: { users: [u.id] } });\n    }\n    if (sub === 'remover') {\n      const u = i.options.getUser('usuario');\n      if (u.id === t.dono) return responder(i, tx('remover_quem_abriu_ticket'), 'erro');\n      await i.channel.permissionOverwrites.delete(u.id).catch(() => {});\n      return i.reply({ content: tx('foi_removido_ticket', { usuario: u }), allowedMentions: { parse: [] } });\n    }\n    if (sub === 'renomear') {\n      const nome = i.options.getString('nome').toLowerCase().replace(/\\s+/g, '-');\n      // o Discord só deixa renomear um canal 2 vezes a cada 10 minutos: responde antes de esperar\n      await i.deferReply({ flags: MessageFlags.Ephemeral });\n      const ok = await i.channel.setName(nome).then(() => true, () => false);\n      return i.editReply(ok ? tx('ticket_renomeado', { nome }) : tx('consegui_renomear_agora'));\n    }\n  },\n};\n\n// ---------------- /ticket assunto ----------------\nfunction assuntos(i, sub) {\n  if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, tx('so_quem_tem_gerenciar'), 'erro');\n  const c = cfg(i.guildId);\n  if (sub === 'adicionar') {\n    const nome = i.options.getString('nome').trim();\n    if (c.assuntos.length >= 25) return responder(i, tx('assunto_limite'), 'erro');\n    if (c.assuntos.some((a) => a.nome.toLowerCase() === nome.toLowerCase())) return responder(i, tx('assunto_existe'), 'erro');\n    const emoji = i.options.getString('emoji')?.trim() || '';\n    if (emoji && !emojiDeBotaoOk(emoji)) return responder(i, tx('assunto_emoji_invalido'), 'erro');\n    const base = nome.normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 24) || 'assunto';\n    let id = base;\n    for (let n = 2; c.assuntos.some((a) => a.id === id); n++) id = `${base}-${n}`;\n    c.assuntos.push({\n      id,\n      nome,\n      emoji,\n      descricao: i.options.getString('descricao') || '',\n      categoria: i.options.getChannel('categoria')?.id ?? null,\n      equipe: i.options.getRole('equipe')?.id ?? null,\n      mensagem: i.options.getString('mensagem') || '',\n    });\n    salvarAjustes();\n    return responder(i, tx('assunto_adicionado', { nome, total: c.assuntos.length }), 'sucesso');\n  }\n  if (sub === 'remover') {\n    const alvo = i.options.getString('nome');\n    const n = c.assuntos.findIndex((a) => a.id === alvo || a.nome.toLowerCase() === alvo.toLowerCase());\n    if (n < 0) return responder(i, tx('assunto_nao_existe'), 'erro');\n    const [a] = c.assuntos.splice(n, 1);\n    salvarAjustes();\n    return responder(i, tx('assunto_removido', { nome: a.nome }), 'sucesso');\n  }\n  const linhas = c.assuntos.map((a) =>\n    tx('assunto_linha', {\n      emoji: a.emoji ? `${a.emoji} ` : '',\n      nome: a.nome,\n      descricao: a.descricao ? ` — ${a.descricao}` : '',\n      extras:\n        (a.categoria ? tx('assunto_extra_categoria', { categoria: `<#${a.categoria}>` }) : '') +\n        (a.equipe ? tx('assunto_extra_equipe', { equipe: `<@&${a.equipe}>` }) : '') +\n        (a.mensagem ? tx('assunto_extra_mensagem') : ''),\n    })\n  );\n  return i.reply({ embeds: [embed(i.guildId).setTitle(tx('assuntos_titulo')).setDescription(linhas.join('\\n') || tx('assuntos_vazio'))], flags: MessageFlags.Ephemeral });\n}\n\n// ---------------- /config tickets ----------------\nconst config = {\n  grupo: 'tickets',\n  montar: (g) =>\n    g\n      .setDescription('Sistema de tickets')\n      .addSubcommand((s) =>\n        s.setName('categoria').setDescription('Categoria onde os tickets são criados').addChannelOption((o) => o.setName('categoria').setDescription('Vazio = sem categoria').addChannelTypes(ChannelType.GuildCategory))\n      )\n      .addSubcommand((s) => s.setName('equipe').setDescription('Cargo que atende os tickets').addRoleOption((o) => o.setName('cargo').setDescription('Vazio = usa /config staff')))\n      .addSubcommand((s) =>\n        s.setName('registro').setDescription('Canal que recebe o histórico dos tickets fechados').addChannelOption((o) => o.setName('canal').setDescription('Vazio desliga').addChannelTypes(ChannelType.GuildText))\n      )\n      .addSubcommand((s) =>\n        s.setName('mensagem').setDescription('Mensagem de boas-vindas do ticket').addStringOption((o) => o.setName('texto').setDescription('Variáveis: {usuario} {nome} {servidor}').setRequired(true).setMaxLength(1500))\n      )\n      .addSubcommand((s) =>\n        s.setName('limite').setDescription('Tickets abertos ao mesmo tempo por pessoa').addIntegerOption((o) => o.setName('quantidade').setDescription('De 1 a 5').setRequired(true).setMinValue(1).setMaxValue(5))\n      ),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    let msg;\n    if (sub === 'categoria') {\n      const cat = i.options.getChannel('categoria');\n      c.categoria = cat?.id ?? null;\n      msg = cat ? tx('tickets_serao_criados', { categoria: cat.name }) : tx('tickets_serao_criados_sem');\n    } else if (sub === 'equipe') {\n      const r = i.options.getRole('cargo');\n      c.equipe = r?.id ?? null;\n      msg = r ? tx('atende_tickets', { cargo: r }) : tx('tickets_usam_cargo_config');\n    } else if (sub === 'registro') {\n      const ch = i.options.getChannel('canal');\n      c.registro = ch?.id ?? null;\n      msg = ch ? tx('historico_tickets_vai', { canal: ch }) : tx('registro_tickets_desligado');\n    } else if (sub === 'mensagem') {\n      c.mensagem = i.options.getString('texto');\n      msg = tx('mensagem_ticket_atualizada');\n    } else if (sub === 'limite') {\n      c.limite = i.options.getInteger('quantidade');\n      msg = tx('cada_pessoa_pode_ter', { limite: c.limite });\n    }\n    salvarAjustes();\n    return responder(i, msg, 'sucesso');\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    const abertos = Object.keys(tickets.ler(guild.id) ?? {}).length;\n    return [\n      tx('categoria', { categoria: c.categoria ? `<#${c.categoria}>` : tx('nenhuma') }),\n      tx('equipe', { equipe: c.equipe ? `<@&${c.equipe}>` : tx('cargo_config_staff') }),\n      tx('registro', { registro: c.registro ? `<#${c.registro}>` : tx('desligado') }),\n      tx('abertos_agora_limite_pessoa', { abertos, limite: c.limite }),\n      tx('resumo_assuntos', { total: c.assuntos.length }),\n    ];\n  },\n};\n\nexport default {\n  id: 'tickets',\n  nome: tx('tickets'),\n  // o conteúdo das mensagens é necessário para salvar o histórico ao fechar\n  intents: [GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent],\n  permissoes: [PermissionFlagsBits.ManageChannels, PermissionFlagsBits.ManageRoles, PermissionFlagsBits.ManageMessages],\n  comandos: [ticket],\n  componentes,\n  config,\n};\n",
  "src/modules/utilidades.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { embed, responder, lerDuracao, duracaoTexto, ts, fmt, cortar } from '../core/util.js';\nimport { textos, botoes, fileira, fileiras } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('utilidades', {\n  nenhuma: 'Nenhuma',\n  baixa: 'Baixa',\n  media: 'Média',\n  alta: 'Alta',\n  muito_alta: 'Muito alta',\n  id: ['ID', 'campo'],\n  conta_criada: ['Conta criada', 'campo'],\n  entrou_servidor: ['Entrou no servidor', 'campo'],\n  apelido: ['Apelido', 'campo'],\n  cargos: ['Cargos ({cargos_total})', 'campo'],\n  impulsiona_desde: ['Impulsiona desde', 'campo'],\n  dono: ['Dono', 'campo'],\n  criado: ['Criado em', 'campo'],\n  membros: ['Membros', 'campo'],\n  online: ' · {online} online',\n  canais: ['Canais', 'campo'],\n  texto_voz_categorias: '{canais_texto} texto · {canais_voz} voz · {categorias} categorias',\n  cargos_2: ['Cargos', 'campo'],\n  emojis: ['Emojis', 'campo'],\n  impulsos: ['Impulsos', 'campo'],\n  nivel: '{impulsos} (nível {nivel})',\n  verificacao: ['Verificação', 'campo'],\n  abrir_navegador: ['Abrir no navegador', 'botao'],\n  avatar_global: ['Avatar global', 'botao'],\n  avatar: ['Avatar de {nome}', 'titulo'],\n  tempo_invalido_ex_10m: ['Tempo inválido (ex.: 10m, 2h, 1d; entre 30s e 1 ano).', 'resposta'],\n  voce_ja_tem_20: ['Você já tem 20 lembretes pendentes.', 'resposta'],\n  combinado_te_lembro: ['Combinado! Te lembro {quando} (em {duracao}).', 'resposta'],\n  utilidades: 'Utilidades',\n  voce_pediu_eu_te: '⏰ <@{usuario}>, você pediu para eu te lembrar ({quando}):\\n> {lembrete}',\n});\n\n// Botões (texto, emoji e cor personalizáveis; alguns podem ser escondidos)\nconst bt = botoes('utilidades', {\n  navegador: { nome: 'Abrir no navegador (/avatar)', rotulo: 'abrir_navegador', emoji: '-', estilo: 'Link', ocultavel: true },\n  global: { nome: 'Avatar global (/avatar)', rotulo: 'avatar_global', emoji: '-', estilo: 'Link', ocultavel: true },\n});\n\n/** Utilidades: informações de membros e do servidor, avatar e lembretes. */\n\nconst lembretes = colecao('lembretes');\nconst VERIFICACAO = [tx('nenhuma'), tx('baixa'), tx('media'), tx('alta'), tx('muito_alta')];\n\nconst userinfo = {\n  data: new SlashCommandBuilder()\n    .setName('userinfo')\n    .setDescription('Informações de um membro')\n    .addUserOption((o) => o.setName('usuario').setDescription('Padrão: você')),\n  async executar(i) {\n    const user = await (i.options.getUser('usuario') ?? i.user).fetch().catch(() => i.options.getUser('usuario') ?? i.user);\n    const membro = i.options.getMember('usuario') ?? (user.id === i.user.id ? i.member : null);\n    const e = embed(i.guildId)\n      .setAuthor({ name: user.tag, iconURL: user.displayAvatarURL() })\n      .setThumbnail(user.displayAvatarURL({ size: 256 }))\n      .addFields(\n        { name: tx('id'), value: user.id, inline: true },\n        { name: tx('conta_criada'), value: `${ts(user.createdTimestamp, 'd')} (${ts(user.createdTimestamp)})`, inline: true },\n      );\n    if (membro) {\n      const cargos = membro.roles.cache.filter((r) => r.id !== i.guildId).sort((a, b) => b.position - a.position);\n      e.addFields(\n        { name: tx('entrou_servidor'), value: `${ts(membro.joinedTimestamp, 'd')} (${ts(membro.joinedTimestamp)})`, inline: true },\n        { name: tx('apelido'), value: membro.nickname || '—', inline: true },\n        { name: tx('cargos', { cargos_total: cargos.size }), value: cortar(cargos.map((r) => `${r}`).join(' ') || 'nenhum', 1024) },\n      );\n      if (membro.premiumSince) e.addFields({ name: tx('impulsiona_desde'), value: ts(membro.premiumSinceTimestamp, 'd'), inline: true });\n      if (membro.displayHexColor !== '#000000') e.setColor(membro.displayColor);\n    }\n    if (user.bannerURL()) e.setImage(user.bannerURL({ size: 1024 }));\n    await i.reply({ embeds: [e], allowedMentions: { parse: [] } });\n  },\n};\n\nconst serverinfo = {\n  data: new SlashCommandBuilder().setName('serverinfo').setDescription('Informações do servidor'),\n  async executar(i) {\n    const g = await i.guild.fetch();\n    const canais = g.channels.cache;\n    const conta = (...t) => canais.filter((c) => t.includes(c.type)).size;\n    const dono = await g.fetchOwner().catch(() => null);\n    const e = embed(i.guildId)\n      .setTitle(g.name)\n      .setThumbnail(g.iconURL({ size: 256 }))\n      .addFields(\n        { name: tx('dono'), value: dono ? `${dono.user}` : '—', inline: true },\n        { name: tx('criado'), value: `${ts(g.createdTimestamp, 'd')} (${ts(g.createdTimestamp)})`, inline: true },\n        { name: tx('id'), value: g.id, inline: true },\n        { name: tx('membros'), value: `${fmt(g.memberCount)}${g.approximatePresenceCount ? tx('online', { online: fmt(g.approximatePresenceCount) }) : ''}`, inline: true },\n        {\n          name: tx('canais'),\n          value: tx('texto_voz_categorias', { canais_texto: conta(ChannelType.GuildText, ChannelType.GuildAnnouncement, ChannelType.GuildForum), canais_voz: conta(ChannelType.GuildVoice, ChannelType.GuildStageVoice), categorias: conta(ChannelType.GuildCategory) }),\n          inline: true,\n        },\n        { name: tx('cargos_2'), value: fmt(g.roles.cache.size - 1), inline: true },\n        { name: tx('emojis'), value: fmt(g.emojis.cache.size), inline: true },\n        { name: tx('impulsos'), value: tx('nivel', { impulsos: g.premiumSubscriptionCount ?? 0, nivel: g.premiumTier }), inline: true },\n        { name: tx('verificacao'), value: VERIFICACAO[g.verificationLevel] ?? '—', inline: true },\n      );\n    if (g.description) e.setDescription(g.description);\n    if (g.bannerURL()) e.setImage(g.bannerURL({ size: 1024 }));\n    await i.reply({ embeds: [e], allowedMentions: { parse: [] } });\n  },\n};\n\nconst avatar = {\n  data: new SlashCommandBuilder()\n    .setName('avatar')\n    .setDescription('Mostra o avatar de alguém')\n    .addUserOption((o) => o.setName('usuario').setDescription('Padrão: você')),\n  async executar(i) {\n    const user = i.options.getUser('usuario') ?? i.user;\n    const membro = i.options.getMember('usuario') ?? (user.id === i.user.id ? i.member : null);\n    const url = (membro?.avatar ? membro.displayAvatarURL({ size: 1024 }) : null) ?? user.displayAvatarURL({ size: 1024 });\n    const row = fileira(bt('navegador')?.setURL(url), membro?.avatar ? bt('global')?.setURL(user.displayAvatarURL({ size: 1024 })) : null);\n    await i.reply({ embeds: [embed(i.guildId).setTitle(tx('avatar', { nome: user.username })).setImage(url)], components: fileiras(row) });\n  },\n};\n\nconst lembrete = {\n  data: new SlashCommandBuilder()\n    .setName('lembrete')\n    .setDescription('O bot te lembra de algo depois')\n    .addStringOption((o) => o.setName('tempo').setDescription('Daqui a quanto tempo: 10m, 2h, 1d').setRequired(true).setMaxLength(20))\n    .addStringOption((o) => o.setName('texto').setDescription('Do que lembrar').setRequired(true).setMaxLength(500)),\n  async executar(i) {\n    const ms = lerDuracao(i.options.getString('tempo'));\n    if (!ms || ms < 30_000 || ms > 365 * 86_400_000) return responder(i, tx('tempo_invalido_ex_10m'), 'erro');\n    const meus = Object.values(lembretes.raiz).filter((l) => l.usuario === i.user.id).length;\n    if (meus >= 20) return responder(i, tx('voce_ja_tem_20'), 'erro');\n    const id = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;\n    lembretes.raiz[id] = { usuario: i.user.id, canal: i.channelId, texto: i.options.getString('texto'), quando: Date.now() + ms, criado: Date.now() };\n    lembretes.salvar();\n    return responder(i, tx('combinado_te_lembro', { quando: ts(Date.now() + ms), duracao: duracaoTexto(ms) }), 'sucesso');\n  },\n};\n\nexport default {\n  id: 'utilidades',\n  nome: tx('utilidades'),\n  comandos: [userinfo, serverinfo, avatar, lembrete],\n  aoIniciar(client) {\n    const checar = async () => {\n      const agora = Date.now();\n      for (const [id, l] of Object.entries(lembretes.raiz)) {\n        if (l.quando > agora) continue;\n        delete lembretes.raiz[id];\n        lembretes.salvar();\n        const texto = tx('voce_pediu_eu_te', { usuario: l.usuario, quando: ts(l.criado), lembrete: cortar(l.texto, 500) });\n        const user = await client.users.fetch(l.usuario).catch(() => null);\n        const foiDm = await user?.send(texto).then(() => true).catch(() => false);\n        if (!foiDm) {\n          const canal = await client.channels.fetch(l.canal).catch(() => null);\n          await canal?.send({ content: texto, allowedMentions: { users: [l.usuario] } }).catch(() => {});\n        }\n      }\n    };\n    checar();\n    setInterval(checar, 15_000);\n  },\n};\n",
  "src/modules/verificacao.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, MessageFlags, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, sorteio, CORES, imagens } from '../core/util.js';\nimport { textos, visuais, botoes } from '../core/textos.js';\n\n// Textos deste módulo (o dono do bot pode trocar todos no \"Personalizar bot.html\")\nconst tx = textos('verificacao', {\n  verificacao: ['🔐 Verificação', 'titulo'],\n  provar_voce_robo_clique: ['Para provar que você não é um robô, clique em **{resposta}**.\\n\\nVocê tem 2 minutos.', 'descricao'],\n  verificacao_ainda_foi_configurada: ['A verificação ainda não foi configurada. Avise a equipe.', 'resposta'],\n  voce_ja_esta_verificado: ['Você já está verificado(a)!', 'resposta'],\n  tentou_verificar_conta_dia: '⛔ {usuario} ({tag}) tentou se verificar com uma conta de {dias} dia(s).',\n  sua_conta_discord_precisa: ['Sua conta do Discord precisa ter pelo menos **{idadeMinima} dia(s)** para entrar aqui. Tente de novo mais tarde.', 'resposta'],\n  tempo_acabou_clique_verificar: ['⏱️ O tempo acabou. Clique em **Verificar** de novo.', 'conteudo'],\n  errou_verificacao_vezes: '⚠️ {usuario} ({tag}) errou a verificação 3 vezes.',\n  voce_errou_vezes_espere: ['❌ Você errou 3 vezes. Espere um pouco e clique em **Verificar** de novo.', 'conteudo'],\n  foi_esse_tente_novo: ['❌ Não foi esse. Tente de novo:', 'conteudo'],\n  consigo_dar_cargo_meu: ['❌ Não consigo dar o cargo (o meu cargo está abaixo dele). Avise a equipe.', 'conteudo'],\n  consegui_te_dar_cargo: ['❌ Não consegui te dar o cargo. Avise a equipe.', 'conteudo'],\n  verificou: '✅ {usuario} ({tag}) se verificou.',\n  verificado_voce_recebeu_bem: ['✅ Verificado(a)! Você recebeu {cargo}. Bem-vindo(a)!', 'conteudo'],\n  escolha_cargo_comum_pode: ['Escolha um cargo comum (não pode ser @everyone nem cargo de bot).', 'resposta'],\n  seguranca_cargo_verificacao_pode: ['Por segurança, o cargo de verificação não pode ser de administrador.', 'resposta'],\n  meu_cargo_precisa_ficar: ['Meu cargo precisa ficar acima de {cargo} em Configurações do servidor → Cargos.', 'resposta'],\n  perde: ', perde <@&{remover}>',\n  conta_pelo_menos_dia: ', conta com pelo menos {idadeMinima} dia(s)',\n  verificacao_configurada_ganha_agora: ['Verificação configurada: ganha {cargo}{remover}{idadeMinima}.\\nAgora use `/verificacao painel`.', 'resposta'],\n  primeiro_use_verificacao_configurar: ['Primeiro use `/verificacao configurar` para escolher o cargo.', 'resposta'],\n  clique_botao_abaixo_verificar: 'Clique no botão abaixo para se verificar e liberar o servidor.',\n  verificar: ['Verificar', 'botao'],\n  consegui_enviar_confira_minhas: ['Não consegui enviar em {canal}. Confira as minhas permissões.', 'resposta'],\n  painel_enviado: ['Painel enviado em {canal}.', 'resposta'],\n  verificacao_2: 'Verificação',\n  configurada_verificacao_configurar: 'Não configurada (`/verificacao configurar`)',\n  remove: ' · remove <@&{remover}>',\n  cargo: 'Cargo: <@&{cargo}>{remover}',\n  dia: '{idadeMinima} dia(s)',\n  sem_limite: 'sem limite',\n  idade_minima_conta: 'Idade mínima da conta: {idadeMinima}',\n  definido: 'não definido',\n  registro: 'Registro: {registro}',\n});\n\n// Botões (texto, emoji e cor personalizáveis; alguns podem ser escondidos)\nconst bt = botoes('verificacao', {\n  iniciar: { nome: 'Verificar (painel)', rotulo: 'verificar', emoji: '✅', estilo: 'Success' },\n});\n\n// Aparência dos embeds principais (cor, imagem, miniatura e rodapé personalizáveis)\nconst vis = visuais('verificacao', {\n  painel: { nome: \"Painel de verificação\", vars: ['servidor_icone'] },\n});\n\n/**\n * Verificação: painel com o botão \"Verificar\". A pessoa resolve um desafio simples\n * (clicar no número certo) e ganha o cargo de membro. Segura contas de bots e raids.\n * Opcional: idade mínima da conta e cargo removido ao verificar.\n */\n\nconst PADRAO = { cargo: null, remover: null, registro: null, idadeMinima: 0 };\nconst cfg = (guildId) => ajustes(guildId, 'verificacao', PADRAO);\n\n// desafios em andamento: \"guild:user\" -> { opcoes, resposta, expira, erros } (a resposta fica só aqui, não no botão)\nconst desafios = new Map();\nconst chave = (i) => `${i.guildId}:${i.user.id}`;\nconst EMOJIS = ['🍎', '🐶', '🚗', '⭐', '🎈', '🍕', '⚽', '🌙', '🔑', '🎧'];\n\nasync function registrar(guild, texto, cor = CORES.sucesso) {\n  const id = cfg(guild.id).registro;\n  const canal = id && guild.channels.cache.get(id);\n  if (canal?.isTextBased()) await canal.send({ embeds: [embed(guild.id).setColor(cor).setDescription(texto).setTimestamp()], allowedMentions: { parse: [] } }).catch(() => {});\n}\n\nfunction novoDesafio(i) {\n  const opcoes = [...EMOJIS].sort(() => Math.random() - 0.5).slice(0, 5);\n  const resposta = opcoes[sorteio(0, opcoes.length - 1)];\n  const antigo = desafios.get(chave(i));\n  desafios.set(chave(i), { opcoes, resposta, expira: Date.now() + 2 * 60_000, erros: antigo?.erros ?? 0 });\n  return {\n    embeds: [embed(i.guildId).setTitle(tx('verificacao')).setDescription(tx('provar_voce_robo_clique', { resposta }))],\n    components: [\n      new ActionRowBuilder().addComponents(\n        opcoes.map((e, n) => new ButtonBuilder().setCustomId(`vf:r:${n}`).setEmoji(e).setStyle(ButtonStyle.Secondary))\n      ),\n    ],\n    flags: MessageFlags.Ephemeral,\n  };\n}\n\nconst componentes = {\n  async vf(i, [acao, indice]) {\n    const c = cfg(i.guildId);\n    const cargo = c.cargo && i.guild.roles.cache.get(c.cargo);\n    if (!cargo) return responder(i, tx('verificacao_ainda_foi_configurada'), 'erro');\n\n    if (acao === 'iniciar') {\n      if (i.member.roles.cache.has(cargo.id)) return responder(i, tx('voce_ja_esta_verificado'), 'sucesso');\n      const dias = (Date.now() - i.user.createdTimestamp) / 86400e3;\n      if (c.idadeMinima && dias < c.idadeMinima) {\n        await registrar(i.guild, tx('tentou_verificar_conta_dia', { usuario: i.user, tag: i.user.tag, dias: Math.floor(dias) }), CORES.aviso);\n        return responder(i, tx('sua_conta_discord_precisa', { idadeMinima: c.idadeMinima }), 'erro');\n      }\n      return i.reply(novoDesafio(i));\n    }\n\n    if (acao === 'r') {\n      const d = desafios.get(chave(i));\n      if (!d || d.expira < Date.now()) {\n        desafios.delete(chave(i));\n        return i.update({ content: tx('tempo_acabou_clique_verificar'), embeds: [], components: [] });\n      }\n      if (d.opcoes[Number(indice)] !== d.resposta) {\n        d.erros += 1;\n        if (d.erros >= 3) {\n          desafios.delete(chave(i));\n          await registrar(i.guild, tx('errou_verificacao_vezes', { usuario: i.user, tag: i.user.tag }), CORES.aviso);\n          return i.update({ content: tx('voce_errou_vezes_espere'), embeds: [], components: [] });\n        }\n        const proximo = novoDesafio(i);\n        return i.update({ content: tx('foi_esse_tente_novo'), embeds: proximo.embeds, components: proximo.components });\n      }\n      desafios.delete(chave(i));\n      if (!cargo.editable) return i.update({ content: tx('consigo_dar_cargo_meu'), embeds: [], components: [] });\n      const ok = await i.member.roles.add(cargo, 'Verificação').then(() => true, () => false);\n      if (!ok) return i.update({ content: tx('consegui_te_dar_cargo'), embeds: [], components: [] });\n      const remover = c.remover && i.guild.roles.cache.get(c.remover);\n      if (remover?.editable && i.member.roles.cache.has(remover.id)) await i.member.roles.remove(remover, 'Verificação').catch(() => {});\n      await registrar(i.guild, tx('verificou', { usuario: i.user, tag: i.user.tag }));\n      return i.update({ content: tx('verificado_voce_recebeu_bem', { cargo }), embeds: [], components: [] });\n    }\n  },\n};\n\nconst verificacao = {\n  data: new SlashCommandBuilder()\n    .setName('verificacao')\n    .setDescription('Configura a verificação de novos membros')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('Cargo que a pessoa ganha ao se verificar e outras opções')\n        .addRoleOption((o) => o.setName('cargo').setDescription('Cargo dado ao verificar').setRequired(true))\n        .addRoleOption((o) => o.setName('remover').setDescription('Cargo tirado ao verificar (ex.: \"Não verificado\")'))\n        .addIntegerOption((o) => o.setName('idade-minima').setDescription('Idade mínima da conta, em dias (0 = sem limite)').setMinValue(0).setMaxValue(365))\n        .addChannelOption((o) => o.setName('registro').setDescription('Canal para registrar as verificações').addChannelTypes(ChannelType.GuildText))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('painel')\n        .setDescription('Envia o painel com o botão \"Verificar\"')\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde enviar (padrão: aqui)').addChannelTypes(ChannelType.GuildText))\n        .addStringOption((o) => o.setName('mensagem').setDescription('Texto do painel').setMaxLength(1500))\n    ),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    if (i.options.getSubcommand() === 'configurar') {\n      const cargo = i.options.getRole('cargo');\n      if (cargo.managed || cargo.id === i.guildId) return responder(i, tx('escolha_cargo_comum_pode'), 'erro');\n      if (cargo.permissions.has(PermissionFlagsBits.Administrator)) return responder(i, tx('seguranca_cargo_verificacao_pode'), 'erro');\n      if (!cargo.editable) return responder(i, tx('meu_cargo_precisa_ficar', { cargo }), 'erro');\n      c.cargo = cargo.id;\n      const remover = i.options.getRole('remover');\n      if (remover !== null) c.remover = remover?.id ?? null;\n      const idade = i.options.getInteger('idade-minima');\n      if (idade !== null) c.idadeMinima = idade;\n      const reg = i.options.getChannel('registro');\n      if (reg) c.registro = reg.id;\n      salvarAjustes();\n      return responder(\n        i,\n        tx('verificacao_configurada_ganha_agora', { cargo, remover: c.remover ? tx('perde', { remover: c.remover }) : '', idadeMinima: c.idadeMinima ? tx('conta_pelo_menos_dia', { idadeMinima: c.idadeMinima }) : '' }),\n        'sucesso'\n      );\n    }\n\n    if (!c.cargo) return responder(i, tx('primeiro_use_verificacao_configurar'), 'erro');\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    const texto = i.options.getString('mensagem') || tx('clique_botao_abaixo_verificar');\n    const msg = await canal\n      .send({\n        embeds: [vis(embed(i.guildId).setTitle(tx('verificacao')).setDescription(texto), 'painel', imagens({ guild: i.guild }))],\n        components: [new ActionRowBuilder().addComponents(bt('iniciar').setCustomId('vf:iniciar'))],\n      })\n      .catch(() => null);\n    if (!msg) return responder(i, tx('consegui_enviar_confira_minhas', { canal }), 'erro');\n    return responder(i, tx('painel_enviado', { canal }), 'sucesso');\n  },\n};\n\n// limpa desafios vencidos\nsetInterval(() => {\n  const agora = Date.now();\n  for (const [k, d] of desafios) if (d.expira < agora) desafios.delete(k);\n}, 5 * 60_000).unref();\n\nexport default {\n  id: 'verificacao',\n  nome: tx('verificacao_2'),\n  comandos: [verificacao],\n  componentes,\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      if (!c.cargo) return [tx('configurada_verificacao_configurar')];\n      return [\n        tx('cargo', { cargo: c.cargo, remover: c.remover ? tx('remove', { remover: c.remover }) : '' }),\n        tx('idade_minima_conta', { idadeMinima: c.idadeMinima ? tx('dia', { idadeMinima: c.idadeMinima }) : tx('sem_limite') }),\n        tx('registro', { registro: c.registro ? `<#${c.registro}>` : tx('definido') }),\n      ];\n    },\n  },\n};\n",
};
